  KEY `idx_severity_level` (`severity_level`),
  CONSTRAINT `cm_emergency_cases_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `cm_patients` (`patient_id`) ON DELETE CASCADE,
