  CONSTRAINT `fk_cm_medicine_usage_medicine` FOREIGN KEY (`medicine_id`) REFERENCES `cm_medicine_inventory` (`medicine_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_cm_medicine_usage_user` FOREIGN KEY (`used_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_cm_usage_medicine` FOREIGN KEY (`medicine_id`) REFERENCES `cm_medicine_inventory` (`medicine_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cm_usage_record` FOREIGN KEY (`record_id`) REFERENCES `cm_medical_records` (`record_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

