/*Table structure for table `em_history` */

DROP TABLE IF EXISTS `em_history`;

CREATE TABLE `em_history` (
  `history_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `company_name` varchar(100) NOT NULL,
  `position` varchar(100) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `salary` decimal(12,2) DEFAULT NULL,
  `reason_for_leaving` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`history_id`),
  KEY `employee_id` (`employee_id`),
  CONSTRAINT `employment_history_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `em_history` */

/*Table structure for table `em_languages` */

DROP TABLE IF EXISTS `em_languages`;

CREATE TABLE `em_languages` (
  `language_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `language_name` varchar(50) NOT NULL,
  `proficiency` enum('Beginner','Intermediate','Advanced','Fluent','Native') DEFAULT 'Intermediate',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`language_id`),
  KEY `employee_id` (`employee_id`),
  CONSTRAINT `employee_languages_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

