/*Table structure for table `em_requirements` */

DROP TABLE IF EXISTS `em_requirements`;

CREATE TABLE `em_requirements` (
  `requirement_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `document_id` int(11) DEFAULT NULL,
  `requirement_name` varchar(100) NOT NULL,
  `status` enum('Submitted','Missing','For Follow-up') NOT NULL DEFAULT 'Missing',
  `remarks` text DEFAULT NULL,
  `submitted_date` date DEFAULT NULL,
  `follow_up_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`requirement_id`),
  KEY `employee_id` (`employee_id`),
  KEY `document_id` (`document_id`),
  CONSTRAINT `fk_em_requirements_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_requirements_document` FOREIGN KEY (`document_id`) REFERENCES `em_documents` (`document_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_requirements_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

