  `scheduled_time` time DEFAULT NULL,
  `approval_status` enum('pending','draft','scheduled','in_progress','approved','completed','archived') NOT NULL DEFAULT 'pending',
  `employee_status_updated` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `fk_exit_surveys_employee` (`employee_id`),
  CONSTRAINT `fk_exit_surveys_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `exit_surveys` */

