  PRIMARY KEY (`case_id`),
  UNIQUE KEY `case_number` (`case_number`),
  KEY `idx_case_student` (`student_number`),
  KEY `idx_case_counselor` (`counselor_id`),
  CONSTRAINT `fk_case_counselor` FOREIGN KEY (`counselor_id`) REFERENCES `em_employees` (`employee_id`),
  CONSTRAINT `fk_case_student` FOREIGN KEY (`student_number`) REFERENCES `enr_students` (`student_number`) ON DELETE CASCADE
