/*Table structure for table `lbr_recommendations` */

DROP TABLE IF EXISTS `lbr_recommendations`;

CREATE TABLE `lbr_recommendations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `borrower_id` int(11) NOT NULL,
  `book_id` int(11) NOT NULL,
  `recommendation_type` enum('genre_based','collaborative','trending','new_arrival') DEFAULT 'genre_based',
  `score` decimal(5,4) DEFAULT 0.0000,
  `was_borrowed` tinyint(1) DEFAULT 0,
  `shown_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_borrower` (`borrower_id`),
  KEY `idx_book` (`book_id`),
  CONSTRAINT `lbr_recommendations_ibfk_1` FOREIGN KEY (`borrower_id`) REFERENCES `lbr_borrowers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `lbr_recommendations_ibfk_2` FOREIGN KEY (`book_id`) REFERENCES `lbr_books` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

