CREATE TABLE `lc_audit_actions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `audit_id` bigint(20) unsigned NOT NULL,
  `item_id` bigint(20) unsigned DEFAULT NULL,
  `title` varchar(180) NOT NULL,
  `description` text NOT NULL,
  `assigned_to` varchar(150) NOT NULL,
  `assigned_email` varchar(190) DEFAULT NULL,
  `due_date` date NOT NULL,
  `status` varchar(25) NOT NULL DEFAULT 'open',
  `resolution_notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_audit_action_parent` (`audit_id`),
  KEY `idx_audit_action_status` (`status`),
  CONSTRAINT `fk_lc_audit_actions_parent` FOREIGN KEY (`audit_id`) REFERENCES `lc_audits` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

