/*Table structure for table `lc_audits` */

DROP TABLE IF EXISTS `lc_audits`;

CREATE TABLE `lc_audits` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `audit_code` varchar(40) NOT NULL,
  `title` varchar(180) NOT NULL,
  `audit_type` varchar(80) NOT NULL,
  `campus` varchar(160) NOT NULL DEFAULT 'Bestlink College of the Philippines - Bulacan Campus',
  `location` varchar(180) NOT NULL,
  `scheduled_date` date NOT NULL,
  `due_date` date NOT NULL,
  `responsible_name` varchar(150) NOT NULL,
  `responsible_email` varchar(190) NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'scheduled',
  `token_hash` char(64) NOT NULL,
  `token_expires_at` datetime NOT NULL,
  `reviewer_notes` text DEFAULT NULL,
  `created_by` varchar(150) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `audit_code` (`audit_code`),
  KEY `idx_audit_status` (`status`),
  KEY `idx_audit_due` (`due_date`),
  KEY `idx_audit_token` (`token_hash`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

