/*Table structure for table `lc_compliance_summary` */

DROP TABLE IF EXISTS `lc_compliance_summary`;

CREATE TABLE `lc_compliance_summary` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) DEFAULT NULL,
  `department_id` int(11) DEFAULT NULL,
  `employment_score` decimal(5,2) DEFAULT 0.00,
  `leave_score` decimal(5,2) DEFAULT 0.00,
  `benefits_score` decimal(5,2) DEFAULT 0.00,
  `working_conditions_score` decimal(5,2) DEFAULT 0.00,
  `workplace_protection_score` decimal(5,2) DEFAULT 0.00,
  `data_privacy_score` decimal(5,2) DEFAULT 0.00,
  `overall_score` decimal(5,2) DEFAULT 0.00,
  `status` enum('compliant','at_risk','non_compliant') DEFAULT 'compliant',
  `critical_issues` int(11) DEFAULT 0,
  `high_risks` int(11) DEFAULT 0,
  `medium_risks` int(11) DEFAULT 0,
  `low_risks` int(11) DEFAULT 0,
  `last_checked` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_lc_compliance_department` (`department_id`),
  KEY `fk_lc_compliance_summary_employee_id` (`employee_id`),
  CONSTRAINT `fk_lc_compliance_department` FOREIGN KEY (`department_id`) REFERENCES `em_departments` (`department_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_compliance_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_compliance_summary_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

