/*Table structure for table `lc_incident_report` */

DROP TABLE IF EXISTS `lc_incident_report`;

CREATE TABLE `lc_incident_report` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `incident_id` varchar(50) DEFAULT NULL,
  `incident_type` varchar(100) DEFAULT NULL,
  `type` varchar(150) DEFAULT NULL,
  `severity` varchar(20) DEFAULT 'medium',
  `status` varchar(50) DEFAULT 'submitted',
  `requires_corrective_action` tinyint(1) NOT NULL DEFAULT 0,
  `incident_date` date DEFAULT NULL,
  `incident_time` time DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `reporter_name` varchar(150) DEFAULT NULL,
  `reporter_department` varchar(150) DEFAULT NULL,
  `assigned_to` int(11) DEFAULT NULL,
  `assigned_name` varchar(150) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=163 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

