/*Table structure for table `lc_incident_workflow` */

DROP TABLE IF EXISTS `lc_incident_workflow`;

CREATE TABLE `lc_incident_workflow` (
  `workflow_id` int(11) NOT NULL AUTO_INCREMENT,
  `id` int(11) NOT NULL,
  `incident_id` int(11) NOT NULL,
  `step` varchar(50) DEFAULT NULL,
  `step_status` varchar(50) DEFAULT 'in_progress',
  `started_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `completed_at` datetime DEFAULT NULL,
  `performed_by` int(11) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`workflow_id`),
  KEY `idx_incident_workflow_incident_id` (`incident_id`),
  KEY `idx_incident_workflow_step` (`step`),
  KEY `idx_incident_workflow_status` (`step_status`),
  CONSTRAINT `fk_incident_workflow_incident` FOREIGN KEY (`incident_id`) REFERENCES `lc_incident_report` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

