/*Table structure for table `lc_labor_law_references` */

DROP TABLE IF EXISTS `lc_labor_law_references`;

CREATE TABLE `lc_labor_law_references` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `reference_type` varchar(100) DEFAULT NULL,
  `reference_number` varchar(100) DEFAULT NULL,
  `short_title` varchar(255) DEFAULT NULL,
  `category_id` int(11) DEFAULT NULL,
  `date_issued` date DEFAULT NULL,
  `effectivity_date` date DEFAULT NULL,
  `issuing_authority` varchar(255) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'active',
  `keywords` text DEFAULT NULL,
  `source_url` varchar(1000) DEFAULT NULL,
  `document_path` varchar(1000) DEFAULT NULL,
  `related_law` varchar(500) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `title` varchar(500) NOT NULL,
  `document_type` varchar(100) DEFAULT NULL,
  `issuing_body` varchar(500) DEFAULT NULL,
  `reference_no` varchar(255) DEFAULT NULL,
  `series_year` varchar(50) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `source_file` varchar(500) NOT NULL,
  `full_text` longtext NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `lc_labor_law_references` */

insert  into `lc_labor_law_references`(`id`,`reference_type`,`reference_number`,`short_title`,`category_id`,`date_issued`,`effectivity_date`,`issuing_authority`,`status`,`keywords`,`source_url`,`document_path`,`related_law`,`summary`,`remarks`,`created_by`,`updated_by`,`updated_at`,`title`,`document_type`,`issuing_body`,`reference_no`,`series_year`,`description`,`source_file`,`full_text`,`created_at`) values 
(2,'Presidential Decree','Presidential Decree No. 442, as amended','Labor Code of the Philippines',1,'1974-05-01','1974-11-01','President of the Philippines','Active','Labor Code, Presidential Decree No. 442, PD 442, labor law, employment, employer, employee, wages, working conditions, hours of work, rest periods, holiday pay, overtime pay, service incentive leave, minimum wage, wage protection, employment relationship, security of tenure, termination of employment, separation pay, retirement, labor standards, labor relations, unfair labor practices, collective bargaining, labor organizations, strikes, lockouts, grievance machinery, voluntary arbitration, National Labor Relations Commission, NLRC, Department of Labor and Employment, DOLE, recruitment, employment agencies, overseas employment, apprenticeship, labor inspection, occupational safety and health, workers benefits, social legislation','https://elibrary.judiciary.gov.ph/thebookshelf/showdocs/26/25306','modules/compliance/assets/law_reference/labor_code_of_the_philippines_pd_442_as_amended.pdf','Republic Act No. 6725; Republic Act No. 6715; Republic Act No. 7877; Republic Act No. 8042; Republic Act No. 8282; Republic Act No. 8558; Republic Act No. 9231; Republic Act No. 9481; Republic Act No. 10151; Republic Act No. 10361; Republic Act No. 10524; Republic Act No. 10911; Republic Act No. 11058; Republic Act No. 11165; Republic Act No. 11210; Republic Act No. 11223; Republic Act No. 11641; Republic Act No. 11701; Republic Act No. 11965; applicable DOLE Department Orders, Labor Advisories,','Presidential Decree No. 442, as amended, otherwise known as the Labor Code of the Philippines, is the principal codification of Philippine labor and employment laws. It establishes the legal framework governing employment relationships, labor standards, labor relations, worker protection, recruitment and placement, wages, working conditions, employment termination, labor organizations, collective bargaining, strikes and lockouts, labor dispute settlement, and related labor administration.\r\n\r\nThe Labor Code was promulgated on May 1, 1974 as Presidential Decree No. 442. Its stated purpose is to revise and consolidate labor and social laws, afford protection to labor, promote employment and human resources development, and ensure industrial peace based on social justice.\r\n\r\nThe Code contains a Preliminary Title and several Books covering major areas of Philippine labor law. These include pre-employment matters, human resources development, conditions of employment, health and safety standards, labor relations, post-employment provisions, and other statutory protections and mechanisms administered through the labor regulatory system.\r\n\r\nThe Code establishes fundamental labor policies including protection to labor, promotion of full employment, equal employment opportunities, regulation of employer-worker relations, workers’ rights to self-organization and collective bargaining, security of tenure, and just and humane conditions of work.\r\n\r\nIt also provides rules concerning recruitment and placement, employment of workers, apprentices and learners, wages and wage-related benefits, working hours, weekly rest periods, holiday pay, service incentive leave, overtime work, night shift work, employment of women and minors, termination of employment, retirement, labor organizations, collective bargaining agreements, unfair labor practices, strikes and lockouts, grievance procedures, voluntary arbitration, labor dispute settlement, and enforcement of labor standards.\r\n\r\nThe Labor Code is a foundational reference for employers, employees, human resource practitioners, labor relations practitioners, compliance officers, legal personnel, and government agencies in determining rights, duties, liabilities, procedures, and minimum standards applicable to employment relationships in the Philippines.','This is a foundational labor-law reference and should be treated as an umbrella legal reference in the HRMS Legal & Compliance module. Because Presidential Decree No. 442 has been amended by numerous subsequent statutes and issuances, the record should always be read together with the latest applicable Republic Acts, Presidential Decrees, Executive Orders, DOLE Department Orders, Labor Advisories, implementing rules and regulations, and relevant Supreme Court jurisprudence.\r\n\r\nThe database record should not be interpreted as replacing the current official text of the law. When a particular article has been amended, the latest applicable amendment should be consulted before using the provision for an HR compliance decision.\r\n\r\nFor document management purposes, the original PDF should be retained in the designated labor-law document repository and the extracted text should be stored in the full_text field where full-text searching is required.',1,1,'2026-08-13 17:23:31','Labor Code of the Philippines – Presidential Decree No. 442, as Amended','Presidential Decree / Labor Code','Republic of the Philippines','P.D. No. 442','1974','The Labor Code of the Philippines, instituted through Presidential Decree No. 442, is the principal statutory framework governing labor and employment relations in the Philippines. It revises and consolidates labor and social laws to provide protection to labor, promote employment and human resources development, and ensure industrial peace based on social justice. As amended, it covers pre-employment, employment standards, wages and benefits, working conditions, occupational safety and health, labor relations, collective bargaining, termination, retirement, labor dispute settlement, and other areas of employment regulation.','labor_code_of_the_philippines_pd_442_as_amended.pdf','PRESIDENTIAL DECREE NO. 442\r\n\r\nAS AMENDED\r\n\r\nA DECREE INSTITUTING A LABOR CODE THEREBY REVISING AND CONSOLIDATING LABOR AND SOCIAL LAWS TO AFFORD PROTECTION TO LABOR, PROMOTE EMPLOYMENT AND HUMAN RESOURCES DEVELOPMENT AND INSURE INDUSTRIAL PEACE BASED ON SOCIAL JUSTICE\r\n\r\nPRELIMINARY TITLE\r\n\r\nCHAPTER I\r\nGENERAL PROVISIONS\r\n\r\nARTICLE 1. NAME OF DECREE.\r\n\r\nThis Decree shall be known as the \"Labor Code of the Philippines.\"\r\n\r\nARTICLE 2. DATE OF EFFECTIVITY.\r\n\r\nThis Code shall take effect six (6) months after its promulgation.\r\n\r\nARTICLE 3. DECLARATION OF BASIC POLICY.\r\n\r\nThe State shall afford protection to labor, promote full employment, ensure equal work opportunities regardless of sex, race or creed and regulate the relations between workers and employers. The State shall assure the rights of workers to self-organization, collective bargaining, security of tenure, and just and humane conditions of work.\r\n\r\nARTICLE 4. CONSTRUCTION IN FAVOR OF LABOR.\r\n\r\nAll doubts in the implementation and interpretation of the provisions of this Code, including its implementing rules and regulations, shall be resolved in favor of labor.\r\n\r\nARTICLE 5. RULES AND REGULATIONS.\r\n\r\nThe Department of Labor and Employment and other government agencies charged with the administration and enforcement of this Code or any of its parts shall promulgate the necessary implementing rules and regulations.\r\n\r\nARTICLE 6. APPLICABILITY.\r\n\r\nAll rights and benefits granted to workers under this Code shall apply to all workers covered by the applicable provisions, subject to the limitations and exclusions expressly provided by law.\r\n\r\nBOOK ONE\r\nPRE-EMPLOYMENT\r\n\r\nThis Book establishes the legal framework governing employment opportunities, recruitment and placement, employment of workers, private employment agencies, overseas employment, and related pre-employment matters.\r\n\r\nBOOK TWO\r\nHUMAN RESOURCES DEVELOPMENT PROGRAM\r\n\r\nThis Book provides the legal framework for human resources development, apprenticeship, learnership, vocational training, and related employment-development programs.\r\n\r\nBOOK THREE\r\nCONDITIONS OF EMPLOYMENT\r\n\r\nThis Book establishes minimum labor standards concerning working conditions and employment benefits. It covers working hours, weekly rest periods, holidays, service incentive leave, wages, wage-related benefits, employment of women, employment of minors, household service, home workers, and related conditions of employment.\r\n\r\nBOOK FOUR\r\nHEALTH, SAFETY AND SOCIAL WELFARE BENEFITS\r\n\r\nThis Book addresses occupational health and safety, medical and health-related matters, employees’ compensation, rehabilitation, and related social welfare protections.\r\n\r\nBOOK FIVE\r\nLABOR RELATIONS\r\n\r\nThis Book governs labor organizations, workers’ rights to self-organization, collective bargaining, unfair labor practices, representation issues, collective bargaining agreements, strikes and lockouts, grievance machinery, voluntary arbitration, labor dispute settlement, and the powers and procedures of the labor relations system.\r\n\r\nBOOK SIX\r\nPOST-EMPLOYMENT\r\n\r\nThis Book contains provisions concerning termination of employment, security of tenure, separation and termination-related rights, retirement, and other post-employment matters.\r\n\r\nBOOK SEVEN\r\nTRANSITORY AND FINAL PROVISIONS\r\n\r\nThis Book contains transitional, final, and related provisions necessary for the implementation and administration of the Labor Code.\r\n\r\nThe Labor Code must be interpreted and applied together with subsequent laws and amendments. Numerous provisions of Presidential Decree No. 442 have been modified, supplemented, repealed, renumbered, or otherwise affected by later legislation and administrative issuances.\r\n\r\nFor HR compliance purposes, relevant provisions include, among others, rules concerning employment classification, wages, working hours, overtime, holiday pay, service incentive leave, night shift differential, employment of women and minors, termination, separation pay, retirement, labor organizations, collective bargaining, unfair labor practices, strikes and lockouts, labor standards inspection, and dispute settlement.\r\n\r\nThe official text of Presidential Decree No. 442 is available through the Supreme Court E-Library and the Department of Labor and Employment. The database copy should preserve the complete PDF and its corresponding extracted text for legal-reference and search purposes.','2026-08-13 15:23:05'),
(3,'Republic Act','Republic Act No. 6725','Anti-Discrimination Against Women in Employment',1,'1989-05-12','1989-05-12','Congress of the Philippines','Active','Republic Act No. 6725, RA 6725, women employment, discrimination against women, sex discrimination, gender discrimination, equal employment opportunity, equal pay, terms and conditions of employment, promotion, training, labor standards, Article 135, Labor Code, female workers, employment discrimination','https://elibrary.judiciary.gov.ph/thebookshelf/showdocs/2/3823','modules/compliance/assets/law_reference/ra_6725.pdf','Presidential Decree No. 442 (Labor Code of the Philippines), Article 135; Republic Act No. 9710 (Magna Carta of Women); Republic Act No. 7877 (Anti-Sexual Harassment Act of 1995); Republic Act No. 10911 (Anti-Age Discrimination in Employment Act)','Republic Act No. 6725 strengthens the prohibition against discrimination against women in employment by amending Article 135 of the Labor Code of the Philippines. It declares unlawful discrimination against any woman employee with respect to terms and conditions of employment solely on account of her sex. The law specifically addresses discrimination in payment of compensation, promotion, training opportunities, and other employment-related benefits or privileges. It also prohibits favoring a male employee over a female employee with respect to promotion, training opportunities, study and scholarship grants solely on account of sex.','Republic Act No. 6725 is a foundational Philippine labor law concerning gender equality and non-discrimination in employment. HR departments should consider its requirements when establishing compensation structures, promotion criteria, training programs, scholarship opportunities, hiring practices, and other employment policies. The law should be applied together with the current provisions of the Labor Code and subsequent laws concerning women’s rights and gender equality.',1,1,'2026-08-13 17:23:31','Republic Act No. 6725 – An Act Strengthening the Prohibition on Discrimination Against Women with Respect to Terms and Conditions of Employment, Amending for the Purpose Article 135 of the Labor Code, as Amended','Republic Act','Congress of the Philippines','R.A. No. 6725','1989','An Act strengthening the prohibition on discrimination against women with respect to terms and conditions of employment by amending Article 135 of the Labor Code of the Philippines, as amended. The law prohibits employment discrimination against women based solely on sex and establishes protections concerning compensation, promotion, training opportunities, study and scholarship grants, and other employment benefits and privileges.','ra_6725.pdf','REPUBLIC ACT NO. 6725\r\n\r\nAN ACT STRENGTHENING THE PROHIBITION ON DISCRIMINATION AGAINST WOMEN WITH RESPECT TO TERMS AND CONDITIONS OF EMPLOYMENT, AMENDING FOR THE PURPOSE ARTICLE ONE HUNDRED THIRTY-FIVE OF THE LABOR CODE, AS AMENDED\r\n\r\nSECTION 1. Article 135 of the Labor Code of the Philippines, as amended, is hereby further amended to read as follows:\r\n\r\n\"ART. 135. Discrimination prohibited. — It shall be unlawful for any employer to discriminate against any woman employee with respect to terms and conditions of employment solely on account of her sex.\r\n\r\nThe following are acts of discrimination:\r\n\r\n(a) Payment of a lesser compensation, including wage, salary or other form of remuneration and fringe benefits, to a female employee as against a male employee, for work of equal value; and\r\n\r\n(b) Favoring a male employee over a female employee with respect to promotion, training opportunities, study and scholarship grants solely on account of their sexes.\r\n\r\nCriminal liability for the willful commission of any unlawful act as provided in this Article or any violation of the rules and regulations issued pursuant to this Article shall be imposed upon the violator: Provided, That in the case of a corporation, trust, estate or partnership, the penalty shall be imposed upon the guilty officer or officers of such corporation, trust, estate or partnership.\r\n\r\nAny act of discrimination in violation of this Article shall be punishable in accordance with the applicable provisions of the Labor Code and its implementing rules and regulations.\"\r\n\r\nSECTION 2. Any provision of law, decree, executive order, rule or regulation inconsistent with the provisions of this Act is hereby repealed, modified or amended accordingly.\r\n\r\nSECTION 3. This Act shall take effect upon its approval.\r\n\r\nApproved: May 12, 1989.','2026-08-13 15:26:37'),
(4,'Republic Act','Republic Act No. 7877','Anti-Sexual Harassment Act of 1995',1,'1995-02-14','1995-03-22','Congress of the Philippines','Active','Republic Act No. 7877, RA 7877, Anti-Sexual Harassment Act of 1995, sexual harassment, workplace sexual harassment, employment sexual harassment, education sexual harassment, training environment, employer, employee, authority, influence, moral ascendancy, sexual favors, unwelcome sexual advances, demand for sexual favors, hostile work environment, complaint procedure, employer liability','https://elibrary.judiciary.gov.ph/thebookshelf/showdocs/2/4460','modules/compliance/assets/law_reference/ra_7877.pdf','Presidential Decree No. 442 (Labor Code of the Philippines), Article 135; Republic Act No. 11313 (Safe Spaces Act); Republic Act No. 9710 (Magna Carta of Women); Republic Act No. 11058 (Occupational Safety and Health Standards Law)','Republic Act No. 7877, otherwise known as the Anti-Sexual Harassment Act of 1995, declares sexual harassment unlawful in employment, education, and training environments. It establishes prohibited acts involving demands, requests, or requirements for sexual favors by persons with authority, influence, or moral ascendancy. In employment settings, the law addresses sexual harassment connected with hiring, continued employment, compensation, terms and conditions of employment, promotion, privileges, and the creation of an intimidating, hostile, or offensive work environment. It also establishes responsibilities for employers and heads of offices to prevent sexual harassment and provide procedures for investigation and resolution.','For HR compliance, organizations should maintain appropriate anti-sexual-harassment policies, procedures for receiving and investigating complaints, preventive measures, and a committee on decorum and investigation. RA 7877 should be read together with Republic Act No. 11313, or the Safe Spaces Act, which provides broader protections against gender-based sexual harassment in workplaces and other environments.',1,1,'2026-08-13 17:23:31','Republic Act No. 7877 – Anti-Sexual Harassment Act of 1995','Republic Act','Congress of the Philippines','R.A. No. 7877','1995','An Act Declaring Sexual Harassment Unlawful in the Employment, Education or Training Environment, and for Other Purposes. The law establishes sexual harassment as an unlawful act in employment, education, and training settings and provides responsibilities for employers, heads of offices, educational institutions, and training institutions in preventing and addressing sexual harassment.','ra_7877.pdf','REPUBLIC ACT NO. 7877\r\n\r\nAN ACT DECLARING SEXUAL HARASSMENT UNLAWFUL IN THE EMPLOYMENT, EDUCATION OR TRAINING ENVIRONMENT, AND FOR OTHER PURPOSES\r\n\r\nSECTION 1. TITLE\r\n\r\nThis Act shall be known as the \"Anti-Sexual Harassment Act of 1995.\"\r\n\r\nSECTION 2. DECLARATION OF POLICY\r\n\r\nThe State shall value the dignity of every individual, enhance the development of its human resources, guarantee full respect for human rights, and uphold the dignity of workers, employees, applicants for employment, students, trainees, and those undergoing training. For this purpose, all forms of sexual harassment in the employment, education or training environment are declared unlawful.\r\n\r\nSECTION 3. WORK, EDUCATION OR TRAINING-RELATED SEXUAL HARASSMENT\r\n\r\nSexual harassment is committed in a work-related or employment environment by an employer, employee, manager, supervisor, agent of the employer, or any other person who, having authority, influence or moral ascendancy over another in a work or training environment, demands, requests or otherwise requires any sexual favor from another, regardless of whether the demand, request or requirement is accepted by the object of said act.\r\n\r\nIt is committed when:\r\n\r\n(a) The sexual favor is made as a condition in the hiring or in the employment, re-employment or continued employment of the individual, or in granting the individual favorable compensation, terms, conditions, promotions, or privileges; or the refusal to grant the sexual favor results in limiting, segregating or classifying the employee which in any way would discriminate, deprive or diminish employment opportunities or otherwise adversely affect the employee;\r\n\r\n(b) The above acts would impair the employee rights or privileges under existing labor laws; or\r\n\r\n(c) The acts result in an intimidating, hostile, or offensive environment for the employee.\r\n\r\nAny person who directs or induces another to commit any act of sexual harassment as defined in the Act, or who cooperates in the commission thereof by another without which it would not have been committed, shall also be held liable under the Act.\r\n\r\nIn an education or training environment, sexual harassment is committed:\r\n\r\n(a) Against one who is under the care, custody or supervision of the offender;\r\n\r\n(b) Against one whose education, training, apprenticeship or internship is entrusted to the offender;\r\n\r\n(c) When the sexual favor is made a condition to the giving of a passing grade, or the granting of honors and scholarships, or the payment of a stipend, allowance or other benefits, privileges or considerations; or\r\n\r\n(d) When the sexual advances result in an intimidating, hostile or offensive environment for the student, trainee or apprentice.\r\n\r\nSECTION 4. DUTY OF THE EMPLOYER OR HEAD OF OFFICE\r\n\r\nIt shall be the duty of the employer or the head of the work-related, educational or training environment or institution to prevent or deter the commission of acts of sexual harassment and to provide the procedures for the resolution, settlement or prosecution of acts of sexual harassment.\r\n\r\nFor the workplace, the employer or head of office shall:\r\n\r\n(a) Promulgate appropriate rules and regulations in consultation with and jointly approved by the employees or students or trainees, through their duly designated representatives, prescribing the procedures for the investigation of sexual harassment cases and the administrative sanctions therefor.\r\n\r\nAdministrative sanctions shall not be a bar to prosecution in the proper courts for unlawful acts of sexual harassment.\r\n\r\nThe rules and regulations shall include guidelines on proper decorum in the workplace, educational or training institution.\r\n\r\n(b) Create a committee on decorum and investigation of cases on sexual harassment. The committee shall conduct meetings, as the case may be, with officers and employees, teachers, instructors, professors, coaches, trainers and students or trainees to increase understanding and prevent incidents of sexual harassment. It shall also conduct investigations of alleged cases constituting sexual harassment.\r\n\r\nThe committee shall be composed of at least one representative each from management, the employees from the supervisory rank, and the rank and file employees. In the case of educational or training institutions, the committee shall include representatives from the administration, faculty, students or trainees, as applicable.\r\n\r\nThe employer or head of office shall disseminate or post a copy of the Act for the information of all concerned.\r\n\r\nSECTION 5. LIABILITY OF THE EMPLOYER, HEAD OF OFFICE, EDUCATIONAL OR TRAINING INSTITUTION\r\n\r\nThe employer or head of office, educational or training institution shall be solidarily liable for damages arising from the acts of sexual harassment committed in the employment, education or training environment if the employer or head of office is informed of such acts by the offended party and no immediate action is taken thereon.\r\n\r\nSECTION 6. INDEPENDENT ACTION FOR DAMAGES\r\n\r\nNothing in this Act shall preclude the victim of work, education or training-related sexual harassment from instituting a separate and independent action for damages and other affirmative relief.\r\n\r\nSECTION 7. PENALTIES\r\n\r\nAny person who violates any provision of this Act shall, upon conviction, be penalized by imprisonment of not less than one month nor more than six months, or a fine of not less than Ten thousand pesos (P10,000) nor more than Twenty thousand pesos (P20,000), or both such fine and imprisonment at the discretion of the court.\r\n\r\nAny action arising from the violation of this Act shall prescribe in three (3) years.\r\n\r\nSECTION 8. SEPARABILITY CLAUSE\r\n\r\nIf any portion or provision of this Act shall be declared void or unconstitutional, the remaining portions or provisions hereof shall not be affected by such declaration.\r\n\r\nSECTION 9. REPEALING CLAUSE\r\n\r\nAll laws, decrees, orders, rules and regulations or parts thereof inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly.\r\n\r\nSECTION 10. EFFECTIVITY CLAUSE\r\n\r\nThis Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation.\r\n\r\nApproved: February 14, 1995.','2026-08-13 15:32:13'),
(5,'Republic Act','Republic Act No. 11313','Safe Spaces Act',1,'2019-04-17',NULL,'Congress of the Philippines','Active','Republic Act No. 11313, RA 11313, Safe Spaces Act, gender-based sexual harassment, sexual harassment, workplace harassment, gender-based harassment, online sexual harassment, streets and public spaces, workplace, educational institutions, training institutions, employer, employee, coworker, gender identity, gender expression, anti-sexual harassment, Committee on Decorum and Investigation, CODI, complaint mechanism, confidentiality, retaliation, DOLE, PCW','https://lawphil.net/statutes/repacts/ra2019/ra_11313_2019.html','modules/compliance/assets/law_reference/ra_11313_safe_spaces_act.pdf','Republic Act No. 7877 (Anti-Sexual Harassment Act of 1995); Republic Act No. 9710 (Magna Carta of Women); Presidential Decree No. 442 (Labor Code of the Philippines), as amended; Republic Act No. 11058 (Occupational Safety and Health Standards Law); Republic Act No. 10173 (Data Privacy Act of 2012); Republic Act No. 9208, as amended by Republic Act No. 10364','Republic Act No. 11313, otherwise known as the Safe Spaces Act, defines and penalizes gender-based sexual harassment in streets, public spaces, online environments, workplaces, and educational or training institutions. It establishes protections against unwanted sexual conduct and gender-based harassment and provides duties and responsibilities for employers, employees, educational institutions, local government units, law enforcement agencies, and other government bodies.\r\n\r\nFor workplace compliance, the law recognizes gender-based sexual harassment through unwelcome sexual advances, requests or demands for sexual favors, acts of a sexual nature, or other conduct based on sex that negatively affects employment conditions, job performance, opportunities, dignity, or creates an intimidating, hostile, or humiliating environment. It expressly recognizes that gender-based sexual harassment may occur between peers and may also be committed by a subordinate against a superior.\r\n\r\nThe law requires employers and persons of authority, influence, or moral ascendancy in the workplace to prevent, deter, and punish gender-based sexual harassment. Employers are required to disseminate the law, conduct preventive measures such as anti-sexual-harassment seminars, establish an independent internal mechanism or committee on decorum and investigation, protect complainants from retaliation, observe due process, maintain confidentiality to the greatest extent possible, and establish a workplace code of conduct or policy.\r\n\r\nThe law also provides duties for employees and coworkers, establishes employer liability for failure to comply with statutory duties or failure to act on reported violations, and requires routine inspections by the Department of Labor and Employment for private-sector workplaces and the Civil Service Commission for the public sector.','This law should be treated as a major workplace compliance reference in the HRMS Legal and Compliance module. HR personnel should use it when monitoring anti-sexual-harassment policies, workplace complaint procedures, employee awareness programs, Committee on Decorum and Investigation activities, compliance inspections, and employer responsibilities.\r\n\r\nRA 11313 should be read together with RA 7877 because the two laws address sexual harassment under different but related legal frameworks. RA 11313 expands protection to gender-based sexual harassment in workplaces and other environments and specifically establishes workplace duties and internal mechanisms.\r\n\r\nFor HRMS implementation, relevant compliance indicators may include existence of an anti-sexual-harassment policy, employee acknowledgment, workplace awareness training, designated complaint mechanism, committee membership, investigation records, confidentiality controls, anti-retaliation measures, and documented employer response to complaints.',1,1,'2026-08-13 18:48:50','Republic Act No. 11313 – Safe Spaces Act','Republic Act','Congress of the Philippines','R.A. No. 11313','2019','An Act Defining Gender-Based Sexual Harassment in Streets, Public Spaces, Online, Workplaces, and Educational or Training Institutions, Providing Protective Measures and Prescribing Penalties Therefor. The Safe Spaces Act establishes comprehensive protections against gender-based sexual harassment and imposes specific duties upon employers, employees, educational institutions, local government units, and relevant government agencies.','ra_11313_safe_spaces_act.pdf','REPUBLIC ACT NO. 11313\r\n\r\nAN ACT DEFINING GENDER-BASED SEXUAL HARASSMENT IN STREETS, PUBLIC SPACES, ONLINE, WORKPLACES, AND EDUCATIONAL OR TRAINING INSTITUTIONS, PROVIDING PROTECTIVE MEASURES AND PRESCRIBING PENALTIES THEREFOR\r\n\r\nSECTION 1. SHORT TITLE\r\n\r\nThis Act shall be known as the \"Safe Spaces Act\".\r\n\r\nSECTION 2. DECLARATION OF POLICIES\r\n\r\nIt is the policy of the State to value the dignity of every human person and guarantee full respect for human rights. It is likewise the policy of the State to recognize the role of women in nation-building and ensure the fundamental equality before the law of women and men.\r\n\r\nThe State recognizes that both men and women must have equality, security and safety not only in private, but also on the streets, public spaces, online, workplaces and educational and training institutions.\r\n\r\nSECTION 3. DEFINITION OF TERMS\r\n\r\nFor purposes of the Act, gender-based online sexual harassment includes online conduct targeted at a particular person that causes or is likely to cause mental, emotional or psychological distress or fear for personal safety. It may include unwanted sexual remarks and comments, threats, uploading or sharing photographs without consent, unauthorized recordings, cyberstalking and online identity theft.\r\n\r\nThe law also defines employee, employer, gender, gender identity and expression, public spaces, stalking, and related terms.\r\n\r\nARTICLE I\r\nGENDER-BASED STREETS AND PUBLIC SPACES SEXUAL HARASSMENT\r\n\r\nSECTION 4. GENDER-BASED STREETS AND PUBLIC SPACES SEXUAL HARASSMENT\r\n\r\nGender-based streets and public spaces sexual harassment includes unwanted and uninvited sexual actions or remarks against any person regardless of the motive. It includes catcalling, wolf-whistling, unwanted invitations, misogynistic, transphobic, homophobic and sexist slurs, persistent unwanted comments or gestures concerning appearance, relentless requests for personal details, sexual comments and suggestions, public masturbation, flashing of private parts, groping, stalking, and unwanted verbal or physical advances.\r\n\r\nSECTION 5. GENDER-BASED SEXUAL HARASSMENT IN PRIVATELY-OWNED PLACES OPEN TO THE PUBLIC\r\n\r\nRestaurants, bars, cinemas, malls, buildings and other privately-owned places open to the public shall adopt a zero-tolerance policy against gender-based streets and public spaces sexual harassment and provide assistance to victims.\r\n\r\nSECTION 6. GENDER-BASED SEXUAL HARASSMENT IN PUBLIC UTILITY VEHICLES\r\n\r\nThe law provides additional penalties and regulatory consequences for gender-based sexual harassment committed in public utility vehicles.\r\n\r\nSECTION 7. GENDER-BASED SEXUAL HARASSMENT IN STREETS AND PUBLIC SPACES COMMITTED BY MINORS\r\n\r\nWhere the offense is committed by a minor, appropriate measures shall be taken in accordance with applicable juvenile justice laws.\r\n\r\nSECTION 8. DUTIES OF LOCAL GOVERNMENT UNITS\r\n\r\nLocal government units shall have primary responsibility for enforcing the provisions concerning gender-based streets and public spaces sexual harassment.\r\n\r\nSECTION 9. ROLE OF THE DILG\r\n\r\nThe Department of the Interior and Local Government shall ensure implementation of the Act by monitoring local government compliance, conducting surveys and studies, and supporting capacity-building activities.\r\n\r\nSECTION 10. IMPLEMENTING BODIES\r\n\r\nThe Metro Manila Development Authority, local units of the Philippine National Police, and Women and Children Protection Desks have responsibilities in enforcing applicable provisions.\r\n\r\nARTICLE II\r\nGENDER-BASED ONLINE SEXUAL HARASSMENT\r\n\r\nSECTION 12. GENDER-BASED ONLINE SEXUAL HARASSMENT\r\n\r\nGender-based online sexual harassment includes acts using information and communications technology to terrorize or intimidate victims through physical, psychological, or emotional threats; unwanted sexual, misogynistic, transphobic, homophobic or sexist remarks; invasion of privacy through cyberstalking and incessant messaging; uploading or sharing media without consent; unauthorized recording and sharing of photographs or videos; impersonation; and other prohibited online conduct.\r\n\r\nSECTION 13. IMPLEMENTING BODIES FOR ONLINE SEXUAL HARASSMENT\r\n\r\nThe Philippine National Police Anti-Cybercrime Group is primarily responsible for receiving complaints involving gender-based online sexual harassment, with other government bodies coordinating in implementation.\r\n\r\nARTICLE IV\r\nGENDER-BASED SEXUAL HARASSMENT IN THE WORKPLACE\r\n\r\nSECTION 16. GENDER-BASED SEXUAL HARASSMENT IN THE WORKPLACE\r\n\r\nGender-based sexual harassment in the workplace includes an act or series of acts involving unwelcome sexual advances, requests or demands for sexual favors, or acts of a sexual nature, whether verbal, physical, or committed through technology, that have or could have a detrimental effect on employment conditions, job performance, or opportunities.\r\n\r\nIt also includes conduct of a sexual nature or conduct based on sex affecting the dignity of a person that is unwelcome, unreasonable and offensive to the recipient.\r\n\r\nThe law also covers unwelcome and pervasive conduct that creates an intimidating, hostile or humiliating environment.\r\n\r\nGender-based sexual harassment may be committed between peers and may also be committed by a subordinate against a superior.\r\n\r\nSECTION 17. DUTIES OF EMPLOYERS\r\n\r\nEmployers or other persons of authority, influence or moral ascendancy in a workplace have the duty to prevent, deter or punish gender-based sexual harassment.\r\n\r\nEmployers shall:\r\n\r\n(a) Disseminate or post in a conspicuous place a copy of the Act to all persons in the workplace;\r\n\r\n(b) Provide measures to prevent gender-based sexual harassment in the workplace, including anti-sexual-harassment seminars;\r\n\r\n(c) Create an independent internal mechanism or committee on decorum and investigation to investigate and address complaints of gender-based sexual harassment;\r\n\r\n(d) Ensure that the internal mechanism adequately represents management, supervisory employees, rank-and-file employees, and the union, if any;\r\n\r\n(e) Designate a woman as head of the internal mechanism and ensure that not less than half of its members are women;\r\n\r\n(f) Ensure that members are impartial and not connected or related to the alleged perpetrator;\r\n\r\n(g) Investigate and decide complaints within ten (10) days or less upon receipt;\r\n\r\n(h) Observe due process;\r\n\r\n(i) Protect complainants from retaliation;\r\n\r\n(j) Guarantee confidentiality to the greatest extent possible; and\r\n\r\n(k) Provide and disseminate a workplace code of conduct or policy that expressly prohibits gender-based sexual harassment, describes complaint procedures, and establishes administrative penalties.\r\n\r\nSECTION 18. DUTIES OF EMPLOYEES AND CO-WORKERS\r\n\r\nEmployees and coworkers shall refrain from committing acts of gender-based sexual harassment, discourage such conduct in the workplace, provide emotional or social support to victims, and report acts of gender-based sexual harassment witnessed in the workplace.\r\n\r\nSECTION 19. LIABILITY OF EMPLOYERS\r\n\r\nEmployers may be held responsible for failure to implement their duties under Section 17 or failure to take action on reported acts of gender-based sexual harassment committed in the workplace.\r\n\r\nSECTION 20. ROUTINE INSPECTION\r\n\r\nThe Department of Labor and Employment for the private sector and the Civil Service Commission for the public sector shall conduct yearly spontaneous inspections to ensure compliance with applicable obligations under the Act.\r\n\r\nARTICLE V\r\nGENDER-BASED SEXUAL HARASSMENT IN EDUCATIONAL AND TRAINING INSTITUTIONS\r\n\r\nSECTION 21. GENDER-BASED SEXUAL HARASSMENT IN EDUCATIONAL AND TRAINING INSTITUTIONS\r\n\r\nSchools shall designate an officer-in-charge to receive complaints and shall provide a gender-sensitive environment for victims. Schools shall adopt and publish grievance procedures for filing complaints.\r\n\r\nSchools that know or reasonably should know about acts of gender-based sexual harassment or sexual violence shall take appropriate action to investigate and address the situation.\r\n\r\nSECTION 22. DUTIES OF SCHOOL HEADS\r\n\r\nSchool heads shall disseminate the Act, provide preventive measures, create an independent internal mechanism or Committee on Decorum and Investigation, observe due process, protect complainants from retaliation, maintain confidentiality, and establish appropriate school policies.\r\n\r\nSECTION 23. LIABILITY OF SCHOOL HEADS\r\n\r\nSchool heads, teachers, instructors, professors, coaches, trainers and other persons with authority may be held responsible for failure to implement their duties or failure to act on reported acts of gender-based sexual harassment.\r\n\r\nARTICLE VI\r\nCOMMON PROVISIONS\r\n\r\nSECTION 26. CONFIDENTIALITY\r\n\r\nAt any stage of investigation, prosecution and trial of offenses under the Act, applicable rights of victims and accused minors shall be recognized.\r\n\r\nSECTION 27. RESTRAINING ORDER\r\n\r\nWhere appropriate, courts may issue orders directing perpetrators to stay away from offended persons or specified locations.\r\n\r\nSECTION 28. REMEDIES AND PSYCHOLOGICAL COUNSELLING\r\n\r\nVictims may avail of appropriate remedies and psychological counselling services in accordance with applicable government programs.\r\n\r\nSECTION 29. ADMINISTRATIVE SANCTIONS\r\n\r\nThe penalties under the Act are without prejudice to applicable administrative sanctions.\r\n\r\nSECTION 30. IMPOSITION OF HEAVIER PENALTIES\r\n\r\nLocal government units may enact ordinances imposing heavier penalties for acts covered by the Act.\r\n\r\nSECTION 31. EXEMPTIONS\r\n\r\nLegitimate expressions of indigenous culture and tradition and breastfeeding in public are not penalized under the Act.\r\n\r\nARTICLE VII\r\nFINAL PROVISIONS\r\n\r\nSECTION 32. PNP WOMEN AND CHILDREN DESKS\r\n\r\nWomen and Children Desks in police stations shall act on complaints covered by the Act.\r\n\r\nSECTION 33. EDUCATIONAL MODULES AND AWARENESS CAMPAIGNS\r\n\r\nThe Philippine Commission on Women shall lead a national awareness campaign concerning the law. Schools shall educate students about gender-based sexual harassment and reporting mechanisms.\r\n\r\nSECTION 34. SAFETY AUDITS\r\n\r\nLocal government units are required to conduct safety audits every three (3) years to assess implementation of the Act within their jurisdictions.\r\n\r\nSECTION 36. PRESCRIPTIVE PERIOD\r\n\r\nThe Act establishes different prescriptive periods depending on the offense, including specific periods for offenses involving streets and public spaces, online sexual harassment, and workplace or educational sexual harassment.\r\n\r\nSECTION 38. IMPLEMENTING RULES AND REGULATIONS\r\n\r\nThe Philippine Commission on Women, in coordination with relevant government agencies, shall formulate the implementing rules and regulations.\r\n\r\nSECTION 39. SEPARABILITY CLAUSE\r\n\r\nIf any provision or part of the Act is held invalid or unconstitutional, the remaining provisions shall remain valid.\r\n\r\nSECTION 40. REPEALING CLAUSE\r\n\r\nLaws, decrees, orders, rules and regulations inconsistent with the Act are repealed, modified or amended according\r\nSECTION 41. EFFECTIVITY\r\n\r\nThe Act shall take effect fifteen (15) days after its publication in the Official Gazette or in any two newspapers of general circulation in the Philippines.\r\n\r\nApproved: April 17, 2019.','2026-08-13 15:33:41'),
(6,'Republic Act','Republic Act No. 11058','Occupational Safety and Health Standards Law',1,'2018-08-17',NULL,'Congress of the Philippines','Active','Republic Act No. 11058, RA 11058, Occupational Safety and Health Standards Law, OSH Law, occupational safety and health, workplace safety, occupational health, safe workplace, health standards, safety officer, occupational health personnel, safety committee, personal protective equipment, PPE, workplace hazards, risk assessment, emergency preparedness, safety training, employee rights, right to refuse unsafe work, DOLE, labor inspection, safety program, occupational accidents, work-related injuries, work-related illness','https://lawphil.net/statutes/repacts/ra2018/ra_11058_2018.html','modules/compliance/assets/law_reference/DOLE Occupational Safety and Health Standards (OSHS).pdf','Presidential Decree No. 442 (Labor Code of the Philippines), as amended; Department Order No. 198, Series of 2018; Occupational Safety and Health Standards (OSHS); Republic Act No. 11058 Implementing Rules and Regulations; Republic Act No. 7160, where applicable; Republic Act No. 11223, where applicable','Republic Act No. 11058, otherwise known as the Occupational Safety and Health Standards Law, strengthens compliance with occupational safety and health standards in the workplace. It requires employers to provide workers with a safe and healthful working environment free from hazardous conditions that may cause death, illness, or physical or psychological harm.\r\n\r\nThe law requires covered employers to provide appropriate information, instruction, training, and personal protective equipment to workers. Employers must implement an occupational safety and health program appropriate to the workplace and its hazards and must establish appropriate safety and health committees, safety officers, occupational health personnel, and other required mechanisms depending on workplace classification and workforce size.\r\n\r\nThe law also establishes important worker rights, including the right to know workplace hazards, the right to report accidents and dangerous occurrences, the right to refuse unsafe work under conditions established by law, and the right to receive appropriate occupational safety and health information and training.\r\n\r\nRA 11058 provides administrative and monetary penalties for violations of occupational safety and health standards and strengthens the authority of the Department of Labor and Employment to inspect workplaces and enforce OSH requirements.','This law is a major HR and Legal Compliance reference for workplace safety. The HRMS should be able to use this reference when monitoring OSH programs, safety training, safety officers, occupational health personnel, workplace inspections, incident and accident reports, PPE issuance, risk assessments, emergency preparedness, and compliance documentation.\r\n\r\nFor implementation purposes, RA 11058 should be read together with its implementing rules and regulations under Department Order No. 198, Series of 2018 and the applicable Occupational Safety and Health Standards.\r\n\r\nCompliance records should include the organization OSH program, workplace risk assessments, safety committee records, safety officer designation, occupational health personnel records, employee safety training, PPE records, accident and incident reports, inspection findings, corrective actions, and proof of compliance.\r\n\r\nThe law also contains provisions concerning worker rights, employer duties, reporting of accidents and dangerous occurrences, workplace inspection, penalties, and enforcement. Current implementing rules and subsequent DOLE issuances should be consulted when determining specific compliance requirements.',1,1,'2026-08-13 19:32:36','Republic Act No. 11058 – An Act Strengthening Compliance with Occupational Safety and Health Standards and Providing Penalties for Violations Thereof','Republic Act','Congress of the Philippines','R.A. No. 11058','2018','An Act Strengthening Compliance with Occupational Safety and Health Standards and Providing Penalties for Violations Thereof. The law requires employers to provide a safe and healthful workplace, establishes occupational safety and health requirements, protects workers from workplace hazards, provides for safety and health training and personal protective equipment, establishes safety and health personnel and committees, recognizes worker rights concerning workplace safety, and provides penalties for violations.','ra_11058_occupational_safety_health.pdf','REPUBLIC ACT NO. 11058\r\n\r\nAN ACT STRENGTHENING COMPLIANCE WITH OCCUPATIONAL SAFETY AND HEALTH STANDARDS AND PROVIDING PENALTIES FOR VIOLATIONS THEREOF\r\n\r\nSECTION 1. SHORT TITLE\r\n\r\nThis Act shall be known as the \"Occupational Safety and Health Standards Law.\"\r\n\r\nSECTION 2. DECLARATION OF POLICY\r\n\r\nIt is the policy of the State to ensure a safe and healthful workplace for all working people by affording full protection against all hazards in their working environment.\r\n\r\nThe State recognizes the right of workers to a safe and healthful workplace and shall promote a culture of occupational safety and health in all workplaces.\r\n\r\nSECTION 3. COVERAGE\r\n\r\nThe Act shall apply to all establishments, projects and workplaces, including their buildings and premises, where work is being undertaken in all branches of economic activity.\r\n\r\nThe applicable requirements may vary depending on the nature of work, workplace conditions, number of workers, and degree of hazard.\r\n\r\nSECTION 4. DUTIES OF EMPLOYERS\r\n\r\nEvery employer shall provide a workplace free from hazardous conditions that are causing or are likely to cause death, illness, or physical harm to workers.\r\n\r\nEmployers shall provide complete job safety instructions and information to workers, conduct orientation and training concerning occupational safety and health, and provide appropriate personal protective equipment where necessary.\r\n\r\nEmployers shall comply with applicable occupational safety and health standards and shall implement an occupational safety and health program appropriate to the workplace.\r\n\r\nEmployers shall ensure that workers are properly informed of workplace hazards and the measures necessary to prevent accidents, injuries and illnesses.\r\n\r\nSECTION 5. DUTIES OF WORKERS\r\n\r\nWorkers shall properly use and maintain safety devices and personal protective equipment provided by the employer.\r\n\r\nWorkers shall observe prescribed safety procedures and report unsafe conditions, hazards, accidents, and dangerous occurrences to the employer or appropriate workplace safety personnel.\r\n\r\nSECTION 6. WORKERS RIGHT TO KNOW\r\n\r\nWorkers shall be adequately informed of the hazards associated with their work, including the nature of the hazards, preventive measures, emergency procedures, and appropriate protective equipment.\r\n\r\nEmployers shall provide appropriate information, education, and training regarding occupational safety and health.\r\n\r\nSECTION 7. WORKERS RIGHT TO REFUSE UNSAFE WORK\r\n\r\nWorkers shall have the right to refuse to perform work without threat or reprisal where, as determined under applicable rules, there is an imminent danger that may result in illness, injury, or death and the employer has not corrected the dangerous condition.\r\n\r\nSECTION 8. WORKERS RIGHT TO REPORT ACCIDENTS\r\n\r\nWorkers and their representatives shall have the right to report accidents, dangerous occurrences, and hazards in the workplace without fear of retaliation.\r\n\r\nSECTION 9. SAFETY IN THE WORKPLACE\r\n\r\nEmployers shall implement measures necessary to eliminate or control hazards and shall provide appropriate protective equipment, safety devices, warning systems, emergency facilities, and other measures required by occupational safety and health standards.\r\n\r\nSECTION 10. SAFETY OFFICER\r\n\r\nCovered workplaces shall designate a safety officer who shall oversee the management of the occupational safety and health program and perform duties required under applicable occupational safety and health standards.\r\n\r\nThe qualifications, training, duties, and number of safety officers shall depend on the applicable workplace classification and requirements.\r\n\r\nSECTION 11. OCCUPATIONAL HEALTH PERSONNEL\r\n\r\nEmployers shall provide appropriate occupational health personnel and facilities depending on the nature of the workplace, number of workers, degree of hazard, and requirements of the applicable occupational safety and health standards.\r\n\r\nSECTION 12. SAFETY AND HEALTH COMMITTEE\r\n\r\nCovered workplaces shall establish a safety and health committee as required by applicable occupational safety and health standards.\r\n\r\nThe committee shall assist in planning, implementing, monitoring, and evaluating the workplace occupational safety and health program.\r\n\r\nSECTION 13. OCCUPATIONAL SAFETY AND HEALTH PROGRAM\r\n\r\nEmployers shall develop and implement an occupational safety and health program that is appropriate to the workplace and its hazards.\r\n\r\nThe program shall contain appropriate measures for hazard identification, risk assessment and control, accident prevention, emergency preparedness, worker training, occupational health, workplace inspections, and other applicable safety and health requirements.\r\n\r\nSECTION 14. SAFETY TRAINING\r\n\r\nWorkers shall receive appropriate occupational safety and health training based on their work, responsibilities, workplace hazards, and applicable occupational safety and health standards.\r\n\r\nSafety officers, occupational health personnel, members of safety and health committees, and other responsible personnel shall receive appropriate training as required by law and implementing rules.\r\n\r\nSECTION 15. PERSONAL PROTECTIVE EQUIPMENT\r\n\r\nEmployers shall provide workers with appropriate personal protective equipment when engineering and administrative controls are insufficient to eliminate or adequately control workplace hazards.\r\n\r\nPersonal protective equipment shall be appropriate to the nature of the hazard and work performed.\r\n\r\nWorkers shall be properly instructed in the correct use, maintenance, storage, and limitations of personal protective equipment.\r\n\r\nSECTION 16. REPORTING OF ACCIDENTS AND DANGEROUS OCCURRENCES\r\n\r\nEmployers shall report occupational accidents, dangerous occurrences, and work-related illnesses to the Department of Labor and Employment in accordance with applicable reporting requirements.\r\n\r\nWorkplace records concerning occupational accidents, illnesses, and dangerous occurrences shall be maintained as required by applicable occupational safety and health standards.\r\n\r\nSECTION 17. WORKPLACE INSPECTION\r\n\r\nThe Department of Labor and Employment shall have authority to conduct workplace inspections to determine compliance with occupational safety and health standards.\r\n\r\nAuthorized representatives may inspect workplaces, examine records, interview workers, investigate accidents and dangerous occurrences, and determine whether occupational safety and health requirements are being followed.\r\n\r\nSECTION 18. COMPLIANCE ORDERS\r\n\r\nWhere violations of occupational safety and health standards are found, appropriate compliance orders and corrective measures may be issued in accordance with applicable law and implementing rules.\r\n\r\nEmployers shall correct identified violations within the period prescribed by the Department of Labor and Employment.\r\n\r\nSECTION 19. PENALTIES\r\n\r\nEmployers and other responsible persons who violate occupational safety and health standards may be subject to administrative and monetary penalties in accordance with the Act and its implementing rules.\r\n\r\nPenalties may be imposed for violations involving occupational safety and health requirements, failure to provide required safety measures, failure to comply with inspection requirements, and other violations specified under the law.\r\n\r\nSECTION 20. ADMINISTRATIVE PENALTY\r\n\r\nThe Department of Labor and Employment may impose administrative fines for violations of occupational safety and health standards in accordance with applicable rules and regulations.\r\n\r\nSECTION 21. SPECIAL PENALTY\r\n\r\nHigher penalties may apply to violations that result in death, serious injury, or other circumstances specified by the Act and its implementing rules.\r\n\r\nSECTION 22. IMPLEMENTING RULES AND REGULATIONS\r\n\r\nThe Department of Labor and Employment shall issue the necessary implementing rules and regulations to effectively implement the provisions of the Act.\r\n\r\nThe implementing rules shall establish detailed requirements concerning workplace classification, safety officers, occupational health personnel, safety committees, training, reporting, inspection, risk assessment, personal protective equipment, and other occupational safety and health requirements.\r\n\r\nSECTION 23. CONSTRUCTION\r\n\r\nNothing in the Act shall be interpreted as diminishing or reducing existing rights and protections granted to workers under other labor and social legislation.\r\n\r\nSECTION 24. SEPARABILITY CLAUSE\r\n\r\nIf any provision of the Act is declared invalid or unconstitutional, the remaining provisions shall continue to be in full force and effect.\r\n\r\nSECTION 25. REPEALING CLAUSE\r\n\r\nAll laws, decrees, executive orders, rules and regulations or parts thereof inconsistent with the provisions of the Act are repealed, amended or modified accordingly.\r\n\r\nSECTION 26. EFFECTIVITY\r\n\r\nThe Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two newspapers of general circulation.\r\n\r\nApproved: August 17, 2018.','2026-08-13 15:35:40'),
(7,'Department Order','Department Order No. 252, Series of 2025','Revised Implementing Rules and Regulations of Republic Act No. 11058',1,'2025-04-28','2025-05-16','Department of Labor and Employment','Active','Department Order No. 252-25, DO 252-25, DO 252 Series of 2025, Occupational Safety and Health, OSH, OSHS, Republic Act No. 11058, Revised IRR, workplace safety, occupational health, safety officer, first aider, occupational health personnel, safety committee, OSH program, risk assessment, hazard identification, workplace inspection, personal protective equipment, PPE, emergency preparedness, accident reporting, work-related illness, safety training, DOLE inspection, labor standards inspection, compliance order, administrative penalties','https://ro6.dole.gov.ph/news/dole-rolls-out-revised-guidelines-of-osh-standards/','modules/compliance/assets/law_reference/Department Order No. 252, Series of 2025 – Revised Implementing Rules and Regulations of Republic Act No. 11058.pdf','Republic Act No. 11058; Department Order No. 198, Series of 2018; Occupational Safety and Health Standards; Presidential Decree No. 442, Labor Code of the Philippines, as amended; Department Order No. 253, Series of 2025; applicable DOLE Occupational Safety and Health issuances','Department Order No. 252, Series of 2025 prescribes the revised Implementing Rules and Regulations of Republic Act No. 11058, otherwise known as the Occupational Safety and Health Law. The Order strengthens and updates the regulatory framework for occupational safety and health compliance in workplaces and supersedes Department Order No. 198, Series of 2018.\r\n\r\nThe revised IRR provides updated rules on occupational safety and health programs, workplace hazard identification and risk assessment, safety officers, first aiders, occupational health personnel, safety and health committees, personal protective equipment, safety training, workplace inspections, reporting requirements, emergency preparedness, and enforcement.\r\n\r\nThe revised framework applies across establishments, projects, and workplaces and introduces clearer requirements based on workplace conditions, risk classification, workforce size, and the nature of operations.\r\n\r\nThe Order also strengthens enforcement and establishes administrative penalties for prohibited acts and violations of occupational safety and health requirements.','This Department Order should be treated as the current principal implementing reference for Republic Act No. 11058 in the HRMS Legal and Compliance module. It supersedes Department Order No. 198, Series of 2018, subject to transitional provisions and cases where a prior final and executory order remains governed by the previous rules.\r\n\r\nFor HR compliance monitoring, the system may track the organization OSH program, safety officer designation and certification, first aider requirements, occupational health personnel, safety and health committee, employee OSH training, risk assessments, workplace inspections, PPE, accident and illness reporting, annual medical reports, work accident and injury exposure data, OSH reports, emergency preparedness, and corrective actions.\r\n\r\nThe Order is particularly relevant to the Compliance, Risk Assessment, Incident Management, Employee Training, Audit and Reporting, and Occupational Safety and Health functions of the HRMS.',1,1,'2026-08-13 18:23:20','Department Order No. 252, Series of 2025 – Revised Implementing Rules and Regulations of Republic Act No. 11058','Department Order','Department of Labor and Employment (DOLE)','D.O. No. 252','2025','Department Order No. 252, Series of 2025 prescribes the Revised Implementing Rules and Regulations of Republic Act No. 11058, or the Occupational Safety and Health Law. It updates the rules governing workplace occupational safety and health compliance, including OSH programs, risk assessment, safety officers, first aiders, occupational health personnel, safety committees, training, personal protective equipment, reporting, inspections, enforcement, and administrative penalties. The Order supersedes Department Order No. 198, Series of 2018.','do_252_2025_revised_irr_ra_11058.pdf','DEPARTMENT OF LABOR AND EMPLOYMENT\r\n\r\nDEPARTMENT ORDER NO. 252\r\nSeries of 2025\r\n\r\nREVISED IMPLEMENTING RULES AND REGULATIONS OF REPUBLIC ACT NO. 11058\r\n\r\nAN ACT STRENGTHENING COMPLIANCE WITH OCCUPATIONAL SAFETY AND HEALTH STANDARDS AND PROVIDING PENALTIES FOR VIOLATIONS THEREOF\r\n\r\nPursuant to Section 32 of Republic Act No. 11058 and Article 5 of the Labor Code of the Philippines, the Department of Labor and Employment hereby issues the Revised Implementing Rules and Regulations to strengthen compliance with occupational safety and health standards and provide updated rules for their effective implementation.\r\n\r\nRULE I\r\nGENERAL PROVISIONS\r\n\r\nThe revised rules establish the requirements for occupational safety and health compliance in establishments, projects and workplaces. The rules apply to covered workplaces regardless of industry, subject to the specific requirements based on workplace classification, size, hazards and nature of operations.\r\n\r\nThe revised rules strengthen preventive occupational safety and health measures and establish a risk-based approach to compliance.\r\n\r\nRULE II\r\nOCCUPATIONAL SAFETY AND HEALTH PROGRAM\r\n\r\nCovered establishments shall develop and implement an appropriate Occupational Safety and Health Program.\r\n\r\nThe OSH Program shall identify workplace hazards and provide appropriate measures for hazard prevention and control.\r\n\r\nThe program shall include policies, procedures, responsibilities, training, emergency preparedness, accident prevention, reporting mechanisms, and other applicable occupational safety and health measures.\r\n\r\nEmployers shall make the OSH Program available to workers and ensure that it is implemented effectively.\r\n\r\nRULE III\r\nHAZARD IDENTIFICATION, RISK ASSESSMENT AND CONTROL\r\n\r\nEmployers shall identify workplace hazards and assess the risks associated with work activities.\r\n\r\nAppropriate control measures shall be implemented according to the hierarchy of controls and applicable occupational safety and health requirements.\r\n\r\nRisk assessments shall consider the nature of work, workplace conditions, equipment, materials, processes, environmental hazards, and other factors that may affect worker safety and health.\r\n\r\nRULE IV\r\nSAFETY OFFICERS\r\n\r\nCovered establishments shall designate qualified Safety Officers in accordance with the applicable workplace classification and requirements.\r\n\r\nSafety Officers shall assist management in implementing the OSH Program, conducting workplace inspections, monitoring compliance, investigating workplace incidents, coordinating safety activities, and performing other functions prescribed by the rules.\r\n\r\nThe required number and classification of Safety Officers shall depend on the applicable risk classification and workplace conditions.\r\n\r\nRULE V\r\nFIRST AIDERS\r\n\r\nCovered workplaces shall provide qualified first aiders in accordance with the applicable requirements.\r\n\r\nThe number and qualification requirements for first aiders shall depend on workplace classification, number of workers, risk level, and applicable occupational safety and health requirements.\r\n\r\nFirst aid facilities and supplies shall be made available and maintained in appropriate condition.\r\n\r\nRULE VI\r\nOCCUPATIONAL HEALTH PERSONNEL\r\n\r\nEmployers shall provide appropriate occupational health personnel and services based on the workplace classification, number of workers, nature of operations, and degree of occupational hazards.\r\n\r\nOccupational health personnel may include physicians, nurses, dentists, and other qualified personnel as required by applicable standards.\r\n\r\nRULE VII\r\nSAFETY AND HEALTH COMMITTEE\r\n\r\nCovered establishments shall establish an Occupational Safety and Health Committee as required by the rules.\r\n\r\nThe committee shall assist in planning, implementing, monitoring, and evaluating occupational safety and health programs and activities.\r\n\r\nThe committee shall facilitate consultation and participation of workers and management in workplace safety and health matters.\r\n\r\nRULE VIII\r\nPERSONAL PROTECTIVE EQUIPMENT\r\n\r\nEmployers shall provide appropriate personal protective equipment when workplace hazards cannot be sufficiently controlled through engineering or administrative controls.\r\n\r\nPPE shall be appropriate to the hazard and work activity.\r\n\r\nWorkers shall receive proper instruction and training regarding the selection, use, maintenance, storage and limitations of PPE.\r\n\r\nRULE IX\r\nSAFETY AND HEALTH TRAINING\r\n\r\nEmployers shall provide appropriate occupational safety and health training to workers.\r\n\r\nTraining shall address workplace hazards, safe work practices, emergency procedures, appropriate protective equipment, and other safety and health requirements relevant to the work.\r\n\r\nSafety Officers, first aiders, occupational health personnel, and members of safety and health committees shall receive training appropriate to their functions.\r\n\r\nRULE X\r\nWORKPLACE INSPECTION\r\n\r\nThe Department of Labor and Employment may conduct inspections and technical or advisory visits to determine compliance with occupational safety and health requirements.\r\n\r\nAuthorized inspectors may examine workplace conditions, records, documents, equipment, safety programs, training records, reports and other materials relevant to occupational safety and health compliance.\r\n\r\nEmployers shall provide access and cooperation during lawful inspections.\r\n\r\nRULE XI\r\nREPORTING REQUIREMENTS\r\n\r\nCovered establishments shall comply with applicable occupational safety and health reporting requirements.\r\n\r\nReports may include work-related accidents, injuries, illnesses, dangerous occurrences, annual medical reports, work accident and injury exposure data, OSH reports, and other reports required by DOLE.\r\n\r\nEmployers shall maintain appropriate records and submit required reports within the prescribed periods.\r\n\r\nRULE XII\r\nEMERGENCY PREPAREDNESS\r\n\r\nEmployers shall establish appropriate emergency preparedness and response measures based on workplace hazards.\r\n\r\nEmergency procedures shall address foreseeable emergencies and shall provide appropriate arrangements for evacuation, first aid, emergency communication, fire safety, and other response measures.\r\n\r\nWorkers shall be informed and trained regarding applicable emergency procedures.\r\n\r\nRULE XIII\r\nWORKER PARTICIPATION AND RIGHTS\r\n\r\nWorkers shall be informed of workplace hazards and the measures necessary to prevent occupational injuries and illnesses.\r\n\r\nWorkers shall have appropriate opportunities to participate in occupational safety and health programs and report unsafe conditions and hazards without unlawful retaliation.\r\n\r\nEmployers shall establish appropriate mechanisms for receiving and addressing safety concerns.\r\n\r\nRULE XIV\r\nEMPLOYER RESPONSIBILITIES\r\n\r\nEmployers shall provide a workplace that complies with applicable occupational safety and health standards.\r\n\r\nThey shall implement preventive measures, provide appropriate safety equipment and training, maintain required safety and health personnel, establish appropriate workplace programs and committees, and comply with reporting and inspection requirements.\r\n\r\nRULE XV\r\nDOCUMENTATION AND RECORD KEEPING\r\n\r\nEmployers shall maintain records necessary to demonstrate compliance with occupational safety and health requirements.\r\n\r\nRecords may include the OSH Program, risk assessments, safety inspection reports, safety training records, first aider records, Safety Officer records, medical reports, accident and injury records, PPE records, committee records, and other required documentation.\r\n\r\nRULE XVI\r\nENFORCEMENT\r\n\r\nThe Department of Labor and Employment shall enforce compliance with Republic Act No. 11058 and its implementing rules.\r\n\r\nInspection findings may result in notices, compliance orders, corrective actions, or other enforcement measures authorized under applicable law.\r\n\r\nRULE XVII\r\nPROHIBITED ACTS AND ADMINISTRATIVE PENALTIES\r\n\r\nThe revised rules identify prohibited acts and establish administrative penalties for violations of occupational safety and health requirements.\r\n\r\nViolations may include failure to provide required safety measures, failure to maintain required personnel or programs, failure to submit required reports, non-compliance with inspection requirements, and other acts or omissions specified under the rules.\r\n\r\nWillful violations may result in enhanced administrative consequences in accordance with the applicable provisions.\r\n\r\nRULE XVIII\r\nCOMPLIANCE AND CORRECTIVE ACTION\r\n\r\nEmployers shall correct identified occupational safety and health violations within the period prescribed by the Department of Labor and Employment.\r\n\r\nCorrective actions shall address the identified hazard or deficiency and shall be documented as appropriate.\r\n\r\nPersistent or willful non-compliance may result in additional enforcement action and penalties.\r\n\r\nRULE XIX\r\nTRANSITORY PROVISIONS\r\n\r\nThe revised implementing rules supersede Department Order No. 198, Series of 2018.\r\n\r\nFor cases where final and executory orders were issued before the effectivity of the revised rules, the applicable previous provisions may continue to govern in accordance with the transitional rules.\r\n\r\nRULE XX\r\nFINAL PROVISIONS\r\n\r\nThe revised rules shall be interpreted consistently with Republic Act No. 11058, the Labor Code of the Philippines, the Occupational Safety and Health Standards, and other applicable labor laws and regulations.\r\n\r\nDepartment Order No. 252, Series of 2025 was issued on April 28, 2025.\r\n\r\nThe Order was published on May 1, 2025.\r\n\r\nThe Order took effect on May 16, 2025.','2026-08-13 15:38:55'),
(8,'Department Order','Department Order No. 238, Series of 2023','Rules on the Administration and Enforcement of Labor Standards',1,'2023-04-12',NULL,'Department of Labor and Employment','Active','Department Order No. 238-23, DO 238-23, DO 238 Series of 2023, labor standards, labor inspection, labor laws compliance, administration and enforcement, Article 128, Labor Code, Republic Act No. 11058, occupational safety and health, OSH, Technical and Advisory Visit, TAV, labor inspector, assistant labor inspector, micro establishment, general labor standards, social legislation, workplace inspection, compliance assessment, action plan, corrective action, DOLE, labor standards compliance, occupational safety and health investigation','https://dole.gov.ph/news/department-order-no-238-23-rules-on-the-administration-and-enforcement-of-labor-standards-pursuant-to-article-128-of-the-labor-code-of-the-philippines-as-renumbered-and-republic-act-no-11058/','modules/compliance/assets/law_reference/Department Order No. 238-23.pdf','Presidential Decree No. 442, Labor Code of the Philippines, as renumbered; Article 128 of the Labor Code; Republic Act No. 11058, Occupational Safety and Health Standards Law; Department Order No. 183, Series of 2017; applicable General Labor Standards and Occupational Safety and Health Standards','Department Order No. 238, Series of 2023 establishes the rules governing the administration and enforcement of labor standards pursuant to Article 128 of the Labor Code of the Philippines, as renumbered, and Republic Act No. 11058. The Order aims to strengthen the visitorial and enforcement powers of the Department of Labor and Employment and secure higher levels of compliance with general labor standards, occupational safety and health standards, and other social legislation.\r\n\r\nThe Order provides the framework for Technical and Advisory Visits, Labor Inspection, and Occupational Safety and Health Investigation. It provides procedures for the assessment of establishments, identification of compliance gaps, issuance of appropriate findings and corrective measures, and enforcement of labor standards.\r\n\r\nThe rules also support DOLE efforts to improve compliance among micro establishments through technical and advisory assistance, labor education, assessment, action planning, and follow-up activities.','This Department Order is highly relevant to the HRMS Legal and Compliance module because it provides the regulatory basis for workplace labor standards compliance assessment and enforcement.\r\n\r\nThe system may use this reference for Labor Standards Audit, Compliance Assessment, Technical and Advisory Visit preparation, Labor Inspection monitoring, OSH Investigation, compliance gap tracking, corrective action plans, inspection findings, notices, supporting documents, and follow-up monitoring.\r\n\r\nFor micro establishments, the Technical and Advisory Visit process may involve labor education, assessment of General Labor Standards, Occupational Safety and Health Standards, and other social legislation, followed by an action plan when compliance gaps are identified.\r\n\r\nThe Order should be read together with current DOLE issuances and applicable labor standards because specific procedures and requirements may be updated by subsequent regulations.',1,1,'2026-08-13 18:31:55','Department Order No. 238-23 – Rules on the Administration and Enforcement of Labor Standards Pursuant to Article 128 of the Labor Code of the Philippines, as Renumbered, and Republic Act No. 11058','Department Order','Department of Labor and Employment (DOLE)','D.O. No. 238','2023','Rules on the Administration and Enforcement of Labor Standards Pursuant to Article 128 of the Labor Code of the Philippines, as Renumbered, and Republic Act No. 11058. The Order establishes rules for the exercise of DOLE visitorial and enforcement powers and provides mechanisms for securing compliance with General Labor Standards, Occupational Safety and Health Standards, and other social legislation.','do_238_2023_labor_standards_enforcement.pdf','DEPARTMENT OF LABOR AND EMPLOYMENT\r\n\r\nDEPARTMENT ORDER NO. 238\r\nSeries of 2023\r\n\r\nRULES ON THE ADMINISTRATION AND ENFORCEMENT OF LABOR STANDARDS PURSUANT TO ARTICLE 128 OF THE LABOR CODE OF THE PHILIPPINES, AS RENUMBERED, AND REPUBLIC ACT NO. 11058\r\n\r\nRULE I\r\nOBJECTIVE AND COVERAGE\r\n\r\nSECTION 1. OBJECTIVE\r\n\r\nThese Rules aim to further strengthen the exercise of the visitorial and enforcement power of the Secretary of Labor and Employment under the Labor Code of the Philippines, as renumbered.\r\n\r\nThe Rules seek to secure a higher level of compliance with General Labor Standards, Occupational Safety and Health Standards, and other social legislation and ensure continuity and sustainability of compliance in all workplaces.\r\n\r\nSECTION 2. COVERAGE AND APPLICABILITY\r\n\r\nThese Rules govern matters relating to the visitorial and enforcement power of the Secretary of Labor and Employment under Article 128 in relation to Article 303 of the Labor Code of the Philippines, as renumbered, and Republic Act No. 11058.\r\n\r\nThe Rules apply to covered establishments and workplaces subject to the labor standards and occupational safety and health requirements enforced by the Department of Labor and Employment.\r\n\r\nSECTION 3. CONSTRUCTION\r\n\r\nThese Rules shall be liberally construed to attain a just, inexpensive, and expeditious correction of noted violations of establishments and secure compliance with labor standards.\r\n\r\nSECTION 4. APPLICATION OF THE RULES OF COURT\r\n\r\nPertinent provisions of the Rules of Court may be applied in a suppletory manner whenever practicable and when there is no applicable provision under these Rules.\r\n\r\nRULE II\r\nDEFINITION OF TERMS\r\n\r\nSECTION 1. DEFINITION OF TERMS\r\n\r\nFor purposes of these Rules, terms relating to labor inspection and enforcement include Labor Inspector, Assistant Labor Inspector, Authority to Inspect, Technical and Advisory Visit, Labor Inspection, Occupational Safety and Health Investigation, compliance order, establishment, employer, worker, General Labor Standards, Occupational Safety and Health Standards, and other terms used in the administration and enforcement of labor standards.\r\n\r\nAn Assistant Labor Inspector refers to a Labor and Employment Officer designated by the Secretary of Labor and Employment or the Regional Director to conduct Technical and Advisory Visits.\r\n\r\nAn Authority to Inspect refers to written authority issued to authorized labor inspectors to conduct inspection activities.\r\n\r\nRULE III\r\nTECHNICAL AND ADVISORY VISIT\r\n\r\nSECTION 1. TECHNICAL AND ADVISORY VISIT\r\n\r\nTechnical and Advisory Visit is an approach used by DOLE to assist establishments in understanding and complying with labor standards, occupational safety and health standards, and other social legislation.\r\n\r\nThe TAV process is particularly applicable to micro establishments and is intended to promote education, awareness, assessment, and voluntary compliance.\r\n\r\nSECTION 2. OBJECTIVES OF TECHNICAL AND ADVISORY VISITS\r\n\r\nThe TAV process aims to:\r\n\r\n(a) Provide labor education;\r\n\r\n(b) Increase employer and worker awareness of labor standards;\r\n\r\n(c) Identify compliance gaps;\r\n\r\n(d) Provide technical assistance;\r\n\r\n(e) Assist establishments in preparing corrective action plans;\r\n\r\n(f) Promote sustainable compliance; and\r\n\r\n(g) Prevent future violations.\r\n\r\nSECTION 3. COVERAGE OF TECHNICAL AND ADVISORY VISITS\r\n\r\nTechnical and Advisory Visits may cover General Labor Standards, Occupational Safety and Health Standards, Child and Family Welfare Program requirements, productivity programs, and other applicable social legislation and DOLE programs.\r\n\r\nSECTION 4. ACTION PLAN\r\n\r\nWhere compliance gaps are identified during a Technical and Advisory Visit, the establishment may be assisted in preparing an appropriate action plan.\r\n\r\nThe action plan shall identify deficiencies, corrective measures, responsible persons, and target dates for completion.\r\n\r\nFollow-up activities may be conducted to determine whether identified compliance gaps have been corrected.\r\n\r\nRULE IV\r\nLABOR INSPECTION\r\n\r\nSECTION 1. LABOR INSPECTION\r\n\r\nLabor Inspection is an enforcement mechanism used by DOLE to determine compliance with labor standards and other applicable labor laws.\r\n\r\nAuthorized Labor Inspectors may examine workplace conditions, employment records, payroll records, policies, documents, facilities, and other evidence relevant to compliance.\r\n\r\nSECTION 2. AUTHORITY TO INSPECT\r\n\r\nLabor Inspectors shall conduct inspection activities pursuant to the authority issued by the appropriate DOLE official.\r\n\r\nEmployers and establishments covered by lawful inspection shall provide access and cooperation to authorized inspectors.\r\n\r\nSECTION 3. VISITORIAL AND ENFORCEMENT POWERS\r\n\r\nThe Secretary of Labor and Employment and authorized representatives may enter workplaces, inspect employment records and conditions, question workers and employers, examine documents, investigate violations, and undertake other activities authorized by Article 128 of the Labor Code and applicable laws.\r\n\r\nSECTION 4. GENERAL LABOR STANDARDS\r\n\r\nLabor inspections may cover compliance with General Labor Standards including wages, working hours, overtime, holiday pay, premium pay, service incentive leave, 13th month pay, statutory benefits, employment records, and other applicable labor standards.\r\n\r\nSECTION 5. OCCUPATIONAL SAFETY AND HEALTH STANDARDS\r\n\r\nLabor inspection may also include assessment of compliance with Occupational Safety and Health Standards and Republic Act No. 11058.\r\n\r\nAreas of assessment may include workplace hazards, OSH programs, safety officers, occupational health personnel, safety committees, personal protective equipment, safety training, emergency preparedness, accident reporting, and workplace safety measures.\r\n\r\nRULE V\r\nOCCUPATIONAL SAFETY AND HEALTH INVESTIGATION\r\n\r\nSECTION 1. OSH INVESTIGATION\r\n\r\nThe Department of Labor and Employment may conduct Occupational Safety and Health Investigations involving workplace accidents, dangerous occurrences, occupational illnesses, hazardous conditions, and other matters involving occupational safety and health.\r\n\r\nSECTION 2. PURPOSE OF INVESTIGATION\r\n\r\nThe investigation seeks to determine the circumstances surrounding an incident, identify violations and hazards, determine appropriate corrective measures, and prevent recurrence.\r\n\r\nSECTION 3. EMPLOYER COOPERATION\r\n\r\nEmployers shall provide access to relevant workplace areas, records, documents, equipment, and personnel necessary for lawful investigation.\r\n\r\nRULE VI\r\nCOMPLIANCE ASSESSMENT\r\n\r\nSECTION 1. ASSESSMENT OF COMPLIANCE\r\n\r\nDOLE shall assess whether an establishment complies with applicable General Labor Standards, Occupational Safety and Health Standards, and other social legislation.\r\n\r\nSECTION 2. COMPLIANCE GAPS\r\n\r\nWhere deficiencies are identified, the establishment may be required to undertake appropriate corrective measures.\r\n\r\nCompliance gaps may relate to wages, benefits, working conditions, workplace safety, employee records, OSH programs, training, statutory benefits, and other labor requirements.\r\n\r\nSECTION 3. CORRECTIVE ACTION\r\n\r\nCorrective measures shall address the deficiencies identified during assessment or inspection.\r\n\r\nEstablishments shall comply within the applicable period prescribed by DOLE.\r\n\r\nRULE VII\r\nENFORCEMENT AND DISPOSITION\r\n\r\nSECTION 1. FINDINGS\r\n\r\nInspection and investigation findings shall be documented through appropriate reports and technical documents.\r\n\r\nSECTION 2. COMPLIANCE ORDER\r\n\r\nWhere authorized by law and applicable rules, DOLE may issue appropriate compliance orders requiring an establishment to correct violations.\r\n\r\nSECTION 3. MANDATORY CONFERENCE\r\n\r\nLabor standards cases may undergo mandatory conferences to facilitate a fair, just, speedy, and inexpensive disposition of compliance issues.\r\n\r\nSECTION 4. CORRECTIVE MEASURES\r\n\r\nEmployers may be required to submit documents or evidence demonstrating correction of identified violations.\r\n\r\nRULE VIII\r\nRECORDS AND DOCUMENTATION\r\n\r\nEstablishments shall maintain employment records and other documents required under applicable labor standards and occupational safety and health laws.\r\n\r\nDocuments may include payroll records, employment contracts, time records, leave records, statutory contribution records, OSH documents, accident reports, safety training records, and other compliance records.\r\n\r\nRULE IX\r\nMICRO ESTABLISHMENTS\r\n\r\nMicro establishments may be provided with technical assistance and labor education through the Technical and Advisory Visit process.\r\n\r\nA micro establishment may be assessed based on applicable General Labor Standards, Occupational Safety and Health Standards, and other social legislation.\r\n\r\nWhere deficiencies are found, the establishment may be assisted in preparing an action plan and may receive follow-up technical assistance.\r\n\r\nRULE X\r\nWORKPLACE COMPLIANCE\r\n\r\nThe overall objective of the Rules is to promote continuous and sustainable compliance with labor standards and occupational safety and health requirements.\r\n\r\nEmployers are expected to establish systems and procedures that maintain compliance rather than merely correct violations after inspection.\r\n\r\nRULE XI\r\nFINAL PROVISIONS\r\n\r\nAll applicable labor laws, occupational safety and health standards, and other DOLE issuances shall continue to apply unless specifically modified or superseded.\r\n\r\nThe Rules shall be implemented by the Department of Labor and Employment through its appropriate offices and authorized personnel.\r\n\r\nDepartment Order No. 238, Series of 2023 was signed on April 12, 2023 and took effect after publication in accordance with applicable requirements.','2026-08-13 15:40:42'),
(9,'Republic Act','Republic Act No. 4670','Magna Carta for Public School Teachers',1,'1966-06-18',NULL,'Congress of the Philippines','Active','Republic Act No. 4670, RA 4670, Magna Carta for Public School Teachers, public school teachers, teachers, teaching personnel, public education, teacher rights, teacher welfare, employment conditions, working conditions, salaries, compensation, tenure, appointment, transfer, promotion, disciplinary action, administrative charges, leave, medical examination, teaching hours, additional compensation, retirement, academic freedom, professional development, public school','https://lawphil.net/statutes/repacts/ra1966/ra_4670_1966.html','modules/compliance/assets/law_reference/ra_4670_magna_carta_public_school_teachers.pdf','Presidential Decree No. 442, Labor Code of the Philippines, as amended; Republic Act No. 9155, Governance of Basic Education Act of 2001; Republic Act No. 10533, Enhanced Basic Education Act of 2013; Republic Act No. 7836, Philippine Teachers Professionalization Act of 1994; Republic Act No. 4670','Republic Act No. 4670, otherwise known as the Magna Carta for Public School Teachers, provides comprehensive protections and benefits for public school teachers. It establishes standards concerning recruitment, appointment, tenure, transfer, promotion, working hours, additional compensation, salaries, leave privileges, medical examinations, compensation for injuries, professional development, disciplinary procedures, and retirement.\r\n\r\nThe law recognizes the importance of teachers in nation-building and seeks to improve their social and economic status, living and working conditions, employment conditions, and career prospects. It establishes protections against arbitrary transfer, unfair disciplinary action, excessive teaching loads, and other employment practices that may adversely affect teachers.\r\n\r\nThe Act also provides provisions concerning teacher organizations, academic freedom, professional development, and participation in educational policy matters.','This law is primarily applicable to public school teachers and public educational institutions. For an HRMS used by a private educational institution, RA 4670 should be maintained as a legal reference but should not automatically be treated as directly applicable to all employees.\r\n\r\nThe system may use this reference when determining whether a compliance requirement specifically applies to public school teaching personnel. Related laws and regulations should be reviewed before applying any particular provision to private-sector employees or private educational institutions.\r\n\r\nFor HR compliance classification, this law may be tagged under Education, Public Sector Employment, Teacher Welfare, Employment Conditions, and Labor Standards.',1,1,'2026-08-13 17:23:31','Republic Act No. 4670 – Magna Carta for Public School Teachers','Republic Act','Congress of the Philippines','R.A. No. 4670','1966','An Act to Strengthen the Social and Economic Status of Public School Teachers and Improve Their Living and Working Conditions, Employment Terms and Career Prospects. The law establishes rights, benefits, employment protections, working conditions, compensation provisions, professional rights, and welfare measures for public school teachers.','ra_4670_magna_carta_public_school_teachers.pdf','REPUBLIC ACT NO. 4670\r\n\r\nTHE MAGNA CARTA FOR PUBLIC SCHOOL TEACHERS\r\n\r\nAN ACT TO STRENGTHEN THE SOCIAL AND ECONOMIC STATUS OF PUBLIC SCHOOL TEACHERS AND TO IMPROVE THEIR LIVING AND WORKING CONDITIONS, THEIR TERMS OF EMPLOYMENT AND CAREER PROSPECTS\r\n\r\nSECTION 1. DECLARATION OF POLICY\r\n\r\nIt is the policy of the State to promote and improve the social and economic status of public school teachers, their living and working conditions, terms of employment and career prospects.\r\n\r\nThe State recognizes that educational advancement depends upon the quality and welfare of teachers and therefore seeks to provide appropriate safeguards and benefits to teaching personnel.\r\n\r\nSECTION 2. TITLE\r\n\r\nThis Act shall be known as the \"Magna Carta for Public School Teachers.\"\r\n\r\nSECTION 3. DEFINITION OF TERMS\r\n\r\nThe term teacher shall refer to all persons engaged in classroom teaching in any level of instruction on a full-time basis, including guidance counselors, school librarians, industrial arts or vocational instructors, and persons performing supervisory or administrative functions in schools, colleges and universities operated by the Government or its political subdivisions.\r\n\r\nThe specific coverage of the Act shall be determined in accordance with the positions and functions covered by the law.\r\n\r\nSECTION 4. RECRUITMENT AND CAREER\r\n\r\nRecruitment policies shall be designed to ensure that qualified teachers are appointed based on appropriate qualifications and standards.\r\n\r\nCareer opportunities shall be made available to qualified teachers and advancement shall be based on merit and appropriate professional qualifications.\r\n\r\nSECTION 5. TENURE OF OFFICE\r\n\r\nTeachers shall be entitled to security of tenure in accordance with applicable laws.\r\n\r\nA teacher shall not be removed or dismissed except for cause and in accordance with due process and applicable legal procedures.\r\n\r\nSECTION 6. CONSENT FOR TRANSFER\r\n\r\nExcept for reasons authorized by law, no teacher shall be transferred without the teacher being informed of the reason for the transfer.\r\n\r\nWhere the transfer is made without the consent of the teacher, appropriate safeguards shall apply.\r\n\r\nSECTION 7. CODE OF PROFESSIONAL CONDUCT\r\n\r\nTeachers shall observe appropriate professional standards and conduct themselves in accordance with the responsibilities of their profession.\r\n\r\nSECTION 8. SAFEGUARDS IN DISCIPLINARY PROCEDURES\r\n\r\nEvery teacher shall be afforded due process in administrative proceedings.\r\n\r\nA teacher shall have the opportunity to examine the evidence, be represented by counsel or another representative as permitted by applicable rules, and defend against administrative charges.\r\n\r\nNo teacher shall be subjected to disciplinary action without appropriate procedural safeguards.\r\n\r\nSECTION 9. ADMINISTRATIVE CHARGES\r\n\r\nAdministrative charges against teachers shall be handled in accordance with applicable procedures.\r\n\r\nTeachers shall be informed of the charges against them and shall be given reasonable opportunity to answer and defend themselves.\r\n\r\nSECTION 10. RIGHT TO ORGANIZE\r\n\r\nPublic school teachers shall have the right to establish and join organizations of their choice for the furtherance and protection of their interests.\r\n\r\nTeachers shall not be prevented from joining lawful organizations.\r\n\r\nSECTION 11. DISCRIMINATION PROHIBITED\r\n\r\nTeachers shall not be discriminated against on the basis of political, religious, or other lawful considerations in the exercise of their professional rights.\r\n\r\nEmployment and career opportunities shall be administered in accordance with applicable laws and professional standards.\r\n\r\nSECTION 12. TEACHING HOURS\r\n\r\nThe normal teaching load of a teacher shall not exceed the limits established by law.\r\n\r\nWhere a teacher is required to render additional teaching services beyond the normal teaching load, appropriate compensation shall be provided in accordance with applicable rules.\r\n\r\nTeachers shall be provided appropriate time for preparation, correction of exercises, and other activities related to teaching.\r\n\r\nSECTION 13. ADDITIONAL COMPENSATION\r\n\r\nTeachers who are required to perform duties beyond their regular responsibilities or teaching load shall receive additional compensation when provided by law and applicable regulations.\r\n\r\nExtra-curricular and other assignments requiring additional services shall be compensated in accordance with applicable government rules.\r\n\r\nSECTION 14. SALARY\r\n\r\nTeacher salaries shall be determined in accordance with applicable government compensation laws and standards.\r\n\r\nSalary structures shall take into consideration qualifications, responsibilities, experience, and other factors established by law.\r\n\r\nSECTION 15. SALARY PROGRESSION\r\n\r\nTeachers shall have opportunities for salary advancement based on applicable qualification standards, experience, performance, and government compensation policies.\r\n\r\nSECTION 16. COST OF LIVING ALLOWANCE\r\n\r\nTeachers shall be entitled to applicable cost of living allowances and other benefits granted under law.\r\n\r\nSECTION 17. SALARY PAYMENT\r\n\r\nSalaries shall be paid regularly and within the periods prescribed by applicable government rules.\r\n\r\nSECTION 18. FREEDOM FROM UNAUTHORIZED DEDUCTIONS\r\n\r\nNo deductions shall be made from teacher salaries except those authorized by law or regulations or those made with the teacher consent as allowed by applicable rules.\r\n\r\nSECTION 19. MEDICAL EXAMINATION\r\n\r\nTeachers shall be provided appropriate medical examinations as required by law.\r\n\r\nWhere medical examination establishes that a teacher requires treatment or medical attention because of work-related circumstances, applicable government benefits and assistance shall be made available.\r\n\r\nSECTION 20. COMPENSATION FOR INJURIES\r\n\r\nTeachers shall be protected against work-related injuries and illnesses in accordance with applicable laws and government compensation programs.\r\n\r\nSECTION 21. STUDY LEAVE\r\n\r\nTeachers may be granted study leave under the conditions and limitations established by law.\r\n\r\nStudy leave is intended to support professional development and further education.\r\n\r\nSECTION 22. INDEFINITE LEAVE\r\n\r\nAppropriate leave privileges may be granted to teachers under circumstances provided by law and applicable regulations.\r\n\r\nSECTION 23. SPECIAL LEAVE\r\n\r\nTeachers may be granted special leave for authorized purposes under applicable government rules.\r\n\r\nSECTION 24. SALARY IN CASE OF ILLNESS\r\n\r\nWhere a teacher becomes ill and is unable to perform duties, applicable leave and salary benefits shall be provided in accordance with law.\r\n\r\nSECTION 25. TEACHER ORGANIZATIONS\r\n\r\nTeachers shall have the right to organize and participate in lawful teacher organizations.\r\n\r\nTeacher organizations may represent the interests and welfare of their members in accordance with applicable laws.\r\n\r\nSECTION 26. DISCRIMINATION AGAINST MEMBERS OF TEACHER ORGANIZATIONS\r\n\r\nNo person shall discriminate against a teacher because of lawful membership or participation in a teacher organization.\r\n\r\nSECTION 27. CONSULTATION\r\n\r\nTeachers shall be provided opportunities for consultation concerning educational policies and matters affecting their professional and working conditions.\r\n\r\nSECTION 28. ACADEMIC FREEDOM\r\n\r\nTeachers shall enjoy appropriate academic freedom in the performance of their professional responsibilities, subject to applicable laws, educational standards, and institutional policies.\r\n\r\nSECTION 29. PROFESSIONAL DEVELOPMENT\r\n\r\nThe government shall promote programs designed to improve the professional competence and development of teachers.\r\n\r\nTeachers shall be provided appropriate opportunities for training, seminars, scholarships, and other professional development activities.\r\n\r\nSECTION 30. RETIREMENT\r\n\r\nTeachers shall be entitled to retirement benefits under applicable government retirement laws and regulations.\r\n\r\nSECTION 31. IMPLEMENTATION\r\n\r\nThe appropriate government agencies shall issue rules and regulations necessary to implement the provisions of the Act.\r\n\r\nSECTION 32. APPROPRIATIONS\r\n\r\nFunds necessary to carry out the purposes of the Act shall be provided in accordance with applicable appropriations laws.\r\n\r\nSECTION 33. SEPARABILITY CLAUSE\r\n\r\nIf any provision of the Act is declared invalid, the remaining provisions shall continue to be effective.\r\n\r\nSECTION 34. REPEALING CLAUSE\r\n\r\nAll laws, decrees, orders, rules and regulations inconsistent with the provisions of this Act are repealed, amended or modified accordingly.\r\n\r\nSECTION 35. EFFECTIVITY\r\n\r\nThis Act shall take effect upon its approval.\r\n\r\nApproved: June 18, 1966.','2026-08-13 15:42:25'),
(10,'Regulatory Manual','Manual of Regulations for Private Schools','Manual of Regulations for Private Schools (MORP)',1,NULL,NULL,'Department of Education','Active','Manual of Regulations for Private Schools, MORP, private schools, private education, private higher education, school personnel, teaching personnel, non-teaching personnel, faculty, employment, school administration, educational institutions, school policies, academic personnel, personnel management, appointment, employment contracts, promotion, tenure, discipline, leave, compensation, benefits, student welfare, school governance, Department of Education, CHED, private educational institutions',NULL,'modules/compliance/assets/law_reference/manual_of_regulations_for_private_schools.pdf','Presidential Decree No. 442, Labor Code of the Philippines, as amended; Republic Act No. 6728, Government Assistance to Students and Teachers in Private Education Act; Republic Act No. 8545, Expanded Government Assistance to Students and Teachers in Private Education Act; Republic Act No. 9155, Governance of Basic Education Act of 2001; Republic Act No. 10533, Enhanced Basic Education Act of 2013; Republic Act No. 11058, Occupational Safety and Health Standards Law; applicable Department of Educ','The Manual of Regulations for Private Schools, commonly referred to as MORP, provides regulatory standards and requirements applicable to private educational institutions. It establishes rules concerning the operation, administration, governance, personnel, academic programs, student affairs, and other matters relating to private schools.\r\n\r\nFor human resources and personnel administration, the manual provides an important regulatory reference for the employment and administration of teaching and non-teaching personnel in private educational institutions. It may cover matters involving qualifications, appointment, employment conditions, personnel policies, faculty responsibilities, administrative procedures, and institutional compliance.\r\n\r\nThe MORP should be interpreted together with applicable Philippine labor laws, education laws, Department of Education issuances, Commission on Higher Education regulations, and other government regulations applicable to the particular type of private educational institution.','This reference is highly relevant to educational institutions and should be included in the HRMS Legal and Compliance library of a private college or school.\r\n\r\nBecause different editions of the Manual of Regulations for Private Schools may contain different provisions and may have been issued or revised at different times, the exact edition should be identified before applying a particular provision as a current compliance requirement.\r\n\r\nFor HRMS purposes, this reference may be connected to employee qualification monitoring, faculty records, personnel policies, employment documentation, disciplinary procedures, school compliance audits, employee documentation, and education-sector regulatory monitoring.\r\n\r\nThe MORP should not be treated as a substitute for the Labor Code, current DOLE regulations, CHED Memoranda, DepEd Orders, or other applicable laws and regulations. Applicability depends on the type and level of educational institution.',1,1,'2026-08-13 17:23:31','Manual of Regulations for Private Schools (MORP)','Regulatory Manual','Department of Education / Appropriate Education Regulatory Authority','MORP',NULL,'The Manual of Regulations for Private Schools is a regulatory reference governing private educational institutions and addressing institutional administration, academic programs, personnel, student affairs, and other requirements applicable to private schools. It serves as an important compliance reference for private educational institutions and their administrators.','manual_of_regulations_for_private_schools.pdf','MANUAL OF REGULATIONS FOR PRIVATE SCHOOLS\r\n\r\nThe Manual of Regulations for Private Schools provides regulatory requirements and standards governing the establishment, operation, administration, and management of private educational institutions.\r\n\r\nThe Manual contains provisions concerning institutional organization, school administration, academic programs, personnel administration, faculty and non-teaching personnel, student affairs, school records, institutional policies, and other requirements applicable to private educational institutions.\r\n\r\nPERSONNEL\r\n\r\nPrivate educational institutions shall maintain qualified personnel appropriate to their authorized programs and operations.\r\n\r\nTeaching personnel shall meet applicable educational, professional, and qualification requirements prescribed by law and the appropriate education regulatory authority.\r\n\r\nSchools shall maintain appropriate personnel records and documentation demonstrating compliance with applicable qualification and employment requirements.\r\n\r\nEMPLOYMENT AND PERSONNEL ADMINISTRATION\r\n\r\nPrivate schools shall establish appropriate policies governing the appointment, assignment, duties, responsibilities, evaluation, promotion, discipline, and separation of personnel, subject to applicable laws and regulations.\r\n\r\nEmployment practices shall comply with applicable labor legislation and other government requirements.\r\n\r\nPersonnel shall be informed of institutional rules and policies applicable to their employment and professional responsibilities.\r\n\r\nTEACHING PERSONNEL\r\n\r\nTeaching personnel shall possess the qualifications required for the subjects, programs, and positions to which they are assigned.\r\n\r\nSchools shall maintain records of faculty qualifications, professional credentials, teaching assignments, and other documents required by applicable regulations.\r\n\r\nFaculty members shall perform their professional responsibilities in accordance with institutional policies, applicable education regulations, and professional standards.\r\n\r\nNON-TEACHING PERSONNEL\r\n\r\nPrivate educational institutions may employ administrative, technical, maintenance, support, and other non-teaching personnel necessary for school operations.\r\n\r\nNon-teaching personnel shall be subject to applicable employment laws, institutional policies, and regulatory requirements.\r\n\r\nSCHOOL ADMINISTRATION\r\n\r\nPrivate schools shall maintain appropriate administrative structures and policies necessary for effective operation.\r\n\r\nSchool administrators shall ensure compliance with applicable education regulations, labor laws, health and safety requirements, and other government requirements.\r\n\r\nPERSONNEL RECORDS\r\n\r\nSchools shall maintain appropriate personnel records and documents required by applicable regulations.\r\n\r\nPersonnel records may include employment documents, qualification records, professional licenses, training records, performance records, assignments, leave records, and other employment-related documentation.\r\n\r\nPROFESSIONAL QUALIFICATIONS\r\n\r\nPrivate schools shall ensure that teaching and other regulated positions are occupied by individuals possessing the qualifications required by applicable laws and regulations.\r\n\r\nProfessional licenses and credentials shall be maintained and monitored where required.\r\n\r\nSCHOOL POLICIES\r\n\r\nPrivate educational institutions shall establish appropriate policies governing school operations, personnel administration, academic matters, student affairs, and institutional responsibilities.\r\n\r\nPolicies shall be consistent with applicable laws and regulations.\r\n\r\nDISCIPLINE AND ADMINISTRATIVE PROCEDURES\r\n\r\nPersonnel and students shall be subject to appropriate institutional rules and administrative procedures.\r\n\r\nDisciplinary measures shall observe applicable legal requirements and principles of due process.\r\n\r\nEMPLOYEE WELFARE\r\n\r\nPrivate schools shall comply with applicable labor laws concerning wages, working conditions, statutory benefits, occupational safety and health, leave privileges, and other employee rights.\r\n\r\nWhere education regulations and labor regulations overlap, the applicable requirements shall be observed according to the nature of the issue and the authority having jurisdiction.\r\n\r\nOCCUPATIONAL SAFETY AND HEALTH\r\n\r\nPrivate educational institutions shall comply with applicable occupational safety and health requirements.\r\n\r\nSchools shall maintain appropriate measures for workplace safety, emergency preparedness, hazard prevention, employee training, and occupational health.\r\n\r\nCOMPLIANCE AND INSPECTION\r\n\r\nPrivate educational institutions may be subject to inspection, monitoring, evaluation, and other compliance activities conducted by the appropriate government regulatory authorities.\r\n\r\nSchools shall maintain documentation demonstrating compliance with applicable education and employment requirements.\r\n\r\nRECORD KEEPING\r\n\r\nSchools shall maintain institutional and personnel records required by applicable regulations.\r\n\r\nRecords shall be maintained accurately and made available to authorized government authorities when legally required.\r\n\r\nREGULATORY COMPLIANCE\r\n\r\nThe requirements of the Manual shall be implemented together with applicable laws, regulations, and issuances governing private education.\r\n\r\nWhere a later law or regulation modifies or supersedes a provision of the Manual, the later applicable legal requirement shall be observed.\r\n\r\nThe Manual should therefore be reviewed together with current Department of Education issuances, Commission on Higher Education regulations, Department of Labor and Employment regulations, and other applicable government requirements.','2026-08-13 15:43:08'),
(11,'Department Order / Regulatory Manual','DECS Order No. 92, Series of 1992','Manual of Regulations for Private Schools – Faculty Employment',1,'1992-08-10',NULL,'Department of Education, Culture and Sports','Active','Manual of Regulations for Private Schools, MORP, 1992 Revised Manual, DECS Order No. 92 s. 1992, faculty employment, private school teachers, teaching personnel, academic personnel, faculty, employment, probationary employment, permanent status, regular status, security of tenure, faculty qualifications, employment contract, teaching load, compensation, remuneration, hours of work, leave, retirement, discipline, termination, dismissal, due process, private education, school personnel','https://www.deped.gov.ph/1992/08/10/do-92-s-1992-1992-revised-manual-of-regulations-of-private-schools-8th-edition-amended-by-do-88-s-2010-2010-revised-manual-of-regulations-for-private-schools-in-basic-education-do-35-s-1993-allowing-student-absences-in-excess-of-20-per-cent-in-individual-cases-in-private-schools/','modules/compliance/assets/law_reference/morp_faculty_employment.pdf','Presidential Decree No. 442, Labor Code of the Philippines, as amended; DECS Order No. 92, Series of 1992; DepEd Order No. 88, Series of 2010; Manual of Regulations for Private Schools; applicable CHED regulations; applicable DOLE regulations; Republic Act No. 6728; Republic Act No. 8545','The Manual of Regulations for Private Schools provides regulatory standards governing private educational institutions and contains provisions concerning the employment and administration of school personnel. Its faculty employment provisions address matters such as qualifications, employment status, probationary service, permanent or regular status, security of tenure, teaching assignments, working conditions, remuneration, discipline, termination, and other conditions of employment.\r\n\r\nFor private school faculty, the Manual is an important education-sector regulatory reference that operates together with applicable labor laws and regulations. The rules concerning employment status and security of tenure are particularly important in determining whether a faculty member has satisfied the applicable requirements for permanent employment.\r\n\r\nThe Manual provides minimum regulatory standards for private schools, while institutions may adopt higher standards when consistent with law and applicable regulations.','This record is intended specifically for faculty employment compliance monitoring. It should be linked to employee records for teaching personnel and may be used by HR to monitor faculty qualifications, employment classification, probationary service, regularization or permanent-status requirements, employment contracts, teaching assignments, evaluation records, and separation or termination documentation.\r\n\r\nThe 1992 Manual should not be applied in isolation. For current compliance, the institution should also check subsequent DepEd issuances, CHED regulations for higher education, DOLE regulations, the Labor Code, applicable collective bargaining agreements, and relevant Supreme Court jurisprudence.\r\n\r\nFor basic education, DepEd Order No. 88, Series of 2010 issued the 2010 Revised Manual of Regulations for Private Schools in Basic Education and provides that provisions concerning probation, security of employment, removal, termination, remuneration, hours of work, teaching load, benefits, and other employment conditions are subject to the Labor Code, its implementing rules, and applicable collective bargaining agreements.\r\n\r\nFor private higher education institutions, applicable CHED regulations and the Manual of Regulations for Private Higher Education should also be checked separately.',1,1,'2026-08-13 17:23:31','Manual of Regulations for Private Schools – Provisions on Faculty Employment','Regulatory Manual','Department of Education, Culture and Sports','DECS Order No. 92, s. 1992','1992','Faculty employment provisions under the Manual of Regulations for Private Schools establish regulatory standards concerning the employment, qualifications, probationary service, permanent status, security of tenure, working conditions, teaching assignments, compensation, discipline, and termination of private school teaching personnel.','morp_faculty_employment.pdf','MANUAL OF REGULATIONS FOR PRIVATE SCHOOLS\r\n\r\nEIGHTH EDITION – 1992\r\n\r\nDECS ORDER NO. 92, SERIES OF 1992\r\n\r\nFACULTY AND SCHOOL PERSONNEL EMPLOYMENT PROVISIONS\r\n\r\nThe Manual of Regulations for Private Schools establishes minimum standards and requirements applicable to private educational institutions.\r\n\r\nThe Manual applies to private educational institutions at the applicable levels of the educational system, subject to provisions that may be specifically applicable to particular types or levels of schools.\r\n\r\nFACULTY QUALIFICATIONS\r\n\r\nPrivate educational institutions shall employ qualified teaching personnel appropriate to the programs and subjects offered by the institution.\r\n\r\nFaculty members shall possess the qualifications required by applicable education regulations and institutional standards.\r\n\r\nSchools shall maintain appropriate records demonstrating the qualifications and professional credentials of their teaching personnel.\r\n\r\nEMPLOYMENT STATUS\r\n\r\nFaculty employment may be subject to probationary conditions before a faculty member acquires permanent or regular status, subject to the applicable requirements of the Manual, labor laws, and institutional regulations.\r\n\r\nThe classification and status of faculty personnel shall be determined according to the applicable legal and regulatory standards.\r\n\r\nPROBATIONARY EMPLOYMENT\r\n\r\nProbationary employment of faculty members shall be governed by the applicable standards established by the Department of Education and the applicable provisions of labor law.\r\n\r\nA probationary faculty member shall be informed of the standards and requirements applicable to the position.\r\n\r\nThe evaluation of probationary faculty shall be based on reasonable and relevant standards applicable to the teaching position and institutional requirements.\r\n\r\nPERMANENT OR REGULAR STATUS\r\n\r\nA qualified full-time faculty member may acquire permanent or regular status after satisfying the applicable requirements concerning length of service, satisfactory performance, qualifications, and other standards prescribed by the Manual and applicable regulations.\r\n\r\nThe Supreme Court has recognized the significance of the Manual in determining the permanent status of private-school faculty members.\r\n\r\nSECURITY OF TENURE\r\n\r\nFaculty members who have acquired permanent or regular employment status shall enjoy security of tenure in accordance with applicable labor laws and regulations.\r\n\r\nA permanent employee may not be dismissed except for a lawful cause and after compliance with applicable substantive and procedural due process requirements.\r\n\r\nEMPLOYMENT CONTRACTS\r\n\r\nPrivate educational institutions should maintain appropriate employment documentation for faculty members.\r\n\r\nEmployment contracts should specify applicable employment conditions, duties, compensation, teaching assignments, employment status, and other terms required by law and institutional policy.\r\n\r\nTEACHING LOAD\r\n\r\nFaculty members shall be assigned teaching loads consistent with applicable education regulations, institutional policies, employment contracts, and labor standards.\r\n\r\nTeaching assignments and additional duties shall be administered in accordance with applicable rules governing workload and compensation.\r\n\r\nWORKING CONDITIONS\r\n\r\nPrivate educational institutions shall provide working conditions consistent with applicable labor laws and education regulations.\r\n\r\nFaculty members shall be provided appropriate working arrangements, facilities, resources, and conditions necessary for the performance of their teaching responsibilities.\r\n\r\nCOMPENSATION AND REMUNERATION\r\n\r\nFaculty members shall receive compensation in accordance with their employment contracts, applicable institutional policies, labor standards, and other applicable regulations.\r\n\r\nCompensation practices shall comply with applicable minimum wage and labor standards requirements.\r\n\r\nAdditional teaching assignments or services shall be compensated when required by law, regulation, collective bargaining agreement, or applicable institutional policy.\r\n\r\nLEAVE AND BENEFITS\r\n\r\nFaculty members shall receive applicable leave privileges and statutory benefits provided under labor laws, regulations, employment contracts, and institutional policies.\r\n\r\nThe Manual does not eliminate statutory employee benefits provided by applicable labor and social legislation.\r\n\r\nPERFORMANCE EVALUATION\r\n\r\nSchools may evaluate faculty performance based on reasonable and relevant academic, professional, and institutional standards.\r\n\r\nPerformance evaluation may be considered in determining continuation of probationary employment, promotion, assignment, or other personnel actions, subject to applicable law.\r\n\r\nPROMOTION AND CAREER DEVELOPMENT\r\n\r\nPrivate educational institutions should provide appropriate opportunities for professional development and career advancement consistent with institutional policies and applicable education regulations.\r\n\r\nFaculty qualifications, professional development, academic credentials, teaching performance, and institutional service may be considered in personnel decisions.\r\n\r\nDISCIPLINE\r\n\r\nFaculty members may be subject to disciplinary procedures for violations of law, institutional policies, employment rules, professional standards, or other applicable requirements.\r\n\r\nDisciplinary procedures must observe applicable due process requirements.\r\n\r\nADMINISTRATIVE CHARGES\r\n\r\nFaculty members who are subject to administrative charges shall be informed of the allegations and shall be given an appropriate opportunity to respond in accordance with applicable law and institutional procedures.\r\n\r\nTERMINATION OF EMPLOYMENT\r\n\r\nTermination of faculty employment shall be governed by the applicable employment status, the Labor Code, education regulations, employment contract, institutional policies, and other applicable laws.\r\n\r\nProbationary faculty may be separated when the applicable probationary requirements are not satisfied, subject to applicable law and required procedures.\r\n\r\nPermanent or regular faculty may be terminated only for authorized or just causes recognized under applicable law and after observance of due process.\r\n\r\nSECURITY OF EMPLOYMENT\r\n\r\nThe employment security of faculty members shall be determined according to their employment status and applicable legal requirements.\r\n\r\nThe Manual should be read together with the Labor Code and its implementing rules when determining employment security, termination, and employee rights.\r\n\r\nLABOR CODE APPLICATION\r\n\r\nThe provisions of the Manual concerning probation, security of employment, removal of school personnel, termination, remuneration, compensation, working hours, teaching load, benefits, and other conditions of employment remain subject to applicable provisions of the Labor Code and its implementing rules.\r\n\r\nCOLLECTIVE BARGAINING AGREEMENTS\r\n\r\nWhere applicable, employment conditions may also be governed by a valid collective bargaining agreement.\r\n\r\nInstitutional employment policies and faculty contracts should be consistent with applicable collective bargaining agreements.\r\n\r\nDUE PROCESS\r\n\r\nAll employment decisions involving disciplinary action, removal, or termination shall comply with applicable due process requirements.\r\n\r\nThe institution should maintain documentation supporting personnel actions.\r\n\r\nPERSONNEL RECORDS\r\n\r\nSchools should maintain complete and accurate faculty personnel records.\r\n\r\nRecords may include employment contracts, appointment documents, qualification records, professional licenses, academic credentials, faculty evaluations, teaching loads, attendance records, training records, leave records, disciplinary records, and separation documents.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nFor HR compliance purposes, private schools should monitor faculty employment status and maintain documentation demonstrating compliance with applicable requirements.\r\n\r\nRecommended monitoring records include:\r\n\r\n1. Faculty employment classification;\r\n2. Date of appointment;\r\n3. Probationary period;\r\n4. Applicable regularization or permanent-status requirements;\r\n5. Faculty qualifications;\r\n6. Academic credentials;\r\n7. Professional licenses;\r\n8. Teaching load;\r\n9. Performance evaluations;\r\n10. Employment contract;\r\n11. Compensation records;\r\n12. Leave and statutory benefits;\r\n13. Training and professional development;\r\n14. Disciplinary records;\r\n15. Separation or termination records.\r\n\r\nRELATIONSHIP WITH OTHER LAWS\r\n\r\nThe Manual of Regulations for Private Schools should be read together with the Labor Code of the Philippines, applicable DOLE regulations, applicable DepEd regulations, applicable CHED regulations, relevant education laws, and controlling Supreme Court decisions.\r\n\r\nWhere a later law or regulation modifies or supersedes an earlier provision, the current applicable legal requirement shall be observed.\r\n\r\nThe 1992 Revised Manual of Regulations for Private Schools was issued through DECS Order No. 92, Series of 1992.','2026-08-13 15:44:00'),
(12,'Jurisprudence','Supreme Court Jurisprudence on Private-School Teacher Probationary Employment','Private-School Teacher Probationary Employment',1,NULL,NULL,'Supreme Court of the Philippines','Active','private school teacher, probationary employment, probationary period, academic personnel, faculty, teaching personnel, permanent status, regular status, security of tenure, three years, six semesters, nine trimesters, satisfactory service, full-time teacher, Manual of Regulations for Private Schools, MORP, Labor Code, Article 296, faculty employment, teacher regularization, private education','https://lawphil.net/judjuris/juri2014/apr2014/gr_196280_2014.html','modules/compliance/assets/law_reference/jurisprudence_private_school_teacher_probationary_employment.pdf','Presidential Decree No. 442, Labor Code of the Philippines, as amended; Article 296 of the Labor Code; 1992 Revised Manual of Regulations for Private Schools; applicable DepEd regulations; applicable CHED regulations','Philippine Supreme Court jurisprudence recognizes that the probationary employment of private-school academic personnel is governed by special rules under the applicable education regulations in addition to the general provisions of the Labor Code. The applicable rules distinguish private-school teachers from ordinary employees subject to the general probationary period.\r\n\r\nFor academic personnel, the applicable probationary period depends on the educational level and applicable regulatory framework. Under the 1992 Revised Manual of Regulations for Private Schools, the probationary period may be up to three consecutive years of satisfactory service for elementary and secondary academic personnel, six consecutive regular semesters for tertiary academic personnel, or nine consecutive trimesters for tertiary institutions operating under a trimester system.\r\n\r\nThe Supreme Court has emphasized that permanent or regular status depends upon compliance with applicable requirements, including full-time employment and satisfactory service.','This jurisprudence should be used as a legal reference when evaluating private-school faculty employment status, probationary service, regularization, permanent status, and security of tenure.\r\n\r\nThe HRMS should distinguish full-time and part-time faculty, basic education and tertiary education personnel, semester and trimester academic calendars, and probationary versus permanent employment.\r\n\r\nThe system should not automatically apply the ordinary six-month probationary rule to private-school academic personnel.\r\n\r\nFor higher education institutions, the applicable CHED regulations and current Manual of Regulations for Private Higher Education should also be reviewed.\r\n\r\nFor basic education institutions, current DepEd regulations should be reviewed.\r\n\r\nThe Labor Code and current DOLE regulations remain applicable to labor standards, employee rights, termination, and due process.',1,1,'2026-08-13 17:23:31','Jurisprudence on Private-School Teacher Probationary Employment and Permanent Status','Supreme Court Jurisprudence','Supreme Court of the Philippines','Private-School Teacher Probationary Employment',NULL,'Supreme Court decisions recognizing special rules governing probationary employment and permanent status of private-school academic personnel. The cases discuss full-time status, satisfactory service, applicable probationary periods, reasonable performance standards, and security of tenure.','jurisprudence_private_school_teacher_probationary_employment.pdf','PRIVATE-SCHOOL TEACHER PROBATIONARY EMPLOYMENT\r\n\r\nGENERAL PROBATIONARY EMPLOYMENT\r\n\r\nArticle 296 of the Labor Code, formerly Article 281, generally provides that probationary employment shall not exceed six months from the date the employee started working, subject to recognized exceptions.\r\n\r\nDuring probationary employment, an employee may be terminated for a just cause or for failure to qualify as a regular employee in accordance with reasonable standards made known by the employer at the time of engagement.\r\n\r\nSPECIAL RULE FOR PRIVATE-SCHOOL FACULTY\r\n\r\nThe Supreme Court has recognized that the general six-month probationary period does not exclusively govern academic personnel in private schools.\r\n\r\nPrivate-school academic personnel are subject to special rules under the applicable Manual of Regulations for Private Schools and education regulations.\r\n\r\nThe applicable probationary period depends on the educational level and the applicable regulatory framework.\r\n\r\n1992 REVISED MANUAL OF REGULATIONS FOR PRIVATE SCHOOLS\r\n\r\nUnder the 1992 Revised Manual of Regulations for Private Schools, the probationary period for academic personnel may extend up to three consecutive years of satisfactory service for elementary and secondary academic personnel.\r\n\r\nFor tertiary academic personnel, the applicable period may be six consecutive regular semesters of satisfactory service.\r\n\r\nFor tertiary institutions operating under a trimester system, the applicable period may be nine consecutive trimesters of satisfactory service.\r\n\r\nFULL-TIME STATUS\r\n\r\nFull-time status is an important consideration when determining whether a private-school teacher may acquire permanent or regular status under the applicable education regulations.\r\n\r\nThe HRMS should therefore maintain a clear distinction between full-time and part-time faculty.\r\n\r\nSATISFACTORY SERVICE\r\n\r\nThe requirement of satisfactory service means that the school must have reasonable standards for evaluating probationary faculty.\r\n\r\nThe standards should be relevant to the teaching position and should be made known to the teacher at the beginning of employment or as required by applicable law.\r\n\r\nSchools should maintain documentation showing the standards used and the results of faculty evaluations.\r\n\r\nPERMANENT OR REGULAR STATUS\r\n\r\nA full-time teacher who satisfactorily completes the applicable probationary period may acquire permanent or regular employment status in accordance with the applicable education regulations and labor laws.\r\n\r\nOnce permanent or regular status is acquired, the teacher is protected by security of tenure.\r\n\r\nSECURITY OF TENURE\r\n\r\nA permanent or regular faculty member may not be dismissed except for a lawful cause and after compliance with substantive and procedural due process requirements.\r\n\r\nPROBATIONARY FACULTY\r\n\r\nProbationary faculty members are also protected by law.\r\n\r\nA probationary teacher may be terminated for a lawful cause or for failure to satisfy reasonable standards applicable to regularization, provided those standards were properly communicated and the required procedures were followed.\r\n\r\nEMPLOYMENT CONTRACTS\r\n\r\nPrivate schools commonly issue employment contracts covering an academic year or academic period.\r\n\r\nThe existence of yearly contracts does not by itself determine whether a faculty member has permanent or regular status.\r\n\r\nThe employment status must be determined based on the applicable law, education regulations, contract, and actual circumstances of employment.\r\n\r\nTERTIARY FACULTY\r\n\r\nFor tertiary academic personnel, the applicable probationary period may be six consecutive regular semesters.\r\n\r\nWhere the institution operates under a trimester system, the applicable period may be nine consecutive trimesters.\r\n\r\nThe HRMS should therefore identify whether the institution uses a semester or trimester academic calendar when calculating probationary service.\r\n\r\nEARLY ACQUISITION OF PERMANENT STATUS\r\n\r\nThe maximum probationary period does not necessarily mean that permanent status can only be acquired at the end of the maximum period.\r\n\r\nWhere the applicable requirements have already been satisfied, permanent status may be acquired earlier depending on the facts and applicable regulations.\r\n\r\nFACULTY EVALUATION\r\n\r\nSchools should maintain appropriate faculty evaluation records during probationary employment.\r\n\r\nEvaluation criteria may include teaching performance, professional competence, classroom management, attendance, fulfillment of academic responsibilities, compliance with institutional policies, professional conduct, research, community service, and other legitimate requirements applicable to the position.\r\n\r\nThe standards must be reasonable and relevant.\r\n\r\nMINIMUM QUALIFICATIONS\r\n\r\nAcademic personnel should possess the qualifications required by applicable education regulations and institutional standards.\r\n\r\nHR should maintain records of academic credentials, professional licenses where applicable, training, experience, and other qualifications.\r\n\r\nPART-TIME FACULTY\r\n\r\nPart-time faculty should be separately classified from full-time faculty because the rules concerning permanent status may differ.\r\n\r\nThe HRMS should record the employee classification and employment status accurately.\r\n\r\nRELEVANT JURISPRUDENCE\r\n\r\nUNIVERSIDAD DE STA. ISABEL v. SAMBAJON\r\n\r\nG.R. Nos. 196280 and 196286, April 2, 2014.\r\n\r\nThe Supreme Court discussed the special probationary rules applicable to private-school teachers and recognized the distinction between ordinary employees and academic personnel.\r\n\r\nDE LA SALLE ARANETA UNIVERSITY, INC. v. MAGDURULANG\r\n\r\nG.R. No. 224319, November 20, 2017.\r\n\r\nThe Supreme Court discussed the applicable probationary periods for academic personnel and the requirements for acquiring permanent status.\r\n\r\nCOLEGIO DEL SANTISIMO ROSARIO v. ROJO\r\n\r\nG.R. No. 170388, September 23, 2013.\r\n\r\nThe Court discussed full-time employment, satisfactory service, and the importance of reasonable standards for evaluating probationary faculty.\r\n\r\nLIM v. LEGAZPI HOPE CHRISTIAN SCHOOL\r\n\r\nG.R. No. 172818, March 31, 2009.\r\n\r\nThe Court discussed the requirements for permanent status of private-school teachers, including full-time service and satisfactory performance.\r\n\r\nLACUESTA v. ATENEO DE MANILA UNIVERSITY\r\n\r\nG.R. No. 152777, December 15, 2005.\r\n\r\nThe Court discussed special rules governing probationary employment of private-school academic personnel and the applicable education regulations.\r\n\r\nUNIVERSITY OF STO. TOMAS v. NATIONAL LABOR RELATIONS COMMISSION\r\n\r\nThe Supreme Court discussed the requirements for permanent status of private-school teachers and the importance of full-time employment and satisfactory service.\r\n\r\nLABAJO v. ALEJANDRO\r\n\r\nG.R. No. 80383, September 26, 1988.\r\n\r\nThe Court discussed the probationary period applicable to private-school teachers and the possibility of acquiring permanent status before the maximum probationary period.\r\n\r\nESCUDERO v. OFFICE OF THE PRESIDENT\r\n\r\nG.R. No. 57822, April 26, 1989.\r\n\r\nThe Court discussed the acquisition of permanent status by private-school teachers and the evidence required to establish such status.\r\n\r\nHRMS COMPLIANCE APPLICATION\r\n\r\nThe HRMS should monitor the following information for probationary faculty:\r\n\r\nEmployee ID\r\nFaculty Name\r\nFaculty Position\r\nAcademic Level\r\nFull-Time or Part-Time Status\r\nInitial Appointment Date\r\nProbationary Start Date\r\nAcademic Calendar\r\nSemester or Trimester\r\nQualifying Semesters\r\nQualifying Trimesters\r\nYears of Satisfactory Service\r\nPerformance Evaluation\r\nMinimum Qualification Status\r\nEmployment Contract\r\nContract Renewal History\r\nRegularization Eligibility Date\r\nPermanent Status Date\r\nNon-Renewal Status\r\nTermination Status\r\nReason for Non-Renewal\r\nSupporting Documents\r\n\r\nThe system should calculate faculty probationary status based on the applicable education regulations and academic calendar rather than automatically applying the ordinary six-month Labor Code rule.\r\n\r\nLEGAL CAUTION\r\n\r\nThis jurisprudence is a legal reference and should not be used as an automatic determination of permanent status.\r\n\r\nThe applicable education regulations, Labor Code, employment contract, faculty manual, institutional policies, collective bargaining agreement where applicable, and current Supreme Court jurisprudence should be considered together.\r\n\r\nFor private higher education institutions, current CHED regulations should be reviewed.\r\n\r\nFor private basic education institutions, current DepEd regulations should be reviewed.\r\n\r\nFor labor standards, termination, and due process issues, current DOLE regulations should also be reviewed.','2026-08-13 15:46:05'),
(13,'Department Order','Department Order No. 258','Free Legal Assistance for Workers, Labor Attorneys\' Office and Labor Justice Clinics',NULL,'2026-06-08','2026-06-08','Department of Labor and Employment (DOLE)','active','free legal assistance, workers, Labor Attorneys\' Office, LAO, Chief Labor Attorney, Legal Representation Division, LRD, Labor Justice Clinics, Gig Economy Unit, platform workers, delivery riders, freelancers, remote workers, app-based service providers, independent contractors, legal counselling, conciliation, mediation, advisory services, referral services, NLRC, SEnA, voluntary arbitration, CLEP, labor rights orientation, alternative dispute resolution, digital access, regional assistance centers, hotline',NULL,'modules/compliance/assets/law_reference/DO-258-26-Institutionalizing-Free-Legal-Assistance-for-Workers-Constituting-the-Labor-Attorneys-Office-Organizing-the-Workers-Legal-Representation-Unit-Labor-Justice-Clinics-2.pdf','Article II, Section 18 of the 1987 Constitution; Revised Administrative Code of 1987; Administrative Order No. 110, Series of 1989; National Labor Relations Commission (NLRC); Single Entry Approach (SEnA); voluntary arbitration; Clinical Legal Education Program (CLEP)','Department Order No. 258, Series of 2026 institutionalizes a unified framework for free legal assistance, counselling, conciliation, mediation, advisory and referral services for indigent and qualified workers and the general public. It constitutes the Labor Attorneys\' Office (LAO) under the Office of the Secretary of Labor and Employment, which absorbs the Department\'s Public Assistance and Complaints Unit (PACU). The Order directs the organization of a Legal Representation Division, regional LRD Desks, Labor Justice Clinics in partnership with accredited educational institutions, a Gig Economy Unit, and digital, social-media, manual-hotline and regional access mechanisms for labor justice.','Official DOLE Department Order dated 8 June 2026. The extracted PDF contains three pages and twelve sections. The Order takes effect immediately upon issuance. Local document path is retained in source_file/document_path for the HRMS legal-law reference repository.',NULL,NULL,'2026-08-13 17:23:31','INSTITUTIONALIZING FREE LEGAL ASSISTANCE FOR WORKERS, CONSTITUTING THE LABOR ATTORNEYS\' OFFICE AND ORGANIZING THE WORKERS LEGAL REPRESENTATION UNIT AND LABOR JUSTICE CLINICS','Department Order','Department of Labor and Employment (DOLE)','Department Order No. 258','2026','This Department Order provides a unified institutional framework for free legal assistance and public assistance within DOLE. Section 1 states the objectives, including support for the constitutional mandate to protect workers\' rights and promote their welfare and the upgrading of the Department\'s PACU. Section 2 constitutes the Labor Attorneys\' Office as a special directorate under the Office of the Secretary; it absorbs PACU and assists indigent and qualified workers involved or potentially involved in NLRC proceedings, SEnA, voluntary arbitration and related quasi-judicial or administrative processes, while providing legal assistance, counselling, conciliation, mediation, advisory and referral services. Section 3 establishes the Chief Labor Attorney, designated by the Secretary from among DOLE Undersecretaries or Assistant Secretaries, to operationalize the mandate, identify qualified personnel and manage day-to-day operations. Section 4 requires a Legal Representation Division within 30 days from effectivity, composed of DOLE lawyers, volunteer lawyers and law students in an accredited Clinical Legal Education Program under lawyer supervision; it also provides for LRD Desks in all regional offices. Section 5 mandates Labor Justice Clinics with accredited law schools and educational institutions, including supervised free legal assistance, labor-rights orientation, documentation assistance and alternative dispute resolution, plus mobile clinics at DOLE job fairs and other official events. Section 6 creates a Gig Economy Unit for platform workers, delivery riders, freelancers, remote workers and app-based service providers. Section 7 provides for national 24/7 electronic, social-media and manual hotline services, volunteer paralegal support, online filing systems, regional assistance centers, mobile clinics and regional hotlines. Section 8 requires coordination with the NLRC, National Conciliation and Mediation Board, Supreme Court Unified Legal Aid System Office, Integrated Bar of the Philippines, Legal Education Board and other concerned agencies. Section 9 authorizes the CLA to call upon DOLE technical staff and explore bilateral or multilateral partnerships. Section 10 provides funding from existing and future appropriations subject to government accounting and auditing rules. Section 11 provides a repealing clause. Section 12 provides that the Order takes effect immediately upon issuance and remains in force unless revoked.','DO-258-26-Institutionalizing-Free-Legal-Assistance-for-Workers-Constituting-the-Labor-Attorneys-Office-Organizing-the-Workers-Legal-Representation-Unit-Labor-Justice-Clinics-2.pdf','       A                    Republic of the Philippines\r\n                    DEPARTTUENT OF LABOR AND EMPLOYTIiENT\r\n                                   lntramuros, Manila                     Y &€\r\n  DEPARTMENTORDERNO. :J\'? ]c\r\n                                                                                        Y,(PYAJ\r\n\r\n\r\n SUBJECT           INSTITUTIONALIZING FREE LEGAL ASSISTANCE FOR\r\n                   WORKERS, CONSTITUTING THE LABOR ATTORNEYS\'\r\n                   OFFICE AND ORGANIZING THE WORKERS LEGAL\r\n                    REPRESENTATION UNIT AND LABOR JUSTICE CLINICS\r\n\r\n\r\n OATE            : 8 JUNE 2026\r\n\r\n       WHEREAS, Article ll, Section 18 of the 1987 Constitution declares thst the State\r\naffirms labor as a primary socioeconomic force. lt shall protecrt the rights of workers and\r\npromole their welfare.\r\n\r\n      WHEREAS, the Departnent of Labor and Employment is the primary policy-\r\nmaking, programming, coordinating and administrative entity of the Executive Branch\r\nof the government in the field of labor and employment and assumes primary\r\nresponsibility for the protection and advancement of workers weltare.\r\n\r\n       WHEREAS, there is a need to consolidate and stroamline free legal assistance,\r\nconciliation support, workers\' education, and legal repre8enlation mechanisms of the\r\nDepartment und6r a unified framework to ensure that workers are aware of their rights\r\nand have full access to th€ Department\'s programs and servicee.\r\n\r\n      WHEREAS, the Department recognizes the emcrging conoBms of the gig\r\neconomy workers, platform-based labor, freelanc€rs, and appbasod sorvice providers\r\nand independent conlractoB requiring free legal assistance and acceesible legal and\r\nadministrative support.\r\n\r\n       WHEREAS, Administrative Order No. 110, series of I 989, mandates the\r\nconstitution of Public Assistance and Complaints Units (PACUs) in all govomment\r\ndeparlm€nts and specifying its principal function to receive and act on complainls and\r\nrequests for assistance from the general public.\r\n\r\n      NOW THEREFORE, pursuant to the authority vested in the Secr6tary of Labor\r\nand Employment by the Revised Administrative Code of \'1987 and relevant laws, rules\r\nand regulations, the following are hereby promulgat€d:\r\n\r\n       SECTION 1, Objectives. - This Order seeks to support the implementalion of\r\nthe constitutional mandate of the D€partm€nt of Labor and Employment to protect the\r\nrights of workers and promote their welfsre, provide public assistanca and support to\r\n\r\n\r\n                                                                                          (\r\n                                                                                Page 2 ot 3\r\n\r\n\r\nworkers and the general public, upgrading for this purpos€, the Dopartment\'s public\r\nAssistance and Complaints Unit (PACU), presently within thc Department,s Legal\r\nService.\r\n\r\n       SECTION 2, Oryanization of lhe Labor Attomeys\' Office. -A spocial directorate\r\nis hereby constituted under lhe Ofiice of tho Secretary of Labor and Employmenl,\r\nhereafter to be known as tha Labor Attorneys\' Ofrice (LAO) which shall ab3orb the\r\nOopartm€nl\'s PACU and its pros€nt functions and operations. The principal function of\r\nthe LAO is to a$ist indigent and qualified workers who arc or may bc invoMed in labor\r\nproceedings before the National Labor Relations Commission (NLRC), Singla Entry\r\nApproach (SEnA), voluntary arbitration proceedings, and related quasi-judicial or\r\nadministrative processes.\r\n\r\n       The LAO shall be under the direct supervision and control of the Secretary and\r\nserye as a unified mechanism for assistance and coordination for workers sooking free\r\nlegal assistance, counselling, conciliation, mediation, advisory and refenal services.\r\n\r\n        SECTION 3, Chief Labor Attorney. -fhe LAO shall be headed by the Chief Labor\r\nAttomey (CLA) to be designated by the Secretary of Labor and Employment from among\r\nthe Undersecretaries or Assistanl Secretaries of the Department. The main task of the\r\nCLA is to operationalize the LAO\'s mandate, identify qualified personnel to implement\r\nits activities, and manage the unit\'s day-to-day operations.\r\n\r\n       SECTION 4. Workers\'Legel Represenlation Division. - ln the implementation of\r\nits mandat6, the LAO shall organize a Legal Representation Division (LRD) within thirty\r\n(30) days from the effectivity of this Order, composed of DOLE lawyers, volunteer\r\nlawyers, and law students enrolled in an accrodited Clinical Legal Education Program\r\n(CLEP) of a recognized law school, und6r tho dkecl supervision of a lawyer, The LRD\r\nshall provide free legal assietance and counsolling lo workers who may be involv€d in\r\nlabor proccedings with th€ NLRC, SEnA, voluntary arbitration proceedlngs, and related\r\nquasi-judicial or administrative proc€ssos. LRD Desks shall also b€ organized in all\r\nregional offices, with lawyers assigned to regional ofiices d€putized as LaborAnom6ys.\r\n\r\n       SECTION 5, Labor Justice Clinics. - The LAO is mandated to organize Labor\r\nJustice Clinics in partnership with accredited law schools of stste universities and\r\ncollegos, private universities and oth6r educational institutions to provide supervis€d\r\nfree legal assistance, labor rights orientation, documentation assistance and alternative\r\ndispute resolution services. Mobile Labor Justice Clinics will also be organized in\r\nDeparlment ,job fairs and other ofiicial events.\r\n\r\n       SECTIOH 6, Gig Economy Unit. - A Gig Economy Unit is hereby constitulod\r\nunder the LAO to address concorns involving platform lvorkers, delivery riders,\r\nfreelancers, remole workers, and app-based service provideB. The Unit shall provide\r\nlegal counselling, mediation assislance, and workers\'rights orientation programs for the\r\naforem€ntioned workerE.\r\n\r\n      SECTION 7, Digital and Regional Acc€ss. - The LAO shall upgrade pres€nt\r\ncapabilities of the Departmont\'s PACU by o3tablishing and operating a nalional 24n\r\n                                                                                    Pag6 3 of 3\r\n\r\n\r\neleclronic social media and manual hotline to be manned by organic Department\r\npersonnel, support€d by volunteer para-legals, to provide real-time assistance, advisory\r\nsupport and quick-response action on any complaints and concems submitted by\r\nworkers and the general public. The LAO may also establish online flling systoms,\r\nregional assistance centers, mobile labor justice clinics and regional hotline gervices to\r\nimprove nationwide accessibility of labor iustice mechanisms.\r\n\r\n       SECTION 8. Coordination with Existing Agencies. - The LAO shall coordinato\r\nwith the NLRC, National Conciliation and Mediation Board, lhe Supreme Court\'s Uniliod\r\nLegal Aid System Ollice, the lntegrated Bar of the Philippines, the Legal Education\r\nBoard, and other concerned agencies for efiective implementietion.\r\n\r\n       SECTION 9. Authority to Call Upon Personnel, Parlnerships. - The LAO CLA is\r\nauthorized to call upon all technical staff of the DOLE, its bureaus, ofiices and attached\r\nagencies to assist in any function of the LAO. The CLA may lik6wis6 explore\r\npartnerships wilh bilaleral or multilaleral int6rnational organizations to supporl programs\r\nand activities impl€mented pursuant to this Order.\r\n\r\n        SECTION 10. Funding. -T he implementation of programs and activities purBuant\r\nto this Order shall be funded from existing appropriations of the Department, and from\r\nfuture appropriations approved for the same purpose, with full complianco lvith\r\ngovernment accounting and auditing rules and regulations.\r\n\r\n       SECTION 11. Repealing C/ause. - All preceding orders and intemal issuances\r\ninconsistent with this Order ar6 hereby superseded, amendad, or repealed accordingly.\r\n\r\n      SECTION 12. Etrectivity.      -  This Order shall take effect immediat€ly upon\r\nissuance and shall be in full force and eficct unless otherwise revoked.\r\n\r\n       For the information and guidance of all concemed.\r\n\r\n\r\n\r\n\r\n                                                       FRANCI       . TOLE        FA OL\r\n                                                                Secretary\r\n                                                         /. Orglmre f tra af mlqm*\r\n                                                         a-4,   ottor ot ti. t.onbry\r\n\r\n                                                        rllliltil[tffilllll[]t]ilil]ilt\r\n                                                                     \'tnal\'\r\n','2026-08-13 14:50:50'),
(14,'Republic Act','Republic Act No. 9504','Tax Exemptions and Minimum Wage Earners',1,'2008-05-24',NULL,'Congress of the Philippines','Active','Republic Act No. 9504, RA 9504, minimum wage earner, MWE, tax exemption, income tax exemption, withholding tax, compensation income, statutory minimum wage, holiday pay, overtime pay, hazard pay, night shift differential, 13th month pay, other benefits, National Internal Revenue Code, NIRC, BIR, Bureau of Internal Revenue, payroll, taxable income, tax compliance','https://lawphil.net/statutes/repacts/ra2008/ra_9504_2008.html','modules/compliance/assets/law_reference/ra_9504_tax_exemptions_minimum_wage_earners.pdf','National Internal Revenue Code of 1997, as amended; Republic Act No. 8424; Republic Act No. 9504; Republic Act No. 10963; applicable BIR regulations; applicable Revenue Memorandum Circulars; applicable regional Wage Orders','Republic Act No. 9504 provides tax relief to qualified minimum wage earners. The law exempts statutory minimum wage from income tax and provides tax treatment for certain additional compensation received by qualified minimum wage earners, including holiday pay, overtime pay, night shift differential, and hazard pay, subject to applicable legal requirements.\r\n\r\nThe law also amended provisions of the National Internal Revenue Code concerning the tax treatment of compensation and certain benefits.\r\n\r\nFor payroll compliance, RA 9504 is relevant because minimum wage earner classification affects the determination of taxable compensation and withholding tax.','RA 9504 should be used together with the current National Internal Revenue Code, subsequent tax legislation, current BIR regulations, and applicable regional Wage Orders.\r\n\r\nThe HRMS should not determine MWE status based only on monthly salary. The system should consider the statutory minimum wage applicable to the employee and the legal definition of a minimum wage earner.\r\n\r\nThe actual current tax computation must use the latest applicable BIR rules because subsequent legislation has amended several tax provisions originally affected by RA 9504.',1,1,'2026-08-13 17:23:31','Republic Act No. 9504 - Tax Exemptions for Minimum Wage Earners','Republic Act','Congress of the Philippines','R.A. No. 9504','2008','An Act Amending the National Internal Revenue Code of 1997, as Amended, to Provide Tax Relief to Minimum Wage Earners, Increasing the Exemption for Other Benefits, and for Other Purposes.','ra_9504_tax_exemptions_minimum_wage_earners.pdf','REPUBLIC ACT NO. 9504\r\n\r\nTAX RELIEF FOR MINIMUM WAGE EARNERS\r\n\r\nGENERAL PURPOSE\r\n\r\nRepublic Act No. 9504 was enacted to provide tax relief to minimum wage earners and to amend provisions of the National Internal Revenue Code of 1997, as amended.\r\n\r\nThe law provides income tax relief for qualified minimum wage earners and modifies the tax treatment of certain compensation and benefits.\r\n\r\nMINIMUM WAGE EARNER\r\n\r\nA minimum wage earner refers to a worker in the private sector who is paid the statutory minimum wage prescribed by the applicable Regional Tripartite Wages and Productivity Board.\r\n\r\nThe classification must be determined according to the statutory definition and applicable implementing regulations.\r\n\r\nThe applicable minimum wage depends upon the region, industry, establishment classification, and employee classification covered by the applicable Wage Order.\r\n\r\nSTATUTORY MINIMUM WAGE\r\n\r\nThe statutory minimum wage is the minimum wage prescribed by the applicable Wage Order.\r\n\r\nRegional minimum wage rates may differ.\r\n\r\nThe HRMS should therefore identify the applicable Wage Order before determining whether an employee qualifies for minimum wage earner treatment.\r\n\r\nINCOME TAX EXEMPTION\r\n\r\nQualified minimum wage earners are exempt from income tax on statutory minimum wage.\r\n\r\nThe exemption is intended to provide tax relief to workers who receive compensation at the statutory minimum wage level.\r\n\r\nADDITIONAL COMPENSATION\r\n\r\nCertain additional compensation received by qualified minimum wage earners may also be exempt from income tax when the requirements of the law are satisfied.\r\n\r\nThese forms of compensation include:\r\n\r\n1. Holiday pay;\r\n2. Overtime pay;\r\n3. Night shift differential;\r\n4. Hazard pay.\r\n\r\nThe exemption applies subject to the statutory requirements and applicable BIR regulations.\r\n\r\nHOLIDAY PAY\r\n\r\nHoliday pay received by a qualified minimum wage earner may qualify for tax exemption under the applicable provisions.\r\n\r\nPayroll systems should identify holiday pay separately from ordinary basic compensation.\r\n\r\nOVERTIME PAY\r\n\r\nOvertime pay received by a qualified minimum wage earner may qualify for tax exemption under the applicable provisions.\r\n\r\nThe payroll system should maintain a separate record of overtime compensation.\r\n\r\nNIGHT SHIFT DIFFERENTIAL\r\n\r\nNight shift differential received by a qualified minimum wage earner may qualify for tax exemption under the applicable provisions.\r\n\r\nThe system should separately record night shift differential for payroll and tax reporting.\r\n\r\nHAZARD PAY\r\n\r\nHazard pay received by a qualified minimum wage earner may qualify for tax exemption under the applicable provisions.\r\n\r\nThe payroll system should maintain separate records of hazard pay and its tax treatment.\r\n\r\n13TH MONTH PAY AND OTHER BENEFITS\r\n\r\nRA 9504 increased the exemption threshold applicable to 13th month pay and other benefits under the National Internal Revenue Code.\r\n\r\nThe tax treatment of 13th month pay and other benefits has subsequently been affected by later tax legislation.\r\n\r\nThe HRMS should therefore use the current tax threshold prescribed by the latest applicable BIR rules rather than relying exclusively on the historical amount contained in RA 9504.\r\n\r\nWITHHOLDING TAX\r\n\r\nEmployers are responsible for determining the taxable compensation of employees and withholding the appropriate amount of tax when required.\r\n\r\nQualified minimum wage earners should not be subjected to income tax withholding on compensation that is expressly exempt under applicable law.\r\n\r\nIf an employee receives compensation that is taxable under current tax rules, the taxable amount must be included in the withholding tax computation.\r\n\r\nTAXABLE COMPENSATION\r\n\r\nThe payroll system should distinguish between exempt and taxable compensation.\r\n\r\nExamples of compensation categories that should be separately monitored include:\r\n\r\n1. Basic salary;\r\n2. Statutory minimum wage;\r\n3. Holiday pay;\r\n4. Overtime pay;\r\n5. Night shift differential;\r\n6. Hazard pay;\r\n7. Allowances;\r\n8. 13th month pay;\r\n9. Other benefits;\r\n10. Other taxable compensation.\r\n\r\nMINIMUM WAGE CONNECTION\r\n\r\nRA 9504 does not establish the actual regional minimum wage.\r\n\r\nThe applicable minimum wage is determined through the wage-setting framework established under the Labor Code and Republic Act No. 6727.\r\n\r\nThe current regional Wage Order should therefore be used to determine the applicable statutory minimum wage.\r\n\r\nREGIONAL WAGE ORDERS\r\n\r\nRegional Tripartite Wages and Productivity Boards issue Wage Orders prescribing minimum wage rates within their respective jurisdictions.\r\n\r\nThe applicable rate may depend on:\r\n\r\n1. Region;\r\n2. Province or locality;\r\n3. Industry;\r\n4. Establishment classification;\r\n5. Employee classification;\r\n6. Wage Order;\r\n7. Effective date.\r\n\r\nThe HRMS should maintain the applicable Wage Order and effectivity date.\r\n\r\nMWE CLASSIFICATION\r\n\r\nThe HRMS should evaluate minimum wage earner status based on the applicable statutory definition.\r\n\r\nThe system should not simply use a fixed salary amount for all employees.\r\n\r\nBecause regional minimum wage rates may change, MWE classification should be reviewed whenever a new Wage Order becomes effective.\r\n\r\nPAYROLL IMPLEMENTATION\r\n\r\nThe payroll system should perform the following sequence:\r\n\r\n1. Identify employee work location;\r\n2. Identify applicable region;\r\n3. Identify applicable Wage Order;\r\n4. Determine statutory minimum wage;\r\n5. Determine employee wage;\r\n6. Determine MWE qualification;\r\n7. Separate exempt compensation;\r\n8. Identify taxable compensation;\r\n9. Apply current BIR withholding tax rules;\r\n10. Generate payroll records.\r\n\r\nEMPLOYEE RECORDS\r\n\r\nThe HRMS should maintain:\r\n\r\n1. Employee ID;\r\n2. Employee name;\r\n3. Work location;\r\n4. Region;\r\n5. Employee classification;\r\n6. Establishment classification;\r\n7. Applicable Wage Order;\r\n8. Wage Order effectivity date;\r\n9. Applicable minimum wage;\r\n10. Actual basic wage;\r\n11. MWE status;\r\n12. MWE status effective date;\r\n13. Holiday pay;\r\n14. Overtime pay;\r\n15. Night shift differential;\r\n16. Hazard pay;\r\n17. 13th month pay;\r\n18. Other benefits;\r\n19. Taxable compensation;\r\n20. Non-taxable compensation;\r\n21. Withholding tax.\r\n\r\nEMPLOYER RESPONSIBILITY\r\n\r\nEmployers must correctly determine the tax treatment of employee compensation.\r\n\r\nEmployers should maintain sufficient documentation supporting MWE classification and the tax treatment applied to employee compensation.\r\n\r\nBIR COMPLIANCE\r\n\r\nThe Bureau of Internal Revenue may issue regulations and other revenue issuances implementing tax provisions affecting minimum wage earners.\r\n\r\nCurrent BIR regulations should be consulted when implementing payroll tax calculations.\r\n\r\nSUBSEQUENT TAX LAWS\r\n\r\nRA 9504 was enacted in 2008.\r\n\r\nSubsequent legislation has amended several provisions of the National Internal Revenue Code.\r\n\r\nRepublic Act No. 10963, known as the TRAIN Law, introduced significant changes to individual income taxation and related tax provisions.\r\n\r\nTherefore, RA 9504 should not be used by itself to determine present-day withholding tax rates or tax brackets.\r\n\r\nThe HRMS should use current BIR rules for actual payroll computation.\r\n\r\nRELATIONSHIP WITH RA 6727\r\n\r\nRepublic Act No. 6727 established the wage rationalization framework and created the regional wage-setting mechanism.\r\n\r\nRA 6727 and applicable Wage Orders determine the statutory minimum wage.\r\n\r\nRA 9504 provides tax treatment for qualified minimum wage earners.\r\n\r\nThe two laws should therefore be linked in the HRMS.\r\n\r\nLEGAL COMPLIANCE WORKFLOW\r\n\r\nThe recommended compliance workflow is:\r\n\r\nRA 6727\r\nRegional Wage Order\r\nEmployee location\r\nEmployee classification\r\nApplicable minimum wage\r\nMWE determination\r\nRA 9504 tax exemption\r\nCurrent BIR regulations\r\nTaxable compensation\r\nWithholding tax\r\n\r\nAUDIT TRAIL\r\n\r\nChanges to MWE status and tax classification should be recorded in the HRMS audit trail.\r\n\r\nThe system should record:\r\n\r\n1. Previous MWE status;\r\n2. New MWE status;\r\n3. Effective date;\r\n4. Applicable Wage Order;\r\n5. Applicable minimum wage;\r\n6. User who made the change;\r\n7. Date and time of change;\r\n8. Reason for change.\r\n\r\nDOCUMENTATION\r\n\r\nHR should maintain supporting records including:\r\n\r\n1. Employment contract;\r\n2. Payroll records;\r\n3. Wage Order;\r\n4. Compensation records;\r\n5. MWE classification;\r\n6. Tax computation;\r\n7. BIR forms;\r\n8. Supporting employee documents;\r\n9. Records of wage adjustments.\r\n\r\nLEGAL CAUTION\r\n\r\nRA 9504 is a historical tax law that remains relevant as part of the development of Philippine tax treatment for minimum wage earners.\r\n\r\nHowever, subsequent laws and BIR regulations have changed the tax system.\r\n\r\nCurrent payroll computations must therefore be based on the latest applicable tax laws and BIR issuances.\r\n\r\nThe HRMS should preserve RA 9504 as a legal reference while using the current tax rules for actual payroll processing.\r\n\r\nAPPROVAL\r\n\r\nRepublic Act No. 9504 was approved on May 24, 2008.','2026-08-13 15:50:53'),
(15,'Department Advisory','Department Advisory No. 01, Series of 2019','Guidelines on the Computation of Salary Differential of Female Workers During Maternity Leave',NULL,'2019-07-09',NULL,'Department of Labor and Employment (DOLE)','active','maternity leave, salary differential, female workers, maternity benefit, maternity leave benefit, RA 11210, Expanded Maternity Leave Law, maternity leave pay, SSS maternity benefit, employer share, salary differential, daily maternity benefit, maternity leave credits, maternity compensation, DOLE',NULL,'modules/compliance/assets/law_reference/DA-01-19-Guidelines-on-the-Computation-of-Salary-Differential-of-Female-Workers-during-her-Maternity.pdf','Republic Act No. 11210 (105-Day Expanded Maternity Leave Law); Implementing Rules and Regulations of Republic Act No. 11210; Social Security Act and applicable SSS maternity benefit rules','Provides guidelines for computing the salary differential of female workers during maternity leave. The advisory explains the relationship between the maternity benefit received from the Social Security System and the amount that may be required from the employer as salary differential, subject to the applicable law, implementing rules, and recognized exemptions. It is intended to guide employers and workers in determining the proper maternity leave compensation and in ensuring compliance with the Expanded Maternity Leave Law and related labor standards.','Department Advisory No. 01, Series of 2019. The original PDF is retained as the source document and the complete extract is stored in full_text. Because this is a 2019 advisory, the HRMS should also cross-reference later laws and implementing rules, particularly Republic Act No. 11210 and its implementing rules, when using this document for current compliance decisions.',NULL,NULL,'2026-08-13 17:23:31','GUIDELINES ON THE COMPUTATION OF SALARY DIFFERENTIAL OF FEMALE WORKERS DURING HER MATERNITY LEAVE','Department Advisory','Department of Labor and Employment (DOLE)','Department Advisory No. 01','2019','This Department Advisory, issued by the Department of Labor and Employment (DOLE) on 9 July 2019, sets out the Guidelines on the Computation of Salary Differential of Female Workers During Her Maternity Leave and the Criteria for Exemption pursuant to Republic Act No. 11210, otherwise known as the 105-Day Expanded Maternity Leave Law, and its Implementing Rules and Regulations. The Advisory is intended to guide employers, workers, DOLE offices and other concerned parties in determining the proper salary differential payable during maternity leave and in processing applications for exemption from payment of the salary differential.\r\n\r\nUnder Section I, Purpose, the Advisory establishes the procedures for computing the salary differential and determining whether an establishment may qualify for exemption under RA No. 11210 and its IRR. Under Section II, Computation of Salary Differential, the employer is required to pay the difference between the female worker\'s full salary during the maternity period and the actual cash maternity benefit received from the Social Security System (SSS). The computation requires: (1) determining the worker\'s full pay by multiplying the applicable monthly salary by the maternity period in months; (2) determining the worker\'s premium contribution share for SSS, PhilHealth and Pag-IBIG covering the maternity period; (3) determining the SSS maternity leave benefit using the prescribed SSS formula; and (4) deducting the employee premium contribution share and SSS maternity leave benefit from the full pay to determine the salary differential. The Advisory also explains that full pay refers to actual remuneration or earnings paid for services rendered on normal working days and hours, at not less than the applicable wage rate fixed by the Regional Tripartite Wages and Productivity Board, including allowances provided under company policy or a collective bargaining agreement, where applicable. It recognizes an equivalent monthly rate computation based on daily rate and the applicable factor and provides that, where a female worker is not uniformly paid and a daily or monthly rate cannot be determined, the average monthly salary for the preceding twelve-month period may be used. For purposes of the computation, a month is treated as thirty (30) days under Article 13 of the Civil Code.\r\n\r\nThe Advisory includes sample computations showing how full pay, SSS maternity benefit, employee premium contributions and resulting salary differential are considered. It also states under Section III, Coverage from Income Tax of the Salary Differential, that the salary differential is treated as taxable income of the female worker, subject to the rules and regulations of the Bureau of Internal Revenue. Under Section IV, Effect on the Computation of Thirteenth (13th) Month Pay, the salary differential is included as part of the basic salary for purposes of computing the thirteenth-month pay of a rank-and-file employee. The Advisory also notes that other salary deductions, such as loans, may be deducted from the salary differential when agreed upon by the employer and female worker.\r\n\r\nSection V provides the criteria and documentary requirements for exemption from payment of salary differential for covered private-sector establishments. Qualified establishments must submit, in duplicate copies and within the first semester of every calendar year, the DOLE-prescribed application form, a certificate of registration from the Department of Trade and Industry, Securities and Exchange Commission or Cooperative Development Authority, as applicable, and the latest business permit issued by the local government unit. Additional documentary requirements apply to specific categories. Distressed establishments must submit audited financial statements duly received by the appropriate government agency or certification from the Bangko Sentral ng Pilipinas showing receivership or liquidation. Retail, service and other enterprises regularly employing not more than ten workers must submit an owner\'s or president\'s affidavit concerning the number of employees. Micro enterprises with total assets not exceeding Three Million Pesos (Php3,000,000.00) must submit a Barangay Micro Business Enterprise (BMBE) Certification. Establishments already providing benefits similar to or greater than those required under RA No. 11210 and its IRR must submit a certified true copy of the existing collective bargaining agreement or policy, or an employer and workers\' representative certification of existing company practice.\r\n\r\nSection VI establishes the application process. Applications for exemption must be filed in duplicate at the DOLE Regional, Provincial, Field or Satellite Office where the applicant principally operates, and no application will be accepted unless the applicable documentary requirements are complete. The DOLE Regional Director or authorized representative may conduct an inspection, when necessary, to verify the number of workers, nature of business and other relevant information within five (5) working days from receipt of the application. The DOLE Regional EML Committee evaluates applications and inspection results within five (5) working days and submits its recommendation to the DOLE Regional Director or authorized representative for approval within another five (5) working days.\r\n\r\nSection VII governs revocation of a Certificate of Exemption. The DOLE Regional Director or authorized representative may revoke a certificate after due process for misrepresentation of facts, falsified or tampered applications or supporting documents, non-compliance with labor standards and working conditions, non-compliance with SSS, Pag-IBIG, PhilHealth or Employees\' Compensation Commission rules, collection of unauthorized fees, or violation of any provision of the Labor Code. A clarificatory hearing may be conducted within seven (7) working days from receipt of a complaint. Hearings are summary in nature, must be terminated within ten (10) working days from the first scheduled hearing, and the Regional Director or authorized representative must resolve the case within ten (10) working days from the last hearing. The Order states that the resulting decision is final and not appealable.\r\n\r\nThe PDF also contains the prescribed exemption application form and certificate template. The application form requires establishment information such as business organization, name and address, contact information, nature of business and number of male and female employees. It identifies exemption categories including distressed establishments, sole proprietorships or partnerships, non-stock non-profit organizations, corporations or cooperatives, banks or quasi-banks, establishments regularly employing not more than ten workers, retail or service enterprises, micro-business enterprises and establishments already providing similar or greater maternity benefits. The form requires the owner or authorized representative and workers\' representative to certify the accuracy and completeness of the information. The requirements checklist covers the DOLE application form, registration documents, business permit and category-specific supporting documents. The certificate template states that the establishment has complied with RA No. 11210, its IRR and applicable supplemental issuances; identifies the establishment and exemption basis; provides for annual justification and re-issuance; and states that the certificate may be revoked before its expiration when applicable. The certificate expressly states that it is not valid as an exemption from payment of the minimum wage.','DA-01-19-Guidelines-on-the-Computation-of-Salary-Differential-of-Female-Workers-during-her-Maternity.pdf','===== PAGE 1 =====\r\nRepublic of the Philippines | w& |\r\n* DEPARTMENT OF LABOR AND EMPLOYMENT |\r\nx * Intramuros, Manila | AJA AB\r\nMore than Jobs! comp SS\r\nHs decor ‘job. Certificate Number: AJA15-0048\r\nDEPARTMENT ADVISORY NO. _O}\r\nSeries of 2019 ee eee ee\r\nGUIDELINES ON THE COMPUTATION OF SALARY orrer tra\r\nOF FEMALE WORKERS DURING HER MATERNITY LEAVE AND ITS CRITERIA\r\nFOR EXEMPTION PURSUANT TO REPUBLIC ACT NO. 11210\r\nAND ITS IMPLEMENTING RULES AND REGULATIONS\r\nI. PURPOSE\r\nThis Guidelines is issued to guide all concerned on the computation of\r\nsalary differential of female workers during maternity leave and its criteria for\r\nexemption pursuant to Republic Act No. 11210 otherwise known as the “105-\r\nDay Expanded Maternity Leave Law’ and its Implementing Rules and\r\nRegulations.\r\nll. COMPUTATION OF SALARY DIFFERENTIAL\r\nThe employer shall pay the salary differential between the full salary of\r\nfemale worker during her maternity leave and the actual cash benefits received\r\nfrom the Social Security System (SSS) which shall be computed as follows:\r\n1. Compute the amount of full pay:\r\nFull pay!) = monthly salary2I$] x maternity period in months\"!\r\n\r\n2. Ascertain the employee’s premium contribution share for SSS,\r\nPhilippine Health Insurance Corporation (PhilHealth), and Home\r\nDevelopment Mutual Fund (Pag-IBIG) covering the maternity period.\r\n\r\n3. Determine the amount of SSS maternity leave benefit of the female\r\nworker based on the prescribed formula and computation by the SSS.\r\n\r\n4. Deduct from the amount of full pay the total amount of employee’s\r\npremium contribution share and SSS maternity leave benefit.\r\n\r\nFull pay, as defined in Section 1(j), Rule Il of the IRR of RA 11210, refers to actual remuneration or earnings\r\npaid by an employer to a worker for services rendered on normal working days and hours not lower than the\r\nwage rate fixed by the Regional Tripartite Wages and Productivity Board (RTWPB) including allowances\r\nprovided for under existing company policy or collective bargaining agreement, if any.\r\n\r\n? Equivalent monthly rate may be computed as follows: (daily rate x factor) / 12.\r\n\r\n3 \\f female worker is not uniformly paid whereby daily rate or monthly rate cannot be determined, the average\r\n\r\nof her monthly salary for the last twelve-month period shall be adopted.\r\n\r\n* As provided in Article 13 of the Civil Code of the Philippines, a month shall be understood as thirty (30) days.\r\n\r\n\r\n===== PAGE 2 =====\r\nGUIDELINES ON THE COMPUTATION OF SALARY DIFFERENTIAL OF FEMALE\r\nWORKERS DURING HER MATERNITY LEAVE AND ITS CRITERIA FOR EXEMPTION\r\nPURSUANT TO REPUBLIC ACT NO. 11210 AND ITS IMPLEMENTING RULES AND\r\nREGULATIONS\r\nPage 2 of 4\r\nTo illustrate, below is a sample computation:\r\nExpanded maternity leave\r\nsalary SSS maternity | differential!\r\nFull pay premium\r\nae benefit\r\ncontributions\r\nPhp14,006.75 | Php49,023.63 | Php2,984.07 | Php49,000.00 | -Php2,960.45\r\nPhp31,300.00 | Php109,550.00| Php4,656.31 | Php70,000.00 | Php34,893.69\r\nIli. COVERAGE FROM INCOME TAX OF THE SALARY DIFFERENTIAL\r\nThe amount of salary differential shall be treated as taxable income of\r\nthe female worker subject to the rules and regulations of the Bureau of Internal\r\nRevenue.\r\nIV. EFFECT ON THE COMPUTATION OF THIRTEENTH (13) MONTH PAY\r\nThe salary differential shall be included as part of the basic salary for\r\npurposes of computation of the 13th month pay of the rank-and-file employee.\r\nV. CRITERIA FOR EXEMPTION OF PAYMENT OF SALARY DIFFERENTIAL\r\nEstablishments in the private sector mentioned in Section 5, Rule V1 of\r\nthe Implementing Rules and Regulations of RA 11210, may be exempted from\r\npaying the salary differential by submitting within the first semester of every\r\ncalendar year, in duplicate copies, at the DOLE\r\nRegional/Provincial/Field/Satellite Office where the applicant principally\r\noperates, all of the following requirements:\r\na. DOLE-prescribed Application Form,\r\nb. Copy of Certificate of Registration issued by the Department of Trade\r\nand Industry or the Securities and Exchange Commission or the\r\nCooperative Development Authority, as the case may be, and\r\nc. Copy of the latest Business Permit issued by the Local Government\r\nUnit.\r\nAdditional requirements, as applicable, for the following:\r\n|. Distressed establishments\r\n* Other deductions in salary such as loans, may be deducted from the salary differential as may be agreed\r\nupon by the employer and the female worker.\r\n\r\n\r\n===== PAGE 3 =====\r\nGUIDELINES ON THE COMPUTATION OF SALARY DIFFERENTIAL OF FEMALE\r\nWORKERS DURING HER MATERNITY LEAVE AND ITS CRITERIA FOR EXEMPTION\r\nPURSUANT TO REPUBLIC ACT NO. 11210 AND ITS IMPLEMENTING RULES AND\r\nREGULATIONS\r\nPage 3 of 4\r\na. Audited Financial Statement/s®! duly received by the Bureau of\r\nInternal Revenue and/or the Securities Exchange Commission or the\r\nCooperative Development Authority or\r\nb. Certification from the Bangko Sentral ng Pilipinas that it is under\r\nreceivership or liquidation.\r\nll. Retail/service establishments and other enterprises regularly employing\r\nnot more than ten (10) workers\r\n- Owner or President’s Affidavit as to the number of employees for the\r\ntwelve-month period preceding the date of application.\r\nill. Micro enterprises whose total assets are not more than Three Million\r\n\r\nPesos (Php3,000,000.00)\r\n\r\n- Barangay Micro Business Enterprise Certification.\r\n\r\nIV.Establishments already providing similar or more than the benefits\r\nprovided in RA 11210 and its IRR\r\n\r\na. Certified True Copy of existing Collective Bargaining Agreement or\r\n\r\npolicy; or\r\n\r\nb. Employer and Workers Representative’s Certification of existing\r\n\r\ncompany practice.\r\n\r\nThe Certificate of Exemption shall be valid for one year from the date of\r\nissuance thereof. However, if an establishment was issued already a Certificate\r\nof Exemption by the Regional Tripartite Wage and Productivity Board (RTWPB)\r\nfrom payment of minimum wage for a certain year, the same Certificate shall\r\nalso carry with it an exemption from payment of salary differential for the same\r\nyear and no separate application shall be required in this case.\r\n\r\nVI. APPLICATION PROCESS\r\n\r\nThe application for exemption from payment of salary differential shall\r\nbe filed in duplicate copies at the DOLE Regional/Provincial/Field/Satellite\r\nOffice where the applicant principally operates. No application for exemption\r\nshall be accepted unless all the requirements in the preceding Section are\r\ncomplied with.\r\n\r\nThe DOLE Regional Director or his/her authorized representative shall\r\nconduct an inspection, if necessary, to verify the number of workers, nature of\r\nbusiness, and other relevant information, within five (5) working days from\r\nreceipt of the application.\r\n\r\n* Where the exemption being sought is for a particular project/branch/division, the consolidated Audited\r\nFinancial Statements of the establishment shall be used as basis for determining its distressed condition.\r\nA corporation/cooperative shall submit their Audited Financial Statement for the last accounting period\r\nimmediately preceding the application, while a sole proprietorship or partnership shall submit their Audited\r\nFinancial Statement for the last two (2) full accounting periods immediately preceding the application.\r\n\r\n\r\n===== PAGE 4 =====\r\nGUIDELINES ON THE COMPUTATION OF SALARY DIFFERENTIAL OF FEMALE\r\nWORKERS DURING HER MATERNITY LEAVE AND ITS CRITERIA FOR EXEMPTION\r\nPURSUANT TO REPUBLIC ACT NO. 11210 AND ITS IMPLEMENTING RULES AND\r\nREGULATIONS\r\n\r\nPage 4 of 4\r\n\r\nThe DOLE Regional EML Committee shall evaluate all applications for\r\nexemption and/or results of inspection within five (5) working days. It shall\r\nsubmit its recommendation to the DOLE Regional Director or his/her authorized\r\nrepresentative for approval within five (5) working days from receipt thereof.\r\n\r\nVil. REVOCATION OF CERTIFICATE OF EXEMPTION\r\n\r\nThe DOLE Regional Director or his/her duly authorized representative\r\nshall revoke the Certificate of Exemption issued to the establishment after due\r\nprocess, based on any of the following grounds:\r\n\r\na. Misrepresentation of facts in the application;\r\n\r\nb. Submission of falsified or tampered application or supporting\r\ndocuments;\r\n\r\nc. Non-compliance with labor standards and working conditions;\r\n\r\nd. Non-compliance with rules and regulations of the Social Security\r\n\r\nSystem, Home Development Mutual Fund, Philippine Health Insurance\r\n\r\nCorporation, or Employers’ Compensation Commission;\r\n\r\ne. Collecting any fees not authorized by law and other applicable rules\r\nand regulations; or\r\nf. Violation of any provision of the Labor Code of the Philippines.\r\n\r\nThe DOLE Regional Director or his/her duly authorized representative\r\nmay conduct a clarificatory hearing within seven (7) working days from receipt\r\nof complaint. The proceedings shall be summary in nature.\r\n\r\nThe conduct of hearings shall be terminated within ten (10) working\r\ndays from the first scheduled clarificatory hearing. The DOLE Regional Director\r\nor his/her duly authorized representative shall resolve the case within ten (10)\r\nworking days from the date of the last hearing. The Order shall be final and not\r\nappealable.\r\n\r\nManila, Philippines, 9 July 2019\r\n\r\nSI : I\r\nSecretary\r\nDept. of Labor & Employment\r\nOffice of the Secretary\r\n0000\r\n\r\n\r\n===== PAGE 5 =====\r\nRepublic of the Philippines\r\n* DEPARTMENT OF LABOR AND EMPLOYMENT\r\nL » DOLE Regional/Provincial/Field/Satellite Office AJA| “AB\r\nMore than Jobs! <n\r\nMs decent job. Certificate Number: AJAIS-0048\r\nAPPLICATION FORM\r\nEXEMPTION FROM PAYMENT OF SALARY DIFFERENTIAL\r\nPlease supply all required information. Misrepresentation, false statement or fraud in this application or in any supporting document is\r\nground for denial of application or revocation of certificate.\r\n© Sole proprietorship O Corporation © Barangay Micro Business\r\nO Partnership O Cooperative Enterprise (BMBE\r\n|b. Nameofestablishment |\r\n| oc. Address\r\n. | d. Contactnumber |\r\n|e. E-mailaddress |\r\n| f. Natureofbusiness |\r\n| _g. Numberofemployees [Female = [| [Male |\r\nlil. CRITERIA ON AVAILMENT OF EXEMPTION (Please check item VII for list of requirements)\r\nO Distressed establishment\r\n© Sole proprietorship or partnership O Non-stock, non-profit organization\r\n© Corporation or cooperative | © Bank or quasi-bank\r\n© Regularly employing not more than ten (10) workers\r\nOs Retail O Service O Otherenterprise\r\n© Micro-business enterprise engaged in the production, processing, or manufacturing of\r\nproducts or commodities including agro-processing, trading, and services, whose total\r\nassets are not more than Three Million Pesos (P3,000,000.00) in accordance with the\r\nBarangay Micro Business Enterprises (BMBE\'s) Act of 2002\r\nO Already providing similar or more than the benefits required under RA 11210 and its IRR\r\npursuant to:\r\nO Collective bargaining © Company practice O Company policy\r\nagreement (CBA\r\n1, (name of owner or authorized representative), declare that the statements made in this\r\nthat the same was made known to all workers of the establishment.\r\nName and signature of owner or\r\na\r\nwithout any intention of circumventing the law and that the details provided herein and its supporting\r\ndocuments are true and correct to the best of my knowledge. ee\r\n[Name and signature of workers’ representative | —=s=~“*~*sétSCSC“‘*~*\r\npa Name\r\n|b. Designation ff —CCCCCdY\r\n|. Contactnumber | SSOC—~—~SCSCSCSCSCSCSY\r\n| d. Emailadress [0 C—“‘“CS*sS*SCSCSCSY\r\n\r\n\r\n===== PAGE 6 =====\r\nVil. REQUIREMENTS\r\nAll of the following:\r\nO Two (2) copies of DOLE-prescribed Application Form and all other applicable requirements,\r\nO Copy of Certificate of Registration from:\r\nO Department of Trade and Industry (DTI),\r\nO Securities and Exchange Commission (SEC), if applicable, or\r\nO Cooperative Development Authority (CDA), if applicable, and\r\nO Copy of the latest Business Permit issued by the Local Government Unit.\r\nAdditional requirements, as applicable, for the following:\r\nDistressed establishments\r\nO Audited Financial Statement/s duly received by the Bureau of Internal Revenue and/or the\r\nSecurities Exchange Commission or the Cooperative Development Authority\r\nO One (1) full accounting period if corporation or cooperative, or\r\nO Two (2) full accounting periods if sole proprietorship or partnership; or\r\nO Certification from the Bangko Sentral ng Pilipinas that it is under receivership or liquidation.\r\nRetail/service establishments and other enterprises reqularly employing not more than ten\r\n(10) workers\r\nO Owner or President\'s Affidavit as to the number of employees for a calendar year\r\nMicro enterprises whose total assets are not more than Three Million Pesos\r\n(Php3,000,000.00)\r\nO Barangay Micro Business Enterprise Certification\r\nEstablishments already providing similar or more than the benefits provided in RA 11210 and\r\nits IRR\r\nO Certified True Copy of existing Collective Bargaining Agreement or policy or\r\nO Employer and Workers Representative’s Certification of existing company practice\r\nPage 2 of 2\r\n\r\n\r\n===== PAGE 7 =====\r\nRepublic of the Philippines | ob |\r\n* DEPARTMENT OF LABOR AND EMPLOYMENT |\r\nok DOLE Regional/Provincial/Field Satellite Office |AJA| “AB\r\nMore than Jobs! cxED eo\r\nWs decent job, ‘Centificate Number. AJA1S-0048\r\nThis\r\nNumbered RO(No.)-(Area)-EML-([MMDDY Y)-(Segq. no.)\r\nis issued to\r\n(Company Name)\r\nWith company address located at (complete address)\r\nAnd Tax Identification No. (TIN) (N umber)\r\n\r\nFor having complied with the requirements as provided for under Republic Act No.\r\n11210, otherwise known as the 105-Day Expanded Maternity Leave Law, its Implementing\r\nRules and Regulations (IRR), and other supplemental issuances. This Certificate of\r\nExemption is being issued on the basis that the company is (cr iteria of\r\nexemption).\r\n\r\nIn witness whereof, and by authority vested in me, I have hereunto set my hand and\r\naffixed the Official Seal of the Department of Labor and Employment (DOLE) Regional\r\nOffice No. (No.) located at (DOLE RO address) on this (day) of (month) (year).\r\n\r\nThis Certificate of Exemption shall be valid until (day) of (month) (year)\r\nsubject for annual justification and re-issuance based on Section 5 (c) of Republic Act No.\r\n11210 and Section 5, Rule VI of its IRR, unless sooner revoked by the Head of the issuing\r\nDOLE Regional Office.\r\n\r\n(Name of Regional Director)\r\nRegional Director\r\nNOT VALID AS EXEMPTION FROM PAYMENT OF MINIMUM WAGE','2026-08-13 14:54:46'),
(16,'Department Order','Department Order No. 177, Series of 2017','DOLE Adjustment Measures Program for Displaced Higher Education Institution Personnel',NULL,NULL,NULL,'Department of Labor and Employment (DOLE)','active','DOLE Adjustment Measures Program, displaced higher education institution personnel, higher education institutions, Republic Act No. 10533, Enhanced Basic Education Act of 2013, K to 12, K-12, teacher displacement, faculty displacement, higher education faculty, HEI personnel, adjustment measures, employment facilitation, livelihood assistance, training, retraining, entrepreneurship, emergency employment, financial assistance, transition assistance',NULL,'modules/compliance/assets/law_reference/DO-177-17-Expanding-DOLE-Adjustment-Measures-Program-For-Displaced-Higher-Education-Institution-Personnel-due-to-the-Implementation-of-Republic-Act-No_-10533.pdf','Republic Act No. 10533, Enhanced Basic Education Act of 2013; K to 12 Basic Education Program; applicable DOLE labor and employment programs and issuances','Expands the DOLE Adjustment Measures Program to cover displaced higher education institution personnel affected by the implementation of Republic Act No. 10533, including qualified faculty and personnel whose employment is displaced or adversely affected by the transition to the K to 12 Basic Education Program. The Order provides adjustment and employment support measures intended to facilitate re-employment, skills development, livelihood and other appropriate assistance.','Department Order No. 177, Series of 2017. The original PDF is retained as the source document and the complete extracted/OCR text is stored in full_text. This reference should be read together with Republic Act No. 10533 and current DOLE issuances when used for present-day compliance or program eligibility decisions.',NULL,NULL,'2026-08-13 17:23:31','EXPANDING THE DOLE ADJUSTMENT MEASURES PROGRAM FOR DISPLACED HIGHER EDUCATION INSTITUTION PERSONNEL DUE TO THE IMPLEMENTATION OF REPUBLIC ACT NO. 10533','Department Order','Department of Labor and Employment (DOLE)','Department Order No. 177','2017','This Department Order expands the DOLE Adjustment Measures Program for displaced personnel of higher education institutions affected by the implementation of Republic Act No. 10533, the Enhanced Basic Education Act of 2013. It recognizes the employment impact of the transition to the K to 12 Basic Education Program on higher education institutions and their personnel and establishes DOLE assistance measures for qualified displaced workers. The program is designed to support affected higher education institution personnel through appropriate adjustment interventions, including employment facilitation, training or retraining, livelihood and self-employment assistance, and other DOLE programs that may respond to their employment and income-displacement needs. The Order identifies the roles of DOLE offices and implementing units in identifying and assisting affected personnel, coordinating available government employment and livelihood services, and facilitating access to appropriate adjustment measures. It also provides an institutional mechanism for implementing the expanded program in response to the continuing effects of Republic Act No. 10533 on higher education personnel.','DO-177-17-Expanding-DOLE-Adjustment-Measures-Program-For-Displaced-Higher-Education-Institution-Personnel-due-to-the-Implementation-of-Republic-Act-No_-10533.pdf','===== PAGE 1 =====\r\n* DEPARTMENT OF LABOR AND EMPLOYMENT AD\r\n‘ple’ Intramuros, Manila == , ~\\\r\nNEPA RaMR REE Not ABO R-O48) EP)\"\r\n\' Administravee Service Central Rectrcs .2 .\r\n10 JUL 2007 |\r\nDEPARTMENT ORDER NO. !77_ | pate: cciapigeceacemeetemnaen\r\nSeries of 2017 TIME: ae i _— |\r\n© Juuus\r\nEXPANDING DOLE ADJUSTMENT MEASURES P GEA F\r\nFOR DISPLACED HIGHER EDUCATION INSTITUTION P - _——\r\nDUE TO THE IMPLEMENTATION OF REPUBLIC ACT NO. 10533\r\nIn the interest of service and pursuant to the DOLE-DepEd-TESDA-CHED Joint Guidelines in the\r\nImplementation of the Labor and Management Component of Republic Act No. 10533, the\r\nDepartment of Labor and Employment (DOLE) hereby promulgates the following rules and\r\nregulations expanding the implementation of DOLE Adjustment Measures Program (AMP) for\r\ndisplaced Higher Education Institution (HEI) personnel due to the implementation of Republic Act\r\nNo. 10533 otherwise known as the Enhanced Basic Education Act of 2013.\r\nArticle |\r\nGENERAL PROVISIONS\r\nSection 1. Declaration of Policy. The 1987 Philippine Constitution guarantees the protection of\r\nlabor, promotion of full employment and equality of employment opportunities for all. Rule VII,\r\nSection 31 of the Implementing Rules and Regulations of Republic Act No. 10533 provides that\r\nthe rights, interests, and welfare of teaching and non-teaching HEI personnel shall be promoted\r\nand protected.\r\nSection 2. Policy Objectives. This Department Order aims to expand the coverage provided\r\nunder Department Order No. 152-16, Series of 2016, entitled, “Guidelines in the Implementation\r\nof K to 12 DOLE Adjustment Measures Program’.\r\nSection 3. Definition of Terms. The following terms, as used in this Department Order, shall\r\nrefer to:\r\na. Displacement - separation between the HEI and its personnel due to the implementation\r\nof Republic Act 10533. In the context of RA 10533, Displacement shall mean any of the\r\nfollowing:\r\n\r\ni. Retrenchment - refers to the economic ground for dismissing employees’\r\nundertaken by HEls to prevent business losses that are reasonably imminent due\r\nto the implementation of RA 10533 in which retrenched HEI personnel were\r\nnotified at least thirty (30) days before the intended date of retrenchment.\r\n\r\ni. | Availment of Early Retirement Program and Voluntary Separation Program -\r\nimplemented by HEls as a cost-saving program which can be availed by HEI\r\npersonnel based on eligibilities determined by the management.\r\n\r\nii. | Non-Renewal of Contracts - undertaken by HEls due to either the transfer of\r\nsubjects from higher education to basic education or shortage of student enrolment\r\nfor bachelor/major subjects/courses.\r\n\r\niv. Work Suspension - undertaken by HEIs due to shortage of student enrolment\r\nwhere the affected faculty members retain the right of recall at the end of the\r\nsuspension.\r\n\r\n. ‘Definition derived from Atlantic Gulf and Pacific Company of Manila, Inc. [AG & P], v. NLR C, G.R. No. 127516, May 28, 1999.\r\nExpanding DOLE Adjustment Measures Program for Displaced Higher Education\r\nInstitution Personnel due to the Implementation of Republic Act No. 10533 Page 1 of 8\r\n\r\n\r\n===== PAGE 2 =====\r\nb. Displaced Personnel - teaching and non-teaching personnel either temporarily or\r\npermanently separated from employment with their HE! due to the implementation of\r\nRepublic Act 10533. In the context of RA 10533, the following types of displaced personnel\r\nshall mean:\r\n\r\n. i. Partially Displaced Personnel - personnel permanently and_ involuntarily\r\nseparated from one of his/her employments and still has other wage employment.\r\n\r\nii. Totally Displaced Personnel - personnel permanently and _ involuntarily\r\nseparated from his/her only employment and has no other wage employment\r\nelsewhere.\r\n\r\niii. | Temporarily Displaced Personnel - personnel whose work is temporarily and\r\ninvoluntarily suspended from his or her only employment and has no other wage\r\nemployment elsewhere.\r\n\r\nc. Higher Education Institution - an education institution, private or public, undertaking\r\noperations of higher education programs with an organized group of students pursuing\r\ndefined studies in higher education, receiving instructions from teachers, usually located\r\nin a building or group of buildings in a particular site specifically intended for educational\r\npurposes.’\r\n\r\nd. Personnel - person, singly or collectively, working in an HEI and are classified as follows:\r\n\r\ni. Teaching Personnel - personnel whose appointment or contract of employment\r\nindicates a teaching position or faculty rank.\r\n\r\nii. Non-Teaching Personnel - personnel whose appointment or contract of\r\nemployment indicates a non-teaching position.\r\n\r\nii. Permanent Non-Teaching Personnel - non-teaching personnel who have\r\nsatisfactorily completed probationary employment? and has attained security of\r\ntenure.\r\n\r\niv. Permanent Teaching Personnel - full-time teaching personnel who have\r\nsatisfactorily completed probationary employment®, who possess the minimum\r\nqualifications required by CHED and the HEI, and are re-hired or re-appointed\r\nimmediately after the end of their probationary employment.*\r\n\r\nv. Non-Permanent Personnel - teaching or non-teaching personnel who do not\r\nmeet the qualifications of a permanent HEI personnel.\r\n\r\ne. Transition Period — the period between 30 May 2014° and the end of Academic Year\r\n2021-2022.\r\n\r\nArticle Il\r\nPROGRAM DESCRIPTION\r\nSection 1. Program Description. The DOLE Adjustment Measures Program for HEI Personnel\r\ndisplaced by the Implementation of Republic Act 10533 (herein referred to as, K to 12 DOLE\r\nAMP) is a social protection program that provides displaced personnel an integrated and\r\ncomprehensive package of assistance during the transition period.\r\nSection 2. Program Objectives. The program aims to provide assistance and interventions to\r\ndisplaced HEI personnel, enhance their employability and competitiveness, and mitigate the\r\nadverse economic impacts of the implementation of Republic Act 10533.\r\n‘Definition lifted from Section 2 (1) of DOLE-DepEd-TESDA-CHED Joint Guidelines in the Implementation of the Labor and\r\neen Component of RA 10533 and Section 5 (16), Article 1, Title A of the Manual of Regulations for Private Higher Education\r\n\"The probationary employment of non-teaching personnel shall not be more than six (6) months as provided by the Labor Code of the\r\nPhilippines, as amended.\r\n3 The probationary employment of teaching personnel shall not be more than a period of six (6) consecutive semester or nine (9)\r\nconsecutive trimesters of satisfactory service, as the case may be.\r\n‘ Definition lifted from Section 118, Article XXIV, Title F of the Manual of Regulations for Private Higher Education of 2008.\r\n5 Date of signing of the DOLE-DepEd-TESDA-CHED Joint Guidelines in the Implementation of the Labor and Management Component\r\nof Republic Act No. 10533.\r\nExpanding DOLE Adjustment Measures Program for Displaced Higher Education\r\nInstitution Personnel due to the Implementation of Republic Act No. 10533 Page 2 of 8\r\n\r\n\r\n===== PAGE 3 =====\r\nSection 3. Coverage. The program shall cover all teaching and non-teaching HEI personnel\r\neither temporarily or permanently displaced due to the implementation of Republic Act 10533\r\nduring the Transition Period through any of the following modes of displacement:\r\n\r\na. Retrenchment as an Authorized Cause of Termination\r\n\r\nb. Availment of Voluntary Separation Program\r\n\r\nc. Availment of Early Retirement Program\r\n\r\nd. Non-Renewal of Contract\r\n\r\ne. Work Suspension\r\n\r\nSection 4. Exclusion. The following personnel displaced due to the implementation of Republic\r\nAct 10533 are excluded from the program:\r\n\r\na. Full-time government employees with part-time teaching load; and\r\n\r\nb. Personnel who are beneficiaries of CHED Development Grants and other government\r\ngrants.\r\n\r\nArticle Ill\r\nPROGRAM ASSISTANCE\r\nSection 1. Program Components. In case displacement from the HEI is inevitable, the following\r\ndisplaced HEI! personnel may avail any or all of the following program components:\r\n\r\na. Financial Support. This component shall provide displaced HEI personnel with financial\r\nrelief necessary to mitigate the immediate adverse economic impacts of the\r\nimplementation of Republic Act 10533. The amount of financial support is equivalent to\r\nten thousand pesos (PHP 10,000.00) or seventy-five percent (75%) of their last monthly\r\ngross salary or the prevailing median salary\' of HEI personnel, whichever is highest.\r\nHowever, the duration of financial support shall depend on the following employment\r\nstatus of the displaced HEI personnel at the date of application:\r\n\r\ni. For totally displaced HE! Personnel. The financial support shall be provided\r\nmonthly for six (6) months subject to compliance with the program conditional\r\nrequirements. Beneficiaries who have successfully obtained a subsequent full-time\r\nwage employment prior to the end of the financial support coverage shall be\r\nentitled to an incentive equivalent to half of the total remaining amount of financial\r\nsupport.\r\n\r\niii |For temporarily displaced HEI Personnel. The financial support shall be\r\nnon-conditional and shall be provided monthly for three (3) months. In case the\r\nbeneficiary eventually becomes totally displaced, duration shall be extended for\r\nthree (3) additional months. The financial support amount for the additional months\r\nshall be equivalent to the previously approved financial support amount or the new\r\nfinancial support computation based on the last monthly gross salary, whichever\r\nis higher.\r\n\r\niii. For partially displaced HEI Personnel. The financial support shall be\r\nnon-conditional and shall be provided monthly for three (3) months.\r\n\r\nb. Employment Facilitation. This component shall provide displaced HEI personnel access\r\nto available job opportunities suitable to the qualifications of the displaced HEI personnel\r\nthrough job matching, referral, and placement services, either local or overseas\r\nemployment, employment coaching and Labor Market Information.\r\n\r\nc. Livelihood Opportunities. This component shall provide displaced HEI personnel with\r\ntraining on how to plan, set up, start and operate their livelihood undertakings; working\r\ncapital in the form of raw materials, equipment, tools and jigs and other support services\r\nnecessary to set up the business; and continuing technical and business advisory services\r\nto ensure efficiency, productivity, and sustainability of the business/enterprise under the\r\nDOLE Integrated Livelihood and Emergency Employment Program.\r\n\r\n* Determined by the Philippine Institute for Development Studies and University of the Philippines Population Institute.\r\nExpanding DOLE Adjustment Measures Program for Displaced Higher Education\r\nInstitution Personnel due to the Implementation of Republic Act No. 10533 Page 3 of 8\r\n\r\n\r\n===== PAGE 4 =====\r\nSection 2. Referral to other Interagency Mitigation Measures. Based on the qualifications and\r\nexpressed interests of displaced HEI personnel, applicants who failed to possess the required\r\neligibilities of the program shall be referred to either CHED (Development Grants), DepEd (Green\r\nLane), or TESDA (Skills Training) for provision of appropriate assistance.\r\nArticle IV\r\nPROGRAM IMPLEMENTATION\r\n\r\nSection 1. General Procedural Guidelines. The following general procedural guidelines shall\r\nbe observed in the implementation of the program components:\r\n\r\na. Eligibility Requirements. Displaced HEI! personnel applying for K to 12 DOLE AMP (1)\r\nmust be displaced between 30 May 2014\' and the end of Academic Year 2021-22, (2)\r\nmust not be excluded from this program as provided under Section 4, Article II of this\r\nDepartment Order, and (3) if totally displaced, must be unemployed at the date of\r\napplication.\r\n\r\nb. Documentary Requirements. Photocopies of the following documentary requirements\r\nmust be submitted together with a duly accomplished K to 12 DOLE AMP Application\r\nForm:\r\n\r\ni. Certificate of Displacement; or copy of complaint duly received by NLRC in case\r\nthe beneficiary has filed a case before the NLRC;\r\n\r\nii. | Certificate of Employment and Compensation; and\r\n\r\niii | Any government-issued ID.\r\n\r\nFurther, original copies of documentary requirements shall be presented for validation and\r\nshall be returned to the applicant.\r\n\r\nc. Application Procedures\r\n\r\ni. K to 12 DOLE AMP Application Form shall only be deemed duly accomplished\r\nonce all information on required fields have been supplied.\r\n\r\nii. Applications with complete documentary requirements shall be submitted\r\npersonally to any DOLE Regional or Field Offices not later than one (1) year from\r\nthe date of displacement.” Applications received by DOLE Field Offices shall be\r\nforwarded to the appropriate DOLE Regional Office within two (2) working days\r\nfrom receipt thereof.\r\n\r\nii. | Applicants with complete documentary requirements shall immediately be\r\nprovided basic orientation on the program components and availment procedures.\r\n\r\niv. Applications shall be evaluated by the appropriate DOLE Regional Office within\r\nthree (3) working days from receipt thereof. The DOLE Regional Offices may use\r\nEstablishment Termination Reports, HEI Displacement Report, or Verification\r\nReports as references in evaluating the application.\r\n\r\nv. The following documents depending on the status of evaluation shall be issued to\r\nthe applicant by the appropriate DOLE Regional Office within three (3) working\r\ndays through registered mail or through electronic mail from the date thereof:\r\n\r\n1. For denied application, a Notice of Denial.\r\n2. For approved application of totally displaced HEI Personnel, a Notice of\r\nAssistance and Beneficiary Progress Report, and_ Initial Beneficiary\r\nAssessment Form.\r\n3. For approved application of partially and temporarily displaced HEI\r\nPersonnel, a Notice of Assistance and Initial Beneficiary Assessment Form.\r\n‘ Date of signing of the DOLE-DepEd-TESDA-CHED Joint Guidelines in the implementation of the Labor and Management Component\r\nof Republic Act No. 10533.\r\n? HEI Personnel displaced prior to the issuance of this Department Order shall be given within one (1) year from the issuance thereof\r\nto apply for the assistance.\r\nExpanding DOLE Adjustment Measures Program for Displaced Higher Education\r\nInstitution Personnel due to the Implementation of Republic Act No. 10533 Page 4 of 8\r\n\r\n\r\n===== PAGE 5 =====\r\nd. Denial of Application. An application may be denied by the DOLE Regional Director upon\r\ndetermination of any of the following grounds:\r\n\r\ni. — Ineligibility of applicant;\r\n\r\nii. | Misrepresentation of facts in the application’; or\r\n\r\niii. | Submission of falsified or tampered document.\r\nSection 2. Component-Specific Procedural Guidelines. Upon approval of the application by\r\nthe Regional Director and upon receipt of the Notice of Assistance and Beneficiary Progress\r\nReport by the beneficiary, the following procedures shall be observed based on desired program\r\ncomponents:\r\n\r\na. Initial Financial Support. The appropriate DOLE Regional Office shall deposit the first\r\ntranche of financial support directly to the beneficiary’s Land Bank of the Philippines\r\naccount at the end of the reference month. Beneficiaries with applications submitted\r\nbeyond the fifth day of the reference month will receive their first tranche of financial\r\nsupport on the next schedule of release the following month.\r\n\r\nb. Conditional Requirements for Subsequent Tranches. Every 15\" day of each month,\r\nor the next working day if the 15\" day falls on a holiday or non-working day, beneficiaries\r\nshall submit to the appropriate DOLE Regional or Field Office their Beneficiary Progress\r\nReport with one (1) proof of active search for employment or job contact through personal\r\nor online submissions of job applications or interviews to continuously receive financial\r\nsupport which shall be released every end of reference month. Only accomplished\r\nBeneficiary Progress Reports shall be accepted by DOLE Regional or Field Offices to be\r\nevaluated within three (3) working days from receipt thereof.\r\n\r\nc. Non-Compliance. Failure to submit an accomplished Beneficiary Progress Report with\r\nproof of job contact warrants the suspension of the financial support through a Notice of\r\nForfeiture which shall be issued to the beneficiary within three (3) working days from the\r\ndeadline of submission through registered mail or electronic mail. Compliance to the\r\nrequirement of the Notice of Forfeiture within three (3) working days from receipt thereof\r\nshall merit the release of the suspended financial support on the following month. Non-\r\ncompliance shall automatically forfeit the financial support for the reference month.\r\n\r\nd. Completion. Beneficiaries under the totally displaced status who receive all approved\r\nfinancial support or obtain a subsequent full-time wage employment successfully complete\r\nthe program and shall be provided a Notice of Completion within three (3) working days\r\nthrough registered mail or through electronic mail upon completion and submission of the\r\nFinal Beneficiary Assessment Form. For those under the partially and temporarily\r\ndisplaced status, an Impact Assessment Form shall be administered to measure the\r\nchanges that took place three (3) months after availment of the Financial Support.\r\n\r\ne. Employment Services. The appropriate DOLE Regional Office shall refer beneficiaries\r\nto the nearest Public Employment Peso Offices (PESO) for the provision of a full-cycle\r\nemployment facilitation. Beneficiaries who intend to find subsequent local and overseas\r\nwage employment shall be referred to appropriate employers with job vacancies matching\r\ntheir qualifications. Simultaneously, beneficiaries shall be provided employment coaching\r\nand relevant labor market information.\r\n\r\nf. Livelihood Opportunities. The DOLE Integrated Livelihood and Emergency Employment\r\n(DILEEP) Guidelines shall be observed in the facilitation of this program component.\r\nBeneficiaries who desire to avail of this component shall comply with the component-\r\nspecific requirements and eligibilities set by the DILEEP Guidelines.\r\n\r\n\' Fraudulent misrepresentation or false statement that will have a negative effect in the evaluation of the application which was\r\nmade knowingly, or without belief in its truth, or recklessly whether it is true or false.\r\n\r\nExpanding DOLE Adjustment Measures Program for Displaced Higher Education\r\n\r\nInstitution Personnel due to the Implementation of Republic Act No. 10533 Page 5 of 8\r\n\r\n\r\n===== PAGE 6 =====\r\nArticle V\r\nPROGRAM MANAGEMENT\r\nSection 1. DOLE Technical Working Group. The DOLE Technical Working Group (TWG) for\r\nthe K to 12 DOLE Adjustment Measures Program (herein referred to as “DOLE TWG for\r\nK12AMP’”) shall ensure the soundness of the policies and effectiveness of interventions for HEI\r\npersonnel displaced due to the implementation of Republic Act No. 10533. The DOLE TWG for\r\nK12AMP, chaired by the Undersecretary for Employment and Policy Support Cluster, shall be\r\ncomposed of the following DOLE bureaus and agencies:\r\na. Bureau of Local Employment (BLE);\r\nb. Bureau of Workers with Special Concern;\r\nc. Financial and Management Service;\r\nd. Information and Publication Service;\r\ne. Legal Service;\r\nf. Planning Service; and\r\ng. Institute for Labor Studies.\r\nSection 2. Program Management Office. A Program Management Office (PMO) established at\r\nthe DOLE-BLE, under the supervision of the BLE Director, shall oversee program implementation\r\nat the national and regional level. The PMO shall:\r\na. Provide the necessary technical and administrative support services to program\r\nimplementers to ensure the efficient and effective implementation of the program;\r\nb. Maintain a management information system, an internal monitoring system, and control\r\nmechanism to ensure attainment of the program objectives;\r\nc. Develop information, education, and communication materials and other promotional\r\nresources to boost program visibility and information reach;\r\nd. Conduct advocacy campaigns and information dissemination activities;\r\ne. Monitor and evaluate the status of the program implementation;\r\nf. Consolidate monthly reports submitted by DOLE Regional Offices;\r\ng. Recommend policies to the TWG based on reports submitted by DOLE Regional Offices\r\nand evaluations conducted;\r\nh. Submit quarterly progress report to the Secretary within fifteen (15) working days from the\r\nreference quarter; and\r\ni. Submit annual evaluation report to the Secretary.\r\nSection 3. DOLE Regional Office. The DOLE Regional Offices, through the leadership of the\r\nRegional Director, shall create a Regional K to 12 Team to perform the following:\r\na. Monitor displacements through Reports of Potential Displacements’;\r\nb. Facilitate the provision of assistance to displaced personnel;\r\nc. Conduct advocacy campaigns and information dissemination activities;\r\nd. Ensure timely delivery of services to beneficiaries;\r\ne. Coordinate with regional counterparts from DepEd, CHED, and TESDA;\r\nf. Consolidate monthly progress reports submitted by DOLE Field Offices;\r\ng. Recommend policies to the BLE to further improve the program; and\r\nh. Prepare and submit progress reports to BLE, through the PMO, every 10\" day of each\r\nreference month or as the need arises.\r\nThe K to 12 DOLE AMP Focal, under the supervision of the TSSD Chief, shall assist in the overall\r\nprogram management, implementation, and monitoring.\r\nSection 4. DOLE Field Office. The DOLE Field Offices shall:\r\na. Receive applications with complete documentary requirements;\r\nb. Conduct preliminary evaluation of received applications;\r\nc. Orient applicants on the desired program component; and\r\nd. Endorse pre-evaluated applications to the K to 12 DOLE AMP Focal for further review or\r\nfor final approval/denial, whichever is applicable.\r\n‘Includes Establishment Termination Reports, HEI Displacement Report, and displacement reports from CHED or DepEd.\r\nExpanding DOLE Adjustment Measures Program for Displaced Higher Education\r\nInstitution Personnel due to the Implementation of Republic Act No. 10533 Page 6 of 8\r\n\r\n\r\n===== PAGE 7 =====\r\nArticle VI\r\nPROGRAM MONITORING AND EVALUATION\r\nSection 1. Monitoring. To ensure that K to 12 DOLE AMP and its beneficiaries achieve the\r\nprogram objectives, the following monitoring tools shall be utilized:\r\n\r\na. Reports. The DOLE Regional Offices shall prepare and submit within the prescribed\r\nperiod, a monthly program progress report composed of overall regional fund utilization,\r\navailment of assistance, information dissemination activities conducted, program\r\nimplementation issues encountered, and recommendations for policy development.\r\n\r\nAll reports shall be consolidated and evaluated by the BLE, through the PMO, and shall\r\nbe submitted within the prescribed period to the Office of the Undersecretary for\r\nEmployment and Policy Support.\r\n\r\nb. Database. A Management Information System shall be developed to monitor the program\r\nimplementation. The system shall hold the list of displaced personnel, application and\r\navailment status, and fund utilization status. It shall also be used to generate reports\r\nrelative to the program.\r\n\r\nThe system shall be monitored by BLE. Full administrator access shall be given to the\r\nPMO while DOLE Regional and Field Office shall be given limited administrator access.\r\nSection 2. Evaluation. Annual evaluation shall be conducted by the PMO to determine the\r\nsoundness of the policies and effectiveness of the program. Regular meetings of the DOLE TWG\r\nand Interagency Committee shall be conducted to discuss and resolve issues and problems\r\narising from the program implementation, either quarterly or as the need arises.\r\nArticle VIl\r\nBUDGET\r\nThe DOLE Central Office shall allocate appropriate funds, sourced from the K to 12 DOLE AMP\r\nFund under the General Appropriations, for the following items subject to the usual accounting\r\nand auditing rules and regulations:\r\n\r\na. Financial Support component;\r\n\r\nb. Administrative funds to DOLE Regional Offices for the implementation and monitoring of\r\nthe program; and\r\n\r\nc. Administrative funds to the Bureau of Local Employment and K to 12 DOLE AMP Program\r\nManagement Office for the operationalization, implementation, and monitoring of the\r\nprogram, which include the development of a Management Information System.\r\n\r\nFunding for the Livelinood Component shall be sourced from the centrally-managed DOLE\r\nAdjustment Measures Program Funds.\r\n\r\nArticle VIII\r\nMISCELLANEOUS PROVISIONS\r\n\r\nSection 1. Retroactive Clause. This Department Order shall be retroactive from 30 May 2014\r\nuntil the effectivity of this Department Order insofar as it does not prejudice nor impair vested or\r\nacquired rights in accordance with the Labor Code of the Philippines, as amended, and other\r\npertinent laws. Existing beneficiaries and those who have completed the program shall receive\r\ndifferential financial support based on the new financial support computation.\r\nSection 2. Separability Clause. If any portion or provision of this Order is declared void or\r\nunconstitutional, the remaining portions or provisions thereof shall not be affected by such\r\ndeclaration.\r\n\r\nExpanding DOLE Adjustment Measures Program for Displaced Higher Education\r\n\r\nInstitution Personnel due to the Implementation of Republic Act No. 10533 Page 7 of 8\r\n\r\n\r\n===== PAGE 8 =====\r\nSection 3. Repealing Clause. The DOLE Department Order No. 152-16 entitled “Guidelines in\r\nthe Implementation of K to 12 DOLE Adjustment Measures Program” and other relevant\r\nissuances inconsistent with this Department Order are hereby repealed accordingly.\r\nSection 4. Effectivity. This Department Order shall take effect fifteen (15) days after its\r\npublication in the Official Gazette or in at least two newspapers of general circulation.\r\nApproved this _!0\"_ day of July, 2017.\r\nSl : O\r\nSecretary\r\nDept. of Labor & Employment\r\n; Office of the Secretary\r\n\r\nExpanding DOLE Adjustment Measures Program for Displaced Higher Education\r\nInstitution Personnel due to the Implementation of Republic Act No. 10533 Page 8 of 8','2026-08-13 14:57:18'),
(19,'Department Order','Department Order No. 195, Series of 2018','Rule Amending Section 10 of Rule VIII on Wage Reduction',NULL,NULL,NULL,'Department of Labor and Employment (DOLE)','active','wage reduction, wage decrease, wage reduction rules, Department Order No. 130, Series of 2013, wage deductions, labor standards, employment conditions, employer-employee agreement, DOLE, wage compliance',NULL,'modules/compliance/assets/law_reference/ra_9504_tax_exemptions_minimum_wage_earners.pdf','Labor Code of the Philippines; Department Order No. 130, Series of 2013, as amended; applicable wage and labor standards laws and regulations','Amends Section 10 of Rule VIII of Department Order No. 130, Series of 2013, as amended, concerning the rules and conditions governing wage reduction. The Order provides the applicable framework for employers seeking to implement wage reduction measures while maintaining compliance with labor standards and protecting affected workers.','Department Order No. 195, Series of 2018. Complete extracted source text is stored in full_text. Use this reference together with the current Labor Code, wage orders and subsequent DOLE issuances when evaluating present-day wage reduction compliance.',NULL,NULL,'2026-08-13 19:42:43','RULE AMENDING SECTION 10 OF RULE VIII OF DEPARTMENT ORDER NO. 130, SERIES OF 2013, AS AMENDED, ON WAGE REDUCTION','Department Order','Department of Labor and Employment (DOLE)','Department Order No. 195','2018','Department Order No. 195, Series of 2018 amends Section 10 of Rule VIII of Department Order No. 130, Series of 2013, as amended, on wage reduction. It establishes the rules governing circumstances in which an employer may implement a reduction in wages or related compensation, with emphasis on compliance with applicable labor standards, lawful procedures and the rights of affected employees. The amendment is intended to clarify the regulatory requirements for wage reduction arrangements and to prevent unilateral or unauthorized reduction of compensation contrary to labor laws and regulations. For HR compliance purposes, the Order should be considered when reviewing proposed wage reduction arrangements, employer cost-adjustment measures, employee compensation changes and related labor standards documentation. Employers must ensure that any wage reduction is implemented only under the conditions and procedures permitted by the governing rules and that applicable minimum wage and other mandatory labor standards are not violated.','DO-195-18-Rule-Amending-Section-10-of-Rule-VIII-of-the-Implementing-Rules-and-Regulations-of-the-Labor-Code-on-Wage-Reduction (1).pdf','===== PAGE 1 =====\r\nRepublic of the Philippines i)\r\n“ DEPARTMENT OF LABOR AND EMPLOYMENT\r\nx * 2 Intramuros, Manila AJA AB\r\nWore than al : prcoces\r\nW\'s dl ole ertificate No.: AJA15-0048\r\nDEPARTMENT ORDER NO. \\95\r\nSeries of 2018\r\nRULE AMENDING SECTION 10 OF RULE Vill OF THE IMPLEMENTING\r\nRULES AND REGULATIONS OF THE LABOR CODE ON WAGE DEDUCTION\r\nPursuant to Article 113 (c) of the Labor Code of the Philippines, as\r\nrenumbered, authorizing the Secretary of Labor and Employment to issue\r\nregulations on wage deduction, and Section 10 of Rule VIII of the Implementing\r\nRules and Regulations of Book III of the Labor Code, this issuance is hereby issued\r\namending the rules on wage deduction for the guidance of all concerned:\r\n1. AMENDED RULE ON WAGE DEDUCTION\r\nSection 10 (b) (Wage deduction) of Rule Vill (Payment of Wages) is hereby\r\namended, as follows:\r\n“SEC. 10. Wage deduction. — Deductions from the wages of the employees\r\nmay be made by the employer in any of the following:\r\na. XXX xX XX X X X\r\nb. When the deductions are with written authorization of the employees for\r\npayment to THE EMPLOYER or a third person and the employer agrees\r\nto do so, provided that the latter does not receive any pecuniary benefit,\r\ndirectly or indirectly, from the transaction.”\r\nli. NON-DIMINUTION OF BENEFIT\r\nNothing in this issuance shall be construed to cause the diminution or\r\nsubstitution of any benefits and privileges currently enjoyed by the employee at the\r\ntime of the issuance hereof.\r\nlll. REPEALING CLAUSE\r\nAll policies, rules, orders and other issuances inconsistent with the provisions\r\nof this issuance are hereby repealed or modified accordingly.\r\nIV. COMPLIANCE AND ENFORCEMENT\r\nThe DOLE Regional Offices shall inspect and monitor the proper\r\nimplementation of this issuance.\r\n\r\n\r\n===== PAGE 2 =====\r\nV. EFFECTIVITY\r\nThis issuance shall take effect fifteen days after its publication in a newspaper\r\nof general circulation.\r\nManila, Philippines, 21 3*Y _—, 2018\r\nSs ; |\r\nSecretary\r\nDept. of Labor & Employment\r\nOffice of the Secretary\r\nUNO A TAT\r\n028653 ee\r\n2','2026-08-13 15:05:52'),
(20,'Republic Act','Republic Act No. 6727','Wage Rationalization Act',1,'1989-06-09',NULL,'Congress of the Philippines','Active','Republic Act No. 6727, RA 6727, Wage Rationalization Act, wage rationalization, minimum wage, regional minimum wage, wage determination, wage rates, National Wages and Productivity Commission, NWPC, Regional Tripartite Wages and Productivity Board, RTWPB, wage board, wage distortion, basic wage, statutory minimum wage, wage order, salary, compensation, labor standards, productivity, gain sharing, wage incentives, Department of Labor and Employment, DOLE','https://lawphil.net/statutes/repacts/ra1989/ra_6727_1989.html','modules/compliance/assets/law_reference/ra_6727_wage_rationalization_act.pdf','Presidential Decree No. 442, Labor Code of the Philippines, as amended; Republic Act No. 8188; applicable Wage Orders issued by Regional Tripartite Wages and Productivity Boards; applicable Department of Labor and Employment regulations','Republic Act No. 6727, known as the Wage Rationalization Act, established the Philippine system for rationalizing wage policy and determining statutory minimum wages. It amended Article 99 of the Labor Code and incorporated provisions creating the National Wages and Productivity Commission and the Regional Tripartite Wages and Productivity Boards.\r\n\r\nThe law provides the institutional framework for determining regional minimum wage rates and directs the wage-setting system to consider regional differences in the cost of living, socio-economic conditions, productivity, and national development objectives.\r\n\r\nRA 6727 also addresses wage distortion, wage incentives, productivity improvement, gain-sharing, and the preservation of existing wage rates and benefits.','This law is a primary legal reference for minimum wage compliance. The actual minimum wage applicable to an employee should be determined using the current Wage Order issued by the appropriate Regional Tripartite Wages and Productivity Board.\r\n\r\nHRMS wage monitoring should therefore link RA 6727 with current regional Wage Orders rather than storing one fixed national minimum wage.\r\n\r\nFor employees in Region III, the applicable wage rate should be obtained from the current Regional Wage Order covering the relevant classification, industry, location, and establishment.\r\n\r\nThe law also provides the legal framework for addressing wage distortion and establishing mechanisms for wage determination.\r\n\r\nRA 6727 should be read together with the Labor Code, current DOLE regulations, NWPC guidelines, and applicable regional Wage Orders.',1,1,'2026-08-13 17:23:31','Republic Act No. 6727 – Wage Rationalization Act','Republic Act','Congress of the Philippines','R.A. No. 6727','1989','An Act to rationalize wage policy determination by establishing the mechanism and proper standards for determining minimum wages, amending Article 99 and incorporating Articles 120, 121, 122, 123, 124, 126 and 127 into the Labor Code of the Philippines, fixing new wage rates, providing wage incentives for industrial dispersal to the countryside, and for other purposes.','ra_6727_wage_rationalization_act.pdf','REPUBLIC ACT NO. 6727\r\n\r\nWAGE RATIONALIZATION ACT\r\n\r\nAN ACT TO RATIONALIZE WAGE POLICY DETERMINATION BY ESTABLISHING THE MECHANISM AND PROPER STANDARDS THEREFOR, AMENDING FOR THE PURPOSE ARTICLE 99 OF, AND INCORPORATING ARTICLES 120, 121, 122, 123, 124, 126 AND 127 INTO, PRESIDENTIAL DECREE NO. 442, AS AMENDED, OTHERWISE KNOWN AS THE LABOR CODE OF THE PHILIPPINES, FIXING NEW WAGE RATES, PROVIDING WAGE INCENTIVES FOR INDUSTRIAL DISPERSAL TO THE COUNTRYSIDE, AND FOR OTHER PURPOSES\r\n\r\nSECTION 1. SHORT TITLE\r\n\r\nThis Act shall be known as the \"Wage Rationalization Act.\"\r\n\r\nSECTION 2. DECLARATION OF POLICY\r\n\r\nIt is hereby declared to be the policy of the State to rationalize the fixing of minimum wages and to promote productivity-improvement and gain-sharing measures to ensure a decent standard of living for workers and their families.\r\n\r\nThe State shall guarantee the rights of labor to its just share in the fruits of production, enhance employment generation in the countryside through industry dispersal, and allow business and industry reasonable returns on investment, expansion, and growth.\r\n\r\nThe State shall promote collective bargaining as the primary mode of settling wages and other terms and conditions of employment.\r\n\r\nWhenever necessary, minimum wage rates shall be adjusted in a fair and equitable manner, taking into consideration existing regional disparities in the cost of living and other socio-economic factors and the national economic and social development plans.\r\n\r\nSECTION 3. AMENDMENT OF THE LABOR CODE\r\n\r\nArticle 99 of Presidential Decree No. 442, as amended, is amended and Articles 120, 121, 122, 123, 124, 126 and 127 are incorporated into the Labor Code.\r\n\r\nARTICLE 99. REGIONAL MINIMUM WAGES\r\n\r\nThe minimum wage rates for agricultural and non-agricultural employees and workers in each region of the country shall be those prescribed by the Regional Tripartite Wages and Productivity Boards.\r\n\r\nNATIONAL WAGES AND PRODUCTIVITY COMMISSION\r\n\r\nThe Act establishes the National Wages and Productivity Commission.\r\n\r\nThe Commission is attached to the Department of Labor and Employment for policy and program coordination.\r\n\r\nThe Commission serves as the national consultative and advisory body on matters relating to wages, incomes, and productivity.\r\n\r\nPOWERS AND FUNCTIONS OF THE COMMISSION\r\n\r\nThe Commission shall provide policy guidance concerning wages, incomes, and productivity.\r\n\r\nIt shall review regional wage levels and establish policies and guidelines for the determination of appropriate minimum wage rates.\r\n\r\nIt shall coordinate with the Regional Tripartite Wages and Productivity Boards.\r\n\r\nThe Commission may conduct studies and develop programs relating to wages, productivity, and income distribution.\r\n\r\nREGIONAL TRIPARTITE WAGES AND PRODUCTIVITY BOARDS\r\n\r\nRegional Tripartite Wages and Productivity Boards are established for the determination of regional minimum wage rates.\r\n\r\nEach Regional Board considers economic and social conditions in its respective region.\r\n\r\nThe Regional Boards may issue Wage Orders prescribing minimum wage rates applicable to workers within their respective territorial jurisdictions.\r\n\r\nWAGE DETERMINATION\r\n\r\nRegional wage determination shall consider factors including the needs of workers and their families, the prevailing wage levels, cost of living, productivity, inflation, employment generation, and the capacity of employers to pay.\r\n\r\nRegional disparities in economic conditions may result in different minimum wage rates among regions.\r\n\r\nSTATUTORY MINIMUM WAGE\r\n\r\nThe statutory minimum wage is the lowest wage rate fixed by law that an employer may pay a worker.\r\n\r\nEmployers must comply with the minimum wage rate applicable to their establishment and employees.\r\n\r\nThe applicable rate depends on the current Wage Order and the employee and establishment classification covered by that Wage Order.\r\n\r\nBASIC WAGE\r\n\r\nBasic wage refers to remuneration or earnings paid by an employer to a worker for services rendered on normal working days and hours.\r\n\r\nThe definition excludes certain allowances, profit-sharing payments, premium payments, thirteenth-month pay, and other monetary benefits that are not considered part of or integrated into the regular salary under the applicable rules.\r\n\r\nWAGE DISTORTION\r\n\r\nWage distortion refers to a situation where an increase in prescribed wage rates results in the elimination or severe contraction of intentional quantitative differences in wage or salary rates between and among employee groups in an establishment.\r\n\r\nThe distortion effectively obliterates distinctions embodied in the wage structure based on skills, length of service, or other logical bases of differentiation.\r\n\r\nWage distortion may arise when a mandated wage increase compresses established salary differentials within an organization.\r\n\r\nEMPLOYER COMPLIANCE\r\n\r\nEmployers must comply with applicable minimum wage rates established through valid Wage Orders.\r\n\r\nAn employer cannot legally pay a covered worker below the applicable statutory minimum wage, subject to lawful exemptions and special rules.\r\n\r\nHR departments should regularly review Wage Orders affecting their establishment.\r\n\r\nWAGE ORDERS\r\n\r\nA Wage Order is an issuance of a Regional Tripartite Wages and Productivity Board prescribing minimum wage rates and related wage adjustments within its jurisdiction.\r\n\r\nThe current Wage Order, rather than RA 6727 alone, determines the actual applicable minimum wage rate.\r\n\r\nEmployers should monitor new Wage Orders and their effectivity dates.\r\n\r\nPRODUCTIVITY IMPROVEMENT\r\n\r\nThe law promotes productivity improvement and gain-sharing measures.\r\n\r\nEmployers and employees may develop productivity improvement programs and incentive schemes consistent with applicable laws and regulations.\r\n\r\nGAIN-SHARING\r\n\r\nGain-sharing programs may provide employees with a share in productivity improvements or economic gains according to applicable arrangements.\r\n\r\nSuch programs should not be used to unlawfully replace statutory minimum wages or mandatory benefits.\r\n\r\nWAGE INCENTIVES\r\n\r\nThe Act provides a framework for wage incentives intended to promote productivity and industrial development.\r\n\r\nEmployers may implement incentive programs consistent with applicable labor laws and regulations.\r\n\r\nCOLLECTIVE BARGAINING\r\n\r\nThe State recognizes collective bargaining as an important mechanism for determining wages and other employment conditions.\r\n\r\nCollective bargaining agreements may establish wages and benefits above statutory minimum requirements.\r\n\r\nNo agreement may lawfully reduce mandatory minimum labor standards.\r\n\r\nPRESERVATION OF EXISTING BENEFITS\r\n\r\nNothing in the Act shall be construed to reduce existing wage rates, allowances, or benefits provided under existing laws, decrees, issuances, executive orders, contracts, or agreements.\r\n\r\nExisting benefits should therefore be protected when implementing wage adjustments.\r\n\r\nWAGE COMPLIANCE MONITORING\r\n\r\nEmployers should maintain payroll and compensation records demonstrating compliance with applicable wage requirements.\r\n\r\nHR and payroll systems should monitor:\r\n\r\n1. Employee basic wage;\r\n2. Daily wage rate;\r\n3. Monthly salary;\r\n4. Applicable regional wage;\r\n5. Current Wage Order;\r\n6. Wage Order effectivity date;\r\n7. Employee classification;\r\n8. Establishment classification;\r\n9. Applicable exemptions;\r\n10. Wage adjustment history;\r\n11. Wage distortion analysis;\r\n12. Payroll compliance;\r\n13. Salary differentials;\r\n14. Productivity incentives;\r\n15. Wage-related employee complaints.\r\n\r\nREGIONAL APPLICATION\r\n\r\nMinimum wage rates are determined regionally.\r\n\r\nThe applicable rate may differ depending on the region, sector, industry, establishment size, and classification covered by the applicable Wage Order.\r\n\r\nFor an HRMS operating in Region III, the system should reference the current Wage Order issued by the Regional Tripartite Wages and Productivity Board for Region III.\r\n\r\nThe applicable Wage Order should be stored separately from RA 6727 because the Wage Order provides the actual current rate.\r\n\r\nRELATIONSHIP WITH THE LABOR CODE\r\n\r\nRA 6727 amended the Labor Code framework for wage determination and incorporated provisions creating the National Wages and Productivity Commission and Regional Tripartite Wages and Productivity Boards.\r\n\r\nThe Act therefore forms part of the legal foundation of the Philippine minimum wage system.\r\n\r\nREPUBLIC ACT NO. 8188\r\n\r\nRepublic Act No. 8188 subsequently amended the penalty provisions related to violations of prescribed wage increases and adjustments.\r\n\r\nThe HRMS legal reference should therefore link RA 6727 with RA 8188 when monitoring wage compliance and penalties.\r\n\r\nEMPLOYEE PROTECTION\r\n\r\nThe law seeks to ensure that workers receive wages consistent with applicable statutory minimum requirements.\r\n\r\nEmployers should ensure that wage adjustments are properly reflected in payroll records and employee compensation.\r\n\r\nCOMPLIANCE AUDIT\r\n\r\nDuring a compliance audit, HR should be able to demonstrate:\r\n\r\n1. The applicable regional Wage Order;\r\n2. The effective date of the Wage Order;\r\n3. The applicable employee classification;\r\n4. The employee basic wage;\r\n5. The minimum wage requirement;\r\n6. Payroll computation;\r\n7. Wage adjustment records;\r\n8. Applicable exemption documents where relevant;\r\n9. Wage distortion assessment where applicable;\r\n10. Documentation of corrective actions.\r\n\r\nEFFECTIVITY\r\n\r\nThe Act provides that it shall take effect fifteen days after complete publication in the Official Gazette or in at least two national newspapers of general circulation, whichever comes earlier.\r\n\r\nApproved: June 9, 1989.','2026-08-13 15:48:14'),
(22,'DOLE Handbook','Workers Statutory Monetary Benefits Handbook','DOLE Handbook on Workers Statutory Monetary Benefits',1,'2024-01-01',NULL,'Department of Labor and Employment','Active','DOLE Handbook, Workers Statutory Monetary Benefits, statutory benefits, labor standards, minimum wage, holiday pay, premium pay, overtime pay, night shift differential, service charges, service incentive leave, maternity leave, paternity leave, solo parent leave, VAWC leave, special leave for women, thirteenth month pay, separation pay, retirement pay, ECC, SSS, PhilHealth, Pag-IBIG, wage compliance, payroll compliance, labor standards compliance','https://nwpc.dole.gov.ph/wp-content/uploads/2024/11/Workers-Statutory-Monetary-Benefits-Handbook-2024-Edition.pdf','modules/compliance/assets/law_reference/dole_handbook_workers_statutory_monetary_benefits_2024.pdf','Labor Code of the Philippines, as amended; Presidential Decree No. 851; Republic Act No. 6727; Republic Act No. 9504; Republic Act No. 10653; Republic Act No. 11210; Republic Act No. 11360; applicable DOLE Department Orders; applicable Wage Orders; SSS, PhilHealth and Pag-IBIG laws and regulations','The Handbook on Workers Statutory Monetary Benefits is a Department of Labor and Employment reference publication intended to provide employers and workers with practical guidance on statutory labor benefits and labor standards. The 2024 Edition incorporates recent developments in labor standards, wage orders, statutory benefits, and related regulations.\r\n\r\nThe handbook provides guidance on minimum wage, holiday pay, premium pay, overtime pay, night shift differential, service charges, service incentive leave, maternity leave, paternity leave, parental leave for solo parents, leave for victims of violence against women and their children, special leave for women, thirteenth month pay, separation pay, retirement pay, and social protection benefits.\r\n\r\nThe handbook also provides explanations, eligibility requirements, computation guidelines, examples, frequently asked questions, and references useful for employer compliance and employee awareness.','This handbook should be treated as an official DOLE compliance reference and practical guide rather than as a substitute for the laws, regulations, Wage Orders, and other issuances that establish the actual legal requirements.\r\n\r\nThe 2024 Edition contains updates on labor standards and includes references to recent wage orders. It also incorporates updates concerning Department Order No. 242, Series of 2024, which revised the rules and regulations concerning service charges.\r\n\r\nFor HRMS implementation, the handbook should be linked to the individual laws and issuances that govern each benefit.\r\n\r\nThe actual minimum wage should be obtained from the applicable current Regional Wage Order.\r\n\r\nCurrent SSS, PhilHealth, Pag-IBIG, BIR, DOLE, and other government rules should be used when calculating present-day statutory deductions and benefits.',1,1,'2026-08-13 17:23:31','DOLE Handbook on Workers Statutory Monetary Benefits - 2024 Edition','DOLE Handbook','Department of Labor and Employment - Bureau of Working Conditions','Workers Statutory Monetary Benefits Handbook','2024','The 2024 Edition of the Handbook on Workers Statutory Monetary Benefits provides updated guidance on Philippine labor standards and statutory monetary benefits for private sector workers. It contains information on wage-related benefits, leave benefits, termination benefits, retirement benefits, social protection benefits, and other mandatory labor standards.','dole_handbook_workers_statutory_monetary_benefits_2024.pdf','DOLE HANDBOOK ON WORKERS STATUTORY MONETARY BENEFITS\r\n\r\n2024 EDITION\r\n\r\nDEPARTMENT OF LABOR AND EMPLOYMENT\r\n\r\nBUREAU OF WORKING CONDITIONS\r\n\r\nPURPOSE OF THE HANDBOOK\r\n\r\nThe Handbook on Workers Statutory Monetary Benefits is published by the Department of Labor and Employment through the Bureau of Working Conditions.\r\n\r\nThe handbook provides practical information concerning statutory labor standards and monetary benefits applicable to workers.\r\n\r\nThe handbook is intended to assist workers, employers, human resource practitioners, students, and other stakeholders in understanding and complying with labor standards.\r\n\r\nMINIMUM WAGE\r\n\r\nThe handbook provides guidance concerning statutory minimum wage.\r\n\r\nMinimum wage rates are determined through the regional wage-setting system.\r\n\r\nThe applicable minimum wage depends on the current Wage Order issued by the appropriate Regional Tripartite Wages and Productivity Board.\r\n\r\nThe HRMS should therefore use the current Wage Order when validating minimum wage compliance.\r\n\r\nHOLIDAY PAY\r\n\r\nHoliday pay refers to the payment required for covered employees during regular holidays in accordance with applicable labor standards.\r\n\r\nThe amount depends on whether the employee works or does not work on the holiday and whether other circumstances such as a rest day are involved.\r\n\r\nThe payroll system should identify the type of holiday and the employee work status before computing holiday pay.\r\n\r\nPREMIUM PAY\r\n\r\nPremium pay applies to work performed within periods covered by special days, rest days, or other circumstances requiring additional compensation.\r\n\r\nThe applicable premium rate depends on the nature of the day and the work performed.\r\n\r\nOVERTIME PAY\r\n\r\nOvertime pay is additional compensation for work performed beyond the normal eight-hour workday.\r\n\r\nThe applicable overtime rate is based on the employee basic hourly rate and the circumstances under which the overtime work was performed.\r\n\r\nThe HRMS should record regular working hours, overtime hours, overtime date, and applicable premium factors.\r\n\r\nNIGHT SHIFT DIFFERENTIAL\r\n\r\nNight shift differential is additional compensation for work performed during the legally covered nighttime period.\r\n\r\nThe statutory night shift differential is generally at least ten percent of the regular wage for each hour of work performed during the covered period.\r\n\r\nThe payroll system should separately record night shift differential hours.\r\n\r\nSERVICE CHARGES\r\n\r\nService charges are subject to applicable rules governing their collection and distribution.\r\n\r\nThe handbook incorporates updates concerning service charges, including Department Order No. 242, Series of 2024.\r\n\r\nThe HRMS should maintain service charge records separately from ordinary wages.\r\n\r\nSERVICE INCENTIVE LEAVE\r\n\r\nQualified employees may be entitled to service incentive leave in accordance with applicable labor standards.\r\n\r\nThe statutory service incentive leave generally consists of five days with pay after the employee has rendered at least one year of service, subject to applicable rules and exclusions.\r\n\r\nThe HRMS should monitor leave eligibility, leave credits, leave usage, and leave conversion where applicable.\r\n\r\nMATERNITY LEAVE\r\n\r\nMaternity leave benefits are governed by Republic Act No. 11210, known as the 105-Day Expanded Maternity Leave Law, and its implementing rules.\r\n\r\nCovered female employees are entitled to maternity leave benefits subject to the requirements and conditions of applicable law.\r\n\r\nThe HRMS should maintain maternity leave records and coordinate employer records with applicable SSS requirements.\r\n\r\nPATERNITY LEAVE\r\n\r\nQualified married male employees may be entitled to paternity leave under Republic Act No. 8187.\r\n\r\nThe statutory paternity leave benefit is subject to the eligibility requirements and conditions established by law.\r\n\r\nSOLO PARENT LEAVE\r\n\r\nQualified solo parents may be entitled to leave benefits under applicable solo parent legislation.\r\n\r\nThe HRMS should verify solo parent eligibility and maintain appropriate supporting documentation.\r\n\r\nLEAVE FOR VICTIMS OF VIOLENCE AGAINST WOMEN AND THEIR CHILDREN\r\n\r\nQualified employees may receive leave benefits under Republic Act No. 9262.\r\n\r\nThe leave is intended for employees who are victims of violence against women and their children and is subject to the conditions established by law.\r\n\r\nSPECIAL LEAVE FOR WOMEN\r\n\r\nQualified female employees may be entitled to special leave under Republic Act No. 9710 and related provisions concerning women workers.\r\n\r\nThe applicable leave entitlement and requirements must be evaluated according to current regulations.\r\n\r\nTHIRTEENTH MONTH PAY\r\n\r\nCovered rank-and-file employees are generally entitled to thirteenth month pay under Presidential Decree No. 851 and applicable implementing rules.\r\n\r\nThe general computation is based on one-twelfth of the total basic salary earned during the calendar year.\r\n\r\nThe HRMS should accumulate basic salary throughout the year and calculate the corresponding thirteenth month pay.\r\n\r\nSEPARATION PAY\r\n\r\nSeparation pay may be required when employment is terminated for authorized causes under the Labor Code and applicable regulations.\r\n\r\nThe amount depends on the applicable authorized cause and the employee circumstances.\r\n\r\nThe HRMS should identify the legal basis for separation before calculating separation pay.\r\n\r\nRETIREMENT PAY\r\n\r\nQualified employees may be entitled to retirement pay under the Labor Code or applicable retirement plans, company policies, collective bargaining agreements, or other lawful arrangements.\r\n\r\nThe applicable retirement benefit should be determined using the governing law and employment arrangements.\r\n\r\nSOCIAL SECURITY BENEFITS\r\n\r\nThe handbook provides information concerning social security benefits.\r\n\r\nThe HRMS should maintain appropriate employee records and coordinate statutory contribution information with current SSS requirements.\r\n\r\nPHILHEALTH BENEFITS\r\n\r\nPhilHealth benefits are governed by applicable social health insurance laws, regulations, and PhilHealth issuances.\r\n\r\nThe HRMS should use the current PhilHealth contribution rules and benefit policies when processing payroll and benefits.\r\n\r\nPAG-IBIG BENEFITS\r\n\r\nPag-IBIG benefits and contributions are governed by applicable HDMF laws and regulations.\r\n\r\nThe HRMS should use current Pag-IBIG contribution requirements when calculating employee and employer contributions.\r\n\r\nEMPLOYER COMPLIANCE\r\n\r\nEmployers should maintain accurate payroll and employment records showing compliance with statutory labor standards.\r\n\r\nRecords should include:\r\n\r\n1. Employee information;\r\n2. Employment status;\r\n3. Basic wage;\r\n4. Minimum wage classification;\r\n5. Wage Order;\r\n6. Working hours;\r\n7. Overtime;\r\n8. Holiday work;\r\n9. Rest day work;\r\n10. Night shift work;\r\n11. Leave credits;\r\n12. Thirteenth month pay;\r\n13. Separation pay;\r\n14. Retirement information;\r\n15. SSS contributions;\r\n16. PhilHealth contributions;\r\n17. Pag-IBIG contributions;\r\n18. Other statutory benefits.\r\n\r\nPAYROLL COMPLIANCE\r\n\r\nThe payroll system should calculate statutory benefits using the applicable current legal rules.\r\n\r\nThe HRMS should not permanently hard-code historical rates because Wage Orders and statutory contribution rates may change.\r\n\r\nEach calculation should be associated with the applicable legal basis and effective date.\r\n\r\nWAGE ORDER MONITORING\r\n\r\nMinimum wage rates are subject to regional Wage Orders.\r\n\r\nThe HRMS should maintain:\r\n\r\n1. Region;\r\n2. Wage Order number;\r\n3. Date issued;\r\n4. Effectivity date;\r\n5. Employee classification;\r\n6. Industry classification;\r\n7. Minimum daily wage;\r\n8. Status.\r\n\r\nThis allows payroll to determine the correct minimum wage for each employee.\r\n\r\nBENEFIT ELIGIBILITY\r\n\r\nEach statutory benefit should have eligibility rules.\r\n\r\nThe HRMS should identify whether the employee is:\r\n\r\n1. Regular;\r\n2. Probationary;\r\n3. Project-based;\r\n4. Seasonal;\r\n5. Casual;\r\n6. Part-time;\r\n7. Rank-and-file;\r\n8. Managerial;\r\n9. Supervisory;\r\n10. Other applicable classifications.\r\n\r\nEligibility should then be evaluated against the applicable law.\r\n\r\nCOMPLIANCE AUDIT\r\n\r\nThe HRMS should support compliance audits by maintaining historical payroll and benefit records.\r\n\r\nAuditors should be able to determine:\r\n\r\n1. Applicable legal requirement;\r\n2. Applicable effective date;\r\n3. Employee classification;\r\n4. Wage rate;\r\n5. Benefit entitlement;\r\n6. Computation;\r\n7. Payment;\r\n8. Supporting documentation;\r\n9. Any adjustment;\r\n10. Corrective action.\r\n\r\nLEGAL REFERENCES\r\n\r\nThe handbook should be linked to the Labor Code and relevant legislation.\r\n\r\nImportant related references include:\r\n\r\nPresidential Decree No. 442;\r\nPresidential Decree No. 851;\r\nRepublic Act No. 6727;\r\nRepublic Act No. 8187;\r\nRepublic Act No. 9262;\r\nRepublic Act No. 9710;\r\nRepublic Act No. 11210;\r\nRepublic Act No. 11360;\r\nDOLE Department Orders;\r\nRegional Wage Orders;\r\nSSS regulations;\r\nPhilHealth regulations;\r\nPag-IBIG regulations.\r\n\r\nCURRENTNESS OF INFORMATION\r\n\r\nThe handbook provides a consolidated guide but individual laws and government issuances may be amended after publication.\r\n\r\nFor this reason, the HRMS should maintain separate records for newer laws, regulations, Wage Orders, and government issuances.\r\n\r\nThe handbook should serve as a reference layer rather than the sole source for automated payroll calculations.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS should store the handbook document together with:\r\n\r\n1. Publication year;\r\n2. Issuing agency;\r\n3. Source URL;\r\n4. Document path;\r\n5. Document version;\r\n6. Date issued;\r\n7. Related laws;\r\n8. Related regulations;\r\n9. Status.\r\n\r\nVERSION CONTROL\r\n\r\nThe HRMS should allow multiple editions of the handbook to be stored.\r\n\r\nOlder editions should not be deleted because they may be relevant when reviewing historical payroll or compliance periods.\r\n\r\nEach edition should have a separate record and publication year.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThe handbook is an informational and compliance reference.\r\n\r\nFor legal determinations, the actual text of the applicable law, regulation, Wage Order, Department Order, and current government issuance should be consulted.\r\n\r\nCurrent government regulations should prevail over outdated handbook information.\r\n\r\n2024 EDITION UPDATES\r\n\r\nThe 2024 Edition includes updates and developments in labor standards and regulations.\r\n\r\nIt includes links to recent Wage Orders reflecting increased minimum wage rates for private sector workers and updated monthly minimum wage information for domestic workers.\r\n\r\nThe edition also incorporates updates concerning Department Order No. 242, Series of 2024, regarding service charge rules.\r\n\r\nThe handbook provides summaries of statutory benefits, computation guidance, frequently asked questions, and updated DOLE regional office contact information.\r\n\r\nSOURCE\r\n\r\nDepartment of Labor and Employment.\r\n\r\nBureau of Working Conditions.\r\n\r\nHandbook on Workers Statutory Monetary Benefits, 2024 Edition.','2026-08-13 15:55:06'),
(23,'Republic Act','Republic Act No. 11210','105-Day Expanded Maternity Leave Law',1,'2019-02-20',NULL,'Congress of the Philippines','Active','Republic Act No. 11210, RA 11210, 105-Day Expanded Maternity Leave Law, Expanded Maternity Leave Law, maternity leave, maternity benefit, 105 days, 60 days, solo parent, 15 additional days, 30 days extension, SSS maternity benefit, salary differential, miscarriage, emergency termination of pregnancy, female workers, pregnancy, parental leave, maternity protection, DOLE, SSS, PhilHealth','https://lawphil.net/statutes/repacts/ra2019/ra_11210_2019.html','modules/compliance/assets/law_reference/ra_11210_105_day_expanded_maternity_leave_law.pdf','Republic Act No. 1161, as amended; Social Security Act; Republic Act No. 8972; Republic Act No. 8187; Republic Act No. 9710; Republic Act No. 11058; Republic Act No. 9262; applicable SSS regulations; applicable DOLE regulations; Implementing Rules and Regulations of RA 11210','Republic Act No. 11210, known as the 105-Day Expanded Maternity Leave Law, increases maternity leave to 105 days with full pay for covered female workers regardless of the manner of delivery. It also provides an additional 15 days of paid maternity leave for qualified solo parents and an optional additional 30 days of maternity leave without pay.\r\n\r\nThe law provides 60 days of maternity leave with full pay in cases of miscarriage or emergency termination of pregnancy. It also allows a female worker to allocate up to seven days of maternity leave credits to the child father or a qualified alternate caregiver, subject to the requirements of the law.\r\n\r\nThe law applies to covered female workers in the public sector, private sector, informal economy, voluntary SSS contributors, and female national athletes.','The HRMS should treat RA 11210 as the primary legal reference for expanded maternity leave entitlement.\r\n\r\nFor private-sector employees, maternity benefits involve SSS maternity benefits and the employer salary differential when applicable. Eligibility and contribution requirements should be validated against current SSS rules.\r\n\r\nThe system should distinguish live childbirth, miscarriage, and emergency termination of pregnancy because the applicable leave periods differ.\r\n\r\nFor live childbirth, the statutory maternity leave is 105 days with full pay. A qualified solo parent receives an additional 15 days with full pay. A female worker may optionally extend the leave for another 30 days without pay.\r\n\r\nMaternity leave may be availed for every instance of pregnancy, miscarriage, or emergency termination of pregnancy, subject to the applicable rules.\r\n\r\nMaternity leave benefits are protected by security of tenure and non-discrimination provisions. Availment of maternity leave must not be used as a basis for demotion or termination.\r\n\r\nThe HRMS should maintain maternity leave records, eligibility information, SSS contribution information, leave dates, salary differential, allocated leave credits, and supporting documents.',1,1,'2026-08-13 17:23:31','Republic Act No. 11210 - 105-Day Expanded Maternity Leave Law','Republic Act','Congress of the Philippines','R.A. No. 11210','2019','An Act Increasing the Maternity Leave Period to One Hundred Five (105) Days for Female Workers With an Option to Extend for an Additional Thirty (30) Days Without Pay, and Granting an Additional Fifteen (15) Days for Solo Mothers, and for Other Purposes.','ra_11210_105_day_expanded_maternity_leave_law.pdf','REPUBLIC ACT NO. 11210\r\n\r\n105-DAY EXPANDED MATERNITY LEAVE LAW\r\n\r\nPURPOSE\r\n\r\nRepublic Act No. 11210 is known as the 105-Day Expanded Maternity Leave Law.\r\n\r\nThe law increases maternity leave benefits for covered female workers and provides additional protection for pregnant workers and mothers.\r\n\r\nThe law recognizes maternity protection as an important labor and social welfare measure.\r\n\r\nCOVERAGE\r\n\r\nThe law covers qualified female workers in the public sector and private sector.\r\n\r\nCoverage also extends to female workers in the informal economy, voluntary SSS contributors, and female national athletes subject to the requirements of the law.\r\n\r\nThe law applies regardless of civil status and legitimacy of the child.\r\n\r\nMATERNITY LEAVE FOR LIVE CHILDBIRTH\r\n\r\nA covered female worker is entitled to 105 days of maternity leave with full pay for live childbirth.\r\n\r\nThe entitlement applies regardless of whether the delivery is normal or through caesarean section.\r\n\r\nThe maternity leave must be enjoyed continuously and cannot be deferred.\r\n\r\nThe leave may be arranged as a combination of prenatal and postnatal leave provided that the statutory requirements are satisfied.\r\n\r\nPOSTNATAL LEAVE\r\n\r\nThe maternity leave may be divided between prenatal and postnatal periods.\r\n\r\nHowever, the compulsory postnatal leave period must not be less than 60 days.\r\n\r\nMIS CARRIAGE OR EMERGENCY TERMINATION OF PREGNANCY\r\n\r\nA covered female worker is entitled to 60 days of maternity leave with full pay in cases of miscarriage or emergency termination of pregnancy.\r\n\r\nThe benefit is available regardless of the frequency of previous maternity leave availment, subject to the applicable rules.\r\n\r\nSOLO PARENT BENEFIT\r\n\r\nA female worker who qualifies as a solo parent under Republic Act No. 8972 is entitled to an additional 15 days of maternity leave with full pay.\r\n\r\nThe additional 15 days are granted on top of the basic 105 days.\r\n\r\nEXTENDED MATERNITY LEAVE\r\n\r\nA female worker may choose to extend maternity leave for an additional 30 days without pay in cases of live childbirth.\r\n\r\nThe employee must provide written notice to the employer within the period required by the implementing rules.\r\n\r\nIn cases of medical emergency, the required prior notice may be waived, subject to subsequent notice.\r\n\r\nThe additional leave without pay is not considered a gap in service.\r\n\r\nPRIVATE SECTOR BENEFIT\r\n\r\nCovered female workers in the private sector are entitled to maternity leave benefits subject to the requirements of the law and SSS rules.\r\n\r\nFor SSS-covered workers, the maternity benefit is based on the applicable SSS maternity benefit computation.\r\n\r\nThe employer may be responsible for the salary differential between the SSS maternity benefit and the worker full pay, subject to the exceptions and conditions established by law and applicable regulations.\r\n\r\nSSS CONTRIBUTION REQUIREMENT\r\n\r\nFor private-sector SSS-covered workers, eligibility for the SSS maternity benefit generally requires at least three monthly contributions within the 12-month period immediately preceding the semester of childbirth, miscarriage, or emergency termination of pregnancy.\r\n\r\nThe SSS determines the applicable maternity benefit based on its contribution and benefit rules.\r\n\r\nThe HRMS should therefore validate contribution information using current SSS regulations.\r\n\r\nEMPLOYER ADVANCEMENT\r\n\r\nThe maternity benefit may be advanced by the employer in accordance with the requirements of the law and applicable SSS rules.\r\n\r\nThe employer may subsequently receive reimbursement from SSS subject to the submission and approval of required documentation.\r\n\r\nSALARY DIFFERENTIAL\r\n\r\nFor covered private-sector employees, full pay may consist of the SSS maternity benefit and the salary differential payable by the employer when applicable.\r\n\r\nThe salary differential is the difference between the employee full pay and the applicable SSS maternity benefit.\r\n\r\nThe HRMS should separately record the SSS maternity benefit and employer salary differential.\r\n\r\nEXEMPTIONS FROM SALARY DIFFERENTIAL\r\n\r\nCertain employers may qualify for exemptions from the salary differential requirement under the conditions provided by law and applicable DOLE rules.\r\n\r\nThese may include distressed establishments, qualifying retail or service establishments and other enterprises with not more than 10 workers, qualifying micro-business enterprises, and employers already providing similar or more beneficial benefits.\r\n\r\nAny exemption must be validated according to current DOLE rules.\r\n\r\nALLOCATION OF MATERNITY LEAVE CREDITS\r\n\r\nA female worker may allocate up to seven days of maternity leave benefits to the child father.\r\n\r\nIf the father is deceased, absent, or incapacitated, the leave may be allocated to a qualified alternate caregiver as allowed by law.\r\n\r\nThe alternate caregiver may include a relative within the fourth degree of consanguinity or the current partner of the female worker who shares the same household, subject to the applicable requirements.\r\n\r\nThe allocation is separate from and in addition to the benefit under the Paternity Leave Act.\r\n\r\nDEATH OR PERMANENT INCAPACITY\r\n\r\nIf the female worker dies or becomes permanently incapacitated, the balance of the maternity leave benefits may accrue to the child father or a qualified alternate caregiver subject to the conditions provided by law.\r\n\r\nThe HRMS should maintain records of remaining maternity leave credits where applicable.\r\n\r\nMATERNITY LEAVE AFTER TERMINATION OF EMPLOYMENT\r\n\r\nMaternity leave with full pay may still be granted when childbirth, miscarriage, or emergency termination of pregnancy occurs not more than 15 calendar days after termination of employment, subject to the conditions provided by law.\r\n\r\nIf employment was terminated without just cause, additional employer obligations may apply.\r\n\r\nThe HRMS should therefore retain maternity eligibility records even when an employee has separated from employment within the relevant period.\r\n\r\nSECURITY OF TENURE\r\n\r\nA female worker who avails of maternity leave is protected by security of tenure.\r\n\r\nMaternity leave cannot be used as a basis for demotion or termination.\r\n\r\nAny transfer or reassignment must not reduce rank, status, salary, or otherwise result in constructive dismissal.\r\n\r\nNON-DISCRIMINATION\r\n\r\nEmployers must not discriminate against women in employment to avoid the maternity benefits provided by law.\r\n\r\nThe recruitment and employment processes should not be structured to avoid statutory maternity obligations.\r\n\r\nPUBLIC SECTOR\r\n\r\nFemale workers in government service are covered by the maternity leave provisions.\r\n\r\nThe law covers employees in National Government Agencies, Local Government Units, Government-Owned or Controlled Corporations, and State Universities and Colleges subject to the applicable rules.\r\n\r\nPublic-sector employees are generally entitled to 105 days of maternity leave with full pay for live childbirth.\r\n\r\nQualified solo parents receive an additional 15 days with full pay.\r\n\r\nAn additional 30 days without pay may be availed at the option of the employee.\r\n\r\nTEACHING PROFESSION\r\n\r\nFemale teachers in the public sector may avail of maternity leave in accordance with applicable government rules.\r\n\r\nThe implementing rules recognize maternity leave situations involving school vacation periods.\r\n\r\nThe HRMS should coordinate maternity leave records with the applicable academic and payroll calendar for teaching personnel.\r\n\r\nNATIONAL ATHLETES\r\n\r\nFemale national athletes who become pregnant may receive maternity leave, allowances, and benefits under the provisions of the law.\r\n\r\nMedical assessment may be required to determine fitness to continue training.\r\n\r\nINFORMAL ECONOMY\r\n\r\nFemale workers in the informal economy may qualify for maternity benefits when the statutory SSS contribution requirements are satisfied.\r\n\r\nThe applicable SSS rules should be used when determining eligibility.\r\n\r\nVOLUNTARY SSS CONTRIBUTORS\r\n\r\nFemale voluntary SSS contributors may qualify for maternity benefits subject to the applicable contribution requirements.\r\n\r\nThe HRMS should distinguish voluntary contributor status from regular employed-member status when applicable.\r\n\r\nPHILHEALTH\r\n\r\nHealth care services relating to prenatal care, delivery, postpartum care, and pregnancy-related conditions may be provided under applicable PhilHealth rules.\r\n\r\nThe maternity leave system should therefore be linked to applicable PhilHealth policies where relevant.\r\n\r\nNON-DIMINUTION OF BENEFITS\r\n\r\nRA 11210 does not diminish existing maternity benefits that are more favorable to the female worker.\r\n\r\nBenefits under collective bargaining agreements, company policies, employment contracts, or other laws may continue when they provide more favorable benefits.\r\n\r\nThe HRMS should identify enhanced company maternity benefits separately from the statutory minimum.\r\n\r\nMATERNITY LEAVE FREQUENCY\r\n\r\nMaternity leave is granted for every instance of pregnancy, miscarriage, or emergency termination of pregnancy, subject to the applicable statutory requirements.\r\n\r\nThere is no fixed lifetime limit on the number of maternity leave grants under the law.\r\n\r\nLEAVE REQUEST PROCESS\r\n\r\nThe HRMS should provide a maternity leave request process containing:\r\n\r\n1. Employee ID;\r\n2. Pregnancy status;\r\n3. Expected delivery date;\r\n4. Actual delivery date;\r\n5. Type of maternity event;\r\n6. Requested start date;\r\n7. Requested end date;\r\n8. Maternity leave category;\r\n9. SSS contribution eligibility;\r\n10. Solo parent status;\r\n11. Allocated leave credits;\r\n12. Alternate caregiver information when applicable;\r\n13. Medical supporting documents;\r\n14. Employer approval;\r\n15. Payroll processing status.\r\n\r\nMATERNITY EVENT TYPES\r\n\r\nThe HRMS should distinguish at least the following:\r\n\r\n1. Live childbirth;\r\n2. Miscarriage;\r\n3. Emergency termination of pregnancy.\r\n\r\nThese events have different statutory leave periods.\r\n\r\nLEAVE COMPUTATION\r\n\r\nFor live childbirth:\r\n\r\nStatutory maternity leave = 105 days with full pay.\r\n\r\nQualified solo parent:\r\n\r\n105 days + 15 additional days with full pay.\r\n\r\nOptional extension:\r\n\r\nAdditional 30 days without pay.\r\n\r\nFor miscarriage or emergency termination of pregnancy:\r\n\r\nStatutory maternity leave = 60 days with full pay.\r\n\r\nPAYROLL PROCESSING\r\n\r\nThe payroll system should identify the employee maternity leave period and determine the applicable payment components.\r\n\r\nFor private-sector employees, the system should distinguish:\r\n\r\n1. SSS maternity benefit;\r\n2. Employer salary differential;\r\n3. Full-pay maternity amount;\r\n4. Other company-provided benefits;\r\n5. Unpaid extension, if applicable.\r\n\r\nThe payroll system should not automatically treat the entire maternity benefit as an ordinary salary payment.\r\n\r\nAUDIT TRAIL\r\n\r\nAll maternity leave transactions should be recorded in the HRMS audit trail.\r\n\r\nThe audit record should include:\r\n\r\n1. Employee ID;\r\n2. Leave application;\r\n3. Maternity event;\r\n4. Start date;\r\n5. End date;\r\n6. Number of days;\r\n7. SSS eligibility;\r\n8. Solo parent status;\r\n9. Allocated leave;\r\n10. Salary differential;\r\n11. Approver;\r\n12. Date and time;\r\n13. Supporting documents.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS should allow authorized HR personnel to attach supporting maternity documents.\r\n\r\nDocuments may include maternity leave applications, medical documents, SSS documentation, solo parent documentation, and employer approvals, subject to applicable privacy and records-management requirements.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nHR should monitor:\r\n\r\n1. Maternity leave eligibility;\r\n2. Leave period;\r\n3. SSS contribution requirement;\r\n4. Maternity benefit;\r\n5. Salary differential;\r\n6. Solo parent additional leave;\r\n7. Extended unpaid leave;\r\n8. Allocated leave credits;\r\n9. Payment status;\r\n10. Supporting documents.\r\n\r\nPENALTIES\r\n\r\nFailure or refusal to comply with RA 11210 may result in penalties provided by the law.\r\n\r\nThe law provides fines and imprisonment for violations.\r\n\r\nCorporate officers and responsible persons may be held liable under the circumstances specified by law.\r\n\r\nIMPLEMENTING RULES\r\n\r\nThe Civil Service Commission, Department of Labor and Employment, and Social Security System issued implementing rules and regulations for the effective implementation of RA 11210.\r\n\r\nThe HRMS should maintain the implementing rules as a related legal reference.\r\n\r\nLEGAL REFERENCES\r\n\r\nThe HRMS should link RA 11210 with:\r\n\r\n1. Republic Act No. 1161, as amended;\r\n2. Republic Act No. 8972;\r\n3. Republic Act No. 8187;\r\n4. Republic Act No. 9710;\r\n5. Republic Act No. 9262;\r\n6. Republic Act No. 11058;\r\n7. SSS regulations;\r\n8. DOLE regulations;\r\n9. PhilHealth regulations;\r\n10. Implementing Rules and Regulations of RA 11210.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nRA 11210 should be read together with its implementing rules and current SSS, DOLE, CSC, and PhilHealth regulations.\r\n\r\nThe HRMS should not hard-code historical SSS contribution rates or benefit formulas.\r\n\r\nCurrent SSS regulations should control the actual maternity benefit calculation.\r\n\r\nThe statutory maternity leave periods established by RA 11210 should be maintained as the legal baseline unless a subsequent law or valid regulation provides otherwise.','2026-08-13 15:56:37'),
(24,'Implementing Rules and Regulations','IRR of Republic Act No. 11210','Implementing Rules of the 105-Day Expanded Maternity Leave Law',1,'2019-05-01',NULL,'Department of Labor and Employment; Civil Service Commission; Social Security System; Commission on Human Rights','Active','RA 11210 IRR, 105-Day Expanded Maternity Leave Law, maternity leave, expanded maternity leave, 105 days, 60 days, solo parent, 15 additional days, 30 days unpaid extension, SSS maternity benefit, salary differential, miscarriage, emergency termination of pregnancy, maternity benefit, female workers, private sector, public sector, informal economy, SSS, DOLE, CSC, maternity leave allocation, alternate caregiver','https://lawphil.net/statutes/repacts/ra2019/irr_11210_2019.html','modules/compliance/assets/law_reference/irr_ra_11210_105_day_expanded_maternity_leave.pdf','Republic Act No. 11210; Republic Act No. 11199; Republic Act No. 8972; Republic Act No. 8187; Republic Act No. 9710; applicable SSS regulations; applicable DOLE regulations; applicable Civil Service Commission rules','The Implementing Rules and Regulations of Republic Act No. 11210 provide the detailed rules for implementing the 105-Day Expanded Maternity Leave Law.\r\n\r\nThe IRR applies to covered female workers in the public sector, private sector, informal economy, voluntary SSS membership, and female national athletes.\r\n\r\nIt provides 105 days of maternity leave with full pay for live childbirth, 60 days with full pay for miscarriage or emergency termination of pregnancy, an additional 15 days with full pay for qualified solo parents, and an optional additional 30 days without pay for live childbirth.\r\n\r\nFor private-sector employees covered by SSS, full pay consists of the SSS maternity benefit and salary differential payable by the employer when applicable.','This IRR should be linked directly to Republic Act No. 11210 and used as the detailed implementation reference for the maternity leave module.\r\n\r\nThe HRMS should distinguish between live childbirth, miscarriage, and emergency termination of pregnancy because the applicable leave periods differ.\r\n\r\nFor private-sector employees, the system should separately track SSS maternity benefit and employer salary differential.\r\n\r\nQualified solo parents should receive the additional 15 days with full pay.\r\n\r\nA female worker may allocate up to seven days of maternity leave benefits to the childs father or a qualified alternate caregiver subject to the requirements of the IRR.\r\n\r\nThe optional additional 30 days of maternity leave is without pay and applies to live childbirth.\r\n\r\nCurrent SSS rules should be used for actual maternity benefit computation and contribution validation.',1,1,'2026-08-13 17:23:31','Implementing Rules and Regulations of Republic Act No. 11210 - 105-Day Expanded Maternity Leave Law','Implementing Rules and Regulations','Department of Labor and Employment; Civil Service Commission; Social Security System; Commission on Human Rights','IRR of RA No. 11210','2019','Implementing Rules and Regulations of Republic Act No. 11210, otherwise known as the 105-Day Expanded Maternity Leave Law.','irr_ra_11210_105_day_expanded_maternity_leave.pdf','IMPLEMENTING RULES AND REGULATIONS OF REPUBLIC ACT NO. 11210\r\n\r\n105-DAY EXPANDED MATERNITY LEAVE LAW\r\n\r\nGENERAL PROVISIONS\r\n\r\nThese rules and regulations implement Republic Act No. 11210, otherwise known as the 105-Day Expanded Maternity Leave Law.\r\n\r\nThe rules recognize the need to protect the rights and welfare of working women and provide an enabling environment that supports maternal functions, health, employment security, and family welfare.\r\n\r\nCOVERAGE\r\n\r\nThe Expanded Maternity Leave Law and its implementing rules cover:\r\n\r\n1. Female workers in the public sector;\r\n2. Female workers in the private sector;\r\n3. Female workers in the informal economy;\r\n4. Female members who are voluntary contributors to SSS;\r\n5. Female national athletes.\r\n\r\nThe rules apply regardless of civil status, employment status, and legitimacy of the child, subject to the applicable requirements.\r\n\r\nMATERNITY LEAVE FOR LIVE CHILDBIRTH\r\n\r\nA qualified female worker is entitled to 105 days of maternity leave with full pay for live childbirth.\r\n\r\nThe 105-day benefit applies regardless of the manner of delivery.\r\n\r\nThe maternity leave may be taken through a combination of prenatal and postnatal leave provided that the statutory requirements are satisfied.\r\n\r\nThe postnatal period must not be less than 60 days.\r\n\r\nMIS CARRIAGE AND EMERGENCY TERMINATION OF PREGNANCY\r\n\r\nA qualified female worker is entitled to 60 days of maternity leave with full pay in cases of miscarriage or emergency termination of pregnancy.\r\n\r\nThe maternity leave benefit for these circumstances is separate from the 105-day live childbirth benefit.\r\n\r\nFREQUENCY OF MATERNITY LEAVE\r\n\r\nMaternity leave is granted for every instance of pregnancy, miscarriage, or emergency termination of pregnancy regardless of frequency, subject to the requirements of the law.\r\n\r\nSOLO PARENT BENEFIT\r\n\r\nA female worker who qualifies as a solo parent under applicable law is entitled to an additional 15 days of maternity leave with full pay.\r\n\r\nThe additional 15 days are granted on top of the 105 days for live childbirth.\r\n\r\nEXTENDED MATERNITY LEAVE\r\n\r\nA female worker may choose to extend maternity leave for an additional 30 days without pay in cases of live childbirth.\r\n\r\nThe employee must provide written notice to the employer within the period required by the implementing rules.\r\n\r\nThe additional unpaid leave does not constitute a gap in service.\r\n\r\nIn cases of medical emergency, prior notice may not be required, subject to subsequent notice.\r\n\r\nSECURITY OF TENURE\r\n\r\nAn employee who avails of maternity leave benefits shall be assured of security of tenure.\r\n\r\nMaternity leave cannot be used as a basis for demotion or termination.\r\n\r\nTransfer or reassignment may be permitted when it does not result in reduction of rank, status, salary, or constructive dismissal.\r\n\r\nNON-DISCRIMINATION\r\n\r\nEmployers must not discriminate against women in employment to avoid the maternity benefits provided by law.\r\n\r\nEmployers must comply with maternity protection requirements regardless of the employee employment status covered by the law.\r\n\r\nPUBLIC SECTOR\r\n\r\nQualified female workers in National Government Agencies, Local Government Units, Government-Owned or Controlled Corporations, State Universities and Colleges, and Local Universities and Colleges may be covered by the public-sector maternity leave rules.\r\n\r\nQualified female workers are generally entitled to 105 days with full pay for live childbirth.\r\n\r\nQualified solo parents receive an additional 15 days with full pay.\r\n\r\nAn optional additional 30 days without pay may be availed for live childbirth.\r\n\r\nTEACHING PROFESSION\r\n\r\nFemale teachers may avail of maternity leave even during long school vacations such as summer and Christmas vacation, subject to applicable rules.\r\n\r\nWhere applicable, maternity leave benefits and proportional vacation pay may be granted according to the governing rules.\r\n\r\nPUBLIC-SECTOR PAYMENT\r\n\r\nFor public-sector employees, full maternity leave pay is generally paid by the government agency through the applicable payroll system.\r\n\r\nThe employee may receive the benefit through regular salary payment or other authorized payment arrangements.\r\n\r\nPRIVATE SECTOR\r\n\r\nQualified female workers in the private sector covered by SSS are entitled to maternity leave benefits subject to the contribution and notification requirements.\r\n\r\nThe employee must satisfy the applicable SSS contribution requirements.\r\n\r\nSSS MATERNITY CONTRIBUTION REQUIREMENT\r\n\r\nA qualified female worker generally needs at least three monthly SSS contributions within the 12-month period immediately preceding the semester of childbirth, miscarriage, or emergency termination of pregnancy.\r\n\r\nOnly contributions paid before the semester of contingency are considered for determining entitlement under the applicable SSS rules.\r\n\r\nMATERNITY NOTIFICATION\r\n\r\nThe female worker should notify the employer of the pregnancy and probable date of childbirth.\r\n\r\nThe employer is responsible for transmitting the required notification to SSS through the prescribed process.\r\n\r\nFailure of the employee to notify the employer does not automatically bar entitlement to maternity benefits when the other statutory requirements are satisfied.\r\n\r\nSALARY DIFFERENTIAL\r\n\r\nFor covered private-sector employees, full pay consists of the SSS maternity benefit and salary differential payable by the employer when applicable.\r\n\r\nThe salary differential represents the difference between the employee full salary and the applicable SSS maternity benefit.\r\n\r\nThe HRMS should separately record the SSS benefit and salary differential.\r\n\r\nEMPLOYER ADVANCEMENT\r\n\r\nThe employer advances the maternity benefit to the qualified employed female worker according to the requirements of the law and applicable SSS rules.\r\n\r\nSSS reimbursement is subject to the submission of satisfactory and legally required proof.\r\n\r\nSALARY DIFFERENTIAL EXEMPTIONS\r\n\r\nCertain private-sector employers may qualify for exemption from paying the salary differential when the statutory requirements are satisfied.\r\n\r\nPotential qualifying categories include certain distressed establishments, qualified retail and service establishments with not more than ten workers, qualifying micro-business enterprises, and employers that already provide similar or more beneficial maternity benefits through a collective bargaining agreement, company policy, or established practice.\r\n\r\nThe employer must provide the required proof and obtain the applicable DOLE approval when required.\r\n\r\nINFORMAL ECONOMY\r\n\r\nFemale workers in the informal economy may qualify for maternity benefits when they satisfy the applicable SSS contribution requirements.\r\n\r\nThe maternity benefit is subject to the rules governing SSS-covered workers.\r\n\r\nVOLUNTARY SSS MEMBERS\r\n\r\nFemale voluntary SSS members may qualify for maternity benefits subject to the applicable contribution and eligibility requirements.\r\n\r\nThe HRMS should distinguish voluntary membership from employer-covered membership.\r\n\r\nALLOCATION OF MATERNITY LEAVE\r\n\r\nA female worker may allocate up to seven days of maternity leave benefits to the childs father.\r\n\r\nThe allocation may be made whether or not the father is married to the female worker.\r\n\r\nThe allocated leave is separate from the paternity leave provided under Republic Act No. 8187.\r\n\r\nALTERNATE CAREGIVER\r\n\r\nIf the childs father is deceased, absent, or incapacitated, the female worker may allocate maternity leave credits to a qualified alternate caregiver.\r\n\r\nThe alternate caregiver may include a relative within the fourth civil degree of consanguinity or the current partner who shares the same household, subject to the requirements of the law.\r\n\r\nThe allocation option does not apply in cases of miscarriage or emergency termination of pregnancy.\r\n\r\nDEATH OR PERMANENT INCAPACITY\r\n\r\nIf the female worker dies or becomes permanently incapacitated, the remaining maternity leave benefits may accrue to the childs father or qualified alternate caregiver subject to the requirements of the implementing rules.\r\n\r\nAppropriate proof such as a death certificate or medical documentation may be required.\r\n\r\nNATIONAL ATHLETES\r\n\r\nFemale national athletes who become pregnant may be referred to an appropriate physician to determine their fitness to continue training.\r\n\r\nThey may be allowed to continue team activities when medically appropriate.\r\n\r\nWhen maternity leave is required, the female national athlete may continue receiving applicable allowances and benefits subject to the rules.\r\n\r\nMATERNITY LEAVE AFTER TERMINATION\r\n\r\nMaternity leave with full pay may still be granted when childbirth, miscarriage, or emergency termination of pregnancy occurs within 15 calendar days after termination of employment, subject to the conditions of the implementing rules.\r\n\r\nWhen employment is illegally terminated due to pregnancy, additional employer liabilities may arise.\r\n\r\nPENDING ADMINISTRATIVE CASE\r\n\r\nMaternity leave benefits may still be enjoyed by qualified female workers even when there is a pending administrative case.\r\n\r\nThe existence of an administrative case does not automatically remove the statutory maternity leave entitlement.\r\n\r\nNON-DIMINUTION OF BENEFITS\r\n\r\nNothing in the implementing rules should diminish maternity benefits already provided through collective bargaining agreements, company policies, employment contracts, or other applicable laws when such benefits are more favorable to the female worker.\r\n\r\nHRMS IMPLEMENTATION\r\n\r\nThe HRMS maternity module should record:\r\n\r\n1. Employee ID;\r\n2. Employee classification;\r\n3. Employment status;\r\n4. Pregnancy event;\r\n5. Expected delivery date;\r\n6. Actual delivery date;\r\n7. Maternity leave type;\r\n8. Leave start date;\r\n9. Leave end date;\r\n10. Number of maternity leave days;\r\n11. Solo parent status;\r\n12. SSS membership status;\r\n13. SSS contribution eligibility;\r\n14. SSS maternity benefit;\r\n15. Employer salary differential;\r\n16. Full-pay amount;\r\n17. Optional unpaid extension;\r\n18. Allocated leave days;\r\n19. Father or alternate caregiver;\r\n20. Supporting documents;\r\n21. Approval status;\r\n22. Payroll status.\r\n\r\nMATERNITY EVENT TYPES\r\n\r\nThe HRMS should provide separate classifications for:\r\n\r\n1. Live childbirth;\r\n2. Miscarriage;\r\n3. Emergency termination of pregnancy.\r\n\r\nThese classifications are necessary because the statutory leave periods are different.\r\n\r\nPAYROLL PROCESSING\r\n\r\nFor a private-sector employee, the payroll module should calculate maternity-related payments separately.\r\n\r\nThe system should identify:\r\n\r\nSSS maternity benefit;\r\nEmployer salary differential;\r\nTotal maternity full pay;\r\nOther company benefits;\r\nUnpaid maternity extension;\r\nApplicable deductions.\r\n\r\nThe maternity benefit should not simply be processed as ordinary salary.\r\n\r\nAUDIT TRAIL\r\n\r\nEvery maternity leave transaction should be recorded in the HRMS audit trail.\r\n\r\nThe audit trail should include:\r\n\r\n1. Employee ID;\r\n2. Application date;\r\n3. Maternity event;\r\n4. Leave period;\r\n5. Number of days;\r\n6. SSS eligibility;\r\n7. SSS benefit;\r\n8. Salary differential;\r\n9. Solo parent status;\r\n10. Allocated leave;\r\n11. Approving officer;\r\n12. Payroll processing date;\r\n13. Adjustments;\r\n14. Supporting documents.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS should allow authorized HR personnel to attach maternity leave documentation.\r\n\r\nDocuments may include maternity leave applications, medical documents, SSS documentation, solo parent documentation, allocation notices, employer approvals, and other legally required records.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nHR should monitor:\r\n\r\n1. Maternity leave eligibility;\r\n2. SSS contribution requirement;\r\n3. Leave period;\r\n4. SSS maternity benefit;\r\n5. Salary differential;\r\n6. Solo parent additional leave;\r\n7. Optional unpaid extension;\r\n8. Allocation of leave credits;\r\n9. Payment status;\r\n10. Supporting documentation.\r\n\r\nDISPUTE RESOLUTION\r\n\r\nDisputes concerning SSS maternity benefits are handled through the applicable Social Security Commission processes.\r\n\r\nDisputes involving salary differential may be brought before the appropriate DOLE office and handled under applicable labor standards enforcement mechanisms.\r\n\r\nPUBLIC-SECTOR DISPUTES\r\n\r\nDisputes concerning public-sector maternity leave full pay may be filed initially with the head of agency and may be appealed through the applicable Civil Service Commission process.\r\n\r\nPENALTIES\r\n\r\nFailure or refusal to comply with RA 11210 and its implementing rules may result in the penalties provided by law.\r\n\r\nThe law provides fines and imprisonment for violations.\r\n\r\nFor organizations, responsible managing heads, directors, partners, or other responsible persons may be held liable under applicable circumstances.\r\n\r\nLEGAL REFERENCES\r\n\r\nThe HRMS should connect this IRR with:\r\n\r\n1. Republic Act No. 11210;\r\n2. Republic Act No. 11199;\r\n3. Republic Act No. 8972;\r\n4. Republic Act No. 8187;\r\n5. Republic Act No. 9710;\r\n6. SSS regulations;\r\n7. DOLE regulations;\r\n8. Civil Service Commission rules;\r\n9. PhilHealth regulations.\r\n\r\nCURRENT IMPLEMENTATION\r\n\r\nThe IRR provides the detailed implementation framework for RA 11210.\r\n\r\nFor actual payroll computation, the HRMS should use current SSS contribution records, SSS maternity benefit rules, current DOLE regulations, and applicable government issuances.\r\n\r\nLEGAL DISCLAIMER\r\n\r\nThis document is an implementation reference for Republic Act No. 11210.\r\n\r\nThe actual legal requirement should be determined from the current law, implementing rules, SSS regulations, DOLE issuances, Civil Service Commission rules, and other applicable government regulations.','2026-08-13 15:57:20'),
(25,'Republic Act','Republic Act No. 8187','Paternity Leave Act of 1996',1,'1996-06-11',NULL,'Congress of the Philippines','Active','Republic Act No. 8187, RA 8187, Paternity Leave Act, Paternity Leave Act of 1996, paternity leave, seven days paternity leave, married male employee, childbirth, miscarriage, spouse, legitimate child, illegitimate child, adoption, private sector, public sector, employee benefits, leave benefits, DOLE, maternity leave','https://lawphil.net/statutes/repacts/ra1996/ra_8187_1996.html','modules/compliance/assets/law_reference/ra_8187_paternity_leave_act.pdf','Republic Act No. 11210; Republic Act No. 8972; Republic Act No. 1161, as amended; Labor Code of the Philippines; applicable DOLE regulations; applicable Civil Service Commission rules','Republic Act No. 8187, known as the Paternity Leave Act of 1996, grants qualified married male employees in the private and public sectors seven days of paternity leave with full pay for the first four deliveries of the legitimate spouse with whom the employee is cohabiting. The benefit may be used for childbirth or miscarriage of the employee spouse.\r\n\r\nThe law provides a paternity leave benefit intended to allow the father to support and care for his wife and newborn child or assist his spouse in cases of miscarriage.','Paternity leave under RA 8187 is separate from maternity leave under RA 11210 and separate from the seven-day maternity leave credits that may be allocated under RA 11210.\r\n\r\nThe statutory benefit is seven days with full pay.\r\n\r\nThe benefit is generally available only to a married male employee whose wife has given birth or suffered a miscarriage.\r\n\r\nThe benefit is limited to the first four deliveries or miscarriages of the legitimate spouse with whom the employee is cohabiting, subject to the statutory requirements.\r\n\r\nThe HRMS should maintain a paternity leave counter to ensure that the employee does not exceed the statutory four-delivery limit.\r\n\r\nThe system should also distinguish paternity leave from other parental and leave benefits available under subsequent legislation.',1,1,'2026-08-13 17:23:31','Republic Act No. 8187 - Paternity Leave Act of 1996','Republic Act','Congress of the Philippines','R.A. No. 8187','1996','An Act Granting Paternity Leave of Seven (7) Days With Full Pay to All Married Male Employees in the Private and Public Sectors for the First Four (4) Deliveries of the Legitimate Spouse With Whom He is Cohabiting and for Other Purposes.','ra_8187_paternity_leave_act.pdf','REPUBLIC ACT NO. 8187\r\n\r\nPATERNITY LEAVE ACT OF 1996\r\n\r\nPURPOSE\r\n\r\nRepublic Act No. 8187 is known as the Paternity Leave Act of 1996.\r\n\r\nThe law grants qualified married male employees seven days of paternity leave with full pay.\r\n\r\nThe purpose of the law is to provide the father with an opportunity to support his wife and care for the newborn child during childbirth or assist his spouse in cases of miscarriage.\r\n\r\nCOVERAGE\r\n\r\nThe law applies to qualified married male employees in both the private and public sectors.\r\n\r\nFor private-sector employees, the benefit is implemented under the labor standards framework and applicable DOLE rules.\r\n\r\nFor public-sector employees, applicable Civil Service Commission rules govern implementation.\r\n\r\nELIGIBILITY\r\n\r\nA male employee may qualify for paternity leave when:\r\n\r\n1. He is married;\r\n2. His wife has given birth or suffered a miscarriage;\r\n3. He is an employee in the private or public sector;\r\n4. He is cohabiting with his legitimate spouse;\r\n5. The childbirth or miscarriage is among the first four deliveries of the legitimate spouse;\r\n6. He complies with the applicable notice and documentation requirements.\r\n\r\nNUMBER OF DAYS\r\n\r\nThe statutory paternity leave benefit is seven days with full pay.\r\n\r\nThe seven days are intended to allow the father to provide care and support to his wife and newborn child.\r\n\r\nFIRST FOUR DELIVERIES\r\n\r\nThe benefit is available for the first four deliveries of the legitimate spouse with whom the employee is cohabiting.\r\n\r\nThe term delivery includes childbirth and miscarriage as recognized under the law and applicable implementing rules.\r\n\r\nThe HRMS should maintain a historical count of qualifying deliveries and miscarriages to determine whether the employee remains eligible.\r\n\r\nFULL PAY\r\n\r\nQualified paternity leave is provided with full pay.\r\n\r\nFor private-sector employees, full pay generally refers to the employees regular daily wage for the period of approved paternity leave, subject to applicable labor standards rules.\r\n\r\nThe HRMS should process the seven days as paid leave when all eligibility requirements are satisfied.\r\n\r\nCOHABITATION\r\n\r\nThe employee must be cohabiting with his legitimate spouse at the time of childbirth or miscarriage.\r\n\r\nThe HRMS should not automatically approve the benefit solely on the basis of marital status.\r\n\r\nAppropriate documentation may be required by the employer to establish eligibility.\r\n\r\nNOTICE REQUIREMENT\r\n\r\nThe employee should notify the employer of the expected date of delivery by the wife.\r\n\r\nThe employee should also notify the employer of the actual date of delivery or miscarriage within the period required by applicable rules.\r\n\r\nEmployers may establish reasonable internal procedures for submitting paternity leave applications provided that these procedures do not defeat the statutory benefit.\r\n\r\nPREGNANCY AND DELIVERY\r\n\r\nThe paternity leave benefit is intended to allow the father to assist his spouse during pregnancy-related childbirth and care for the newborn.\r\n\r\nThe employee should submit the required supporting documentation after the delivery.\r\n\r\nMIS CARRIAGE\r\n\r\nPaternity leave may also apply when the employee spouse suffers a miscarriage, subject to the requirements of the law.\r\n\r\nThe HRMS should allow miscarriage as a separate paternity leave event type.\r\n\r\nThe system should record the date of the miscarriage and supporting documentation while protecting confidential information.\r\n\r\nPRIVATE SECTOR\r\n\r\nQualified private-sector employees are entitled to the statutory seven-day paternity leave with full pay.\r\n\r\nThe employer should include the approved paternity leave in the employee attendance and payroll records.\r\n\r\nThe leave should not be deducted from service incentive leave credits unless specifically permitted by law.\r\n\r\nPUBLIC SECTOR\r\n\r\nQualified government employees are covered by the law subject to applicable Civil Service Commission rules.\r\n\r\nGovernment agencies should implement the leave consistently with the statutory requirements and relevant civil service regulations.\r\n\r\nRELATIONSHIP WITH MATERNITY LEAVE\r\n\r\nPaternity leave is separate from maternity leave.\r\n\r\nMaternity leave under Republic Act No. 11210 is granted to the female worker.\r\n\r\nPaternity leave under Republic Act No. 8187 is granted to the qualified married male employee.\r\n\r\nThe two benefits should therefore be recorded separately in the HRMS.\r\n\r\nRELATIONSHIP WITH RA 11210\r\n\r\nRepublic Act No. 11210 allows a female worker to allocate up to seven days of her maternity leave benefit to the childs father or qualified alternate caregiver under specified conditions.\r\n\r\nThis allocated leave is separate from the seven-day paternity leave under Republic Act No. 8187.\r\n\r\nTherefore, an eligible father may potentially receive the statutory paternity leave under RA 8187 and allocated maternity leave credits under RA 11210, subject to the requirements of both laws.\r\n\r\nThe HRMS should maintain separate leave categories for these benefits.\r\n\r\nADOPTION\r\n\r\nRA 8187 primarily concerns childbirth and miscarriage involving the legitimate spouse.\r\n\r\nAdoption-related leave benefits are governed by other applicable laws and should not automatically be recorded as paternity leave under RA 8187.\r\n\r\nEMPLOYMENT RECORD\r\n\r\nThe HRMS should record:\r\n\r\n1. Employee ID;\r\n2. Employee name;\r\n3. Employment status;\r\n4. Civil status;\r\n5. Spouse information;\r\n6. Marriage information;\r\n7. Expected delivery date;\r\n8. Actual delivery date;\r\n9. Pregnancy event;\r\n10. Paternity leave start date;\r\n11. Paternity leave end date;\r\n12. Number of days used;\r\n13. Number of previous qualifying deliveries;\r\n14. Remaining statutory eligibility;\r\n15. Supporting documents;\r\n16. Approval status;\r\n17. Payroll status.\r\n\r\nLEAVE EVENT TYPES\r\n\r\nThe system should provide:\r\n\r\n1. Childbirth;\r\n2. Miscarriage.\r\n\r\nEach event should be associated with the appropriate supporting documentation.\r\n\r\nFOUR-DELIVERY LIMIT\r\n\r\nThe HRMS should maintain the number of qualifying deliveries or miscarriages for which the employee has previously used paternity leave.\r\n\r\nThe system should prevent automatic approval when the statutory four-delivery limit has already been reached.\r\n\r\nHR personnel should be able to review historical leave records before approving a new application.\r\n\r\nPAYROLL PROCESSING\r\n\r\nApproved paternity leave should be reflected in the employee attendance record.\r\n\r\nThe seven days should be treated as paid leave.\r\n\r\nThe payroll system should calculate the employee regular pay for the approved leave period in accordance with applicable payroll rules.\r\n\r\nPaternity leave should be identified separately from ordinary vacation leave, sick leave, service incentive leave, and other statutory leaves.\r\n\r\nATTENDANCE PROCESSING\r\n\r\nWhen paternity leave is approved:\r\n\r\n1. Attendance status should be marked as Paternity Leave;\r\n2. The approved leave dates should be excluded from absence deductions;\r\n3. The employee should receive the applicable full pay;\r\n4. The leave should be recorded in the employee leave history.\r\n\r\nLEAVE BALANCE\r\n\r\nThe statutory paternity leave entitlement should be tracked separately from other leave balances.\r\n\r\nThe HRMS should not deduct the seven-day paternity leave from the employees service incentive leave balance.\r\n\r\nDOCUMENTATION\r\n\r\nThe employer may require appropriate proof of eligibility.\r\n\r\nDocuments may include:\r\n\r\n1. Marriage certificate;\r\n2. Birth certificate;\r\n3. Medical certificate;\r\n4. Proof of miscarriage;\r\n5. Employee paternity leave application;\r\n6. Other legally appropriate documents.\r\n\r\nSensitive documents should be accessible only to authorized HR personnel.\r\n\r\nAUDIT TRAIL\r\n\r\nAll paternity leave transactions should be recorded in the HRMS audit trail.\r\n\r\nThe audit record should include:\r\n\r\n1. Employee ID;\r\n2. Application date;\r\n3. Leave event;\r\n4. Leave start date;\r\n5. Leave end date;\r\n6. Number of days;\r\n7. Previous qualifying deliveries;\r\n8. Approval decision;\r\n9. Approver;\r\n10. Payroll processing status;\r\n11. Date and time of transaction.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nHR should monitor:\r\n\r\n1. Employee eligibility;\r\n2. Marriage status;\r\n3. Cohabitation requirement;\r\n4. Spouse delivery or miscarriage;\r\n5. Four-delivery limit;\r\n6. Leave dates;\r\n7. Seven-day entitlement;\r\n8. Full-pay processing;\r\n9. Supporting documentation;\r\n10. Payroll treatment.\r\n\r\nEMPLOYER POLICY\r\n\r\nAn employer may establish reasonable internal procedures for filing and documenting paternity leave applications.\r\n\r\nCompany policy may provide benefits more favorable than the statutory minimum.\r\n\r\nThe HRMS should therefore distinguish statutory paternity leave from enhanced company-provided parental benefits.\r\n\r\nNON-DIMINUTION OF BENEFITS\r\n\r\nThe statutory paternity leave benefit should not be interpreted as preventing an employer from providing additional or more favorable leave benefits.\r\n\r\nCollective bargaining agreements, company policies, employment contracts, and established practices may provide additional benefits.\r\n\r\nLEGAL COMPLIANCE\r\n\r\nThe HRMS should link RA 8187 with:\r\n\r\n1. Republic Act No. 11210;\r\n2. Republic Act No. 8972;\r\n3. Labor Code of the Philippines;\r\n4. Applicable DOLE regulations;\r\n5. Applicable Civil Service Commission rules.\r\n\r\nCURRENT IMPLEMENTATION\r\n\r\nRA 8187 should be read together with current DOLE and Civil Service Commission rules.\r\n\r\nThe HRMS should not rely exclusively on historical implementation rules when determining current employee eligibility.\r\n\r\nThe statutory seven-day benefit and four-delivery limitation should remain separately configurable from other leave benefits.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis record is intended as a legal and HR compliance reference.\r\n\r\nFor actual leave administration, the current text of RA 8187, applicable implementing rules, DOLE issuances, Civil Service Commission rules, and other applicable laws should be consulted.\r\n\r\nThe HRMS should maintain an audit trail for any manual override of paternity leave eligibility or computation.','2026-08-13 15:58:07'),
(26,'Republic Act','Republic Act No. 8972','Solo Parents Welfare Act of 2000',1,'2000-11-07',NULL,'Congress of the Philippines','Active','Republic Act No. 8972, RA 8972, Solo Parents Welfare Act, Solo Parents Welfare Act of 2000, solo parent, solo parent benefits, solo parent leave, parental leave, seven days parental leave, flexible work schedule, employment benefits, non-discrimination, child support, family welfare, DOLE, DSWD, solo parent ID, SPIC','https://lawphil.net/statutes/repacts/ra2000/ra_8972_2000.html','modules/compliance/assets/law_reference/ra_8972_solo_parents_welfare_act.pdf','Republic Act No. 11861; Republic Act No. 11210; Republic Act No. 8187; Labor Code of the Philippines; applicable DOLE regulations; DSWD regulations; applicable rules concerning solo parent identification and benefits','Republic Act No. 8972, known as the Solo Parents Welfare Act of 2000, establishes a comprehensive program of services and benefits for solo parents and their children. The law provides employment-related benefits, parental leave, flexible work schedules, protection against discrimination, and other social welfare assistance.\r\n\r\nThe law was subsequently expanded and amended by Republic Act No. 11861, also known as the Expanded Solo Parents Welfare Act. The HRMS should therefore maintain RA 8972 as the historical legal foundation while linking it to the current amended provisions under RA 11861.','RA 8972 originally established the Solo Parents Welfare Act. Republic Act No. 11861 expanded the law and amended several provisions, including the definition and benefits applicable to solo parents.\r\n\r\nFor current HRMS implementation, RA 11861 and its implementing rules should be consulted together with RA 8972.\r\n\r\nQualified solo parents may be entitled to parental leave of up to seven working days with pay every year, subject to the statutory eligibility and service requirements.\r\n\r\nThe HRMS should verify solo parent eligibility and maintain the applicable solo parent documentation.\r\n\r\nThe system should also distinguish statutory parental leave for solo parents from maternity leave, paternity leave, service incentive leave, and other leave benefits.',1,1,'2026-08-13 17:23:31','Republic Act No. 8972 - Solo Parents Welfare Act of 2000','Republic Act','Congress of the Philippines','R.A. No. 8972','2000','An Act Providing for Benefits and Privileges to Solo Parents and Their Children, Appropriating Funds Therefor and for Other Purposes.','ra_8972_solo_parents_welfare_act.pdf','REPUBLIC ACT NO. 8972\r\n\r\nSOLO PARENTS WELFARE ACT OF 2000\r\n\r\nPURPOSE\r\n\r\nRepublic Act No. 8972 is known as the Solo Parents Welfare Act of 2000.\r\n\r\nThe law establishes a comprehensive program of social development and welfare services for solo parents and their children.\r\n\r\nThe law recognizes the special circumstances faced by parents who independently assume parental responsibility.\r\n\r\nOBJECTIVES\r\n\r\nThe law seeks to provide:\r\n\r\n1. Comprehensive social development and welfare services;\r\n2. Employment-related benefits;\r\n3. Parental leave;\r\n4. Flexible work schedules;\r\n5. Protection against discrimination;\r\n6. Educational assistance;\r\n7. Health and social welfare services;\r\n8. Housing assistance;\r\n9. Other appropriate government assistance.\r\n\r\nDEFINITION OF SOLO PARENT\r\n\r\nUnder the original law, a solo parent includes a parent who provides sole parental care and support to a child or children under circumstances recognized by law.\r\n\r\nThe circumstances may include:\r\n\r\n1. A woman who gives birth as a result of rape and raises the child;\r\n2. A parent left solo due to death of the spouse;\r\n3. A parent whose spouse is detained or is serving a sentence for a criminal conviction for at least one year;\r\n4. A parent whose spouse is physically or mentally incapacitated;\r\n5. A parent who is legally separated or separated in fact and has custody of the children;\r\n6. A parent whose marriage has been annulled or declared null and void;\r\n7. A parent who is unmarried and has chosen to keep and rear the child;\r\n8. A person who solely provides parental care and support to a child or children;\r\n9. A family member who assumes responsibility for the child or children because of the death, abandonment, disappearance, or prolonged absence of the parents;\r\n10. A pregnant woman who solely provides and supports the unborn child.\r\n\r\nThe current expanded definitions should be evaluated under Republic Act No. 11861.\r\n\r\nEMPLOYMENT BENEFITS\r\n\r\nSolo parents who are qualified employees may receive employment-related benefits.\r\n\r\nThese benefits are intended to help solo parents balance employment responsibilities with parental responsibilities.\r\n\r\nPARENTAL LEAVE\r\n\r\nA qualified solo parent may be entitled to parental leave of up to seven working days with pay every year.\r\n\r\nThe leave is subject to the eligibility conditions provided by law and applicable regulations.\r\n\r\nThe employee generally needs to have rendered at least one year of service, whether continuous or broken, subject to applicable rules.\r\n\r\nThe leave may be used to attend to parental duties and responsibilities.\r\n\r\nThe HRMS should maintain a separate parental leave balance for qualified solo parents.\r\n\r\nFLEXIBLE WORK SCHEDULE\r\n\r\nQualified solo parents may request a flexible work schedule from their employer.\r\n\r\nThe purpose is to enable the employee to balance work and parental responsibilities.\r\n\r\nFlexible work arrangements should be implemented without compromising productivity and legitimate business requirements.\r\n\r\nThe HRMS may support flexible schedule requests and approval workflows.\r\n\r\nNON-DISCRIMINATION\r\n\r\nEmployers are prohibited from discriminating against employees on the basis of their status as solo parents.\r\n\r\nEmployment decisions involving hiring, promotion, compensation, training, assignment, and termination should not be based on solo parent status.\r\n\r\nThe HRMS should not use solo parent status as a negative employment-performance indicator.\r\n\r\nEMPLOYMENT RECORDS\r\n\r\nThe HRMS should maintain the following information when required:\r\n\r\n1. Employee ID;\r\n2. Solo parent status;\r\n3. Solo parent identification;\r\n4. Date of solo parent certification;\r\n5. Validity period;\r\n6. Number of qualified children;\r\n7. Child information;\r\n8. Custody or parental responsibility information;\r\n9. Parental leave usage;\r\n10. Flexible work schedule arrangements;\r\n11. Supporting documents;\r\n12. Approval status.\r\n\r\nCONFIDENTIALITY\r\n\r\nSolo parent documentation may contain personal and family information.\r\n\r\nAccess should therefore be restricted to authorized HR personnel.\r\n\r\nThe HRMS should implement role-based access controls for solo parent records.\r\n\r\nPARENTAL LEAVE APPLICATION\r\n\r\nThe HRMS should provide a parental leave application containing:\r\n\r\n1. Employee ID;\r\n2. Application date;\r\n3. Leave reason;\r\n4. Leave start date;\r\n5. Leave end date;\r\n6. Number of working days;\r\n7. Remaining balance;\r\n8. Solo parent eligibility;\r\n9. Supporting documentation;\r\n10. Approval status;\r\n11. Payroll status.\r\n\r\nLEAVE BALANCE\r\n\r\nThe system should calculate the employee remaining parental leave balance.\r\n\r\nThe statutory parental leave should be tracked independently from:\r\n\r\n1. Maternity leave;\r\n2. Paternity leave;\r\n3. Service incentive leave;\r\n4. Vacation leave;\r\n5. Sick leave;\r\n6. Special leave;\r\n7. Other company-provided leave.\r\n\r\nMATERNITY LEAVE RELATIONSHIP\r\n\r\nSolo parent status may affect maternity leave benefits under Republic Act No. 11210.\r\n\r\nA qualified solo mother is entitled to an additional 15 days of maternity leave with full pay under RA 11210.\r\n\r\nThe HRMS should therefore link solo parent status with the maternity leave module.\r\n\r\nThe additional 15 days under RA 11210 should not be confused with the seven-day parental leave under the Solo Parents Welfare Act.\r\n\r\nPATERNITY LEAVE RELATIONSHIP\r\n\r\nPaternity leave under Republic Act No. 8187 is separate from solo parent parental leave.\r\n\r\nThe HRMS should maintain separate leave categories.\r\n\r\nCURRENT EXPANDED SOLO PARENT LAW\r\n\r\nRepublic Act No. 11861 expanded and amended the Solo Parents Welfare Act.\r\n\r\nThe expanded law provides additional benefits and broadens the categories of persons who may qualify as solo parents.\r\n\r\nThe HRMS should use RA 11861 for current eligibility and benefits while retaining RA 8972 as the historical legal reference.\r\n\r\nSOLO PARENT IDENTIFICATION\r\n\r\nQualified solo parents may obtain a Solo Parent Identification Card or other official proof of eligibility under applicable government procedures.\r\n\r\nThe HRMS should record the validity period of the applicable solo parent documentation.\r\n\r\nExpired documentation should trigger an HR compliance notification.\r\n\r\nELIGIBILITY VERIFICATION\r\n\r\nThe HRMS should provide a verification workflow.\r\n\r\nHR personnel should be able to review:\r\n\r\n1. Solo parent application;\r\n2. Supporting documents;\r\n3. Child information;\r\n4. Custody or parental responsibility;\r\n5. Solo Parent Identification Card;\r\n6. Certification from the appropriate local government office;\r\n7. Expiration date;\r\n8. Renewal status.\r\n\r\nBENEFIT MONITORING\r\n\r\nThe HRMS should monitor:\r\n\r\n1. Solo parent status;\r\n2. Eligibility;\r\n3. Documentation validity;\r\n4. Parental leave;\r\n5. Flexible work arrangements;\r\n6. Maternity leave additional entitlement;\r\n7. Other applicable benefits.\r\n\r\nAUDIT TRAIL\r\n\r\nAll changes to solo parent records should be recorded in the HRMS audit trail.\r\n\r\nThe audit record should contain:\r\n\r\n1. Employee ID;\r\n2. Previous status;\r\n3. New status;\r\n4. Reason for change;\r\n5. Supporting document;\r\n6. Approving HR officer;\r\n7. Date and time.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe system should allow authorized HR users to store solo parent documents.\r\n\r\nPossible documents include:\r\n\r\n1. Solo Parent Identification Card;\r\n2. Certification of Eligibility;\r\n3. Birth certificates of children;\r\n4. Death certificate of spouse;\r\n5. Medical certification;\r\n6. Court documents;\r\n7. Custody documents;\r\n8. Other supporting documents.\r\n\r\nDocument access must be restricted because these records may contain sensitive family information.\r\n\r\nEMPLOYER COMPLIANCE\r\n\r\nEmployers should maintain policies that recognize qualified solo parent employees.\r\n\r\nHR should ensure that qualified employees are not denied benefits because of their solo parent status.\r\n\r\nCOMPANY POLICY\r\n\r\nEmployers may provide benefits more favorable than the statutory minimum.\r\n\r\nCollective bargaining agreements, company policies, employment contracts, or established company practices may provide additional leave or flexible working arrangements.\r\n\r\nThe HRMS should distinguish statutory benefits from enhanced company benefits.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nThe HRMS should generate alerts for:\r\n\r\n1. Expiring solo parent documentation;\r\n2. Pending solo parent applications;\r\n3. Parental leave requests;\r\n4. Remaining parental leave balance;\r\n5. Flexible work schedule requests;\r\n6. Invalid or incomplete documentation;\r\n7. Renewal requirements.\r\n\r\nPAYROLL PROCESSING\r\n\r\nApproved solo parent parental leave should be processed as paid leave when the employee satisfies statutory requirements.\r\n\r\nThe payroll system should identify the number of approved parental leave days and ensure that the employee is not improperly deducted for the approved leave.\r\n\r\nPAYSLIP\r\n\r\nWhere applicable, the payroll system should display the paid parental leave period separately from regular working days.\r\n\r\nAUDIT AND REPORTING\r\n\r\nThe HRMS should generate reports such as:\r\n\r\n1. Active solo parent employees;\r\n2. Expiring solo parent IDs;\r\n3. Parental leave utilization;\r\n4. Remaining parental leave;\r\n5. Flexible work arrangements;\r\n6. Pending eligibility verification;\r\n7. Compliance exceptions.\r\n\r\nRELATIONSHIP WITH RA 11861\r\n\r\nRepublic Act No. 11861 is an important related law because it expanded the benefits and coverage of solo parents.\r\n\r\nFor current compliance implementation, the HRMS should not rely solely on the original provisions of RA 8972.\r\n\r\nThe system should link this record to RA 11861 and its implementing rules.\r\n\r\nIMPLEMENTING RULES\r\n\r\nThe implementing rules and regulations of the Solo Parents Welfare Act should be maintained as a separate legal reference.\r\n\r\nThe HRMS should use the current implementing rules when validating eligibility and benefit administration.\r\n\r\nLEGAL REFERENCES\r\n\r\nRelated references include:\r\n\r\n1. Republic Act No. 8972;\r\n2. Republic Act No. 11861;\r\n3. Republic Act No. 11210;\r\n4. Republic Act No. 8187;\r\n5. Labor Code of the Philippines;\r\n6. Applicable DOLE issuances;\r\n7. Applicable DSWD regulations;\r\n8. Local government solo parent regulations.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nRepublic Act No. 8972 has been amended by Republic Act No. 11861.\r\n\r\nFor current HRMS implementation, the amended law and its current implementing rules should be consulted.\r\n\r\nThis database record should be retained as a historical legal reference while the current requirements should be sourced from RA 11861 and applicable government issuances.','2026-08-13 15:59:02'),
(27,'Republic Act','Republic Act No. 11861','Expanded Solo Parents Welfare Act',1,'2022-06-04',NULL,'Congress of the Philippines','Active','Republic Act No. 11861, RA 11861, Expanded Solo Parents Welfare Act, solo parent, expanded solo parent, solo parent benefits, solo parent leave, parental leave, seven days parental leave, flexible work schedule, non-discrimination, solo parent ID, Solo Parent Identification Card, SPIC, children, employment benefits, tax benefits, discounts, medical assistance, educational assistance, housing assistance, DSWD, DOLE, social protection','https://lawphil.net/statutes/repacts/ra2022/ra_11861_2022.html','modules/compliance/assets/law_reference/Republic Act No. 11861 - Expanded Solo Parents Welfare Act.pdf','Republic Act No. 8972; Republic Act No. 11210; Republic Act No. 8187; Labor Code of the Philippines; applicable DSWD regulations; applicable DOLE regulations; implementing rules and regulations of RA 11861','Republic Act No. 11861, known as the Expanded Solo Parents Welfare Act, amends Republic Act No. 8972 and expands the coverage, benefits, privileges, and protections available to solo parents and their children. The law broadens the definition of a solo parent and provides employment, leave, tax, medical, educational, housing, and other social protection benefits.\r\n\r\nFor employment purposes, qualified solo parents may be entitled to parental leave of up to seven working days with pay every year, subject to the conditions of the law and implementing rules. The law also provides protection against discrimination and recognizes the need for flexible work arrangements for qualified solo parents.\r\n\r\nThe law also establishes the Solo Parent Identification Card and related certification system and provides additional benefits for qualified solo parents depending on their income, number and age of children, and other statutory conditions.','RA 11861 amended RA 8972 and should be treated as the current expanded statutory framework for solo parent benefits.\r\n\r\nThe HRMS should link this record to RA 8972 as its predecessor and maintain the implementing rules as a separate legal reference.\r\n\r\nThe system should verify solo parent eligibility and maintain the validity of the Solo Parent Identification Card or certification.\r\n\r\nQualified employees may be entitled to up to seven working days of parental leave with pay every year, subject to statutory eligibility and service requirements.\r\n\r\nThe system should distinguish solo parent parental leave from maternity leave under RA 11210 and paternity leave under RA 8187.\r\n\r\nA qualified solo mother may also receive the additional 15 days of maternity leave with full pay under RA 11210, subject to the requirements of that law.\r\n\r\nThe HRMS should also support monitoring of solo parent documentation, leave utilization, flexible work arrangements, and applicable employment benefits.',1,1,'2026-08-13 18:35:22','Republic Act No. 11861 - Expanded Solo Parents Welfare Act','Republic Act','Congress of the Philippines','R.A. No. 11861','2022','An Act Expanding the Coverage of Benefits and Privileges of Solo Parents, Amending for the Purpose Republic Act No. 8972, Otherwise Known as the Solo Parents Welfare Act of 2000, and for Other Purposes.','ra_11861_expanded_solo_parents_welfare_act.pdf','REPUBLIC ACT NO. 11861\r\n\r\nEXPANDED SOLO PARENTS WELFARE ACT\r\n\r\nPURPOSE\r\n\r\nRepublic Act No. 11861 is known as the Expanded Solo Parents Welfare Act.\r\n\r\nThe law amends Republic Act No. 8972, otherwise known as the Solo Parents Welfare Act of 2000.\r\n\r\nThe law expands the coverage and benefits available to solo parents and their children.\r\n\r\nIt recognizes the need to provide comprehensive assistance to solo parents who independently perform parental responsibilities.\r\n\r\nOBJECTIVES\r\n\r\nThe law seeks to provide:\r\n\r\n1. Expanded social protection;\r\n2. Employment benefits;\r\n3. Parental leave;\r\n4. Flexible work arrangements;\r\n5. Protection against discrimination;\r\n6. Health and medical assistance;\r\n7. Educational assistance;\r\n8. Housing assistance;\r\n9. Tax benefits;\r\n10. Discounts and privileges;\r\n11. Other government support.\r\n\r\nDEFINITION OF SOLO PARENT\r\n\r\nThe law expands the circumstances under which a person may qualify as a solo parent.\r\n\r\nA solo parent may include a person who solely exercises parental care and support over a child or children because of circumstances recognized by law.\r\n\r\nThese circumstances include situations involving:\r\n\r\n1. Birth of a child as a result of rape where the mother keeps and raises the child;\r\n2. Death of the spouse;\r\n3. Spouse being detained or serving a sentence for a criminal conviction for at least one year;\r\n4. Physical or mental incapacity of the spouse;\r\n5. Legal separation or separation in fact where the parent has custody of the children;\r\n6. Annulment or declaration of nullity of marriage where the parent has custody of the children;\r\n7. Unmarried parent who chooses to keep and rear the child;\r\n8. Person who solely provides parental care and support to a child;\r\n9. Relative or family member who assumes parental responsibility because the parents are deceased, abandoned the child, disappeared, or are absent;\r\n10. Pregnant woman who provides sole parental care and support to the unborn child;\r\n11. Other circumstances recognized by the expanded law and implementing rules.\r\n\r\nThe current implementing rules should be consulted when determining actual eligibility.\r\n\r\nCHILDREN COVERED\r\n\r\nThe law recognizes children who are dependent on and living with the solo parent and who satisfy the age and dependency requirements provided by law.\r\n\r\nThe HRMS should record the number of qualified children and relevant eligibility information.\r\n\r\nSOLO PARENT IDENTIFICATION CARD\r\n\r\nQualified solo parents may obtain a Solo Parent Identification Card.\r\n\r\nThe card serves as official proof of solo parent status for purposes of claiming applicable benefits.\r\n\r\nThe HRMS should maintain:\r\n\r\n1. Solo Parent ID number;\r\n2. Date issued;\r\n3. Date of expiration;\r\n4. Issuing local government unit;\r\n5. Verification status;\r\n6. Renewal status.\r\n\r\nCERTIFICATION\r\n\r\nSolo parent status should be supported by appropriate certification and documentary evidence.\r\n\r\nThe local government unit or authorized office determines eligibility under applicable procedures.\r\n\r\nThe HRMS should allow authorized HR personnel to record the verification status without replacing the authority of the government issuing office.\r\n\r\nEMPLOYMENT BENEFIT\r\n\r\nA qualified solo parent employee is entitled to parental leave of up to seven working days with pay every year, subject to the statutory conditions.\r\n\r\nThe leave is intended to enable the solo parent to attend to parental duties and responsibilities.\r\n\r\nThe HRMS should maintain a separate solo parent parental leave balance.\r\n\r\nELIGIBILITY FOR PARENTAL LEAVE\r\n\r\nThe employee must satisfy the eligibility requirements established by law and implementing rules.\r\n\r\nThe HRMS should verify the employee solo parent status and required service period before approving statutory parental leave.\r\n\r\nThe employee should maintain valid documentation supporting solo parent status.\r\n\r\nPARENTAL LEAVE DAYS\r\n\r\nThe statutory parental leave benefit is up to seven working days with pay every year.\r\n\r\nThe leave may be used continuously or intermittently as permitted by the applicable rules and employer procedures.\r\n\r\nUnused statutory parental leave should be handled according to the implementing rules.\r\n\r\nFLEXIBLE WORK SCHEDULE\r\n\r\nQualified solo parents may request a flexible work schedule.\r\n\r\nThe purpose is to allow the employee to balance work responsibilities and parental responsibilities.\r\n\r\nThe employer should evaluate the request in accordance with applicable labor standards and operational requirements.\r\n\r\nThe HRMS may provide a workflow for flexible work arrangement requests.\r\n\r\nNON-DISCRIMINATION\r\n\r\nEmployers must not discriminate against employees because of solo parent status.\r\n\r\nSolo parent status should not be used as a basis for:\r\n\r\n1. Hiring discrimination;\r\n2. Denial of promotion;\r\n3. Reduction of compensation;\r\n4. Denial of training;\r\n5. Unlawful reassignment;\r\n6. Termination;\r\n7. Other discriminatory employment action.\r\n\r\nThe HRMS should not use solo parent status as a negative performance factor.\r\n\r\nMATERNITY LEAVE RELATIONSHIP\r\n\r\nRA 11861 should be linked with Republic Act No. 11210.\r\n\r\nA qualified solo mother may be entitled to an additional 15 days of maternity leave with full pay under RA 11210.\r\n\r\nThe additional maternity leave is separate from the seven-day parental leave under RA 11861.\r\n\r\nThe HRMS should maintain separate leave categories.\r\n\r\nPATERNITY LEAVE RELATIONSHIP\r\n\r\nPaternity leave under Republic Act No. 8187 is separate from solo parent parental leave.\r\n\r\nAn employee should not have the two benefits automatically combined into one leave category.\r\n\r\nThe HRMS should maintain separate legal references and leave types.\r\n\r\nTAX BENEFITS\r\n\r\nQualified solo parents may receive tax-related benefits under the conditions established by RA 11861 and applicable tax regulations.\r\n\r\nEligibility may depend on income and other statutory conditions.\r\n\r\nThe payroll system should not automatically apply tax benefits solely based on an employee declaration.\r\n\r\nThe HRMS should require verification of eligibility and apply current BIR rules.\r\n\r\nDISCOUNTS AND PRIVILEGES\r\n\r\nQualified solo parents and their children may receive discounts and other privileges under the conditions established by law.\r\n\r\nThese may include discounts involving selected goods and services for qualified beneficiaries.\r\n\r\nThe exact applicability should be determined using current implementing rules and government regulations.\r\n\r\nMEDICAL BENEFITS\r\n\r\nThe law provides medical assistance and related benefits for qualified solo parents and their children subject to the conditions of the law and applicable government programs.\r\n\r\nThe HRMS may maintain benefit-reference information but should not independently determine eligibility for government medical programs.\r\n\r\nEDUCATIONAL ASSISTANCE\r\n\r\nQualified solo parents and their children may be eligible for educational assistance subject to government program requirements.\r\n\r\nEducational benefits may include scholarships, grants, and other forms of assistance.\r\n\r\nHOUSING ASSISTANCE\r\n\r\nQualified solo parents may be given priority or assistance under applicable government housing programs.\r\n\r\nThe HRMS should record available programs as informational references rather than automatically granting government benefits.\r\n\r\nSOCIAL WELFARE SERVICES\r\n\r\nGovernment agencies may provide social welfare services to qualified solo parents.\r\n\r\nThe Department of Social Welfare and Development and local government units play important roles in implementation.\r\n\r\nEMPLOYER RESPONSIBILITIES\r\n\r\nEmployers should recognize the employment rights of qualified solo parents.\r\n\r\nEmployers should:\r\n\r\n1. Respect parental leave rights;\r\n2. Avoid discrimination;\r\n3. Evaluate flexible work arrangements;\r\n4. Maintain accurate leave records;\r\n5. Protect employee documentation;\r\n6. Provide applicable employment benefits;\r\n7. Maintain compliance records.\r\n\r\nHRMS SOLO PARENT PROFILE\r\n\r\nThe HRMS should include:\r\n\r\n1. Employee ID;\r\n2. Solo parent status;\r\n3. Solo Parent ID;\r\n4. Issuing LGU;\r\n5. Date issued;\r\n6. Expiration date;\r\n7. Number of qualified children;\r\n8. Child information;\r\n9. Eligibility category;\r\n10. Verification status;\r\n11. Supporting documents;\r\n12. Parental leave balance;\r\n13. Flexible work arrangement;\r\n14. Benefit eligibility;\r\n15. Renewal status.\r\n\r\nPARENTAL LEAVE APPLICATION\r\n\r\nThe HRMS should provide a dedicated application containing:\r\n\r\n1. Employee ID;\r\n2. Application date;\r\n3. Leave reason;\r\n4. Leave start date;\r\n5. Leave end date;\r\n6. Number of working days;\r\n7. Remaining balance;\r\n8. Solo Parent ID;\r\n9. Eligibility status;\r\n10. Supporting documents;\r\n11. Approval status;\r\n12. Payroll status.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS should allow authorized HR users to upload supporting documents.\r\n\r\nPossible documents include:\r\n\r\n1. Solo Parent Identification Card;\r\n2. Solo Parent Certification;\r\n3. Birth certificates;\r\n4. Death certificate of spouse;\r\n5. Medical certification;\r\n6. Court orders;\r\n7. Custody documents;\r\n8. Proof of income where required;\r\n9. Other government-issued documents.\r\n\r\nAccess to these records should be restricted.\r\n\r\nDOCUMENT EXPIRATION\r\n\r\nThe HRMS should monitor the expiration of solo parent documentation.\r\n\r\nThe system should generate alerts before expiration.\r\n\r\nRecommended alert periods may include:\r\n\r\n1. 90 days before expiration;\r\n2. 60 days before expiration;\r\n3. 30 days before expiration;\r\n4. On expiration.\r\n\r\nRENEWAL\r\n\r\nEmployees should be able to submit updated documentation for renewal.\r\n\r\nHR should verify the new documentation before updating the employee status.\r\n\r\nAn expired Solo Parent ID should not automatically result in permanent deletion of the employee historical record.\r\n\r\nAUDIT TRAIL\r\n\r\nEvery change to solo parent status should be recorded.\r\n\r\nThe audit trail should include:\r\n\r\n1. Employee ID;\r\n2. Previous status;\r\n3. New status;\r\n4. Eligibility category;\r\n5. Document submitted;\r\n6. Verification result;\r\n7. Approver;\r\n8. Date and time;\r\n9. Reason for change.\r\n\r\nPAYROLL PROCESSING\r\n\r\nApproved parental leave should be processed as paid leave when the employee satisfies statutory requirements.\r\n\r\nThe payroll system should identify:\r\n\r\n1. Regular working days;\r\n2. Solo parent parental leave days;\r\n3. Paid leave amount;\r\n4. Other leave deductions;\r\n5. Applicable statutory deductions.\r\n\r\nThe seven-day parental leave should not be deducted from unrelated leave balances.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nThe HRMS should monitor:\r\n\r\n1. Valid Solo Parent ID;\r\n2. Eligibility;\r\n3. Documentation;\r\n4. Parental leave usage;\r\n5. Remaining leave balance;\r\n6. Flexible work arrangements;\r\n7. Tax benefit eligibility;\r\n8. Renewal requirements;\r\n9. Expiring documentation;\r\n10. Compliance exceptions.\r\n\r\nREPORTING\r\n\r\nThe HRMS should generate reports including:\r\n\r\n1. Active solo parent employees;\r\n2. Expiring Solo Parent IDs;\r\n3. Expired documentation;\r\n4. Parental leave utilization;\r\n5. Remaining parental leave;\r\n6. Flexible work arrangement requests;\r\n7. Pending eligibility verification;\r\n8. Benefit eligibility;\r\n9. Compliance exceptions.\r\n\r\nPRIVACY\r\n\r\nSolo parent records may contain personal and family information.\r\n\r\nAccess must be limited to authorized HR personnel.\r\n\r\nThe HRMS should implement role-based access control.\r\n\r\nSensitive supporting documents should not be visible to unauthorized users.\r\n\r\nRELATIONSHIP WITH RA 8972\r\n\r\nRA 11861 amends and expands RA 8972.\r\n\r\nRA 8972 should remain in the legal database because it is the original Solo Parents Welfare Act.\r\n\r\nRA 11861 should be used as the current expanded statutory reference.\r\n\r\nThe HRMS should link both records through the related-law field and legal-reference relationships.\r\n\r\nIMPLEMENTING RULES\r\n\r\nThe implementing rules and regulations of RA 11861 should be maintained as a separate record.\r\n\r\nThe HRMS should use the implementing rules when determining the practical procedures for eligibility verification, Solo Parent ID issuance, parental leave, and other benefits.\r\n\r\nGOVERNMENT AGENCIES\r\n\r\nImplementation involves government agencies including:\r\n\r\n1. Department of Social Welfare and Development;\r\n2. Department of Labor and Employment;\r\n3. Department of Health;\r\n4. Department of Education;\r\n5. Commission on Higher Education;\r\n6. Department of Human Settlements and Urban Development;\r\n7. Department of Finance;\r\n8. Bureau of Internal Revenue;\r\n9. Local government units;\r\n10. Other relevant government agencies.\r\n\r\nEMPLOYMENT COMPLIANCE\r\n\r\nThe HRMS should provide HR officers with a compliance view showing whether the employee has:\r\n\r\n1. Valid solo parent documentation;\r\n2. Verified eligibility;\r\n3. Available parental leave;\r\n4. Pending renewal;\r\n5. Approved flexible work arrangement;\r\n6. Applicable maternity benefit;\r\n7. Applicable tax benefit.\r\n\r\nLEGAL REFERENCES\r\n\r\nThe HRMS should connect RA 11861 with:\r\n\r\n1. Republic Act No. 8972;\r\n2. Republic Act No. 11210;\r\n3. Republic Act No. 8187;\r\n4. Labor Code of the Philippines;\r\n5. Applicable DOLE regulations;\r\n6. Applicable DSWD regulations;\r\n7. Applicable BIR regulations;\r\n8. Implementing Rules and Regulations of RA 11861.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nRA 11861 should be interpreted together with its implementing rules and subsequent government issuances.\r\n\r\nFor current payroll, tax, leave, and employment processing, the HRMS should use the latest applicable DOLE, DSWD, BIR, and other government regulations.\r\n\r\nThe law should not be treated as permitting automatic benefits without verification of the employee eligibility requirements.','2026-08-13 15:59:37'),
(28,'Republic Act','Republic Act No. 7322','Maternity Benefits for Women Workers in the Private Sector',1,'1992-03-30',NULL,'Congress of the Philippines','Historical/Amended','Republic Act No. 7322, RA 7322, maternity benefits, maternity leave, women workers, female employees, private sector, SSS maternity benefit, Social Security System, maternity contribution, childbirth, abortion, miscarriage, Caesarian delivery, sixty days, seventy-eight days, maternity cash benefit, Republic Act No. 1161, SSS Act','https://lawphil.net/statutes/repacts/ra1992/ra_7322_1992.html','modules/compliance/assets/law_reference/ra_7322_maternity_benefits.pdf','Republic Act No. 1161; Republic Act No. 8282; Republic Act No. 11199; Republic Act No. 11210; Social Security Act; 105-Day Expanded Maternity Leave Law','Republic Act No. 7322 increased maternity benefits for women workers in the private sector by amending Section 14-A of Republic Act No. 1161, as amended. It provided a maternity benefit equivalent to 100 percent of the covered female employee daily basic salary, allowances, and other benefits or their cash equivalents for 60 days, subject to the statutory conditions.\r\n\r\nThe law also provided 78 days of maternity benefit in cases of Caesarian delivery. It required at least three monthly maternity contributions within the 12-month period preceding the semester of childbirth, abortion, or miscarriage and required the employee to be currently employed.\r\n\r\nRA 7322 also provided rules concerning employer advance payment, SSS reimbursement, notification of pregnancy, and the limitation of maternity benefits to the first four deliveries under the law then in force.','RA 7322 is a historical maternity-benefit law and should not be used by the HRMS as the current basis for computing maternity leave.\r\n\r\nIt amended Section 14-A of RA 1161 and was subsequently affected by later amendments to the Social Security Act and the enactment of RA 11210.\r\n\r\nFor current maternity leave administration, the HRMS should use Republic Act No. 11210 and its implementing rules.\r\n\r\nRA 7322 should be retained in the legal-reference database because it forms part of the historical development of Philippine maternity benefits.\r\n\r\nThe database status is therefore marked Historical/Amended to distinguish it from the current maternity-leave framework.',1,1,'2026-08-13 17:23:31','Republic Act No. 7322 - Increasing Maternity Benefits in Favor of Women Workers in the Private Sector','Republic Act','Congress of the Philippines','R.A. No. 7322','1992','An Act Increasing Maternity Benefits in Favor of Women Workers in the Private Sector, Amending for the Purpose Section 14-A of Republic Act No. 1161, as Amended, and for Other Purposes.','ra_7322_maternity_benefits.pdf','REPUBLIC ACT NO. 7322\r\n\r\nAN ACT INCREASING MATERNITY BENEFITS IN FAVOR OF WOMEN WORKERS IN THE PRIVATE SECTOR, AMENDING FOR THE PURPOSE SECTION 14-A OF REPUBLIC ACT NO. 1161, AS AMENDED, AND FOR OTHER PURPOSES\r\n\r\nPURPOSE\r\n\r\nRepublic Act No. 7322 increased maternity benefits for covered women workers in the private sector.\r\n\r\nThe law amended Section 14-A of Republic Act No. 1161, otherwise known as the Social Security Act.\r\n\r\nCOVERAGE\r\n\r\nThe law applied to covered female employees in the private sector who satisfied the applicable Social Security System contribution and employment requirements.\r\n\r\nMATERNITY CONTRIBUTION REQUIREMENT\r\n\r\nA covered female employee was required to have paid at least three monthly maternity contributions within the 12-month period immediately preceding the semester of childbirth, abortion, or miscarriage.\r\n\r\nThe employee also had to be currently employed at the time of the contingency.\r\n\r\nMATERNITY BENEFIT\r\n\r\nThe law provided a daily maternity benefit equivalent to 100 percent of the employee present basic salary, allowances, and other benefits or their cash equivalents for 60 days.\r\n\r\nThe maternity benefit was subject to the conditions established by the law and applicable SSS regulations.\r\n\r\nCAESARIAN DELIVERY\r\n\r\nIn case of Caesarian delivery, the maternity benefit was payable for 78 days.\r\n\r\nThe 78-day period represented the special maternity benefit period provided under RA 7322.\r\n\r\nCHILDBIRTH, ABORTION, AND MISCARRIAGE\r\n\r\nThe law provided maternity benefits for childbirth, abortion, or miscarriage subject to the applicable statutory requirements.\r\n\r\nNOTIFICATION OF PREGNANCY\r\n\r\nThe employee was required to notify her employer of her pregnancy and probable date of childbirth.\r\n\r\nThe employer was required to transmit the appropriate notice to the Social Security System in accordance with applicable SSS rules.\r\n\r\nEMPLOYER ADVANCEMENT\r\n\r\nThe maternity benefit was to be advanced by the employer in two equal installments within 30 days from the filing of the maternity leave application.\r\n\r\nThe employer was subsequently entitled to reimbursement from the Social Security System upon submission of satisfactory proof of payment and legality of the benefit.\r\n\r\nSSS REIMBURSEMENT\r\n\r\nThe Social Security System was required to reimburse the employer for the maternity benefits advanced to the employee upon receipt of satisfactory proof of payment and compliance with the applicable requirements.\r\n\r\nFAILURE TO REMIT CONTRIBUTIONS\r\n\r\nIf an employee gave birth or suffered abortion or miscarriage without the required contributions having been remitted by the employer to the SSS, the employer could become liable for damages equivalent to the maternity benefits the employee would otherwise have received.\r\n\r\nThe SSS would then pay the corresponding amount to the employee in accordance with the law.\r\n\r\nFAILURE TO NOTIFY SSS\r\n\r\nIf the required pregnancy notification was not properly transmitted to the SSS, the employer could likewise be liable under the applicable statutory provisions.\r\n\r\nFIRST FOUR DELIVERIES\r\n\r\nUnder RA 7322, maternity benefits were payable only for the first four deliveries after March 13, 1973.\r\n\r\nThis limitation reflected the maternity-benefit framework applicable at the time the law was enacted.\r\n\r\nNON-DIMINUTION OF BENEFITS\r\n\r\nNothing in RA 7322 was intended to diminish existing maternity benefits under other laws or collective bargaining agreements.\r\n\r\nWhere a collective bargaining agreement or employer policy provided more favorable maternity benefits, the more favorable benefit could continue to apply subject to the applicable rules.\r\n\r\nRELATIONSHIP WITH RA 1161\r\n\r\nRA 7322 directly amended Section 14-A of Republic Act No. 1161.\r\n\r\nThe amendment increased the maternity benefit applicable to covered private-sector women workers under the SSS system.\r\n\r\nRELATIONSHIP WITH LATER SSS LAWS\r\n\r\nRA 7322 formed part of the historical development of Philippine maternity benefits under the Social Security System.\r\n\r\nSubsequent amendments to the Social Security Act modified the statutory maternity-benefit framework.\r\n\r\nThe HRMS should therefore not use the numerical benefit periods contained in RA 7322 as the current maternity-benefit computation.\r\n\r\nRELATIONSHIP WITH RA 11210\r\n\r\nRepublic Act No. 11210, the 105-Day Expanded Maternity Leave Law, substantially changed the current maternity-leave framework.\r\n\r\nUnder RA 11210, qualified female workers are generally entitled to 105 days of maternity leave with full pay for live childbirth and 60 days with full pay for miscarriage or emergency termination of pregnancy.\r\n\r\nA qualified solo parent may receive an additional 15 days with full pay.\r\n\r\nA qualified female worker may also elect an additional 30 days of maternity leave without pay for live childbirth subject to the statutory requirements.\r\n\r\nTherefore, RA 11210 and its implementing rules should be used for current maternity-leave administration.\r\n\r\nPRIVATE-SECTOR HRMS IMPLEMENTATION\r\n\r\nFor historical-reference purposes, the HRMS should record RA 7322 as a predecessor maternity-benefit law.\r\n\r\nThe system should prevent RA 7322 from being automatically used in current maternity payroll calculations.\r\n\r\nThe current maternity calculation should instead reference the latest applicable laws and SSS regulations.\r\n\r\nHISTORICAL DOCUMENTATION\r\n\r\nThe HRMS may retain RA 7322 because historical labor-law references are useful for:\r\n\r\n1. Legal research;\r\n2. Audit documentation;\r\n3. Policy history;\r\n4. Compliance training;\r\n5. Historical payroll review;\r\n6. Legal-reference management.\r\n\r\nCURRENT COMPLIANCE\r\n\r\nCurrent maternity leave administration should be based primarily on:\r\n\r\n1. Republic Act No. 11210;\r\n2. Implementing Rules and Regulations of RA 11210;\r\n3. Republic Act No. 11199;\r\n4. Current SSS regulations;\r\n5. Applicable DOLE issuances;\r\n6. Applicable company policies and collective bargaining agreements.\r\n\r\nHRMS MATERNITY RECORD\r\n\r\nFor current maternity processing, the HRMS should maintain:\r\n\r\n1. Employee ID;\r\n2. Pregnancy event;\r\n3. Expected delivery date;\r\n4. Actual delivery date;\r\n5. Maternity leave type;\r\n6. Leave start date;\r\n7. Leave end date;\r\n8. SSS membership;\r\n9. SSS contribution eligibility;\r\n10. Maternity benefit;\r\n11. Salary differential;\r\n12. Solo parent status;\r\n13. Supporting documents;\r\n14. Approval status;\r\n15. Payroll status.\r\n\r\nHISTORICAL STATUS\r\n\r\nRA 7322 should be retained as a historical and amended legal reference.\r\n\r\nThe system should display a warning when users access this record for current compliance processing.\r\n\r\nSuggested system warning:\r\n\r\nTHIS IS A HISTORICAL LEGAL REFERENCE. DO NOT USE RA 7322 AS THE CURRENT BASIS FOR MATERNITY LEAVE COMPUTATION. REFER TO RA 11210, ITS IMPLEMENTING RULES, AND CURRENT SSS REGULATIONS.\r\n\r\nLEGAL DISCLAIMER\r\n\r\nThis record is maintained for labor-law reference and historical compliance purposes.\r\n\r\nThe current legal requirements for maternity leave and maternity benefits may differ from those provided under RA 7322 because of subsequent legislation and regulations.\r\n\r\nFor current HRMS implementation, consult Republic Act No. 11210, its implementing rules, current SSS regulations, DOLE issuances, and other applicable laws.','2026-08-13 16:01:06'),
(29,'Republic Act','Republic Act No. 9710','Magna Carta of Women',1,'2009-08-14','2009-09-15','Congress of the Philippines','Active','Republic Act No. 9710, RA 9710, Magna Carta of Women, women rights, gender equality, gender discrimination, equal opportunity, equal treatment, employment discrimination, women workers, workplace rights, maternity protection, women in employment, sexual harassment, violence against women, gender and development, GAD, Philippine Commission on Women, PCW','https://lawphil.net/statutes/repacts/ra2009/ra_9710_2009.html','modules/compliance/assets/law_reference/ra_9710_magna_carta_of_women.pdf','1987 Constitution; Labor Code of the Philippines; Republic Act No. 6725; Republic Act No. 7877; Republic Act No. 9262; Republic Act No. 11313; Republic Act No. 11210; Republic Act No. 11058; Republic Act No. 10173; implementing rules and regulations of RA 9710','Republic Act No. 9710, known as the Magna Carta of Women, is a comprehensive human rights law that promotes the empowerment of women and eliminates discrimination against women. It establishes mechanisms for substantive equality between women and men and requires protection of women against discrimination in employment and other areas of life.','RA 9710 is a broad gender equality and women rights framework. Specific employment benefits should be administered according to the specific and current law governing each benefit. Related laws include RA 6725 on discrimination against women in employment, RA 7877 on sexual harassment, RA 11313 on safe spaces, and RA 11210 on maternity leave.',1,1,'2026-08-13 17:23:31','Republic Act No. 9710 - Magna Carta of Women','Republic Act','Congress of the Philippines','R.A. No. 9710','2009','An Act Providing for the Magna Carta of Women.','ra_9710_magna_carta_of_women.pdf','REPUBLIC ACT NO. 9710\r\n\r\nMAGNA CARTA OF WOMEN\r\n\r\nPURPOSE\r\n\r\nRepublic Act No. 9710 is known as the Magna Carta of Women.\r\n\r\nThe law is a comprehensive human rights law that seeks to eliminate discrimination against women and promote equality between women and men.\r\n\r\nThe law recognizes that women are entitled to equal rights, opportunities, and treatment before the law.\r\n\r\nDECLARATION OF POLICY\r\n\r\nThe State recognizes the role of women in nation-building and ensures the fundamental equality of women and men before the law.\r\n\r\nThe State shall provide mechanisms for the protection and promotion of women rights.\r\n\r\nThe law seeks to eliminate discrimination against women in all areas of life.\r\n\r\nHUMAN RIGHTS OF WOMEN\r\n\r\nThe law recognizes women rights as human rights.\r\n\r\nWomen are entitled to equal protection and equal benefit of the law, non-discrimination, equal opportunity, participation in decision-making, freedom from violence, access to education, access to health services, equal treatment in employment, social protection, and other rights recognized by law.\r\n\r\nNON-DISCRIMINATION\r\n\r\nDiscrimination against women is prohibited.\r\n\r\nGovernment agencies, employers, institutions, and other covered entities should ensure that policies and practices do not discriminate against women.\r\n\r\nEmployment decisions should be based on legitimate qualifications and requirements rather than sex or gender.\r\n\r\nEMPLOYMENT RIGHTS\r\n\r\nThe law protects women in employment and requires equal opportunities.\r\n\r\nWomen should have equal access to employment, promotion, training, compensation, benefits, career development, and leadership opportunities.\r\n\r\nRECRUITMENT\r\n\r\nRecruitment practices should not discriminate against women.\r\n\r\nEmployers should not impose discriminatory employment requirements based solely on sex.\r\n\r\nJob advertisements, application forms, interviews, and selection procedures should be reviewed for gender-based discrimination.\r\n\r\nEQUAL OPPORTUNITY\r\n\r\nWomen should have equal opportunities for employment and career advancement.\r\n\r\nThe HRMS may monitor recruitment, promotion, training, and other employment statistics to support gender equality compliance.\r\n\r\nEQUAL PAY\r\n\r\nWomen should receive equal remuneration for work of equal value, subject to applicable labor standards.\r\n\r\nCompensation structures should not discriminate against women.\r\n\r\nThe HRMS payroll and compensation modules may support monitoring for unexplained gender-based pay disparities.\r\n\r\nWORKPLACE PROTECTION\r\n\r\nEmployers should provide a safe and non-discriminatory workplace.\r\n\r\nWorkplace policies should protect women from harassment, violence, intimidation, and discriminatory treatment.\r\n\r\nThe HRMS should connect this legal reference with workplace incident and complaint management.\r\n\r\nSEXUAL HARASSMENT\r\n\r\nSexual harassment is governed by specific legislation including Republic Act No. 7877.\r\n\r\nWorkplace sexual harassment should be addressed through appropriate policies, reporting procedures, investigation processes, and disciplinary mechanisms.\r\n\r\nRA 9710 provides a broader gender equality framework supporting protection against discrimination and violence.\r\n\r\nSAFE SPACES\r\n\r\nRepublic Act No. 11313, known as the Safe Spaces Act, provides specific protections against gender-based sexual harassment in workplaces and other covered environments.\r\n\r\nThe HRMS should maintain RA 11313 as a separate but related legal reference.\r\n\r\nMATERNITY PROTECTION\r\n\r\nWomen workers are entitled to maternity protections under applicable laws.\r\n\r\nThe current maternity leave framework is principally governed by Republic Act No. 11210.\r\n\r\nRA 9710 provides a broader policy framework supporting protection and non-discrimination for women workers.\r\n\r\nThe HRMS should link RA 9710 to the maternity leave and maternity benefit modules.\r\n\r\nEMPLOYMENT DISCRIMINATION\r\n\r\nThe law requires measures to eliminate discrimination against women in employment.\r\n\r\nDiscrimination may occur in recruitment, hiring, promotion, compensation, training, assignment, benefits, termination, retirement, or other employment decisions.\r\n\r\nThe HRMS should support compliance monitoring for these areas.\r\n\r\nWOMEN IN LEADERSHIP\r\n\r\nThe law promotes increased participation of women in decision-making and leadership positions.\r\n\r\nOrganizations should support equal opportunities for women to participate in management and leadership.\r\n\r\nGENDER AND DEVELOPMENT\r\n\r\nThe law strengthens gender and development mechanisms.\r\n\r\nCovered institutions should integrate gender perspectives into policies, plans, programs, and budgets as applicable.\r\n\r\nCOMPLAINT AND REPORTING MECHANISMS\r\n\r\nEmployees should have access to appropriate mechanisms for reporting discrimination, harassment, and other violations.\r\n\r\nThe HRMS may provide complaint records, incident reports, investigation tracking, case status, evidence management, resolution records, and audit trails.\r\n\r\nCONFIDENTIALITY\r\n\r\nReports involving discrimination, harassment, or violence may contain sensitive personal information.\r\n\r\nAccess to these records should be limited to authorized personnel.\r\n\r\nThe HRMS should implement role-based access controls and appropriate audit logging.\r\n\r\nHEALTH RIGHTS\r\n\r\nThe law recognizes women rights to appropriate health services and protection.\r\n\r\nWorkplace health programs should consider the specific health needs of women workers.\r\n\r\nSOCIAL PROTECTION\r\n\r\nWomen should have access to social protection programs without discrimination.\r\n\r\nEmployment benefits should be administered consistently with applicable labor and social-security laws.\r\n\r\nEDUCATION AND TRAINING\r\n\r\nWomen should have equal opportunities for education, training, scholarships, and professional development.\r\n\r\nThe HRMS learning and development module should be designed without discriminatory restrictions based on sex or gender.\r\n\r\nHRMS COMPLIANCE MONITORING\r\n\r\nThe HRMS should monitor:\r\n\r\n1. Recruitment;\r\n2. Hiring;\r\n3. Promotion;\r\n4. Compensation;\r\n5. Training;\r\n6. Leave;\r\n7. Benefits;\r\n8. Workplace complaints;\r\n9. Workplace incidents;\r\n10. Disciplinary actions;\r\n11. Terminations.\r\n\r\nThe system should use these records for legitimate HR and compliance purposes while protecting employee privacy.\r\n\r\nAUDIT TRAIL\r\n\r\nCompliance-related actions should be logged.\r\n\r\nAudit records may include user, action, employee record, date, time, previous value, new value, and reason for change.\r\n\r\nCOMPLIANCE DASHBOARD\r\n\r\nThe HRMS may provide indicators for:\r\n\r\n1. Gender distribution;\r\n2. Recruitment statistics;\r\n3. Promotion statistics;\r\n4. Training participation;\r\n5. Compensation analysis;\r\n6. Women in management;\r\n7. Workplace complaints;\r\n8. Sexual harassment cases;\r\n9. Policy acknowledgements;\r\n10. Compliance actions.\r\n\r\nThese indicators should not expose confidential employee information.\r\n\r\nRELATED LAWS\r\n\r\nThe HRMS should connect RA 9710 with:\r\n\r\n1. Republic Act No. 6725;\r\n2. Republic Act No. 7877;\r\n3. Republic Act No. 9262;\r\n4. Republic Act No. 11313;\r\n5. Republic Act No. 11210;\r\n6. Republic Act No. 11861;\r\n7. Labor Code of the Philippines;\r\n8. Republic Act No. 11058;\r\n9. Republic Act No. 10173.\r\n\r\nREPUBLIC ACT NO. 6725\r\n\r\nRA 6725 specifically addresses discrimination against women in employment.\r\n\r\nIt should therefore be maintained as a specific employment-law reference linked to RA 9710.\r\n\r\nREPUBLIC ACT NO. 7877\r\n\r\nRA 7877 specifically addresses sexual harassment in employment, education, and training environments.\r\n\r\nIt should remain a separate legal reference.\r\n\r\nREPUBLIC ACT NO. 11313\r\n\r\nRA 11313 expands protection against gender-based sexual harassment and establishes obligations concerning workplace policies and mechanisms.\r\n\r\nIt should remain a separate legal reference.\r\n\r\nREPUBLIC ACT NO. 11210\r\n\r\nRA 11210 provides the current expanded maternity leave framework.\r\n\r\nThe HRMS should use RA 11210 for maternity leave computation while RA 9710 provides the broader women rights framework.\r\n\r\nEMPLOYER COMPLIANCE\r\n\r\nHR should ensure that employment policies comply with equality and non-discrimination principles.\r\n\r\nHR should review recruitment policies, compensation policies, promotion policies, training policies, leave policies, workplace conduct policies, complaint procedures, and disciplinary procedures.\r\n\r\nPOLICY ACKNOWLEDGEMENT\r\n\r\nThe HRMS may require employees to acknowledge relevant workplace policies involving:\r\n\r\n1. Gender equality;\r\n2. Anti-discrimination;\r\n3. Sexual harassment;\r\n4. Safe spaces;\r\n5. Workplace conduct;\r\n6. Complaint procedures.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS may store gender equality policies, anti-discrimination policies, workplace harassment policies, GAD policies, employee acknowledgements, compliance reports, training records, and incident reports.\r\n\r\nSensitive case records should have restricted access.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nRA 9710 remains an active legal framework concerning women rights and gender equality.\r\n\r\nSpecific employment benefits should be validated against the more specific and current laws applicable to the particular benefit.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nRA 9710 is a broad women rights and gender equality law.\r\n\r\nIt should be read together with its implementing rules and regulations and other applicable labor, employment, anti-discrimination, workplace safety, privacy, and social protection laws.\r\n\r\nFor specific leave, compensation, harassment, or employment benefit computations, the HRMS should use the specific current law governing the benefit rather than relying solely on RA 9710.','2026-08-13 16:02:35'),
(30,'Republic Act','Republic Act No. 10653','Thirteenth Month Pay',1,'2014-02-12',NULL,'Congress of the Philippines','Active','Republic Act No. 10653, RA 10653, thirteenth month pay, 13th month pay, tax exemption, thirteen month pay, compensation, benefits, minimum wage earners, income tax, National Internal Revenue Code, BIR, Bureau of Internal Revenue, payroll, annual compensation, exempt benefits','https://lawphil.net/statutes/repacts/ra2014/ra_10653_2014.html','modules/compliance/assets/law_reference/ra_10653_thirteenth_month_pay.pdf','Presidential Decree No. 851; Republic Act No. 9504; Republic Act No. 8424; Republic Act No. 10963; National Internal Revenue Code of 1997, as amended; applicable BIR regulations and revenue issuances','Republic Act No. 10653 increased the tax exemption ceiling for thirteenth month pay and other benefits from fifty thousand pesos to eighty-two thousand pesos. The law amended Section 32(B) of the National Internal Revenue Code of 1997, as amended.','This law concerns the tax treatment of thirteenth month pay and other benefits. Presidential Decree No. 851 remains the primary legal basis for the mandatory payment of thirteenth month pay. Current tax treatment must also consider subsequent tax laws and current BIR regulations.',1,1,'2026-08-13 17:23:31','Republic Act No. 10653 - Thirteenth Month Pay and Other Benefits','Republic Act','Congress of the Philippines','R.A. No. 10653','2014','An Act Increasing the Tax Exemption Ceiling on the Thirteenth Month Pay and Other Benefits to Eighty-Two Thousand Pesos, Amending for the Purpose Section 32(B), Chapter VI of the National Internal Revenue Code of 1997, as Amended.','ra_10653_thirteenth_month_pay.pdf','Republic Act No. 10653 was enacted to increase the tax exemption ceiling applicable to thirteenth month pay and other benefits.\r\n\r\nThe law amended Section 32(B) of the National Internal Revenue Code of 1997, as amended.\r\n\r\nPrior to this amendment, the exclusion for thirteenth month pay and other benefits was fifty thousand pesos.\r\n\r\nRA 10653 increased the exclusion to eighty-two thousand pesos.\r\n\r\nTHIRTEENTH MONTH PAY\r\n\r\nThirteenth month pay is a mandatory benefit generally provided to covered rank-and-file employees pursuant to Presidential Decree No. 851 and its implementing rules.\r\n\r\nThe amount is generally equivalent to one-twelfth of the basic salary earned by the employee during the calendar year.\r\n\r\nThe computation should use the applicable definition of basic salary under labor regulations and relevant jurisprudence.\r\n\r\nTAX EXEMPTION\r\n\r\nRA 10653 increased the amount of thirteenth month pay and other benefits that may be excluded from gross income.\r\n\r\nThe ceiling established by this law was eighty-two thousand pesos.\r\n\r\nAmounts within the applicable statutory ceiling may be excluded from taxable income subject to applicable tax rules.\r\n\r\nAmounts exceeding the applicable ceiling may be subject to income tax.\r\n\r\nOTHER BENEFITS\r\n\r\nThe tax exemption may cover thirteenth month pay and other benefits recognized under the National Internal Revenue Code and applicable regulations.\r\n\r\nPayroll systems should maintain separate records for thirteenth month pay and other qualified benefits.\r\n\r\nBASIC COMPUTATION\r\n\r\nThe general formula for thirteenth month pay is:\r\n\r\nTotal basic salary earned during the calendar year divided by twelve.\r\n\r\nFor example, if an employee earns a total basic salary of three hundred sixty thousand pesos during the calendar year, the corresponding thirteenth month pay is thirty thousand pesos.\r\n\r\nPROPORTIONATE THIRTEENTH MONTH PAY\r\n\r\nEmployees who worked for only part of the calendar year may be entitled to proportionate thirteenth month pay.\r\n\r\nThe amount is generally based on the basic salary actually earned during the covered period divided by twelve.\r\n\r\nEmployees who separate from employment during the year may receive proportionate thirteenth month pay as part of their final pay when applicable.\r\n\r\nPAYMENT\r\n\r\nCovered employers generally must provide thirteenth month pay not later than December 24 of every year, subject to applicable labor regulations.\r\n\r\nEmployers may provide the benefit earlier provided that the statutory requirement is satisfied.\r\n\r\nEMPLOYEE COVERAGE\r\n\r\nThe mandatory thirteenth month pay requirement generally covers rank-and-file employees who have worked for at least one month during the calendar year, subject to applicable rules and exemptions.\r\n\r\nThe tax treatment under RA 10653 should be distinguished from the labor entitlement established under Presidential Decree No. 851.\r\n\r\nRELATIONSHIP WITH PRESIDENTIAL DECREE NO. 851\r\n\r\nPresidential Decree No. 851 established the mandatory thirteenth month pay requirement.\r\n\r\nRA 10653 primarily concerns the tax exemption ceiling for thirteenth month pay and other benefits.\r\n\r\nThe HRMS should therefore maintain separate legal references for both laws.\r\n\r\nPAYROLL REQUIREMENTS\r\n\r\nThe payroll system should maintain:\r\n\r\nEmployee ID;\r\nEmployee name;\r\nEmployment start date;\r\nEmployment end date;\r\nEmployee classification;\r\nRank-and-file status;\r\nMonthly basic salary;\r\nBasic salary earned;\r\nThirteenth month pay;\r\nOther qualified benefits;\r\nTotal benefits;\r\nApplicable tax exemption ceiling;\r\nTaxable excess;\r\nTaxable compensation;\r\nWithholding tax.\r\n\r\nANNUAL COMPUTATION\r\n\r\nThe system should accumulate basic salary earned during the calendar year.\r\n\r\nAt year end, the system should calculate thirteenth month pay based on the total basic salary earned.\r\n\r\nThe system should then determine the tax treatment separately.\r\n\r\nTAXABLE EXCESS\r\n\r\nWhen qualified thirteenth month pay and other benefits exceed the applicable non-taxable ceiling, the excess amount may become taxable under the applicable tax rules.\r\n\r\nThe payroll system should identify the exempt amount and taxable excess separately.\r\n\r\nCURRENT TAX RULES\r\n\r\nRA 10653 established an eighty-two thousand peso ceiling in 2014.\r\n\r\nSubsequent tax legislation may change the applicable tax treatment.\r\n\r\nThe HRMS should therefore not permanently hard-code the historical RA 10653 amount when calculating current payroll taxes.\r\n\r\nThe current BIR rules and subsequent tax legislation should control present-day payroll computation.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nHR should monitor:\r\n\r\n1. Employee eligibility;\r\n2. Basic salary earned;\r\n3. Calendar year;\r\n4. Computed thirteenth month pay;\r\n5. Payment date;\r\n6. Other qualified benefits;\r\n7. Applicable tax exemption ceiling;\r\n8. Taxable excess;\r\n9. Withholding tax;\r\n10. Final pay computation.\r\n\r\nAUDIT TRAIL\r\n\r\nChanges to thirteenth month pay computations should be recorded in the HRMS audit trail.\r\n\r\nThe audit record should contain the employee ID, previous computation, updated computation, computation period, reason for adjustment, user who made the change, and date and time of change.\r\n\r\nDOCUMENTATION\r\n\r\nEmployers should retain payroll records supporting the computation and payment of thirteenth month pay.\r\n\r\nRecommended records include payroll registers, payslips, employment contracts, salary history, thirteenth month computation, payment records, tax computation, BIR documentation, and final pay records.\r\n\r\nLEGAL RELATIONSHIP\r\n\r\nThe HRMS legal compliance database should connect RA 10653 with Presidential Decree No. 851, Republic Act No. 9504, the National Internal Revenue Code, Republic Act No. 10963, current BIR regulations, and applicable DOLE regulations.\r\n\r\nLEGAL CAUTION\r\n\r\nRA 10653 concerns the tax exemption ceiling for thirteenth month pay and other benefits.\r\n\r\nIt should not be treated as the primary law establishing the mandatory thirteenth month pay benefit.\r\n\r\nFor current payroll processing, the system should use the latest applicable labor regulations and BIR tax rules.\r\n\r\nAPPROVAL\r\n\r\nRepublic Act No. 10653 was approved on February 12, 2014.','2026-08-13 15:54:11'),
(31,'Republic Act','Republic Act No. 11036','Mental Health Act',1,'2018-06-21','2018-07-05','Congress of the Philippines','Active','Republic Act No. 11036, RA 11036, Mental Health Act, mental health, mental health rights, psychological health, mental health services, workplace mental health, employee mental health, occupational health, discrimination, confidentiality, informed consent, mental health assessment, mental health support, mental health program, DOH, DOLE, workplace wellness','https://lawphil.net/statutes/repacts/ra2018/ra_11036_2018.html','modules/compliance/assets/law_reference/ra_11036_mental_health_act.pdf','1987 Constitution; Labor Code of the Philippines; Republic Act No. 11058; Republic Act No. 10173; Republic Act No. 7277; Republic Act No. 11650; Republic Act No. 11223; applicable DOLE occupational safety and health regulations; implementing rules and regulations of RA 11036','Republic Act No. 11036, known as the Mental Health Act, establishes a national mental health policy and promotes the protection of the rights of persons who use mental health services. It provides for accessible, integrated, and comprehensive mental health services and establishes safeguards against discrimination, abuse, and violations of the rights of persons with mental health conditions.\r\n\r\nFor HR and workplace compliance, the law supports the development of workplace mental health programs, promotes a safe and supportive work environment, protects employees from discrimination based on mental health status, and recognizes the confidentiality and privacy of mental health information.','RA 11036 is an active national law and should be linked to workplace health, occupational safety, employee assistance, clinic, privacy, anti-discrimination, and wellness policies.\r\n\r\nThe HRMS should not expose an employees mental health information to ordinary HR users unless access is legally authorized and necessary.\r\n\r\nMental health information should be treated as highly confidential and should have restricted access.\r\n\r\nThe law should be implemented together with current DOLE occupational safety and health regulations, applicable privacy requirements, and relevant Department of Health rules.',1,1,'2026-08-13 17:23:31','Republic Act No. 11036 - Mental Health Act','Republic Act','Congress of the Philippines','R.A. No. 11036','2018','An Act Establishing a National Mental Health Policy for the Purpose of Enhancing the Delivery of Integrated Mental Health Services, Promoting and Protecting the Rights of Persons Utilizing Psychosocial Health Services, Appropriating Funds Therefor, and for Other Purposes.','ra_11036_mental_health_act.pdf','REPUBLIC ACT NO. 11036\r\n\r\nMENTAL HEALTH ACT\r\n\r\nPURPOSE\r\n\r\nRepublic Act No. 11036 is known as the Mental Health Act.\r\n\r\nThe law establishes a national mental health policy and provides a framework for accessible, integrated, and comprehensive mental health services.\r\n\r\nIt promotes the protection of persons with mental health conditions and persons using mental health services.\r\n\r\nMENTAL HEALTH AS A HUMAN RIGHT\r\n\r\nThe law recognizes the right of every person to mental health.\r\n\r\nMental health services should be accessible, affordable, culturally appropriate, and responsive to the needs of individuals.\r\n\r\nThe law promotes the protection of human dignity and the rights of persons with mental health conditions.\r\n\r\nRIGHTS OF PERSONS USING MENTAL HEALTH SERVICES\r\n\r\nPersons using mental health services have rights that must be respected.\r\n\r\nThese include:\r\n\r\n1. Freedom from discrimination and stigma;\r\n2. Access to appropriate mental health services;\r\n3. Respect for dignity and autonomy;\r\n4. Confidentiality of information;\r\n5. Informed consent;\r\n6. Access to information;\r\n7. Participation in treatment decisions;\r\n8. Protection from abuse;\r\n9. Protection from unnecessary restraint or confinement;\r\n10. Other rights provided by law.\r\n\r\nNON-DISCRIMINATION\r\n\r\nA person should not be discriminated against solely because of a mental health condition.\r\n\r\nWorkplace policies should therefore avoid discriminatory treatment based on actual or perceived mental health conditions.\r\n\r\nEmployment decisions should be based on legitimate and lawful employment considerations.\r\n\r\nWORKPLACE MENTAL HEALTH\r\n\r\nThe law supports the development of mental health programs in workplaces.\r\n\r\nEmployers and institutions should promote a healthy and supportive environment that considers the mental health and psychological well-being of workers.\r\n\r\nWorkplace mental health initiatives may include:\r\n\r\n1. Mental health awareness;\r\n2. Mental health education;\r\n3. Stress management;\r\n4. Employee assistance;\r\n5. Referral mechanisms;\r\n6. Psychological support;\r\n7. Wellness programs;\r\n8. Suicide prevention awareness;\r\n9. Anti-stigma activities;\r\n10. Appropriate workplace accommodations.\r\n\r\nEMPLOYER RESPONSIBILITIES\r\n\r\nEmployers should promote an environment that supports mental health and prevents discrimination.\r\n\r\nWorkplace programs should be consistent with applicable DOLE occupational safety and health requirements and other relevant regulations.\r\n\r\nThe HRMS may be used to monitor compliance activities but should not unnecessarily collect clinical information.\r\n\r\nMENTAL HEALTH PROGRAM\r\n\r\nAn organization may establish a workplace mental health program.\r\n\r\nThe program may include:\r\n\r\n1. Mental health policy;\r\n2. Employee awareness programs;\r\n3. Referral procedures;\r\n4. Counseling access;\r\n5. Crisis response;\r\n6. Workplace wellness activities;\r\n7. Anti-discrimination measures;\r\n8. Return-to-work support;\r\n9. Reasonable workplace support;\r\n10. Confidential reporting channels.\r\n\r\nMENTAL HEALTH SERVICES\r\n\r\nMental health services may include prevention, treatment, rehabilitation, recovery, and psychosocial support.\r\n\r\nOrganizations should establish appropriate referral mechanisms when employees require professional mental health services.\r\n\r\nHR personnel should not perform clinical diagnosis unless they are appropriately licensed professionals.\r\n\r\nCONFIDENTIALITY\r\n\r\nMental health information must be handled confidentially.\r\n\r\nMedical records, psychological assessments, counseling information, diagnoses, treatment information, and related documents should not be accessible to unauthorized personnel.\r\n\r\nThe HRMS should use strict role-based access controls.\r\n\r\nPRIVACY\r\n\r\nMental health information is highly sensitive personal information.\r\n\r\nThe HRMS should comply with applicable data protection and privacy requirements.\r\n\r\nRelevant privacy safeguards include:\r\n\r\n1. Access control;\r\n2. Authentication;\r\n3. Encryption where appropriate;\r\n4. Audit logging;\r\n5. Secure storage;\r\n6. Limited data collection;\r\n7. Retention controls;\r\n8. Secure disposal.\r\n\r\nREPUBLIC ACT NO. 10173\r\n\r\nRepublic Act No. 10173, the Data Privacy Act of 2012, should be considered together with RA 11036 when processing employee mental health information.\r\n\r\nThe HRMS should collect only information necessary for legitimate HR, occupational health, legal, or administrative purposes.\r\n\r\nINFORMED CONSENT\r\n\r\nMental health services should respect informed consent requirements.\r\n\r\nEmployees should receive appropriate information about services and interventions before consent is obtained, subject to situations recognized by law.\r\n\r\nEMPLOYEE ASSISTANCE\r\n\r\nEmployers may establish employee assistance mechanisms that provide access to counseling, referral, wellness programs, or other appropriate support.\r\n\r\nThe HRMS may track participation at an appropriate administrative level without storing unnecessary clinical information.\r\n\r\nWORKPLACE ACCOMMODATION\r\n\r\nEmployees experiencing mental health conditions may require appropriate workplace support or accommodation.\r\n\r\nAccommodation requests should be assessed individually and in accordance with applicable laws, workplace policies, medical recommendations, and legitimate operational requirements.\r\n\r\nThe HRMS may record the existence and status of an approved accommodation without unnecessarily storing detailed medical information.\r\n\r\nRETURN TO WORK\r\n\r\nThe organization may establish return-to-work procedures for employees who have been absent because of health-related circumstances.\r\n\r\nThe process should respect employee privacy and applicable medical confidentiality requirements.\r\n\r\nHR should focus on work capacity, approved accommodations, and employment requirements rather than unnecessary clinical details.\r\n\r\nMENTAL HEALTH AND OCCUPATIONAL SAFETY\r\n\r\nMental health is relevant to occupational safety and employee well-being.\r\n\r\nWorkplace mental health programs may be integrated with occupational safety and health programs.\r\n\r\nThe HRMS should connect RA 11036 with occupational safety and health monitoring under Republic Act No. 11058 and applicable DOLE regulations.\r\n\r\nANTI-STIGMA\r\n\r\nOrganizations should promote awareness and reduce stigma related to mental health.\r\n\r\nWorkplace training may include:\r\n\r\n1. Mental health awareness;\r\n2. Recognition of workplace stress;\r\n3. Psychological first aid awareness;\r\n4. Suicide prevention awareness;\r\n5. Referral procedures;\r\n6. Anti-discrimination;\r\n7. Confidentiality.\r\n\r\nDISCRIMINATION IN EMPLOYMENT\r\n\r\nEmployees should not be subjected to unlawful discrimination because of a mental health condition.\r\n\r\nHR policies should be reviewed for discriminatory provisions involving:\r\n\r\n1. Recruitment;\r\n2. Hiring;\r\n3. Promotion;\r\n4. Training;\r\n5. Compensation;\r\n6. Benefits;\r\n7. Assignment;\r\n8. Performance management;\r\n9. Discipline;\r\n10. Termination.\r\n\r\nEMPLOYEE WELLNESS\r\n\r\nOrganizations may implement employee wellness programs addressing physical and mental well-being.\r\n\r\nExamples include:\r\n\r\n1. Wellness seminars;\r\n2. Stress management programs;\r\n3. Counseling referral;\r\n4. Work-life balance programs;\r\n5. Mental health awareness;\r\n6. Physical activity programs;\r\n7. Employee assistance programs.\r\n\r\nCOMPLAINT MECHANISM\r\n\r\nEmployees should have appropriate mechanisms for raising concerns about discrimination, harassment, or violations of mental health rights.\r\n\r\nThe HRMS may support:\r\n\r\n1. Complaint intake;\r\n2. Case tracking;\r\n3. Investigation;\r\n4. Resolution;\r\n5. Referral;\r\n6. Audit trail.\r\n\r\nComplaint records involving mental health should have restricted access.\r\n\r\nCRISIS MANAGEMENT\r\n\r\nOrganizations should establish appropriate procedures for mental health emergencies.\r\n\r\nThe HRMS may record administrative information concerning an emergency response while avoiding unnecessary storage of clinical details.\r\n\r\nProfessional healthcare providers and emergency services should handle clinical assessment and treatment.\r\n\r\nTRAINING\r\n\r\nHR personnel, managers, supervisors, and other appropriate personnel may receive training concerning:\r\n\r\n1. Mental health awareness;\r\n2. Workplace stress;\r\n3. Anti-discrimination;\r\n4. Confidentiality;\r\n5. Referral procedures;\r\n6. Crisis response;\r\n7. Employee assistance;\r\n8. Workplace accommodations.\r\n\r\nMANAGER RESPONSIBILITIES\r\n\r\nManagers should maintain respectful workplace practices.\r\n\r\nManagers should not attempt to diagnose employees.\r\n\r\nManagers should refer employees to qualified professionals or designated HR support channels when appropriate.\r\n\r\nManagers should protect employee confidentiality.\r\n\r\nHRMS DATA MANAGEMENT\r\n\r\nThe HRMS should separate administrative HR records from clinical mental health records whenever possible.\r\n\r\nRecommended administrative fields include:\r\n\r\n1. Employee ID;\r\n2. Program participation;\r\n3. Referral status;\r\n4. Accommodation status;\r\n5. Wellness activity;\r\n6. Case status;\r\n7. Date of action;\r\n8. Authorized personnel.\r\n\r\nDetailed medical or psychological information should remain in the appropriate confidential medical record system.\r\n\r\nACCESS CONTROL\r\n\r\nMental health-related records should be accessible only to authorized personnel.\r\n\r\nRecommended access levels include:\r\n\r\n1. HR administrator;\r\n2. Occupational health personnel;\r\n3. Authorized medical personnel;\r\n4. Authorized compliance officer.\r\n\r\nOrdinary supervisors should not have access to confidential medical information.\r\n\r\nAUDIT TRAIL\r\n\r\nAccess and changes to confidential mental health records should be logged.\r\n\r\nThe audit trail may include:\r\n\r\n1. User;\r\n2. Action;\r\n3. Record accessed;\r\n4. Date;\r\n5. Time;\r\n6. Purpose where required;\r\n7. Result.\r\n\r\nDATA RETENTION\r\n\r\nMental health information should not be retained indefinitely without a legitimate purpose.\r\n\r\nRetention periods should be based on applicable laws, regulations, medical-record requirements, organizational policies, and legitimate business purposes.\r\n\r\nSECURE DISPOSAL\r\n\r\nWhen records are no longer required, they should be securely disposed of according to applicable retention policies and privacy requirements.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nThe HRMS may monitor:\r\n\r\n1. Workplace mental health program status;\r\n2. Employee wellness activities;\r\n3. Mental health awareness training;\r\n4. Employee assistance availability;\r\n5. Referral mechanisms;\r\n6. Accommodation requests;\r\n7. Anti-discrimination complaints;\r\n8. Compliance activities;\r\n9. Policy acknowledgement;\r\n10. Program evaluations.\r\n\r\nThe monitoring system should avoid unnecessary disclosure of individual mental health information.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS may store:\r\n\r\n1. Mental health policies;\r\n2. Workplace wellness policies;\r\n3. Employee assistance procedures;\r\n4. Referral procedures;\r\n5. Training materials;\r\n6. Program reports;\r\n7. Policy acknowledgements;\r\n8. Compliance documents.\r\n\r\nClinical records should not be stored in ordinary document-management areas unless specifically authorized and appropriately secured.\r\n\r\nREPORTING\r\n\r\nThe HRMS may generate aggregate reports such as:\r\n\r\n1. Number of wellness activities;\r\n2. Number of employees reached by awareness programs;\r\n3. Training completion;\r\n4. Program participation;\r\n5. Accommodation requests;\r\n6. Compliance status.\r\n\r\nReports should use aggregated information whenever individual identification is unnecessary.\r\n\r\nRELATED LAWS\r\n\r\nThe HRMS should link RA 11036 with:\r\n\r\n1. Republic Act No. 10173;\r\n2. Republic Act No. 11058;\r\n3. Labor Code of the Philippines;\r\n4. Republic Act No. 7277;\r\n5. Republic Act No. 11223;\r\n6. Applicable DOLE occupational safety and health regulations;\r\n7. Applicable Department of Health regulations.\r\n\r\nREPUBLIC ACT NO. 11058\r\n\r\nRA 11058 concerns occupational safety and health standards.\r\n\r\nMental health and psychological well-being may be integrated into broader occupational safety and health programs where applicable.\r\n\r\nREPUBLIC ACT NO. 10173\r\n\r\nRA 10173 provides privacy protections for personal information.\r\n\r\nIt is particularly relevant when an HRMS processes mental health or medical information.\r\n\r\nEMPLOYEE RIGHTS\r\n\r\nEmployees should be treated with dignity and respect.\r\n\r\nMental health information should not be used for discriminatory purposes.\r\n\r\nEmployees should have access to appropriate support and referral mechanisms.\r\n\r\nLEGAL COMPLIANCE\r\n\r\nThe organization should maintain a workplace environment that supports mental health and protects employees from discrimination.\r\n\r\nPolicies should be reviewed periodically to reflect current legal requirements and government regulations.\r\n\r\nHRMS COMPLIANCE DASHBOARD\r\n\r\nThe HRMS may include:\r\n\r\n1. Mental health policy status;\r\n2. Wellness program status;\r\n3. Mental health training completion;\r\n4. Employee assistance availability;\r\n5. Accommodation requests;\r\n6. Compliance tasks;\r\n7. Related policy acknowledgements;\r\n8. Audit activities.\r\n\r\nNo confidential clinical information should be displayed on a general compliance dashboard.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nRA 11036 should be interpreted together with its implementing rules and regulations, applicable DOLE occupational safety and health requirements, Department of Health regulations, the Data Privacy Act, and other applicable laws.\r\n\r\nThe HRMS should not be used to diagnose mental health conditions.\r\n\r\nClinical assessment and treatment should be performed only by qualified and licensed professionals.\r\n\r\nFor current compliance implementation, HR should verify the latest applicable government regulations and issuances.','2026-08-13 16:03:30'),
(33,'Occupational Safety and Health Standards','DOLE OSHS','Occupational Safety and Health Standards',1,NULL,NULL,'Department of Labor and Employment','Active','DOLE OSHS, Occupational Safety and Health Standards, OSH, occupational safety, occupational health, workplace safety, workplace health, workplace hazards, hazard identification, risk assessment, safety officer, safety committee, personal protective equipment, PPE, workplace inspection, emergency preparedness, first aid, industrial hygiene','https://oshc.dole.gov.ph/','modules/compliance/assets/law_reference/DOLE Occupational Safety and Health Standards (OSHS).pdf','Republic Act No. 11058; Department Order No. 252-25; Department Order No. 198-18; Labor Code of the Philippines','The Occupational Safety and Health Standards provide technical and administrative requirements intended to protect workers from occupational hazards and promote safe and healthful working conditions. The standards cover workplace safety, occupational health, hazard identification, risk assessment, workplace inspection, personal protective equipment, emergency preparedness, first aid, industrial hygiene, machinery safety, electrical safety, chemical safety, and other occupational safety and health requirements.','This reference should be connected to the HRMS Risk Assessment, Incident Management, Employee Clinic, Learning and Development, Audit and Reporting, Compliance Calendar, and Occupational Safety and Health modules. Specific requirements should be evaluated based on the nature of the establishment, workplace hazards, number of workers, and applicable DOLE regulations.',1,1,'2026-08-13 17:26:43','DOLE Occupational Safety and Health Standards (OSHS)','Occupational Safety and Health Standards','Department of Labor and Employment','DOLE OSHS',NULL,'The Occupational Safety and Health Standards establish technical requirements for protecting workers against occupational hazards and promoting safe and healthful working conditions.','dole_occupational_safety_health_standards.pdf','DOLE OCCUPATIONAL SAFETY AND HEALTH STANDARDS\r\n\r\nThe Occupational Safety and Health Standards provide requirements for maintaining safe and healthful workplaces.\r\n\r\nThe standards cover workplace safety and occupational health measures designed to prevent accidents, injuries, illnesses, and exposure to occupational hazards.\r\n\r\nGENERAL OCCUPATIONAL SAFETY\r\n\r\nEmployers should identify workplace hazards and implement appropriate measures to eliminate, reduce, or control those hazards.\r\n\r\nOccupational safety management may include hazard identification, risk assessment, workplace inspection, safety training, emergency preparedness, incident investigation, corrective action, and record keeping.\r\n\r\nHAZARD IDENTIFICATION\r\n\r\nWorkplace hazards may include physical, chemical, biological, mechanical, electrical, ergonomic, environmental, and other occupational hazards.\r\n\r\nOrganizations should identify hazards associated with their workplace activities and determine appropriate preventive measures.\r\n\r\nRISK ASSESSMENT\r\n\r\nWorkplace risks should be evaluated according to the likelihood and severity of potential harm.\r\n\r\nRisk assessment records may include the hazard, location, likelihood, severity, risk level, existing controls, recommended controls, responsible person, target date, and compliance status.\r\n\r\nOCCUPATIONAL SAFETY AND HEALTH PROGRAM\r\n\r\nCovered establishments should maintain an appropriate occupational safety and health program consistent with applicable laws and regulations.\r\n\r\nThe program may include safety policies, hazard identification, risk assessment, preventive measures, emergency procedures, training, workplace inspections, incident reporting, occupational health activities, and corrective actions.\r\n\r\nSAFETY OFFICER\r\n\r\nQualified safety personnel should be designated as required by applicable occupational safety and health regulations.\r\n\r\nSafety officers may assist in workplace inspections, hazard identification, safety training, incident investigation, safety documentation, and corrective action monitoring.\r\n\r\nSAFETY COMMITTEE\r\n\r\nWhere required, establishments should establish an occupational safety and health committee.\r\n\r\nThe committee may review workplace hazards, incidents, inspection findings, corrective actions, training requirements, emergency preparedness, and other safety concerns.\r\n\r\nWORKPLACE INSPECTION\r\n\r\nWorkplaces should be inspected to identify unsafe conditions and determine whether corrective action is necessary.\r\n\r\nInspection records may include the inspection date, location, inspector, finding, risk level, corrective action, responsible person, target completion date, verification, and status.\r\n\r\nWORK ENVIRONMENT MEASUREMENT\r\n\r\nWork environment measurement may be necessary where employees are exposed to environmental or occupational hazards.\r\n\r\nMeasurements may concern noise, heat, illumination, ventilation, vibration, dust, chemicals, gases, and other workplace exposures.\r\n\r\nPERSONAL PROTECTIVE EQUIPMENT\r\n\r\nAppropriate personal protective equipment should be provided when required by identified workplace hazards and applicable standards.\r\n\r\nPPE may include safety helmets, eye protection, face protection, hearing protection, respiratory protection, gloves, safety footwear, protective clothing, fall protection equipment, and other job-specific protective equipment.\r\n\r\nFIRE SAFETY\r\n\r\nWorkplaces should maintain appropriate fire prevention and emergency procedures.\r\n\r\nFire safety measures may include emergency exits, fire extinguishers, alarms, evacuation procedures, emergency drills, fire safety training, and appropriate signage.\r\n\r\nELECTRICAL SAFETY\r\n\r\nElectrical systems and equipment should be properly installed, maintained, and operated to minimize electrical hazards.\r\n\r\nMACHINE SAFETY\r\n\r\nMachinery and equipment should be operated and maintained in a manner that protects workers from moving parts, mechanical hazards, and other foreseeable risks.\r\n\r\nCHEMICAL SAFETY\r\n\r\nHazardous chemicals should be properly identified, labeled, stored, handled, and controlled.\r\n\r\nChemical safety may require appropriate information, exposure controls, protective equipment, emergency procedures, worker training, and proper disposal.\r\n\r\nBIOLOGICAL SAFETY\r\n\r\nWorkplaces involving biological hazards should implement appropriate sanitation, hygiene, protective equipment, exposure prevention, and waste-management procedures.\r\n\r\nERGONOMIC SAFETY\r\n\r\nWorkplace activities should be assessed for ergonomic hazards such as repetitive movements, prolonged sitting, improper posture, heavy lifting, and awkward work positions.\r\n\r\nFIRST AID\r\n\r\nAppropriate first-aid facilities, supplies, and trained first-aiders should be available as required.\r\n\r\nThe HRMS may monitor first-aid training, certification, and renewal requirements.\r\n\r\nEMERGENCY PREPAREDNESS\r\n\r\nOrganizations should establish appropriate emergency procedures for foreseeable workplace emergencies.\r\n\r\nEmergency planning may include fire, earthquake, severe weather, medical emergencies, chemical incidents, workplace accidents, evacuation, and other emergency situations.\r\n\r\nINCIDENT REPORTING\r\n\r\nWorkplace accidents, injuries, illnesses, and other applicable incidents should be documented and reported according to applicable requirements.\r\n\r\nIncident records may include the incident number, employee, date, time, location, incident type, description, injury information, immediate action, investigation, root cause, corrective action, and final status.\r\n\r\nINCIDENT INVESTIGATION\r\n\r\nWorkplace incidents should be investigated where required to determine causes and contributing factors and to establish corrective or preventive measures.\r\n\r\nCORRECTIVE ACTION\r\n\r\nSafety findings should be assigned to responsible persons and monitored until completion.\r\n\r\nCorrective action records may include the finding, required action, responsible person, deadline, status, completion date, verification, and supporting documentation.\r\n\r\nSAFETY TRAINING\r\n\r\nWorkers should receive appropriate occupational safety and health information and training.\r\n\r\nTraining may cover workplace hazards, safe work procedures, emergency response, fire safety, first aid, PPE, chemical safety, equipment safety, incident reporting, and job-specific safety requirements.\r\n\r\nEMPLOYEE SAFETY RECORDS\r\n\r\nThe HRMS may maintain employee safety records concerning safety orientation, training, certifications, PPE issuance, emergency drills, and other authorized safety activities.\r\n\r\nMEDICAL AND OCCUPATIONAL HEALTH RECORDS\r\n\r\nOccupational health records should be maintained securely.\r\n\r\nAccess to medical information should be limited to authorized health and occupational safety personnel.\r\n\r\nDATA PRIVACY\r\n\r\nEmployee health, medical, and other personal information contained in OSH records should be protected in accordance with Republic Act No. 10173, or the Data Privacy Act of 2012.\r\n\r\nThe HRMS should implement appropriate access controls, confidentiality measures, retention rules, and security safeguards.\r\n\r\nWORKER PARTICIPATION\r\n\r\nWorkers should be provided appropriate opportunities to participate in occupational safety and health activities.\r\n\r\nParticipation may include safety committees, hazard reporting, safety inspections, training, emergency drills, and safety consultations.\r\n\r\nHAZARD REPORTING\r\n\r\nThe organization should provide an appropriate mechanism for employees to report unsafe conditions and workplace hazards.\r\n\r\nThe HRMS may provide a safety concern reporting function containing the reporter, location, hazard, description, date, supporting evidence, assigned person, corrective action, and resolution.\r\n\r\nCOMPLIANCE DOCUMENTATION\r\n\r\nRelevant OSH records should be maintained and made available when required.\r\n\r\nRecords may include the OSH program, risk assessments, workplace inspections, safety training, safety officer documentation, safety committee records, PPE records, incident reports, emergency drill records, and corrective action records.\r\n\r\nCOMPLIANCE AUDIT\r\n\r\nThe HRMS Compliance module may conduct periodic occupational safety and health audits.\r\n\r\nAudit areas may include the OSH program, workplace inspections, risk assessment, safety training, PPE, emergency preparedness, incident management, occupational health, safety officer compliance, and required documentation.\r\n\r\nCOMPLIANCE CALENDAR\r\n\r\nThe HRMS may schedule workplace inspections, safety training, certification renewals, emergency drills, safety committee meetings, risk assessments, corrective action deadlines, and compliance reviews.\r\n\r\nCOMPLIANCE NOTIFICATIONS\r\n\r\nThe HRMS may generate notifications for expiring safety certifications, upcoming training, overdue inspections, high-risk findings, open corrective actions, incident investigation deadlines, emergency drills, and required compliance reports.\r\n\r\nHRMS RISK REGISTER\r\n\r\nThe OSHS reference should be connected to the HRMS Risk Register.\r\n\r\nRisk records may contain the hazard, risk category, location, likelihood, severity, risk score, existing controls, recommended controls, responsible person, deadline, and status.\r\n\r\nHRMS EMPLOYEE CLINIC\r\n\r\nThe Employee Clinic module may support occupational health compliance by maintaining authorized records concerning workplace injuries, first aid, medical referrals, and occupational health activities.\r\n\r\nConfidential clinical information should not be displayed to unauthorized HR users.\r\n\r\nHRMS AUDIT TRAIL\r\n\r\nImportant occupational safety and health compliance activities should be recorded in the HRMS audit trail.\r\n\r\nAudit entries may include the user, action, affected record, date, time, previous value, new value, and reason.\r\n\r\nRELATED LAWS\r\n\r\nRepublic Act No. 11058 provides the statutory framework for strengthening compliance with occupational safety and health standards.\r\n\r\nDepartment Order No. 252-25 provides revised implementing rules and regulations related to Republic Act No. 11058.\r\n\r\nDepartment Order No. 198-18 was an earlier implementing issuance concerning Republic Act No. 11058.\r\n\r\nRepublic Act No. 10173 applies to personal and sensitive personal information contained in HR and occupational health records.\r\n\r\nRepublic Act No. 11036 may also be relevant to workplace mental health and psychosocial health concerns.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nThe Occupational Safety and Health Standards should be maintained as an active compliance reference and monitored together with subsequent DOLE issuances, amendments, and applicable occupational safety and health regulations.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis reference is intended for HRMS legal-reference and compliance-monitoring purposes.\r\n\r\nActual occupational safety and health compliance requirements may vary according to the nature of the establishment, workplace activities, hazards, workforce size, and applicable regulations.\r\n\r\nThe complete and current OSHS, Republic Act No. 11058, Department Order No. 252-25, and other applicable DOLE issuances should be consulted for actual compliance decisions.','2026-08-13 16:06:41'),
(34,'Department Order','Department Order No. 235-22','Rules on Certification of First Aiders and Accreditation of First Aid Training Providers',1,'2022-12-12',NULL,'Department of Labor and Employment','Active','Department Order No. 235-22, DO 235-22, first aider, first aid, first aid training, first aid training provider, accreditation, certification, occupational safety and health, OSH, safety officer, workplace emergency, emergency response, first aid certification, DOLE, Occupational Safety and Health Center, OSHC','https://oshc.dole.gov.ph/','modules/compliance/assets/law_reference/Department Order No. 235-22 - Rules on Certification of First Aiders and Accreditation of First Aid Training Providers.pdf','Republic Act No. 11058; Department Order No. 198-18; Department Order No. 252-25; Occupational Safety and Health Standards','Department Order No. 235-22 establishes rules concerning the certification of first aiders and the accreditation of first aid training providers for occupational safety and health purposes. It provides requirements concerning first aider certification, first aid training, training providers, accreditation, qualifications, training programs, assessment, documentation, and related compliance requirements.','This reference should be connected to the HRMS Occupational Safety and Health, Employee Clinic, Learning and Development, Compliance Calendar, Employee Documents, and Audit and Reporting modules. The HRMS may monitor designated first aiders, training completion, certificates, certification validity, renewal requirements, accredited training providers, and first aid training schedules.',1,1,'2026-08-13 18:34:22','Department Order No. 235-22 - Rules on Certification of First Aiders and Accreditation of First Aid Training Providers','Department Order','Department of Labor and Employment','D.O. No. 235-22','2022','Rules governing the certification of first aiders and the accreditation of first aid training providers for occupational safety and health purposes.','do_235_22_first_aiders_training_providers.pdf','DEPARTMENT ORDER NO. 235-22\r\n\r\nRULES ON CERTIFICATION OF FIRST AIDERS AND ACCREDITATION OF FIRST AID TRAINING PROVIDERS\r\n\r\nPURPOSE\r\n\r\nDepartment Order No. 235-22 establishes rules concerning the certification of first aiders and the accreditation of first aid training providers in relation to occupational safety and health.\r\n\r\nThe issuance supports the requirement for workplaces to have appropriately trained personnel capable of providing immediate first aid assistance during workplace emergencies.\r\n\r\nLEGAL BASIS\r\n\r\nThe issuance is related to the occupational safety and health framework established under Republic Act No. 11058 and its implementing rules and regulations.\r\n\r\nIt should be read together with the Occupational Safety and Health Standards and other applicable Department of Labor and Employment issuances.\r\n\r\nFIRST AIDER\r\n\r\nA first aider is a person who has undergone appropriate first aid training and is qualified to provide immediate assistance to a person who becomes ill or injured before professional medical assistance becomes available.\r\n\r\nFirst aiders play an important role in workplace emergency preparedness.\r\n\r\nFIRST AIDER CERTIFICATION\r\n\r\nCertification of first aiders is subject to the applicable requirements established by the Department of Labor and Employment.\r\n\r\nThe HRMS may maintain a first aider certification record containing:\r\n\r\n1. Employee name;\r\n2. Employee identification number;\r\n3. Department;\r\n4. Position;\r\n5. First aider designation;\r\n6. Training provider;\r\n7. Training program;\r\n8. Training date;\r\n9. Certificate number;\r\n10. Certification date;\r\n11. Expiration or renewal date where applicable;\r\n12. Certification status;\r\n13. Supporting certificate.\r\n\r\nFIRST AIDER QUALIFICATION\r\n\r\nPersons designated as first aiders should complete the appropriate first aid training required under applicable occupational safety and health rules.\r\n\r\nThe organization should designate first aiders based on workplace requirements and applicable regulations.\r\n\r\nFIRST AID TRAINING\r\n\r\nFirst aid training provides workers with knowledge and skills necessary to respond to workplace emergencies.\r\n\r\nTraining may include:\r\n\r\n1. Basic first aid principles;\r\n2. Emergency assessment;\r\n3. Cardiopulmonary resuscitation;\r\n4. Basic life support where included in the approved training;\r\n5. Management of injuries;\r\n6. Management of medical emergencies;\r\n7. Bleeding control;\r\n8. Shock management;\r\n9. Fracture and sprain management;\r\n10. Burns;\r\n11. Emergency transport;\r\n12. Workplace emergency procedures.\r\n\r\nTRAINING PROVIDERS\r\n\r\nFirst aid training providers must meet applicable requirements for accreditation.\r\n\r\nAccredited providers should deliver training consistent with applicable standards and requirements.\r\n\r\nThe HRMS may maintain an accredited training provider database containing:\r\n\r\n1. Provider name;\r\n2. Accreditation number;\r\n3. Accreditation status;\r\n4. Accreditation date;\r\n5. Validity information;\r\n6. Training programs;\r\n7. Contact information;\r\n8. Supporting accreditation documents.\r\n\r\nACCREDITATION\r\n\r\nAccreditation allows qualified training providers to conduct recognized first aid training subject to applicable requirements.\r\n\r\nTraining providers should comply with requirements imposed by the Department of Labor and Employment and its appropriate offices.\r\n\r\nTRAINING PROGRAM\r\n\r\nFirst aid training programs should comply with applicable content, duration, competency, trainer, facility, equipment, and assessment requirements.\r\n\r\nThe HRMS Learning and Development module may store the training program and associated records.\r\n\r\nTRAINING RECORDS\r\n\r\nThe organization should maintain appropriate documentation showing completion of required first aid training.\r\n\r\nRecords may include:\r\n\r\n1. Employee;\r\n2. Course;\r\n3. Provider;\r\n4. Trainer;\r\n5. Training date;\r\n6. Training hours;\r\n7. Certificate number;\r\n8. Certification status;\r\n9. Renewal date;\r\n10. Supporting documents.\r\n\r\nCERTIFICATE MANAGEMENT\r\n\r\nThe HRMS may provide document management for first aider certificates.\r\n\r\nCertificates should be stored securely and accessible only to authorized personnel.\r\n\r\nThe system may automatically notify HR and designated safety personnel when certificates approach expiration or renewal dates.\r\n\r\nFIRST AIDER DATABASE\r\n\r\nThe HRMS may maintain a centralized first aider registry.\r\n\r\nThe registry may contain:\r\n\r\n1. First aider ID;\r\n2. Employee;\r\n3. Department;\r\n4. Workplace location;\r\n5. Designation;\r\n6. Training provider;\r\n7. Certificate;\r\n8. Certification date;\r\n9. Validity;\r\n10. Status.\r\n\r\nWORKPLACE COVERAGE\r\n\r\nThe organization should determine the number and distribution of first aiders required according to applicable occupational safety and health requirements.\r\n\r\nFirst aiders should be appropriately assigned to workplace areas where their services may be needed.\r\n\r\nThe HRMS may monitor first aider coverage by department, building, floor, campus, or workplace location.\r\n\r\nEMERGENCY RESPONSE\r\n\r\nFirst aiders form part of the organization emergency response capability.\r\n\r\nEmergency response procedures may include:\r\n\r\n1. Recognition of an emergency;\r\n2. Immediate first aid;\r\n3. Activation of emergency response;\r\n4. Contacting medical assistance;\r\n5. Emergency transportation;\r\n6. Incident documentation;\r\n7. Follow-up.\r\n\r\nFIRST AID FACILITIES\r\n\r\nWorkplaces should maintain appropriate first aid facilities and supplies according to applicable occupational safety and health requirements.\r\n\r\nThe HRMS may maintain an inventory of first aid supplies.\r\n\r\nInventory records may include:\r\n\r\n1. Item;\r\n2. Quantity;\r\n3. Location;\r\n4. Expiration date;\r\n5. Reorder level;\r\n6. Responsible person;\r\n7. Inspection date;\r\n8. Status.\r\n\r\nFIRST AID KIT MONITORING\r\n\r\nThe HRMS may provide alerts for first aid supplies requiring replacement.\r\n\r\nThe system may monitor:\r\n\r\n1. Expired supplies;\r\n2. Low inventory;\r\n3. Missing items;\r\n4. Inspection schedules;\r\n5. Responsible personnel.\r\n\r\nTRAINER QUALIFICATIONS\r\n\r\nFirst aid training should be delivered by appropriately qualified trainers under applicable accreditation requirements.\r\n\r\nTraining providers should maintain appropriate trainer qualifications and supporting documentation.\r\n\r\nTRAINING PROVIDER MONITORING\r\n\r\nThe HRMS Compliance module may monitor training provider accreditation.\r\n\r\nRecords may include:\r\n\r\n1. Provider;\r\n2. Accreditation number;\r\n3. Accreditation status;\r\n4. Accreditation date;\r\n5. Validity period;\r\n6. Authorized training;\r\n7. Supporting documents.\r\n\r\nTRAINING SCHEDULE\r\n\r\nThe HRMS Learning and Development module may schedule first aid training sessions.\r\n\r\nSchedule information may include:\r\n\r\n1. Training title;\r\n2. Provider;\r\n3. Trainer;\r\n4. Date;\r\n5. Time;\r\n6. Venue;\r\n7. Participants;\r\n8. Training hours;\r\n9. Status.\r\n\r\nEMPLOYEE TRAINING STATUS\r\n\r\nThe system may classify employees as:\r\n\r\n1. Certified first aider;\r\n2. Training scheduled;\r\n3. Training completed;\r\n4. Certification pending;\r\n5. Certification expired;\r\n6. Renewal required;\r\n7. Not designated.\r\n\r\nCOMPLIANCE CALENDAR\r\n\r\nThe HRMS Compliance Calendar may contain:\r\n\r\n1. First aid training;\r\n2. Certification renewal;\r\n3. First aid kit inspection;\r\n4. Training provider accreditation monitoring;\r\n5. Emergency drills;\r\n6. OSH compliance reviews.\r\n\r\nNOTIFICATIONS\r\n\r\nThe system may generate alerts for:\r\n\r\n1. Expiring first aider certificates;\r\n2. Upcoming first aid training;\r\n3. Expired certifications;\r\n4. Training provider accreditation expiration;\r\n5. First aid kit inspection deadlines;\r\n6. Emergency preparedness activities.\r\n\r\nEMPLOYEE CLINIC\r\n\r\nThe Employee Clinic module may coordinate first aid and workplace emergency records.\r\n\r\nClinic personnel may document first aid treatment and workplace incidents subject to applicable privacy and confidentiality requirements.\r\n\r\nMedical information should be restricted to authorized personnel.\r\n\r\nINCIDENT MANAGEMENT\r\n\r\nFirst aid activities may be associated with workplace incident records.\r\n\r\nIncident records may include:\r\n\r\n1. Incident number;\r\n2. Employee;\r\n3. Date;\r\n4. Time;\r\n5. Location;\r\n6. Incident type;\r\n7. Injury;\r\n8. First aid provided;\r\n9. First aider;\r\n10. Referral;\r\n11. Investigation;\r\n12. Corrective action.\r\n\r\nPRIVACY AND CONFIDENTIALITY\r\n\r\nFirst aid and medical information may contain personal and sensitive personal information.\r\n\r\nRepublic Act No. 10173, or the Data Privacy Act of 2012, should be considered when collecting, storing, accessing, or disclosing such information.\r\n\r\nThe HRMS should implement appropriate access controls and security safeguards.\r\n\r\nROLE-BASED ACCESS\r\n\r\nAccess to first aider records should be based on job responsibilities.\r\n\r\nPossible authorized users include:\r\n\r\n1. HR administrator;\r\n2. Compliance officer;\r\n3. Safety officer;\r\n4. Employee clinic personnel;\r\n5. Authorized management personnel.\r\n\r\nOrdinary employees should not have access to confidential medical information.\r\n\r\nAUDIT TRAIL\r\n\r\nThe HRMS should maintain audit records for important first aider compliance activities.\r\n\r\nAudit records may include:\r\n\r\n1. User;\r\n2. Action;\r\n3. Record affected;\r\n4. Date;\r\n5. Time;\r\n6. Previous value;\r\n7. New value;\r\n8. Reason.\r\n\r\nCOMPLIANCE AUDIT\r\n\r\nThe HRMS Compliance module may audit:\r\n\r\n1. First aider designation;\r\n2. Certification status;\r\n3. Training completion;\r\n4. Certification validity;\r\n5. Training provider accreditation;\r\n6. First aid facilities;\r\n7. First aid kit inspection;\r\n8. Emergency preparedness;\r\n9. Required documentation.\r\n\r\nRISK MANAGEMENT\r\n\r\nFirst aider compliance should be considered within the organization occupational safety and health risk management program.\r\n\r\nThe HRMS Risk Register may identify inadequate first aider coverage as a potential workplace safety risk.\r\n\r\nCORRECTIVE ACTION\r\n\r\nIf required first aider coverage or certification is lacking, the organization may create corrective action records.\r\n\r\nCorrective action may include:\r\n\r\n1. Designating additional first aiders;\r\n2. Scheduling training;\r\n3. Renewing certification;\r\n4. Engaging an accredited training provider;\r\n5. Updating emergency procedures;\r\n6. Improving first aid facilities.\r\n\r\nCOMPLIANCE REPORTING\r\n\r\nThe HRMS may generate first aider compliance reports containing:\r\n\r\n1. Total designated first aiders;\r\n2. Certified first aiders;\r\n3. Expiring certifications;\r\n4. Expired certifications;\r\n5. Employees scheduled for training;\r\n6. Training completion rate;\r\n7. Accredited training providers;\r\n8. Outstanding corrective actions.\r\n\r\nCOMPLIANCE DASHBOARD\r\n\r\nThe OSH dashboard may display:\r\n\r\n1. First aider compliance rate;\r\n2. Active first aider count;\r\n3. Expiring certifications;\r\n4. Expired certifications;\r\n5. Upcoming training;\r\n6. Provider accreditation status;\r\n7. First aid kit compliance;\r\n8. Open corrective actions.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS may store:\r\n\r\n1. First aider certificates;\r\n2. Training records;\r\n3. Training provider accreditation documents;\r\n4. Training attendance sheets;\r\n5. Training materials;\r\n6. First aid inspection reports;\r\n7. Emergency response records.\r\n\r\nRECORD RETENTION\r\n\r\nFirst aider and training records should be retained according to applicable legal, regulatory, and organizational retention requirements.\r\n\r\nRecords should be securely stored and disposed of when no longer required, subject to applicable law.\r\n\r\nRELATED LAW\r\n\r\nRepublic Act No. 11058 establishes the occupational safety and health framework.\r\n\r\nDepartment Order No. 252-25 provides revised implementing rules related to Republic Act No. 11058.\r\n\r\nThe Occupational Safety and Health Standards provide technical requirements for workplace safety and occupational health.\r\n\r\nRepublic Act No. 10173 applies to the protection of personal and sensitive personal information contained in employee and health records.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nDepartment Order No. 235-22 should be monitored together with subsequent DOLE issuances, amendments, and applicable occupational safety and health regulations.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis record is intended for HRMS legal-reference and compliance-monitoring purposes.\r\n\r\nActual certification, training, accreditation, and workplace first aid requirements should be verified against the complete and current text of Department Order No. 235-22 and other applicable DOLE occupational safety and health issuances.','2026-08-13 16:08:01'),
(35,'Department Order','Department Order No. 147-15','Rules and Regulations Governing the Employment and Working Conditions of Security Guards in the Private Security Industry',1,'2015-10-09',NULL,'Department of Labor and Employment','Active','Department Order No. 147-15, DO 147-15, security guards, private security industry, security agency, security services, employment conditions, working conditions, wages, benefits, hours of work, rest periods, overtime, holiday pay, service incentive leave, 13th month pay, statutory benefits, labor standards, DOLE','https://www.dole.gov.ph/','modules/compliance/assets/law_reference/do_147_15_security_guards.pdf','Labor Code of the Philippines; Republic Act No. 6727; Republic Act No. 10361 where applicable; Republic Act No. 11058; Republic Act No. 10151; Presidential Decree No. 851','Department Order No. 147-15 provides rules and regulations concerning the employment and working conditions of security guards employed in the private security industry. It addresses labor standards and employment conditions applicable to security guards, including wages, working hours, rest periods, overtime work, holiday and premium pay, leave benefits, statutory monetary benefits, social protection, employment records, and other conditions of employment.','For HRMS compliance purposes, this reference may be linked to employee records, employment contracts, attendance and timekeeping, payroll, government contributions, leave management, incident management, compliance monitoring, and audit reporting. The actual application of specific provisions should be evaluated according to the employment arrangement, applicable labor standards, and subsequent DOLE issuances.',1,1,'2026-08-13 17:23:31','Department Order No. 147-15 - Rules and Regulations Governing the Employment and Working Conditions of Security Guards in the Private Security Industry','Department Order','Department of Labor and Employment','D.O. No. 147-15','2015','Rules and regulations governing the employment and working conditions of security guards in the private security industry.','do_147_15_security_guards.pdf','DEPARTMENT ORDER NO. 147-15\r\n\r\nRULES AND REGULATIONS GOVERNING THE EMPLOYMENT AND WORKING CONDITIONS OF SECURITY GUARDS IN THE PRIVATE SECURITY INDUSTRY\r\n\r\nPURPOSE\r\n\r\nDepartment Order No. 147-15 establishes rules governing the employment and working conditions of security guards employed in the private security industry.\r\n\r\nThe issuance is intended to ensure compliance with applicable labor standards and to provide appropriate protection for security guards in relation to their employment.\r\n\r\nCOVERAGE\r\n\r\nThe rules apply to security guards employed by private security agencies and other covered establishments within the scope of the issuance.\r\n\r\nThe applicable employment relationship and responsibilities of the parties should be determined based on the actual employment arrangement and applicable law.\r\n\r\nEMPLOYMENT RELATIONSHIP\r\n\r\nSecurity guards may be deployed to client establishments by private security agencies.\r\n\r\nThe employment arrangement should comply with applicable labor standards.\r\n\r\nEmployment records should accurately identify the employer, employee, employment status, position, compensation, and applicable conditions of employment.\r\n\r\nEMPLOYMENT CONTRACT\r\n\r\nSecurity guards should be provided with appropriate documentation concerning their employment.\r\n\r\nThe HRMS may maintain employment contract records containing:\r\n\r\n1. Employee name;\r\n2. Employee identification number;\r\n3. Employer;\r\n4. Position;\r\n5. Employment status;\r\n6. Date of employment;\r\n7. Place of assignment;\r\n8. Basic wage;\r\n9. Benefits;\r\n10. Working schedule;\r\n11. Applicable policies;\r\n12. Contract status.\r\n\r\nWAGES\r\n\r\nSecurity guards are entitled to wages consistent with applicable minimum wage laws and regulations.\r\n\r\nEmployers should comply with the applicable regional wage orders and other wage-related issuances.\r\n\r\nThe HRMS Payroll module may monitor the applicable basic wage and statutory wage adjustments.\r\n\r\nWAGE ORDERS\r\n\r\nThe applicable minimum wage depends on the region, wage category, and other factors established by the appropriate Regional Tripartite Wages and Productivity Board.\r\n\r\nThe HRMS should therefore avoid hard-coding a single national minimum wage for security guards.\r\n\r\nWORKING HOURS\r\n\r\nWorking hours should comply with applicable provisions of the Labor Code and related regulations.\r\n\r\nThe HRMS Time and Attendance module may monitor scheduled working hours, actual working hours, overtime, rest periods, and other attendance information.\r\n\r\nOVERTIME WORK\r\n\r\nWhere employees are required or permitted to work beyond normal working hours, applicable overtime rules should be observed.\r\n\r\nThe HRMS may calculate and monitor overtime based on applicable payroll rules.\r\n\r\nREST PERIODS\r\n\r\nEmployees should receive applicable rest periods during the workday and appropriate weekly rest periods according to labor standards and the nature of the work.\r\n\r\nThe HRMS may monitor scheduled rest days and actual attendance.\r\n\r\nNIGHT WORK\r\n\r\nSecurity work may involve night assignments.\r\n\r\nApplicable rules concerning night work and night shift differential should be observed when the employee performs covered night work.\r\n\r\nThe HRMS Payroll module may calculate applicable night shift differential.\r\n\r\nHOLIDAY PAY\r\n\r\nSecurity guards should receive applicable holiday and premium pay in accordance with labor standards and applicable regulations.\r\n\r\nPayroll calculations should consider whether the day is an ordinary holiday, special day, or regular holiday and whether the employee worked on the relevant day.\r\n\r\nPREMIUM PAY\r\n\r\nPremium pay may apply to work performed during rest days or special days as provided by law.\r\n\r\nThe HRMS should calculate premium pay based on the applicable statutory rules.\r\n\r\nSERVICE INCENTIVE LEAVE\r\n\r\nCovered employees may be entitled to service incentive leave subject to the applicable Labor Code provisions and exceptions.\r\n\r\nThe HRMS Leave Management module may monitor leave entitlement, usage, balance, and applicable eligibility.\r\n\r\nTHIRTEENTH MONTH PAY\r\n\r\nCovered rank-and-file employees may be entitled to thirteenth month pay under applicable law.\r\n\r\nThe HRMS Payroll module may calculate thirteenth month pay using the applicable statutory formula.\r\n\r\nSTATUTORY BENEFITS\r\n\r\nSecurity guards should receive applicable statutory benefits.\r\n\r\nThese may include:\r\n\r\n1. Social Security System benefits and contributions;\r\n2. PhilHealth benefits and contributions;\r\n3. Pag-IBIG benefits and contributions;\r\n4. Employees Compensation;\r\n5. Other mandatory benefits under applicable law.\r\n\r\nThe HRMS Government Contributions module may monitor the applicable contributions.\r\n\r\nSOCIAL SECURITY\r\n\r\nCovered employees should be registered with and properly reported to the Social Security System where required.\r\n\r\nEmployee and employer contributions should be deducted and remitted according to current SSS rules.\r\n\r\nPHILHEALTH\r\n\r\nCovered employees should be properly registered with PhilHealth and applicable contributions should be remitted according to current PhilHealth rules.\r\n\r\nPAG-IBIG\r\n\r\nCovered employees should be registered with Pag-IBIG and applicable contributions should be deducted and remitted according to current HDMF rules.\r\n\r\nEMPLOYEES COMPENSATION\r\n\r\nEmployees covered by the Employees Compensation Program should receive applicable protection for work-related sickness, injury, disability, or death.\r\n\r\nThe HRMS may connect workplace incidents with applicable employee compensation records.\r\n\r\nOCCUPATIONAL SAFETY AND HEALTH\r\n\r\nSecurity guards are entitled to a safe and healthful working environment.\r\n\r\nEmployers should comply with applicable occupational safety and health requirements.\r\n\r\nRepublic Act No. 11058 and the Occupational Safety and Health Standards should be considered together with this issuance where applicable.\r\n\r\nPERSONAL PROTECTIVE EQUIPMENT\r\n\r\nWhere security work exposes employees to workplace hazards requiring personal protective equipment, appropriate PPE should be provided according to applicable occupational safety and health requirements.\r\n\r\nThe HRMS may monitor PPE issuance and replacement.\r\n\r\nWORKPLACE INCIDENTS\r\n\r\nSecurity guards may be exposed to risks arising from their assigned duties.\r\n\r\nWorkplace accidents and incidents should be documented and handled according to applicable occupational safety and health requirements.\r\n\r\nThe HRMS Incident Management module may record:\r\n\r\n1. Incident date;\r\n2. Incident time;\r\n3. Location;\r\n4. Employee;\r\n5. Incident type;\r\n6. Description;\r\n7. Immediate response;\r\n8. Investigation;\r\n9. Corrective action;\r\n10. Resolution.\r\n\r\nEMPLOYMENT RECORDS\r\n\r\nEmployers should maintain appropriate employment records.\r\n\r\nRecords may include:\r\n\r\n1. Employee information;\r\n2. Employment contract;\r\n3. Payroll records;\r\n4. Attendance records;\r\n5. Leave records;\r\n6. Benefits records;\r\n7. Government contribution records;\r\n8. Training records;\r\n9. Assignment records;\r\n10. Other required employment documents.\r\n\r\nDEPLOYMENT RECORDS\r\n\r\nFor security guards deployed to client establishments, the employer may maintain appropriate assignment records.\r\n\r\nThe HRMS may track:\r\n\r\n1. Security guard;\r\n2. Client establishment;\r\n3. Assignment location;\r\n4. Assignment start date;\r\n5. Assignment end date;\r\n6. Schedule;\r\n7. Post assignment;\r\n8. Supervisor;\r\n9. Status.\r\n\r\nSECURITY POST ASSIGNMENT\r\n\r\nSecurity guards may be assigned to specific security posts according to the requirements of the client establishment and the security agency.\r\n\r\nAssignment information should be properly documented.\r\n\r\nWORK SCHEDULE\r\n\r\nSecurity agencies should maintain appropriate schedules for deployed security guards.\r\n\r\nThe HRMS Schedule and Time and Attendance modules may track:\r\n\r\n1. Shift;\r\n2. Assignment;\r\n3. Date;\r\n4. Start time;\r\n5. End time;\r\n6. Rest day;\r\n7. Overtime;\r\n8. Attendance;\r\n9. Schedule changes.\r\n\r\nATTENDANCE\r\n\r\nAccurate attendance records should be maintained.\r\n\r\nThe HRMS may record actual time-in, time-out, undertime, absences, overtime, rest days, holidays, and other attendance information.\r\n\r\nPAYROLL\r\n\r\nPayroll records should accurately reflect applicable compensation and statutory deductions.\r\n\r\nThe HRMS Payroll module may integrate:\r\n\r\n1. Basic salary;\r\n2. Overtime;\r\n3. Night shift differential;\r\n4. Holiday pay;\r\n5. Premium pay;\r\n6. Leave pay;\r\n7. Statutory deductions;\r\n8. Government contributions;\r\n9. Other lawful deductions.\r\n\r\nDEDUCTIONS\r\n\r\nOnly lawful deductions should be made from employee compensation.\r\n\r\nThe HRMS should validate payroll deductions against applicable law and authorized employee deductions.\r\n\r\nEMPLOYMENT BENEFITS\r\n\r\nSecurity guards should receive benefits required under applicable labor laws.\r\n\r\nThe HRMS Benefits module may monitor statutory and company-provided benefits.\r\n\r\nTRAINING\r\n\r\nSecurity guards may be required to complete training appropriate to their duties and applicable regulations.\r\n\r\nThe HRMS Learning and Development module may maintain training records.\r\n\r\nTraining records may include:\r\n\r\n1. Training title;\r\n2. Training provider;\r\n3. Training date;\r\n4. Duration;\r\n5. Certificate;\r\n6. Expiration date;\r\n7. Status.\r\n\r\nEMPLOYEE DOCUMENTS\r\n\r\nThe HRMS may maintain required employment documents for security guards.\r\n\r\nDocuments may include:\r\n\r\n1. Employment contract;\r\n2. Identification documents;\r\n3. Training certificates;\r\n4. Assignment records;\r\n5. Government registration documents;\r\n6. Employment records;\r\n7. Other legally required documents.\r\n\r\nDOCUMENT EXPIRATION\r\n\r\nWhere security-related certifications or documents have expiration dates, the HRMS may issue reminders before expiration.\r\n\r\nThe Compliance Calendar may be used to schedule renewal requirements.\r\n\r\nDISCIPLINE\r\n\r\nEmployee disciplinary action should follow applicable labor law, employment policies, and due process requirements.\r\n\r\nThe HRMS Incident and Employee Relations modules may record disciplinary matters subject to appropriate access controls.\r\n\r\nTERMINATION\r\n\r\nTermination of employment should comply with applicable labor laws and due process requirements.\r\n\r\nThe HRMS Exit Management module may record separation information and required clearance documents.\r\n\r\nFINAL PAY\r\n\r\nUpon separation, the employer should process applicable final pay and other amounts required by law and company policy.\r\n\r\nThe HRMS Exit Management and Payroll modules may coordinate final pay processing.\r\n\r\n13TH MONTH PAY ON SEPARATION\r\n\r\nWhere applicable, the employee should receive the proportionate amount of thirteenth month pay required under law.\r\n\r\nThe HRMS Payroll module may calculate the applicable amount during final pay processing.\r\n\r\nCERTIFICATE OF EMPLOYMENT\r\n\r\nEmployees may request a certificate of employment subject to applicable requirements.\r\n\r\nThe HRMS Document Generation module may generate employment certificates from employee records.\r\n\r\nGOVERNMENT COMPLIANCE\r\n\r\nThe organization should maintain appropriate records and comply with government reporting and remittance obligations.\r\n\r\nThe HRMS Government Contributions and Compliance modules may monitor:\r\n\r\n1. SSS;\r\n2. PhilHealth;\r\n3. Pag-IBIG;\r\n4. Employees Compensation;\r\n5. Other applicable government requirements.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nThe HRMS Compliance module may monitor security guard employment compliance.\r\n\r\nCompliance categories may include:\r\n\r\n1. Wage compliance;\r\n2. Working hours;\r\n3. Overtime;\r\n4. Rest days;\r\n5. Night shift differential;\r\n6. Holiday pay;\r\n7. Leave benefits;\r\n8. Thirteenth month pay;\r\n9. Government contributions;\r\n10. Occupational safety and health;\r\n11. Employment documentation.\r\n\r\nAUDIT\r\n\r\nThe organization may conduct periodic compliance audits of security guard employment records.\r\n\r\nAudit records may include:\r\n\r\n1. Audit date;\r\n2. Auditor;\r\n3. Employee or group;\r\n4. Finding;\r\n5. Applicable requirement;\r\n6. Corrective action;\r\n7. Responsible person;\r\n8. Deadline;\r\n9. Resolution.\r\n\r\nCOMPLIANCE CALENDAR\r\n\r\nThe HRMS Compliance Calendar may schedule:\r\n\r\n1. Wage review;\r\n2. Government contribution deadlines;\r\n3. Training;\r\n4. Document renewal;\r\n5. OSH inspection;\r\n6. Employment record review;\r\n7. Compliance audit.\r\n\r\nNOTIFICATIONS\r\n\r\nThe HRMS may generate notifications for:\r\n\r\n1. Expiring documents;\r\n2. Upcoming training;\r\n3. Payroll compliance deadlines;\r\n4. Government contribution deadlines;\r\n5. Compliance audit dates;\r\n6. Open corrective actions.\r\n\r\nDATA PRIVACY\r\n\r\nEmployee information, payroll records, government identification numbers, employment documents, and other personal information should be processed in accordance with Republic Act No. 10173, or the Data Privacy Act of 2012.\r\n\r\nThe HRMS should implement appropriate role-based access, audit logging, data security, and retention controls.\r\n\r\nAUDIT TRAIL\r\n\r\nThe HRMS should record significant compliance actions.\r\n\r\nAudit trail entries may contain:\r\n\r\n1. User;\r\n2. Action;\r\n3. Affected record;\r\n4. Date;\r\n5. Time;\r\n6. Previous value;\r\n7. New value;\r\n8. Reason.\r\n\r\nRELATED LAWS\r\n\r\nDepartment Order No. 147-15 should be read together with the Labor Code of the Philippines and other applicable labor standards.\r\n\r\nRepublic Act No. 6727 and applicable regional wage orders should be considered for wage compliance.\r\n\r\nPresidential Decree No. 851 and related regulations should be considered for thirteenth month pay.\r\n\r\nRepublic Act No. 11058 and applicable Occupational Safety and Health Standards should be considered for workplace safety.\r\n\r\nRepublic Act No. 10173 should be considered when processing employee personal and sensitive personal information.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis reference is intended for HRMS legal-reference and compliance-monitoring purposes.\r\n\r\nThe actual rights, benefits, and obligations applicable to security guards depend on the specific employment arrangement, applicable wage orders, current DOLE regulations, and other relevant laws and issuances.\r\n\r\nThe complete and current text of Department Order No. 147-15 and subsequent amendments or related DOLE issuances should be consulted for actual legal compliance decisions.','2026-08-13 16:08:57'),
(36,'Department Order','Department Order No. 40-03','Revised Rules Implementing Book V of the Labor Code',1,'2003-02-17',NULL,'Department of Labor and Employment','Active','Department Order No. 40-03, DO 40-03, labor relations, Book V, Labor Code, labor organizations, registration, unions, workers association, collective bargaining, certification election, bargaining representative, unfair labor practice, strikes, lockouts, voluntary arbitration, conciliation, mediation, labor disputes, DOLE','https://www.dole.gov.ph/','modules/compliance/assets/law_reference/do_40_03_labor_relations.pdf','Labor Code of the Philippines, Book V; Executive Order No. 180; Republic Act No. 6715; Department Order No. 40-03-A','Department Order No. 40-03 contains the revised rules implementing Book V of the Labor Code concerning labor relations. It provides rules concerning labor organizations, registration and reporting requirements, workers associations, collective bargaining, representation, certification elections, labor disputes, strikes and lockouts, and related labor relations proceedings.','This reference may be linked to the HRMS Employee Relations, Labor Relations, Complaints, Incident Management, Legal Compliance, Audit and Reporting, Document Management, and Notification modules. The HRMS should distinguish between employee relations records and formal labor cases and should apply role-based access because labor relations records may contain confidential information.',1,1,'2026-08-13 17:23:32','Department Order No. 40-03 - Revised Rules Implementing Book V of the Labor Code','Department Order','Department of Labor and Employment','D.O. No. 40-03','2003','Revised rules implementing Book V of the Labor Code concerning labor relations, labor organizations, collective bargaining, representation, certification elections, labor disputes, and related proceedings.','do_40_03_labor_relations.pdf','DEPARTMENT ORDER NO. 40-03\r\n\r\nREVISED RULES IMPLEMENTING BOOK V OF THE LABOR CODE\r\n\r\nPURPOSE\r\n\r\nDepartment Order No. 40-03 provides rules for implementing Book V of the Labor Code concerning labor relations.\r\n\r\nThe rules establish procedures and requirements relating to labor organizations, workers associations, representation, collective bargaining, certification elections, labor disputes, strikes, lockouts, and other labor relations matters.\r\n\r\nBOOK V OF THE LABOR CODE\r\n\r\nBook V of the Labor Code governs labor relations.\r\n\r\nThe framework recognizes the rights of workers and employers in relation to organization, collective bargaining, representation, and the peaceful settlement of labor disputes.\r\n\r\nLABOR ORGANIZATIONS\r\n\r\nWorkers may organize and form or join labor organizations subject to applicable law.\r\n\r\nLabor organizations may represent workers in collective bargaining and other lawful labor relations activities.\r\n\r\nREGISTRATION\r\n\r\nLabor organizations are required to comply with applicable registration requirements.\r\n\r\nThe organization may be required to submit documents and information prescribed by the Department of Labor and Employment.\r\n\r\nThe HRMS may maintain records concerning labor organization registration where such information is relevant to the organization.\r\n\r\nWORKERS ASSOCIATIONS\r\n\r\nWorkers may form workers associations subject to applicable legal requirements.\r\n\r\nThe HRMS may maintain records of recognized employee organizations where appropriate and legally permissible.\r\n\r\nMEMBERSHIP\r\n\r\nEmployees may exercise rights concerning membership in labor organizations in accordance with law.\r\n\r\nEmployment records should not be used to discriminate against employees because of lawful exercise of labor rights.\r\n\r\nCOLLECTIVE BARGAINING\r\n\r\nCollective bargaining involves negotiations between an employer and the duly recognized or certified bargaining representative of employees.\r\n\r\nCollective bargaining may cover wages, hours of work, benefits, working conditions, and other terms and conditions of employment.\r\n\r\nThe HRMS may maintain records relating to collective bargaining agreements.\r\n\r\nCOLLECTIVE BARGAINING AGREEMENT\r\n\r\nA collective bargaining agreement may establish terms and conditions applicable to covered employees.\r\n\r\nThe HRMS Document Management module may store:\r\n\r\n1. Collective bargaining agreement;\r\n2. Effective date;\r\n3. Expiration date;\r\n4. Covered employees;\r\n5. Bargaining unit;\r\n6. Parties;\r\n7. Key provisions;\r\n8. Renewal information;\r\n9. Supporting documents.\r\n\r\nBARGAINING UNIT\r\n\r\nA bargaining unit consists of employees covered by a collective bargaining relationship according to applicable law.\r\n\r\nThe determination of an appropriate bargaining unit should follow the applicable legal rules and decisions of competent authorities.\r\n\r\nCERTIFICATION ELECTION\r\n\r\nA certification election is a process used to determine the employees authorized to represent a bargaining unit for collective bargaining purposes.\r\n\r\nThe HRMS may maintain administrative records concerning certification election dates, notices, and related documents where appropriate.\r\n\r\nBARGAINING REPRESENTATIVE\r\n\r\nThe duly recognized or certified bargaining representative may negotiate with the employer on behalf of covered employees.\r\n\r\nThe HRMS may identify the recognized bargaining representative for purposes of CBA administration.\r\n\r\nUNFAIR LABOR PRACTICE\r\n\r\nUnfair labor practices are acts prohibited by the Labor Code in relation to labor relations rights.\r\n\r\nEmployers and labor organizations should comply with applicable legal restrictions.\r\n\r\nThe HRMS Legal Compliance module may record formal labor-related complaints or cases subject to appropriate access controls.\r\n\r\nEMPLOYEE RIGHTS\r\n\r\nEmployees have rights concerning self-organization and collective bargaining subject to the Labor Code and applicable regulations.\r\n\r\nHR policies should not interfere with lawful labor rights.\r\n\r\nEMPLOYER RIGHTS\r\n\r\nEmployers retain rights recognized by law, subject to the limitations imposed by labor laws and applicable agreements.\r\n\r\nManagement actions involving employees should comply with labor standards and labor relations requirements.\r\n\r\nLABOR DISPUTES\r\n\r\nLabor disputes may arise from disagreements involving employment, labor relations, collective bargaining, representation, or other matters covered by labor law.\r\n\r\nThe HRMS may record labor dispute information including:\r\n\r\n1. Case number;\r\n2. Parties;\r\n3. Date filed;\r\n4. Nature of dispute;\r\n5. Subject matter;\r\n6. Status;\r\n7. Assigned officer;\r\n8. Hearings;\r\n9. Documents;\r\n10. Resolution.\r\n\r\nCONCILIATION AND MEDIATION\r\n\r\nLabor disputes may be subject to conciliation or mediation procedures before or during formal proceedings as provided by law.\r\n\r\nThe HRMS may track:\r\n\r\n1. Conference date;\r\n2. Parties;\r\n3. Issues;\r\n4. Agreements;\r\n5. Action items;\r\n6. Next schedule;\r\n7. Status.\r\n\r\nVOLUNTARY ARBITRATION\r\n\r\nCertain labor disputes may be submitted to voluntary arbitration pursuant to applicable law or collective bargaining agreements.\r\n\r\nThe HRMS may maintain records concerning arbitration cases and decisions.\r\n\r\nSTRIKES\r\n\r\nEmployees and labor organizations may exercise the right to strike subject to the conditions and procedures established by law.\r\n\r\nThe HRMS should not automatically classify employee absences or activities as unlawful merely because they are associated with a labor dispute.\r\n\r\nLOCKOUTS\r\n\r\nEmployers may exercise the right to lockout subject to applicable legal requirements.\r\n\r\nLabor relations actions should be handled using appropriate legal and administrative procedures.\r\n\r\nNOTICE REQUIREMENTS\r\n\r\nApplicable labor relations proceedings may require notices, filings, certifications, or other documentation.\r\n\r\nThe HRMS Compliance Calendar may track applicable deadlines.\r\n\r\nLABOR ORGANIZATION REPORTING\r\n\r\nRegistered labor organizations may have reporting obligations under applicable rules.\r\n\r\nThe HRMS may maintain compliance records where the organization is required to monitor such obligations.\r\n\r\nCOLLECTIVE BARGAINING AGREEMENT MONITORING\r\n\r\nThe HRMS may monitor the status of collective bargaining agreements.\r\n\r\nRecords may include:\r\n\r\n1. CBA title;\r\n2. Parties;\r\n3. Bargaining unit;\r\n4. Start date;\r\n5. End date;\r\n6. Renewal date;\r\n7. Negotiation schedule;\r\n8. Status;\r\n9. Related documents.\r\n\r\nCBA EXPIRATION ALERTS\r\n\r\nThe HRMS Compliance Calendar may generate alerts before a collective bargaining agreement expires.\r\n\r\nNotifications may be sent to authorized HR and management personnel.\r\n\r\nLABOR RELATIONS CASE MANAGEMENT\r\n\r\nThe Legal Compliance module may provide labor relations case management.\r\n\r\nCase records may include:\r\n\r\n1. Case number;\r\n2. Case title;\r\n3. Parties;\r\n4. Type;\r\n5. Filing date;\r\n6. Authority;\r\n7. Current status;\r\n8. Hearing dates;\r\n9. Assigned legal officer;\r\n10. Documents;\r\n11. Resolution;\r\n12. Closing date.\r\n\r\nCOMPLAINT MANAGEMENT\r\n\r\nEmployee complaints involving labor relations matters may be recorded and routed to the appropriate HR or legal personnel.\r\n\r\nThe system should distinguish internal complaints from formal government or judicial proceedings.\r\n\r\nDUE PROCESS\r\n\r\nLabor relations cases should be handled using applicable procedures and due process requirements.\r\n\r\nThe HRMS should maintain records of notices, responses, conferences, decisions, and other relevant documents.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS may store labor relations documents including:\r\n\r\n1. Registration documents;\r\n2. Notices;\r\n3. Certification election documents;\r\n4. Collective bargaining agreements;\r\n5. Labor organization correspondence;\r\n6. Conciliation records;\r\n7. Arbitration documents;\r\n8. Case resolutions;\r\n9. Government filings.\r\n\r\nACCESS CONTROL\r\n\r\nLabor relations information may contain confidential employee, organizational, and legal information.\r\n\r\nAccess should be restricted according to user roles.\r\n\r\nPossible authorized users include:\r\n\r\n1. HR administrator;\r\n2. Employee relations officer;\r\n3. Legal or compliance officer;\r\n4. Authorized management personnel.\r\n\r\nAUDIT TRAIL\r\n\r\nThe HRMS should record important changes to labor relations records.\r\n\r\nAudit information may include:\r\n\r\n1. User;\r\n2. Action;\r\n3. Record;\r\n4. Date;\r\n5. Time;\r\n6. Previous value;\r\n7. New value;\r\n8. Reason.\r\n\r\nCOMPLIANCE CALENDAR\r\n\r\nThe HRMS may schedule:\r\n\r\n1. CBA expiration;\r\n2. CBA negotiations;\r\n3. Labor organization reporting;\r\n4. Hearings;\r\n5. Conciliation conferences;\r\n6. Arbitration schedules;\r\n7. Government filing deadlines;\r\n8. Compliance reviews.\r\n\r\nNOTIFICATIONS\r\n\r\nThe system may issue notifications for:\r\n\r\n1. Upcoming labor hearings;\r\n2. CBA expiration;\r\n3. Negotiation schedules;\r\n4. Filing deadlines;\r\n5. Pending case actions;\r\n6. Required responses;\r\n7. Compliance tasks.\r\n\r\nREPORTING\r\n\r\nThe HRMS may generate labor relations reports containing:\r\n\r\n1. Active labor cases;\r\n2. Pending complaints;\r\n3. CBA status;\r\n4. Upcoming hearings;\r\n5. Labor organization records;\r\n6. Open compliance actions;\r\n7. Case resolutions.\r\n\r\nLEGAL COMPLIANCE DASHBOARD\r\n\r\nThe Legal Compliance dashboard may display:\r\n\r\n1. Active labor relations cases;\r\n2. Pending labor complaints;\r\n3. Upcoming hearings;\r\n4. CBA agreements;\r\n5. Expiring CBAs;\r\n6. Pending compliance tasks;\r\n7. Recent labor relations activities.\r\n\r\nDATA PRIVACY\r\n\r\nLabor relations records may contain personal and sensitive personal information.\r\n\r\nRepublic Act No. 10173, or the Data Privacy Act of 2012, should be considered when collecting, processing, storing, or disclosing employee and labor relations information.\r\n\r\nThe HRMS should implement appropriate role-based access, security controls, audit trails, retention policies, and confidentiality measures.\r\n\r\nEMPLOYEE RELATIONS INTEGRATION\r\n\r\nThe HRMS Employee Relations module may connect individual employee concerns with formal labor relations matters where appropriate.\r\n\r\nThe system should avoid exposing confidential labor case information to unauthorized users.\r\n\r\nAUDIT AND REPORTING INTEGRATION\r\n\r\nLabor relations activities should be included in appropriate compliance audit and reporting functions.\r\n\r\nThe system may monitor:\r\n\r\n1. Pending cases;\r\n2. Case deadlines;\r\n3. CBA expiration;\r\n4. Filing requirements;\r\n5. Corrective actions;\r\n6. Resolution status.\r\n\r\nRELATED LAWS\r\n\r\nDepartment Order No. 40-03 implements provisions of Book V of the Labor Code concerning labor relations.\r\n\r\nRepublic Act No. 6715 amended provisions of the Labor Code relating to labor relations.\r\n\r\nExecutive Order No. 180 concerns the right to organize and collective bargaining for government employees and should be distinguished from private-sector labor relations covered by Book V.\r\n\r\nDepartment Order No. 40-03-A subsequently amended certain provisions of Department Order No. 40-03.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nDepartment Order No. 40-03 should be maintained together with subsequent amendments and related DOLE issuances.\r\n\r\nFor actual legal decisions, the current Labor Code, applicable DOLE regulations, and current rules and decisions of competent labor authorities should be consulted.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis record is intended for HRMS legal-reference and compliance-monitoring purposes.\r\n\r\nThe specific procedures and requirements applicable to a labor relations matter depend on the nature of the dispute, parties involved, applicable law, and current regulations.\r\n\r\nThe complete and current text of Department Order No. 40-03, its amendments, and other applicable labor relations rules should be consulted for actual legal compliance decisions.','2026-08-13 16:09:44'),
(37,'Department Order','Department Order No. 40-E-05','Amending Rule IX of Book V of the Omnibus Rules Implementing the Labor Code',1,'2005-11-30',NULL,'Department of Labor and Employment','Active','Department Order No. 40-E-05, DO 40-E-05, labor relations, Book V, Labor Code, Rule IX, certification election, election protest, Med-Arbiter, appeal, Secretary of Labor, bargaining representative, labor organization, union, certification election protest, labor dispute, DOLE','https://blr.dole.gov.ph/2014/12/11/issuances/','modules/compliance/assets/law_reference/do_40_e_05.pdf','Presidential Decree No. 442, Labor Code of the Philippines; Book V of the Labor Code; Department Order No. 40-03, Series of 2003','Department Order No. 40-E-05 amends Rule IX of Book V of the Omnibus Rules Implementing the Labor Code, as amended by Department Order No. 40-03. The issuance provides rules concerning appeals from decisions of the Med-Arbiter in certification election protests, including the period for appeal, requirements for the memorandum of appeal, filing procedures, action by the Secretary of Labor and Employment, finality of decisions, and remand of records for implementation.','This reference should be connected to the HRMS Labor Relations, Employee Relations, Legal Compliance, Case Management, Document Management, Compliance Calendar, and Audit Trail modules. The system may monitor certification election cases, appeal deadlines, hearing dates, required submissions, case status, decisions, and related documents.',1,1,'2026-08-13 17:23:32','Department Order No. 40-E-05 - Amending Rule IX, Book V of the Omnibus Rules Implementing the Labor Code of the Philippines','Department Order','Department of Labor and Employment','D.O. No. 40-E-05','2005','Amends Rule IX, Book V of the Omnibus Rules Implementing the Labor Code, as amended by Department Order No. 40-03, particularly concerning the appeal procedure in certification election protests.','do_40_e_05.pdf','DEPARTMENT ORDER NO. 40-E-05\r\n\r\nAMENDING RULE IX, BOOK V OF THE OMNIBUS RULES IMPLEMENTING THE LABOR CODE OF THE PHILIPPINES, AS AMENDED BY DEPARTMENT ORDER NO. 40-03, SERIES OF 2003\r\n\r\nPURPOSE\r\n\r\nDepartment Order No. 40-E-05 amends Rule IX of Book V of the Omnibus Rules Implementing the Labor Code.\r\n\r\nThe amendment clarifies the appeal procedure for certification election protests and establishes procedures for appealing decisions issued by the Med-Arbiter.\r\n\r\nLEGAL BASIS\r\n\r\nThe issuance was issued pursuant to the authority of the Department of Labor and Employment under the Labor Code.\r\n\r\nIt amends the implementing rules of Book V of the Labor Code as previously amended by Department Order No. 40-03, Series of 2003.\r\n\r\nRULE IX\r\n\r\nRule IX governs certification election procedures and related proceedings involving representation of employees for collective bargaining purposes.\r\n\r\nThe amendment provides additional rules concerning appeals from decisions of the Med-Arbiter.\r\n\r\nAPPEAL OF MED-ARBITER DECISION\r\n\r\nA decision of the Med-Arbiter may be appealed to the Secretary of Labor and Employment within the prescribed period from receipt of the decision by the parties.\r\n\r\nThe HRMS Legal Compliance module may monitor the date of receipt and calculate the applicable appeal deadline.\r\n\r\nMEMORANDUM OF APPEAL\r\n\r\nThe appeal should be made through a memorandum of appeal.\r\n\r\nThe memorandum should specifically state the grounds relied upon by the appellant and provide the supporting arguments and evidence required by the applicable rules.\r\n\r\nThe HRMS may maintain the following information:\r\n\r\n1. Case number;\r\n2. Date of decision;\r\n3. Date received;\r\n4. Date of appeal;\r\n5. Appellant;\r\n6. Grounds for appeal;\r\n7. Supporting documents;\r\n8. Appeal status.\r\n\r\nPERIOD FOR APPEAL\r\n\r\nThe applicable appeal must be filed within the period prescribed by the rules.\r\n\r\nFailure to file an appeal within the prescribed period may cause the Med-Arbiter decision to become final and executory.\r\n\r\nThe HRMS Compliance Calendar may generate an alert before the appeal deadline.\r\n\r\nFINALITY OF DECISION\r\n\r\nWhere no appeal is filed within the applicable period, the decision may become final and executory according to the rules.\r\n\r\nThe HRMS may update the case status to indicate finality when supported by the appropriate legal record.\r\n\r\nACTION ON APPEAL\r\n\r\nAn appeal is subject to review by the appropriate authority within the Department of Labor and Employment.\r\n\r\nThe appeal record should contain the decision being questioned, memorandum of appeal, supporting arguments, and relevant evidence.\r\n\r\nREPLY TO APPEAL\r\n\r\nThe opposing party may be required or permitted to submit a reply according to the applicable rules and procedure.\r\n\r\nThe HRMS may record:\r\n\r\n1. Date of notice;\r\n2. Date received;\r\n3. Deadline;\r\n4. Date filed;\r\n5. Party filing the reply;\r\n6. Supporting documents;\r\n7. Status.\r\n\r\nSECRETARY OF LABOR AND EMPLOYMENT\r\n\r\nThe Secretary of Labor and Employment may act on appeals from Med-Arbiter decisions in accordance with the applicable labor relations rules.\r\n\r\nThe HRMS may maintain the date of submission, status, decision, and related documents.\r\n\r\nDECISION RECORD\r\n\r\nA decision record may contain:\r\n\r\n1. Case number;\r\n2. Parties;\r\n3. Authority;\r\n4. Date of decision;\r\n5. Nature of dispute;\r\n6. Findings;\r\n7. Resolution;\r\n8. Supporting documents;\r\n9. Finality status.\r\n\r\nREMAND OF RECORDS\r\n\r\nAfter the appropriate decision becomes final, records may be remanded to the appropriate office for implementation.\r\n\r\nThe HRMS may monitor the remand date and subsequent implementation actions.\r\n\r\nCERTIFICATION ELECTION\r\n\r\nA certification election is a proceeding used to determine the employees authorized to select their bargaining representative where applicable.\r\n\r\nThe issuance concerns the appeal process associated with certification election protests rather than establishing the entire certification election framework.\r\n\r\nLABOR ORGANIZATIONS\r\n\r\nLabor organizations participating in certification election proceedings should comply with applicable registration and representation requirements.\r\n\r\nThe HRMS may maintain administrative records relating to recognized labor organizations where appropriate.\r\n\r\nBARGAINING REPRESENTATIVE\r\n\r\nCertification election proceedings may determine the bargaining representative of employees within an appropriate bargaining unit.\r\n\r\nThe HRMS may record the final bargaining representative associated with a completed proceeding.\r\n\r\nLABOR RELATIONS CASE MANAGEMENT\r\n\r\nThe HRMS may create a labor relations case for each certification election protest.\r\n\r\nCase information may include:\r\n\r\n1. Case number;\r\n2. Case title;\r\n3. Parties;\r\n4. Bargaining unit;\r\n5. Labor organization;\r\n6. Employer;\r\n7. Med-Arbiter;\r\n8. Date filed;\r\n9. Decision date;\r\n10. Appeal date;\r\n11. Appeal status;\r\n12. Final decision;\r\n13. Case status.\r\n\r\nCASE DEADLINES\r\n\r\nThe HRMS Compliance Calendar may monitor important deadlines.\r\n\r\nPotential events include:\r\n\r\n1. Filing of appeal;\r\n2. Submission of memorandum;\r\n3. Submission of reply;\r\n4. Hearing;\r\n5. Decision;\r\n6. Finality;\r\n7. Remand;\r\n8. Implementation.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS may store:\r\n\r\n1. Petition;\r\n2. Med-Arbiter decision;\r\n3. Notice of decision;\r\n4. Memorandum of appeal;\r\n5. Supporting evidence;\r\n6. Reply;\r\n7. Secretary decision;\r\n8. Final order;\r\n9. Remand documents;\r\n10. Certification election records.\r\n\r\nACCESS CONTROL\r\n\r\nLabor relations and legal case records may contain confidential information.\r\n\r\nAccess should be restricted to authorized HR, employee relations, legal, compliance, and management personnel.\r\n\r\nThe HRMS should use role-based access controls.\r\n\r\nAUDIT TRAIL\r\n\r\nImportant case activities should be recorded in the audit trail.\r\n\r\nAudit information may include:\r\n\r\n1. User;\r\n2. Action;\r\n3. Case number;\r\n4. Date;\r\n5. Time;\r\n6. Previous status;\r\n7. New status;\r\n8. Document uploaded;\r\n9. Action performed.\r\n\r\nNOTIFICATIONS\r\n\r\nThe HRMS may generate notifications for:\r\n\r\n1. Appeal deadlines;\r\n2. Hearing dates;\r\n3. Filing deadlines;\r\n4. Pending replies;\r\n5. Upcoming decisions;\r\n6. Finality of decisions;\r\n7. Remand actions.\r\n\r\nCOMPLIANCE REPORTING\r\n\r\nThe HRMS may generate reports showing:\r\n\r\n1. Active certification election cases;\r\n2. Pending appeals;\r\n3. Upcoming deadlines;\r\n4. Completed appeals;\r\n5. Final decisions;\r\n6. Pending implementation;\r\n7. Closed cases.\r\n\r\nLEGAL COMPLIANCE DASHBOARD\r\n\r\nThe Legal Compliance dashboard may display:\r\n\r\n1. Active labor relations cases;\r\n2. Pending certification election protests;\r\n3. Upcoming appeal deadlines;\r\n4. Cases awaiting decisions;\r\n5. Final decisions;\r\n6. Pending implementation actions.\r\n\r\nDATA PRIVACY\r\n\r\nLabor relations case records may contain personal information.\r\n\r\nRepublic Act No. 10173, or the Data Privacy Act of 2012, should be considered when processing employee, labor organization, and case information.\r\n\r\nAccess to sensitive case information should be restricted.\r\n\r\nRELATED LAW\r\n\r\nDepartment Order No. 40-03, Series of 2003, contains the implementing rules of Book V of the Labor Code concerning labor relations.\r\n\r\nDepartment Order No. 40-E-05 specifically amends Rule IX of those implementing rules.\r\n\r\nThe Bureau of Labor Relations identifies Department Order No. 40-E-05 as an amendment to Rule IX of Book V. \r\n\r\nRepublic Act No. 9481 subsequently amended provisions concerning labor organization registration and related labor relations matters, and later DOLE issuances further amended the Book V implementing rules.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nThis reference should be maintained as an amendment to Department Order No. 40-03.\r\n\r\nWhen processing an actual labor relations case, the HRMS should consider subsequent amendments and current rules issued by the Department of Labor and Employment.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis record is intended for HRMS legal-reference and compliance-monitoring purposes.\r\n\r\nThe actual procedure and deadlines applicable to a certification election protest should be verified against the complete and current text of Department Order No. 40-E-05, Department Order No. 40-03 as amended, and subsequent applicable DOLE issuances.','2026-08-13 16:10:30'),
(38,'Department Order','Department Order No. 40-J-22','Amending Rule VII of the Implementing Rules of Book V of the Labor Code',1,'2022-04-01',NULL,'Department of Labor and Employment','Active','Department Order No. 40-J-22, DO 40-J-22, labor relations, Book V, Labor Code, SEBA, sole and exclusive bargaining agent, certification, bargaining representative, labor organization, collective bargaining, workers association, union, representation, employer, employee, DOLE, Bureau of Labor Relations','https://blr.dole.gov.ph/2014/12/11/issuances/','modules/compliance/assets/law_reference/Department Order No. 40-J-22 - Amending Rule VII of the Implementing Rules of Book V of the Labor Code of the Philippines.pdf','Presidential Decree No. 442, Labor Code of the Philippines; Book V of the Labor Code; Department Order No. 40-03, Series of 2003','Department Order No. 40-J-22 amends Rule VII of the Implementing Rules of Book V of the Labor Code of the Philippines. The issuance concerns the certification of a Sole and Exclusive Bargaining Agent, or SEBA, in relation to collective bargaining representation and labor relations.','This reference may be connected to the HRMS Labor Relations, Employee Relations, Legal Compliance, Case Management, Document Management, Compliance Calendar, Notifications, and Audit Trail modules. The system may monitor SEBA certification records, bargaining representatives, labor organization information, applicable documents, certification status, deadlines, and related labor relations activities.',1,1,'2026-08-13 18:36:18','Department Order No. 40-J-22 - Amending Rule VII of the Implementing Rules of Book V of the Labor Code of the Philippines','Department Order','Department of Labor and Employment','D.O. No. 40-J-22','2022','Amends Rule VII of the Implementing Rules of Book V of the Labor Code of the Philippines concerning certification of the Sole and Exclusive Bargaining Agent.','do_40_j_22_seba_certification.pdf','DEPARTMENT ORDER NO. 40-J-22\r\n\r\nAMENDING RULE VII OF THE IMPLEMENTING RULES OF BOOK V OF THE LABOR CODE OF THE PHILIPPINES\r\n\r\nPURPOSE\r\n\r\nDepartment Order No. 40-J-22 amends Rule VII of the Implementing Rules of Book V of the Labor Code.\r\n\r\nThe issuance establishes rules concerning certification of a Sole and Exclusive Bargaining Agent, commonly referred to as SEBA, for purposes of collective bargaining representation.\r\n\r\nLEGAL BASIS\r\n\r\nThe issuance is based on Book V of the Labor Code of the Philippines and the implementing rules governing labor relations.\r\n\r\nIt amends the implementing rules previously established under Department Order No. 40-03.\r\n\r\nLABOR RELATIONS\r\n\r\nLabor relations include the legal relationship between employers, employees, and their respective organizations concerning self-organization, representation, collective bargaining, and settlement of labor disputes.\r\n\r\nThe HRMS Labor Relations module may maintain records relevant to these relationships.\r\n\r\nSOLE AND EXCLUSIVE BARGAINING AGENT\r\n\r\nA Sole and Exclusive Bargaining Agent, or SEBA, is the labor organization recognized or certified to represent employees in an appropriate bargaining unit for collective bargaining purposes, subject to applicable labor laws and regulations.\r\n\r\nSEBA certification provides a mechanism for identifying the bargaining representative of employees under the applicable labor relations framework.\r\n\r\nCERTIFICATION\r\n\r\nCertification of the bargaining representative should comply with the requirements and procedures established by the Department of Labor and Employment.\r\n\r\nThe HRMS may maintain SEBA certification records containing:\r\n\r\n1. Certification number;\r\n2. Labor organization;\r\n3. Employer;\r\n4. Bargaining unit;\r\n5. Date of certification;\r\n6. Certifying authority;\r\n7. Certification status;\r\n8. Supporting documents;\r\n9. Effective date;\r\n10. Related collective bargaining agreement.\r\n\r\nBARGAINING UNIT\r\n\r\nA bargaining unit refers to the group of employees represented for purposes of collective bargaining.\r\n\r\nThe appropriate bargaining unit should be determined in accordance with applicable law and labor relations rules.\r\n\r\nThe HRMS may record employees covered by the bargaining unit where legally appropriate.\r\n\r\nLABOR ORGANIZATION\r\n\r\nLabor organizations may represent employees for collective bargaining purposes.\r\n\r\nThe HRMS may maintain administrative information concerning labor organizations that is relevant to the employer\'s labor relations records.\r\n\r\nLabor organization records may include:\r\n\r\n1. Organization name;\r\n2. Registration information;\r\n3. Representative;\r\n4. Certification status;\r\n5. Bargaining unit;\r\n6. Recognition date;\r\n7. Supporting documents.\r\n\r\nEMPLOYEE REPRESENTATION\r\n\r\nEmployees within an appropriate bargaining unit may be represented by the duly recognized or certified bargaining representative.\r\n\r\nThe HRMS may identify the applicable bargaining representative for employees covered by a collective bargaining relationship.\r\n\r\nCOLLECTIVE BARGAINING\r\n\r\nThe SEBA may represent covered employees in collective bargaining with the employer.\r\n\r\nCollective bargaining may concern:\r\n\r\n1. Wages;\r\n2. Working hours;\r\n3. Benefits;\r\n4. Leave;\r\n5. Working conditions;\r\n6. Employment policies;\r\n7. Other terms and conditions of employment.\r\n\r\nCOLLECTIVE BARGAINING AGREEMENT\r\n\r\nA collective bargaining agreement may establish terms and conditions applicable to employees covered by the bargaining relationship.\r\n\r\nThe HRMS Document Management module may store:\r\n\r\n1. CBA;\r\n2. Parties;\r\n3. Bargaining unit;\r\n4. Effective date;\r\n5. Expiration date;\r\n6. Negotiation history;\r\n7. Amendments;\r\n8. Supporting documents.\r\n\r\nSEBA RECORD\r\n\r\nThe HRMS may maintain a dedicated SEBA record.\r\n\r\nPossible fields include:\r\n\r\n1. SEBA ID;\r\n2. Employer;\r\n3. Labor organization;\r\n4. Bargaining unit;\r\n5. Certification number;\r\n6. Certification date;\r\n7. Status;\r\n8. Representative;\r\n9. CBA reference;\r\n10. Supporting documents.\r\n\r\nCERTIFICATION STATUS\r\n\r\nThe HRMS may classify SEBA records as:\r\n\r\n1. Pending;\r\n2. Certified;\r\n3. Active;\r\n4. Under review;\r\n5. Superseded;\r\n6. Terminated where legally applicable.\r\n\r\nAny legal status should be based on the applicable official record.\r\n\r\nLABOR RELATIONS CASE MANAGEMENT\r\n\r\nThe HRMS Legal Compliance module may create a case record for matters involving SEBA certification.\r\n\r\nCase information may include:\r\n\r\n1. Case number;\r\n2. Parties;\r\n3. Labor organization;\r\n4. Employer;\r\n5. Bargaining unit;\r\n6. Filing date;\r\n7. Authority;\r\n8. Current status;\r\n9. Hearings;\r\n10. Decisions;\r\n11. Supporting documents.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS may store SEBA-related documents including:\r\n\r\n1. Certification documents;\r\n2. Labor organization documents;\r\n3. Notices;\r\n4. Petitions;\r\n5. Agreements;\r\n6. Decisions;\r\n7. Correspondence;\r\n8. Collective bargaining agreements;\r\n9. Government filings.\r\n\r\nCOMPLIANCE CALENDAR\r\n\r\nThe HRMS Compliance Calendar may monitor important labor relations dates.\r\n\r\nEvents may include:\r\n\r\n1. Certification proceedings;\r\n2. Hearings;\r\n3. Submission deadlines;\r\n4. Negotiation dates;\r\n5. CBA negotiation schedules;\r\n6. CBA expiration;\r\n7. Compliance review dates.\r\n\r\nNOTIFICATIONS\r\n\r\nThe HRMS may generate notifications for:\r\n\r\n1. Upcoming certification proceedings;\r\n2. Labor relations deadlines;\r\n3. CBA expiration;\r\n4. Required document submissions;\r\n5. Pending case actions;\r\n6. Scheduled negotiations.\r\n\r\nEMPLOYEE RELATIONS\r\n\r\nThe Employee Relations module may connect employee concerns with labor relations records when appropriate.\r\n\r\nAccess to labor relations information should be restricted according to user role.\r\n\r\nLABOR ORGANIZATION INFORMATION\r\n\r\nWhere appropriate, the HRMS may maintain organizational information concerning the recognized bargaining representative.\r\n\r\nThe system should not expose confidential labor relations information to unauthorized employees.\r\n\r\nAUDIT TRAIL\r\n\r\nThe system should maintain an audit trail for significant SEBA-related actions.\r\n\r\nAudit information may include:\r\n\r\n1. User;\r\n2. Action;\r\n3. Record affected;\r\n4. Date;\r\n5. Time;\r\n6. Previous value;\r\n7. New value;\r\n8. Supporting document.\r\n\r\nACCESS CONTROL\r\n\r\nLabor relations information may contain confidential organizational and employee information.\r\n\r\nAccess should be restricted to authorized users such as:\r\n\r\n1. HR administrator;\r\n2. Employee relations officer;\r\n3. Legal officer;\r\n4. Compliance officer;\r\n5. Authorized management personnel.\r\n\r\nDATA PRIVACY\r\n\r\nPersonal information contained in labor relations records should be processed in accordance with Republic Act No. 10173, or the Data Privacy Act of 2012.\r\n\r\nThe HRMS should implement appropriate technical, organizational, and access controls.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nThe HRMS may monitor:\r\n\r\n1. SEBA certification;\r\n2. Labor organization status;\r\n3. Bargaining unit;\r\n4. Collective bargaining agreements;\r\n5. Labor relations cases;\r\n6. Compliance deadlines;\r\n7. Supporting documents.\r\n\r\nCOMPLIANCE REPORTING\r\n\r\nThe HRMS may generate reports containing:\r\n\r\n1. Active bargaining representatives;\r\n2. SEBA certifications;\r\n3. Pending labor relations cases;\r\n4. CBA status;\r\n5. Upcoming labor relations deadlines;\r\n6. Open compliance actions.\r\n\r\nLEGAL COMPLIANCE DASHBOARD\r\n\r\nThe Legal Compliance dashboard may display:\r\n\r\n1. Active SEBA records;\r\n2. Labor organizations;\r\n3. Active CBAs;\r\n4. Pending certification matters;\r\n5. Upcoming labor relations deadlines;\r\n6. Open cases;\r\n7. Recent labor relations activities.\r\n\r\nRELATIONSHIP WITH DEPARTMENT ORDER NO. 40-03\r\n\r\nDepartment Order No. 40-J-22 amends Rule VII of the implementing rules of Book V previously amended by Department Order No. 40-03.\r\n\r\nThe HRMS should therefore treat DO 40-J-22 as an amendment-related reference within the labor relations framework.\r\n\r\nRELATED LAWS AND ISSUANCES\r\n\r\nPresidential Decree No. 442, as amended, otherwise known as the Labor Code of the Philippines, provides the principal statutory framework for labor relations.\r\n\r\nBook V of the Labor Code governs labor relations.\r\n\r\nDepartment Order No. 40-03 contains implementing rules for Book V.\r\n\r\nDepartment Order No. 40-J-22 amends Rule VII concerning the applicable labor relations certification framework.\r\n\r\nRepublic Act No. 9481 amended provisions of the Labor Code concerning labor organization registration and representation.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nDepartment Order No. 40-J-22 should be maintained in the HRMS legal reference library together with Department Order No. 40-03 and subsequent related labor relations issuances.\r\n\r\nFor actual labor relations proceedings, the current Labor Code, applicable DOLE regulations, and official decisions or orders should be consulted.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis record is intended for HRMS legal-reference and compliance-monitoring purposes.\r\n\r\nThe actual requirements for SEBA certification, bargaining representation, and collective bargaining depend on applicable labor relations rules and the specific circumstances of the case.\r\n\r\nThe complete and current text of Department Order No. 40-J-22 and subsequent amendments or related issuances should be consulted for actual legal compliance decisions.','2026-08-13 16:11:54'),
(39,'Department Order','Department Order No. 256-26','Revised Implementing Rules and Regulations of Republic Act No. 10395 or the Tripartism Law',1,'2026-03-31',NULL,'Department of Labor and Employment','Active','Department Order No. 256-26, DO 256-26, Republic Act No. 10395, RA 10395, Tripartism Law, tripartism, tripartite councils, labor-management-government, social dialogue, labor relations, labor sector, management sector, government sector, National Tripartite Industrial Peace Council, Regional Tripartite Industrial Peace Council, DOLE','https://dole.gov.ph/department-orders/','modules/compliance/assets/law_reference/Department Order No. 256-26 - Revised Implementing Rules and Regulations of Republic Act No. 10395 or the Tripartism Law.pdf','Republic Act No. 10395; Presidential Decree No. 442, Labor Code of the Philippines, Article 275; Department Order No. 40-03; Labor relations laws and regulations','Department Order No. 256-26 provides the revised implementing rules and regulations of Republic Act No. 10395, otherwise known as the Tripartism Law. The issuance strengthens the institutional framework for tripartite consultation, social dialogue, and cooperation among government, workers, and employers in the formulation and implementation of labor and employment policies.','This reference may be connected to the HRMS Legal Compliance, Labor Relations, Employee Relations, Compliance Calendar, Government Compliance, Policy Management, Audit and Reporting, and Document Management modules. The system may maintain records of tripartite consultations, labor-management-government activities, assigned representatives, meetings, resolutions, recommendations, compliance actions, and related documents.',1,1,'2026-08-13 18:22:35','Department Order No. 256-26 - Revised Implementing Rules and Regulations of Republic Act No. 10395 or the Tripartism Law','Department Order','Department of Labor and Employment','D.O. No. 256-26','2026','Revised implementing rules and regulations of Republic Act No. 10395, strengthening tripartism and amending Article 275 of the Labor Code of the Philippines.','do_256_26_tripartism.pdf','DEPARTMENT ORDER NO. 256-26\r\n\r\nREVISED IMPLEMENTING RULES AND REGULATIONS OF REPUBLIC ACT NO. 10395\r\n\r\nAN ACT STRENGTHENING TRIPARTISM, AMENDING FOR THE PURPOSE ARTICLE 275 OF PRESIDENTIAL DECREE NO. 442, OTHERWISE KNOWN AS THE LABOR CODE OF THE PHILIPPINES, AS AMENDED\r\n\r\nTHE TRIPARTISM LAW\r\n\r\nPURPOSE\r\n\r\nDepartment Order No. 256-26 provides the revised implementing rules and regulations of Republic Act No. 10395, otherwise known as the Tripartism Law.\r\n\r\nThe issuance strengthens the institutional framework for tripartism and social dialogue in the Philippines.\r\n\r\nLEGAL BASIS\r\n\r\nRepublic Act No. 10395 strengthens tripartism by amending Article 275 of the Labor Code of the Philippines.\r\n\r\nDepartment Order No. 256-26 provides revised implementing rules and regulations for the implementation of the law.\r\n\r\nTRIPARTISM\r\n\r\nTripartism refers to cooperation and consultation among three major sectors:\r\n\r\n1. Government;\r\n2. Workers; and\r\n3. Employers.\r\n\r\nTripartism provides a mechanism for consultation and participation in labor and employment policy development.\r\n\r\nSOCIAL DIALOGUE\r\n\r\nSocial dialogue allows representatives of government, workers, and employers to discuss labor and employment concerns.\r\n\r\nThe process may involve consultation, negotiation, information exchange, recommendations, and coordinated action.\r\n\r\nThe HRMS may maintain records of organizational participation in appropriate labor-management-government activities.\r\n\r\nTRIPARTITE CONSULTATION\r\n\r\nTripartite consultation provides a forum for the three sectors to discuss labor and employment policies.\r\n\r\nTopics may include:\r\n\r\n1. Labor standards;\r\n2. Employment policies;\r\n3. Worker protection;\r\n4. Wages;\r\n5. Productivity;\r\n6. Occupational safety and health;\r\n7. Labor relations;\r\n8. Employment generation;\r\n9. Social protection;\r\n10. Other labor and employment concerns.\r\n\r\nTRIPARTITE BODIES\r\n\r\nTripartite bodies provide institutional mechanisms for dialogue among government, workers, and employers.\r\n\r\nThe HRMS may maintain a directory of applicable tripartite bodies and participating representatives.\r\n\r\nNATIONAL TRIPARTITE INDUSTRIAL PEACE COUNCIL\r\n\r\nThe National Tripartite Industrial Peace Council serves as a national mechanism for consultation and cooperation among government, workers, and employers.\r\n\r\nThe council may discuss national labor and employment policies and issues affecting industrial peace.\r\n\r\nREGIONAL TRIPARTITE INDUSTRIAL PEACE COUNCILS\r\n\r\nRegional tripartite councils provide mechanisms for social dialogue at the regional level.\r\n\r\nThe HRMS may maintain records of regional councils and activities where organizational participation is relevant.\r\n\r\nLABOR REPRESENTATIVES\r\n\r\nWorkers should be represented in appropriate tripartite consultation mechanisms by qualified representatives.\r\n\r\nThe HRMS may maintain representative information where required for administrative purposes.\r\n\r\nEMPLOYER REPRESENTATIVES\r\n\r\nEmployers may participate in tripartite consultation through recognized employer organizations or designated representatives.\r\n\r\nThe HRMS may maintain information concerning authorized employer representatives.\r\n\r\nGOVERNMENT REPRESENTATIVES\r\n\r\nGovernment agencies may participate in tripartite bodies according to their respective mandates.\r\n\r\nThe Department of Labor and Employment provides an important institutional role in labor and employment policy coordination.\r\n\r\nSOCIAL PARTNERS\r\n\r\nGovernment, workers, and employers are recognized as social partners in the development of labor and employment policies.\r\n\r\nTripartism promotes cooperation rather than unilateral decision-making on matters requiring tripartite consultation.\r\n\r\nLABOR POLICY CONSULTATION\r\n\r\nTripartite mechanisms may be used to consult stakeholders regarding proposed labor and employment policies.\r\n\r\nThe HRMS Compliance module may maintain records of relevant policy consultations.\r\n\r\nPOLICY DEVELOPMENT\r\n\r\nTripartite consultation may contribute to the development, review, and improvement of labor policies.\r\n\r\nThe HRMS Policy Management module may link relevant consultation records to internal policies where appropriate.\r\n\r\nLABOR-MANAGEMENT COOPERATION\r\n\r\nEmployers and workers may establish mechanisms for workplace cooperation.\r\n\r\nThese mechanisms may address:\r\n\r\n1. Productivity;\r\n2. Employee welfare;\r\n3. Workplace relations;\r\n4. Occupational safety;\r\n5. Grievance management;\r\n6. Organizational development.\r\n\r\nMEETINGS\r\n\r\nTripartite bodies may conduct regular or special meetings to discuss labor and employment issues.\r\n\r\nThe HRMS may maintain:\r\n\r\n1. Meeting date;\r\n2. Meeting venue;\r\n3. Participating organization;\r\n4. Representatives;\r\n5. Agenda;\r\n6. Minutes;\r\n7. Resolutions;\r\n8. Action items.\r\n\r\nMEETING AGENDA\r\n\r\nThe agenda may identify labor and employment issues to be discussed by the tripartite body.\r\n\r\nThe HRMS Compliance Calendar may schedule meetings and related activities.\r\n\r\nMINUTES OF MEETINGS\r\n\r\nMinutes may document discussions, recommendations, resolutions, and assigned actions.\r\n\r\nThe HRMS Document Management module may store approved meeting minutes.\r\n\r\nRESOLUTIONS\r\n\r\nTripartite councils may adopt resolutions concerning matters within their mandate.\r\n\r\nThe HRMS may record:\r\n\r\n1. Resolution number;\r\n2. Date;\r\n3. Subject;\r\n4. Participating sectors;\r\n5. Resolution text;\r\n6. Status;\r\n7. Related actions.\r\n\r\nRECOMMENDATIONS\r\n\r\nTripartite bodies may issue recommendations concerning labor and employment policies.\r\n\r\nRecommendations should be properly documented and transmitted to the appropriate authority.\r\n\r\nACTION ITEMS\r\n\r\nWhere a tripartite consultation results in agreed actions, the responsible organization or representative may be assigned an action item.\r\n\r\nThe HRMS may monitor:\r\n\r\n1. Action;\r\n2. Responsible person;\r\n3. Deadline;\r\n4. Status;\r\n5. Completion date;\r\n6. Supporting document.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nThe HRMS may monitor organizational responsibilities arising from applicable tripartite activities.\r\n\r\nCompliance records may include:\r\n\r\n1. Requirement;\r\n2. Responsible unit;\r\n3. Deadline;\r\n4. Status;\r\n5. Evidence;\r\n6. Remarks.\r\n\r\nLABOR RELATIONS\r\n\r\nTripartism supports industrial peace by promoting dialogue among government, workers, and employers.\r\n\r\nThe HRMS Labor Relations module may link applicable consultation records to labor relations activities.\r\n\r\nEMPLOYEE RELATIONS\r\n\r\nEmployee Relations may use relevant tripartite policies and recommendations when developing workplace programs.\r\n\r\nInternal employee relations activities should remain consistent with applicable labor laws and organizational policies.\r\n\r\nOCCUPATIONAL SAFETY AND HEALTH\r\n\r\nTripartite consultation may address occupational safety and health issues.\r\n\r\nThe HRMS Compliance and OSH modules may record relevant policy activities, consultations, recommendations, and corrective actions.\r\n\r\nWAGES AND PRODUCTIVITY\r\n\r\nTripartite mechanisms may discuss wages and productivity policies.\r\n\r\nThe HRMS Payroll and Compliance modules may monitor resulting internal compliance requirements where applicable.\r\n\r\nSOCIAL PROTECTION\r\n\r\nTripartite discussions may cover social protection and worker welfare.\r\n\r\nRelevant programs may involve statutory benefits, employment protection, worker welfare, and other social protection policies.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS may store:\r\n\r\n1. Tripartite meeting notices;\r\n2. Agendas;\r\n3. Attendance records;\r\n4. Minutes;\r\n5. Resolutions;\r\n6. Recommendations;\r\n7. Policy proposals;\r\n8. Consultation documents;\r\n9. Official correspondence.\r\n\r\nREPRESENTATIVE DATABASE\r\n\r\nWhere organizational participation requires representation, the HRMS may maintain representative records containing:\r\n\r\n1. Name;\r\n2. Organization;\r\n3. Sector;\r\n4. Position;\r\n5. Appointment date;\r\n6. Term;\r\n7. Contact information;\r\n8. Representation status.\r\n\r\nCOMPLIANCE CALENDAR\r\n\r\nThe HRMS Compliance Calendar may monitor:\r\n\r\n1. Tripartite meetings;\r\n2. Consultation dates;\r\n3. Submission deadlines;\r\n4. Resolution deadlines;\r\n5. Action item deadlines;\r\n6. Policy review dates;\r\n7. Reporting deadlines.\r\n\r\nNOTIFICATIONS\r\n\r\nThe HRMS may generate notifications for:\r\n\r\n1. Upcoming tripartite meetings;\r\n2. Consultation deadlines;\r\n3. Pending action items;\r\n4. Resolution implementation;\r\n5. Document submission;\r\n6. Policy review;\r\n7. Compliance deadlines.\r\n\r\nAUDIT TRAIL\r\n\r\nThe system should maintain an audit trail for significant tripartite compliance records.\r\n\r\nAudit information may include:\r\n\r\n1. User;\r\n2. Action;\r\n3. Record affected;\r\n4. Date;\r\n5. Time;\r\n6. Previous value;\r\n7. New value;\r\n8. Supporting document.\r\n\r\nLEGAL COMPLIANCE REPORTING\r\n\r\nThe HRMS may generate reports concerning:\r\n\r\n1. Tripartite activities;\r\n2. Meetings;\r\n3. Resolutions;\r\n4. Recommendations;\r\n5. Open action items;\r\n6. Compliance deadlines;\r\n7. Participating representatives.\r\n\r\nLEGAL COMPLIANCE DASHBOARD\r\n\r\nThe Legal Compliance dashboard may display:\r\n\r\n1. Upcoming tripartite activities;\r\n2. Pending action items;\r\n3. Recent resolutions;\r\n4. Active representatives;\r\n5. Open compliance requirements;\r\n6. Upcoming consultation deadlines.\r\n\r\nDATA PRIVACY\r\n\r\nTripartite records may contain personal information concerning representatives and participants.\r\n\r\nRepublic Act No. 10173, or the Data Privacy Act of 2012, should be considered when processing personal information.\r\n\r\nThe HRMS should apply appropriate access controls and security safeguards.\r\n\r\nRECORD RETENTION\r\n\r\nTripartite documents should be retained according to applicable legal, regulatory, and organizational retention requirements.\r\n\r\nRecords should be securely stored and disposed of when no longer required.\r\n\r\nRELATED LAW\r\n\r\nRepublic Act No. 10395 is the principal statute implemented by Department Order No. 256-26.\r\n\r\nRepublic Act No. 10395 strengthened tripartism and amended Article 275 of the Labor Code.\r\n\r\nPresidential Decree No. 442, as amended, provides the underlying Labor Code framework.\r\n\r\nOther labor laws and DOLE issuances may be considered where they concern matters submitted for tripartite consultation.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nDepartment Order No. 256-26 is a current 2026 DOLE issuance concerning the revised implementing rules and regulations of the Tripartism Law.\r\n\r\nThe official Department of Labor and Employment lists DO 256-26 under its 2026 Department Orders and identifies it as the revised IRR of Republic Act No. 10395.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis record is intended for HRMS legal-reference and compliance-monitoring purposes.\r\n\r\nThe actual rights, responsibilities, procedures, and composition of tripartite bodies should be verified against the complete and current text of Department Order No. 256-26, Republic Act No. 10395, the Labor Code, and subsequent DOLE issuances.','2026-08-13 16:12:38'),
(40,'Republic Act','Republic Act No. 10173','Data Privacy Act of 2012',1,'2012-08-15','2012-09-08','Congress of the Philippines','Active','Republic Act No. 10173, RA 10173, Data Privacy Act, Data Privacy Act of 2012, personal data, personal information, sensitive personal information, data privacy, data protection, privacy rights, National Privacy Commission, NPC, personal information controller, PIC, personal information processor, PIP, data breach, privacy impact assessment, consent, data subject rights, security measures, employee data, HR data','https://lawphil.net/statutes/repacts/ra2012/ra_10173_2012.html','modules/compliance/assets/law_reference/ra_10173_data_privacy_act.pdf','1987 Constitution; Republic Act No. 11036; Republic Act No. 11058; Republic Act No. 10175; Republic Act No. 8792; Republic Act No. 11165; National Privacy Commission issuances; Implementing Rules and Regulations of RA 10173','Republic Act No. 10173, known as the Data Privacy Act of 2012, protects the fundamental right to privacy while ensuring the free flow of information for innovation and growth. It regulates the processing of personal information and establishes obligations for organizations that collect, store, use, disclose, or otherwise process personal data.\r\n\r\nFor HRMS purposes, RA 10173 is highly relevant because employee records contain personal and sensitive personal information such as names, addresses, contact information, government identification numbers, payroll information, employment records, medical information, disciplinary records, and other information requiring appropriate safeguards.','The HRMS should implement privacy by design, role-based access control, appropriate security measures, data minimization, access logging, retention controls, secure disposal, and procedures for handling data subject requests.\r\n\r\nPersonal and sensitive personal information should only be collected and processed for legitimate and authorized purposes.\r\n\r\nThe system should distinguish ordinary personal information from sensitive personal information and restrict access accordingly.\r\n\r\nWhere required, the organization should maintain appropriate privacy notices, consent mechanisms, processing records, data breach procedures, and agreements with personal information processors.',1,1,'2026-08-13 17:23:32','Republic Act No. 10173 - Data Privacy Act of 2012','Republic Act','Congress of the Philippines','R.A. No. 10173','2012','An Act Protecting Individual Personal Information in Information and Communications Systems in the Government and the Private Sector, Creating for this Purpose a National Privacy Commission, and for Other Purposes.','ra_10173_data_privacy_act.pdf','REPUBLIC ACT NO. 10173\r\n\r\nDATA PRIVACY ACT OF 2012\r\n\r\nPURPOSE\r\n\r\nRepublic Act No. 10173 is known as the Data Privacy Act of 2012.\r\n\r\nThe law protects the fundamental right of privacy while ensuring the free flow of information for innovation and growth.\r\n\r\nIt regulates the processing of personal information and establishes standards for responsible data processing.\r\n\r\nSCOPE\r\n\r\nThe law applies to the processing of all forms of personal information and to any natural or juridical person involved in personal information processing.\r\n\r\nIt applies to processing performed in government and private-sector systems subject to the conditions and limitations provided by law.\r\n\r\nDATA PRIVACY PRINCIPLES\r\n\r\nPersonal information processing must follow the principles of:\r\n\r\n1. Transparency;\r\n2. Legitimate purpose;\r\n3. Proportionality.\r\n\r\nTransparency requires that the data subject understands how personal information is collected, used, stored, and processed.\r\n\r\nLegitimate purpose requires that processing be compatible with a declared and lawful purpose.\r\n\r\nProportionality requires that personal information collected and processed be adequate, relevant, suitable, and not excessive in relation to the purpose.\r\n\r\nPERSONAL INFORMATION\r\n\r\nPersonal information refers to any information from which the identity of an individual is apparent or can be reasonably and directly determined by the entity holding the information.\r\n\r\nHR records commonly contain personal information.\r\n\r\nExamples include:\r\n\r\n1. Full name;\r\n2. Address;\r\n3. Telephone number;\r\n4. Email address;\r\n5. Date of birth;\r\n6. Employment information;\r\n7. Education records;\r\n8. Government identification information;\r\n9. Work history;\r\n10. Attendance information.\r\n\r\nSENSITIVE PERSONAL INFORMATION\r\n\r\nSensitive personal information receives additional protection under the law.\r\n\r\nExamples relevant to HR include information concerning:\r\n\r\n1. Health;\r\n2. Education;\r\n3. Government-issued identification;\r\n4. Tax information;\r\n5. Benefits;\r\n6. Medical records;\r\n7. Disciplinary records where applicable;\r\n8. Other information classified as sensitive under law.\r\n\r\nThe HRMS should restrict access to sensitive personal information.\r\n\r\nDATA SUBJECT\r\n\r\nA data subject is an individual whose personal information is processed.\r\n\r\nEmployees, applicants, former employees, contractors, and other individuals whose information is stored in the HRMS may be data subjects.\r\n\r\nPERSONAL INFORMATION CONTROLLER\r\n\r\nA personal information controller determines the purposes and means of processing personal information.\r\n\r\nThe organization operating the HRMS may act as a personal information controller depending on the actual processing arrangement.\r\n\r\nPERSONAL INFORMATION PROCESSOR\r\n\r\nA personal information processor processes personal information on behalf of a personal information controller.\r\n\r\nExamples may include third-party HR software providers, cloud service providers, payroll processors, hosting providers, or other service providers that process employee information on behalf of the organization.\r\n\r\nPROCESSING OF PERSONAL INFORMATION\r\n\r\nProcessing includes operations performed on personal information.\r\n\r\nThese may include:\r\n\r\n1. Collection;\r\n2. Recording;\r\n3. Organization;\r\n4. Storage;\r\n5. Updating;\r\n6. Retrieval;\r\n7. Consultation;\r\n8. Use;\r\n9. Disclosure;\r\n10. Transfer;\r\n11. Destruction;\r\n12. Disposal.\r\n\r\nLAWFUL PROCESSING\r\n\r\nPersonal information must be processed only when a lawful basis exists.\r\n\r\nThe HRMS should not rely on employee consent as the only basis for every type of HR processing.\r\n\r\nDepending on the specific processing activity, lawful processing may arise from consent, fulfillment of a contract, compliance with a legal obligation, protection of vital interests, response to a national emergency, or other lawful bases recognized by the Data Privacy Act.\r\n\r\nCONSENT\r\n\r\nConsent may be required when applicable.\r\n\r\nWhen consent is used as the lawful basis, it should be freely given, specific, informed, and properly documented.\r\n\r\nThe HRMS should record consent where necessary.\r\n\r\nConsent should not be treated as a universal requirement for every employment-related processing activity.\r\n\r\nPRIVACY NOTICE\r\n\r\nEmployees and other data subjects should receive appropriate information regarding the processing of their personal information.\r\n\r\nA privacy notice may explain:\r\n\r\n1. Information collected;\r\n2. Purpose of processing;\r\n3. Legal basis;\r\n4. Data retention;\r\n5. Data sharing;\r\n6. Data recipients;\r\n7. Data subject rights;\r\n8. Contact information of the responsible privacy office.\r\n\r\nDATA MINIMIZATION\r\n\r\nThe HRMS should collect only information necessary for legitimate purposes.\r\n\r\nUnnecessary personal information should not be collected merely because the system is capable of storing it.\r\n\r\nFor example, an employee profile should not contain unrelated personal information that is not necessary for HR administration.\r\n\r\nDATA SECURITY\r\n\r\nOrganizations must implement reasonable and appropriate organizational, physical, and technical measures to protect personal information.\r\n\r\nHRMS security controls may include:\r\n\r\n1. User authentication;\r\n2. Strong passwords;\r\n3. Role-based access;\r\n4. Session management;\r\n5. Encryption where appropriate;\r\n6. Database security;\r\n7. Secure backups;\r\n8. Audit logging;\r\n9. Malware protection;\r\n10. Network security;\r\n11. Secure development practices;\r\n12. Regular security review.\r\n\r\nROLE-BASED ACCESS CONTROL\r\n\r\nThe HRMS should restrict information according to user roles.\r\n\r\nPossible roles include:\r\n\r\n1. HR administrator;\r\n2. HR staff;\r\n3. Payroll officer;\r\n4. Clinic or occupational health personnel;\r\n5. Compliance officer;\r\n6. Manager;\r\n7. Employee;\r\n8. System administrator.\r\n\r\nA manager should not automatically have access to confidential medical, payroll, disciplinary, or government identification records.\r\n\r\nAUDIT TRAIL\r\n\r\nThe HRMS should maintain audit logs for important data-processing activities.\r\n\r\nAudit records may include:\r\n\r\n1. User;\r\n2. Action;\r\n3. Record affected;\r\n4. Date;\r\n5. Time;\r\n6. Previous value where applicable;\r\n7. New value where applicable;\r\n8. IP address where appropriate;\r\n9. System event;\r\n10. Result.\r\n\r\nThe audit trail should itself be protected against unauthorized alteration.\r\n\r\nDATA SUBJECT RIGHTS\r\n\r\nData subjects have rights under the Data Privacy Act.\r\n\r\nThese include rights relating to:\r\n\r\n1. Information;\r\n2. Access;\r\n3. Correction;\r\n4. Object;\r\n5. Data portability where applicable;\r\n6. Be informed;\r\n7. File a complaint;\r\n8. Damages;\r\n9. Other rights recognized by law.\r\n\r\nThe HRMS may provide workflows for handling applicable data subject requests.\r\n\r\nRIGHT TO ACCESS\r\n\r\nA data subject may have the right to access personal information concerning the data subject, subject to the limitations provided by law.\r\n\r\nHR should establish a verification procedure before releasing personal information.\r\n\r\nRIGHT TO CORRECTION\r\n\r\nData subjects may request correction of inaccurate or outdated personal information subject to applicable rules.\r\n\r\nThe HRMS should maintain a controlled process for updating employee information.\r\n\r\nCorrections should be recorded in the audit trail.\r\n\r\nRIGHT TO OBJECT\r\n\r\nA data subject may have the right to object to processing under circumstances provided by law.\r\n\r\nHR should evaluate the applicable legal basis and processing purpose before acting on an objection.\r\n\r\nDATA PORTABILITY\r\n\r\nWhere applicable, data subjects may have the right to obtain or request personal information in a structured and commonly used format.\r\n\r\nThe HRMS may provide controlled export functionality where legally required.\r\n\r\nDATA RETENTION\r\n\r\nPersonal information should not be retained longer than necessary for the purpose for which it was collected, subject to legal and regulatory requirements.\r\n\r\nThe HRMS should implement retention schedules for:\r\n\r\n1. Employee records;\r\n2. Applicant records;\r\n3. Payroll records;\r\n4. Attendance records;\r\n5. Leave records;\r\n6. Medical records;\r\n7. Disciplinary records;\r\n8. Audit records;\r\n9. Government compliance records;\r\n10. Other HR documents.\r\n\r\nDATA DISPOSAL\r\n\r\nPersonal information that is no longer required should be securely disposed of in accordance with applicable retention requirements.\r\n\r\nDigital disposal may include secure deletion or destruction of storage media.\r\n\r\nPhysical documents containing personal information should be securely destroyed.\r\n\r\nDATA BREACH\r\n\r\nA personal data breach may involve unauthorized access, disclosure, alteration, loss, or destruction of personal information.\r\n\r\nThe organization should maintain a data breach response procedure.\r\n\r\nThe response may include:\r\n\r\n1. Detection;\r\n2. Containment;\r\n3. Assessment;\r\n4. Documentation;\r\n5. Notification where legally required;\r\n6. Remediation;\r\n7. Post-incident review.\r\n\r\nBREACH NOTIFICATION\r\n\r\nWhere a personal data breach meets the legal requirements for mandatory notification, the organization must follow the applicable notification requirements of the law and National Privacy Commission regulations.\r\n\r\nThe HRMS may provide a data breach incident workflow.\r\n\r\nNATIONAL PRIVACY COMMISSION\r\n\r\nThe law created the National Privacy Commission.\r\n\r\nThe Commission administers and implements the provisions of the Data Privacy Act and issues regulations, advisories, and other guidance concerning data privacy.\r\n\r\nDATA PROTECTION OFFICER\r\n\r\nOrganizations subject to applicable requirements may need to designate a Data Protection Officer.\r\n\r\nThe DPO oversees privacy compliance and helps ensure that personal information processing follows applicable requirements.\r\n\r\nThe HRMS should identify the responsible privacy officer or DPO where applicable.\r\n\r\nPRIVACY IMPACT ASSESSMENT\r\n\r\nA Privacy Impact Assessment may be appropriate for processing activities that create privacy risks.\r\n\r\nThe HRMS may maintain a record of privacy impact assessments for systems and processes involving personal information.\r\n\r\nExamples include:\r\n\r\n1. Employee monitoring;\r\n2. Biometric attendance;\r\n3. CCTV;\r\n4. Health information;\r\n5. Payroll;\r\n6. Recruitment databases;\r\n7. Applicant screening;\r\n8. Employee portals;\r\n9. Cloud systems.\r\n\r\nTHIRD-PARTY PROCESSORS\r\n\r\nIf the organization uses external service providers to process personal information, appropriate contractual and privacy safeguards should be established.\r\n\r\nExamples include:\r\n\r\n1. Cloud hosting;\r\n2. Payroll providers;\r\n3. Email providers;\r\n4. HR software providers;\r\n5. Document management providers;\r\n6. Backup providers.\r\n\r\nThe HRMS should maintain processor information and applicable agreements where appropriate.\r\n\r\nEMPLOYEE DATA\r\n\r\nEmployee information should be processed only for legitimate HR, payroll, legal, administrative, security, and other authorized purposes.\r\n\r\nHR should avoid collecting unnecessary employee information.\r\n\r\nAPPLICANT DATA\r\n\r\nApplicant information should also be protected.\r\n\r\nRecruitment systems may contain:\r\n\r\n1. Resumes;\r\n2. Contact information;\r\n3. Educational information;\r\n4. Employment history;\r\n5. Interview records;\r\n6. Assessment results;\r\n7. References;\r\n8. Identification documents.\r\n\r\nApplicant data should be retained and disposed of according to applicable policies and requirements.\r\n\r\nPAYROLL DATA\r\n\r\nPayroll information may contain sensitive financial and employment information.\r\n\r\nAccess should be restricted to authorized personnel.\r\n\r\nPayroll exports should be secured and should not be publicly accessible.\r\n\r\nGOVERNMENT IDENTIFICATION DATA\r\n\r\nThe HRMS may contain government identification numbers such as:\r\n\r\n1. SSS number;\r\n2. PhilHealth number;\r\n3. Pag-IBIG number;\r\n4. TIN;\r\n5. Other government identifiers.\r\n\r\nThese should be protected using appropriate access controls.\r\n\r\nMEDICAL DATA\r\n\r\nMedical information requires heightened confidentiality.\r\n\r\nThe HRMS should separate ordinary employee information from detailed medical information whenever possible.\r\n\r\nClinic personnel should have access only to information necessary for legitimate medical or occupational health purposes.\r\n\r\nMENTAL HEALTH INFORMATION\r\n\r\nMental health information is particularly sensitive.\r\n\r\nRA 11036 should be read together with RA 10173 when processing employee mental health information.\r\n\r\nDetailed clinical information should not be displayed on general HR dashboards.\r\n\r\nBIOMETRIC DATA\r\n\r\nBiometric information may involve heightened privacy risks.\r\n\r\nIf the HRMS uses fingerprint, facial recognition, or other biometric attendance technology, the organization should establish an appropriate lawful basis, privacy notice, security controls, retention policy, and other safeguards.\r\n\r\nCCTV DATA\r\n\r\nCCTV recordings may contain personal information.\r\n\r\nThe organization should establish appropriate notice, access, retention, security, and disclosure procedures.\r\n\r\nEMAIL AND COMMUNICATION\r\n\r\nEmployee email addresses and communication records should be processed only for legitimate organizational purposes.\r\n\r\nThe organization should establish appropriate policies for monitoring and accessing employee communications.\r\n\r\nHR DOCUMENT MANAGEMENT\r\n\r\nDocuments stored in the HRMS should have appropriate access restrictions.\r\n\r\nDocument categories may include:\r\n\r\n1. Employment contracts;\r\n2. Government documents;\r\n3. Medical documents;\r\n4. Disciplinary records;\r\n5. Performance records;\r\n6. Training records;\r\n7. Leave documents;\r\n8. Payroll documents;\r\n9. Legal documents;\r\n10. Compliance records.\r\n\r\nDOCUMENT SHARING\r\n\r\nPersonal information should not be shared with unauthorized persons.\r\n\r\nBefore sharing a document, HR should verify:\r\n\r\n1. Recipient;\r\n2. Purpose;\r\n3. Legal basis;\r\n4. Information included;\r\n5. Security of transmission;\r\n6. Retention requirements.\r\n\r\nEMPLOYEE SELF-SERVICE\r\n\r\nEmployee portals should allow employees to access only their own authorized information.\r\n\r\nEmployees should not be able to access another employees records through URL manipulation, database queries, or other application vulnerabilities.\r\n\r\nSYSTEM SECURITY\r\n\r\nThe HRMS should protect against unauthorized access.\r\n\r\nRecommended controls include:\r\n\r\n1. Password hashing;\r\n2. Multi-factor authentication where appropriate;\r\n3. Session timeout;\r\n4. CSRF protection;\r\n5. SQL injection prevention;\r\n6. Input validation;\r\n7. Access authorization;\r\n8. Secure file uploads;\r\n9. Security logging;\r\n10. Backup protection.\r\n\r\nDATABASE SECURITY\r\n\r\nDatabase users should receive only the permissions necessary for their functions.\r\n\r\nDatabase credentials should not be exposed in publicly accessible source code.\r\n\r\nProduction database credentials should be stored securely.\r\n\r\nBACKUP SECURITY\r\n\r\nBackups containing personal information are also subject to privacy and security requirements.\r\n\r\nBackup files should be:\r\n\r\n1. Access restricted;\r\n2. Securely stored;\r\n3. Protected against unauthorized copying;\r\n4. Encrypted where appropriate;\r\n5. Covered by retention policies.\r\n\r\nHRMS PRIVACY MODULE\r\n\r\nThe HRMS may include a dedicated privacy compliance module containing:\r\n\r\n1. Privacy policies;\r\n2. Privacy notices;\r\n3. Consent records;\r\n4. Data subject requests;\r\n5. Data breach records;\r\n6. Privacy impact assessments;\r\n7. Data processing records;\r\n8. Processor records;\r\n9. Compliance audits;\r\n10. Privacy training.\r\n\r\nDATA SUBJECT REQUEST WORKFLOW\r\n\r\nA privacy request workflow may contain:\r\n\r\n1. Request date;\r\n2. Requester;\r\n3. Request type;\r\n4. Identity verification;\r\n5. Information requested;\r\n6. Assigned privacy officer;\r\n7. Review status;\r\n8. Response;\r\n9. Completion date;\r\n10. Supporting documents.\r\n\r\nDATA BREACH WORKFLOW\r\n\r\nA data breach workflow may contain:\r\n\r\n1. Incident number;\r\n2. Date discovered;\r\n3. Date occurred if known;\r\n4. System affected;\r\n5. Type of information affected;\r\n6. Number of affected individuals;\r\n7. Risk assessment;\r\n8. Containment action;\r\n9. Notification status;\r\n10. Corrective action;\r\n11. Closure date.\r\n\r\nPRIVACY TRAINING\r\n\r\nEmployees who handle personal information should receive appropriate privacy training.\r\n\r\nTraining topics may include:\r\n\r\n1. Data Privacy Act;\r\n2. Privacy principles;\r\n3. Secure password practices;\r\n4. Phishing awareness;\r\n5. Data handling;\r\n6. Document security;\r\n7. Confidentiality;\r\n8. Data breach reporting.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nThe HRMS may monitor:\r\n\r\n1. Privacy policy acknowledgement;\r\n2. Privacy training;\r\n3. Access reviews;\r\n4. Data subject requests;\r\n5. Data breaches;\r\n6. Privacy impact assessments;\r\n7. Processor agreements;\r\n8. Data retention;\r\n9. Secure disposal;\r\n10. Audit findings.\r\n\r\nPRIVACY AUDIT\r\n\r\nRegular privacy audits may examine:\r\n\r\n1. User access;\r\n2. Database security;\r\n3. File permissions;\r\n4. Employee records;\r\n5. Data retention;\r\n6. Privacy notices;\r\n7. Third-party processors;\r\n8. Incident logs;\r\n9. Data breach controls;\r\n10. Compliance documentation.\r\n\r\nVIOLATIONS\r\n\r\nUnauthorized processing, disclosure, access, or other prohibited acts involving personal information may result in penalties under applicable law.\r\n\r\nThe organization should establish appropriate administrative, technical, and organizational safeguards.\r\n\r\nRELATED LAWS\r\n\r\nThe HRMS should link RA 10173 with:\r\n\r\n1. Republic Act No. 11036;\r\n2. Republic Act No. 11058;\r\n3. Republic Act No. 10175;\r\n4. Republic Act No. 8792;\r\n5. Republic Act No. 11210;\r\n6. Labor Code of the Philippines;\r\n7. Applicable National Privacy Commission issuances;\r\n8. Applicable DOLE regulations.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nRA 10173 remains an active Philippine law.\r\n\r\nThe HRMS should treat privacy compliance as an ongoing requirement rather than a one-time implementation task.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis legal reference is provided for HRMS compliance and legal-reference purposes.\r\n\r\nThe Data Privacy Act should be implemented together with its implementing rules, National Privacy Commission issuances, and other applicable laws and regulations.\r\n\r\nThe specific lawful basis, retention period, notification requirement, and security measure applicable to a processing activity should be evaluated based on the actual circumstances.\r\n\r\nFor high-risk processing activities, the organization should consult its Data Protection Officer and appropriate legal or privacy professionals.','2026-08-13 16:04:44'),
(42,'Department Order','Department Order No. 259-26','Guidelines on the Prevention and Elimination of Violence and Harassment in the Workplace',1,'2026-05-01',NULL,'Department of Labor and Employment','Active','Department Order No. 259-26, DO 259-26, violence and harassment, workplace violence, workplace harassment, sexual harassment, gender-based harassment, prevention, elimination, safe workplace, dignity at work, occupational safety and health, OSH, labor standards, ILO Convention No. 190, Republic Act No. 11058, Republic Act No. 7877, Republic Act No. 11313','https://dole.gov.ph/department-orders/','modules/compliance/assets/law_reference/Department Order No. 259-26 - Guidelines on the Prevention and Elimination of Violence and Harassment in the Workplace.pdf','Republic Act No. 11058; Republic Act No. 7877; Republic Act No. 11313; Republic Act No. 10173; ILO Convention No. 190; Labor Code of the Philippines','Department Order No. 259-26 provides guidelines for the prevention and elimination of violence and harassment in the workplace. It establishes a workplace framework promoting dignity, safety, respect, equality, and protection from violence and harassment and provides guidance for prevention, reporting, response, investigation, protection, and corrective measures.','This reference may be integrated with the HRMS Legal Compliance, Employee Relations, Incident Management, Complaints, Risk Assessment, Occupational Safety and Health, Policy Management, Training, Notifications, Document Management, and Audit Trail modules. Employers should maintain appropriate workplace policies, reporting channels, procedures, records, and preventive measures while protecting confidentiality and personal information.',1,1,'2026-08-13 17:58:23','Department Order No. 259-26 - Guidelines on the Prevention and Elimination of Violence and Harassment in the Workplace','Department Order','Department of Labor and Employment','D.O. No. 259-26','2026','Guidelines for preventing and eliminating violence and harassment in the workplace and promoting a safe, respectful, inclusive, and dignified working environment.','do_259_26_violence_harassment.pdf','DEPARTMENT ORDER NO. 259-26\r\n\r\nGUIDELINES ON THE PREVENTION AND ELIMINATION OF VIOLENCE AND HARASSMENT IN THE WORKPLACE\r\n\r\nPURPOSE\r\n\r\nDepartment Order No. 259-26 establishes guidelines for the prevention and elimination of violence and harassment in the workplace.\r\n\r\nThe guidelines promote a workplace environment where workers are treated with dignity, respect, fairness, and equality.\r\n\r\nThe guidelines support the prevention of conduct that may cause physical, psychological, sexual, economic, or other forms of harm in connection with work.\r\n\r\nWORKPLACE DIGNITY\r\n\r\nWorkers should be able to perform their duties in an environment free from violence and harassment.\r\n\r\nEmployers should promote respect for human dignity and should take reasonable measures to prevent prohibited conduct.\r\n\r\nVIOLENCE AND HARASSMENT\r\n\r\nViolence and harassment may include unacceptable behaviors, practices, or threats that result in or are likely to result in physical, psychological, sexual, or economic harm.\r\n\r\nThe assessment of workplace violence or harassment should consider applicable labor laws, regulations, workplace policies, and the circumstances of the incident.\r\n\r\nFORMS OF WORKPLACE VIOLENCE AND HARASSMENT\r\n\r\nWorkplace violence and harassment may include:\r\n\r\n1. Physical violence;\r\n2. Threats;\r\n3. Intimidation;\r\n4. Bullying;\r\n5. Verbal abuse;\r\n6. Psychological harassment;\r\n7. Sexual harassment;\r\n8. Gender-based harassment;\r\n9. Discriminatory harassment;\r\n10. Online or technology-facilitated harassment;\r\n11. Other prohibited conduct recognized under applicable law.\r\n\r\nSEXUAL HARASSMENT\r\n\r\nSexual harassment is prohibited under applicable Philippine law.\r\n\r\nRepublic Act No. 7877, or the Anti-Sexual Harassment Act of 1995, provides legal protection against sexual harassment in employment, education, and training environments.\r\n\r\nRepublic Act No. 11313, or the Safe Spaces Act, provides additional protection against gender-based sexual harassment, including workplace-related conduct.\r\n\r\nSAFE WORKPLACE\r\n\r\nEmployers should establish measures designed to maintain a safe and healthy workplace.\r\n\r\nThe HRMS may support workplace safety and compliance by maintaining:\r\n\r\n1. Workplace policies;\r\n2. Employee acknowledgements;\r\n3. Training records;\r\n4. Incident records;\r\n5. Complaint records;\r\n6. Risk assessments;\r\n7. Corrective actions;\r\n8. Compliance reports.\r\n\r\nPREVENTION\r\n\r\nPrevention should be an important component of workplace violence and harassment management.\r\n\r\nPreventive measures may include:\r\n\r\n1. Workplace policies;\r\n2. Employee orientation;\r\n3. Awareness programs;\r\n4. Anti-harassment training;\r\n5. Supervisor training;\r\n6. Risk assessment;\r\n7. Workplace monitoring;\r\n8. Reporting mechanisms;\r\n9. Management commitment;\r\n10. Employee participation.\r\n\r\nWORKPLACE POLICY\r\n\r\nEmployers should establish appropriate policies addressing violence and harassment.\r\n\r\nA workplace policy may identify:\r\n\r\n1. Prohibited conduct;\r\n2. Reporting channels;\r\n3. Responsible personnel;\r\n4. Investigation procedures;\r\n5. Confidentiality requirements;\r\n6. Protection measures;\r\n7. Corrective actions;\r\n8. Disciplinary procedures;\r\n9. Non-retaliation measures;\r\n10. Employee assistance mechanisms.\r\n\r\nHRMS POLICY MANAGEMENT\r\n\r\nThe HRMS Policy Management module may maintain:\r\n\r\n1. Policy title;\r\n2. Policy number;\r\n3. Effective date;\r\n4. Review date;\r\n5. Version;\r\n6. Responsible department;\r\n7. Approval status;\r\n8. Employee acknowledgement;\r\n9. Related legal reference.\r\n\r\nREPORTING MECHANISMS\r\n\r\nEmployees should have accessible channels for reporting violence and harassment.\r\n\r\nReporting channels may include:\r\n\r\n1. HR office;\r\n2. Designated officer;\r\n3. Grievance mechanism;\r\n4. Complaint portal;\r\n5. Confidential reporting channel;\r\n6. Other authorized reporting mechanisms.\r\n\r\nThe HRMS may provide a controlled complaint-recording function.\r\n\r\nCONFIDENTIALITY\r\n\r\nReports involving violence and harassment may contain sensitive personal information.\r\n\r\nInformation should only be accessed by authorized personnel with a legitimate need to know.\r\n\r\nThe HRMS should implement role-based access controls.\r\n\r\nNON-RETALIATION\r\n\r\nWorkers who report incidents or participate in an investigation should be protected against retaliation as provided by applicable law and organizational policy.\r\n\r\nRetaliatory conduct should be treated as a serious compliance concern.\r\n\r\nCOMPLAINT MANAGEMENT\r\n\r\nThe HRMS Complaints module may record workplace violence and harassment complaints.\r\n\r\nRecords may include:\r\n\r\n1. Complaint number;\r\n2. Date reported;\r\n3. Reporting channel;\r\n4. Nature of complaint;\r\n5. Parties involved;\r\n6. Incident date;\r\n7. Incident location;\r\n8. Assigned investigator;\r\n9. Case status;\r\n10. Resolution.\r\n\r\nINCIDENT MANAGEMENT\r\n\r\nThe HRMS Incident Management module may maintain records of workplace incidents.\r\n\r\nIncident records may include:\r\n\r\n1. Incident number;\r\n2. Date;\r\n3. Time;\r\n4. Location;\r\n5. Persons involved;\r\n6. Description;\r\n7. Immediate response;\r\n8. Witness information;\r\n9. Evidence;\r\n10. Investigation status;\r\n11. Corrective action.\r\n\r\nINVESTIGATION\r\n\r\nWorkplace complaints should be handled through fair and appropriate procedures.\r\n\r\nThe investigation process may include:\r\n\r\n1. Receipt of complaint;\r\n2. Initial assessment;\r\n3. Assignment of investigator;\r\n4. Notice to appropriate parties;\r\n5. Evidence gathering;\r\n6. Interviews;\r\n7. Documentation;\r\n8. Findings;\r\n9. Recommendation;\r\n10. Resolution.\r\n\r\nDUE PROCESS\r\n\r\nInvestigations and disciplinary actions should observe applicable due process requirements.\r\n\r\nThe HRMS should maintain documentation showing relevant notices, responses, findings, and decisions.\r\n\r\nPROTECTION MEASURES\r\n\r\nAppropriate protective measures may be implemented when necessary to protect workers during the handling of a complaint.\r\n\r\nMeasures may include temporary workplace arrangements or other lawful administrative actions.\r\n\r\nAny measure should be implemented consistently with applicable law and organizational policy.\r\n\r\nRISK ASSESSMENT\r\n\r\nEmployers should identify workplace risks that may contribute to violence or harassment.\r\n\r\nThe HRMS Risk Assessment module may monitor:\r\n\r\n1. Workplace hazards;\r\n2. Risk level;\r\n3. Affected employees;\r\n4. Existing controls;\r\n5. Recommended controls;\r\n6. Responsible department;\r\n7. Target completion date;\r\n8. Corrective action status.\r\n\r\nHIGH-RISK WORK ENVIRONMENTS\r\n\r\nAdditional preventive measures may be appropriate in workplaces or situations presenting increased risks of violence or harassment.\r\n\r\nRisk factors may include:\r\n\r\n1. Working alone;\r\n2. Public-facing work;\r\n3. Night work;\r\n4. Interaction with potentially aggressive individuals;\r\n5. Remote or isolated locations;\r\n6. Work-related travel;\r\n7. Other workplace-specific conditions.\r\n\r\nTRAINING AND AWARENESS\r\n\r\nEmployers may conduct appropriate training and awareness activities.\r\n\r\nTraining may cover:\r\n\r\n1. Workplace dignity;\r\n2. Violence prevention;\r\n3. Anti-harassment policies;\r\n4. Sexual harassment prevention;\r\n5. Reporting procedures;\r\n6. Non-retaliation;\r\n7. Investigation procedures;\r\n8. Employee responsibilities;\r\n9. Management responsibilities.\r\n\r\nThe HRMS Learning and Development module may maintain training records.\r\n\r\nTRAINING RECORDS\r\n\r\nTraining records may include:\r\n\r\n1. Training title;\r\n2. Employee;\r\n3. Date;\r\n4. Trainer;\r\n5. Completion status;\r\n6. Certificate;\r\n7. Expiration or renewal date.\r\n\r\nMANAGEMENT RESPONSIBILITY\r\n\r\nManagement should support the implementation of workplace prevention measures.\r\n\r\nManagers and supervisors should respond appropriately to reported incidents and avoid conduct that may contribute to a hostile or unsafe workplace.\r\n\r\nEMPLOYEE RESPONSIBILITY\r\n\r\nEmployees should comply with workplace policies and cooperate with legitimate investigations.\r\n\r\nEmployees should use established reporting mechanisms for incidents requiring attention.\r\n\r\nCOMMITTEE AND DESIGNATED PERSONNEL\r\n\r\nWhere required by applicable law, regulations, or organizational policy, employers should designate appropriate persons or committees to handle workplace violence and harassment concerns.\r\n\r\nThe HRMS may maintain:\r\n\r\n1. Designated officer;\r\n2. Committee membership;\r\n3. Appointment date;\r\n4. Term;\r\n5. Training;\r\n6. Contact information;\r\n7. Status.\r\n\r\nRECORDKEEPING\r\n\r\nEmployers should maintain appropriate records concerning workplace violence and harassment prevention and response.\r\n\r\nThe HRMS may store:\r\n\r\n1. Policies;\r\n2. Training records;\r\n3. Risk assessments;\r\n4. Complaints;\r\n5. Incident reports;\r\n6. Investigation documents;\r\n7. Corrective actions;\r\n8. Resolutions;\r\n9. Compliance reports.\r\n\r\nDOCUMENT MANAGEMENT\r\n\r\nThe HRMS Document Management module may store relevant documents.\r\n\r\nDocuments may include:\r\n\r\n1. Workplace policies;\r\n2. Complaint forms;\r\n3. Incident reports;\r\n4. Investigation reports;\r\n5. Notices;\r\n6. Employee acknowledgements;\r\n7. Training certificates;\r\n8. Corrective action documents;\r\n9. Resolutions.\r\n\r\nCOMPLIANCE CALENDAR\r\n\r\nThe HRMS Compliance Calendar may monitor:\r\n\r\n1. Policy review dates;\r\n2. Training schedules;\r\n3. Risk assessments;\r\n4. Committee meetings;\r\n5. Investigation deadlines;\r\n6. Corrective action deadlines;\r\n7. Compliance reviews.\r\n\r\nNOTIFICATIONS\r\n\r\nThe system may issue notifications for:\r\n\r\n1. Pending complaints;\r\n2. Investigation deadlines;\r\n3. Required employee responses;\r\n4. Training schedules;\r\n5. Policy acknowledgements;\r\n6. Corrective action deadlines;\r\n7. Risk assessment reviews.\r\n\r\nAUDIT TRAIL\r\n\r\nSignificant actions involving workplace violence and harassment records should be logged.\r\n\r\nAudit information may include:\r\n\r\n1. User;\r\n2. Action;\r\n3. Record;\r\n4. Date;\r\n5. Time;\r\n6. Previous status;\r\n7. New status;\r\n8. Document activity.\r\n\r\nACCESS CONTROL\r\n\r\nBecause these records may contain sensitive personal information, access should be restricted.\r\n\r\nPossible authorized roles include:\r\n\r\n1. HR administrator;\r\n2. Employee relations officer;\r\n3. Compliance officer;\r\n4. Legal officer;\r\n5. Authorized management personnel.\r\n\r\nDATA PRIVACY\r\n\r\nPersonal information and sensitive personal information contained in workplace violence and harassment records should be handled in accordance with Republic Act No. 10173, or the Data Privacy Act of 2012.\r\n\r\nThe HRMS should implement appropriate security safeguards, access restrictions, retention controls, and audit mechanisms.\r\n\r\nNON-DISCRIMINATION\r\n\r\nWorkplace prevention measures should be implemented without unlawful discrimination.\r\n\r\nEmployees should be treated fairly regardless of protected characteristics under applicable Philippine law.\r\n\r\nEMPLOYEE ASSISTANCE\r\n\r\nOrganizations may establish appropriate mechanisms for supporting employees affected by workplace violence or harassment.\r\n\r\nThe HRMS may maintain referrals or administrative records concerning available employee support programs while limiting access to sensitive information.\r\n\r\nCORRECTIVE ACTION\r\n\r\nWhere an investigation establishes a violation, appropriate corrective or disciplinary action may be taken in accordance with applicable law, company policy, employment contracts, and due process requirements.\r\n\r\nCOMPLIANCE MONITORING\r\n\r\nThe HRMS Legal Compliance module may monitor:\r\n\r\n1. Workplace violence policies;\r\n2. Anti-harassment policies;\r\n3. Employee acknowledgements;\r\n4. Training completion;\r\n5. Risk assessments;\r\n6. Complaints;\r\n7. Incidents;\r\n8. Investigations;\r\n9. Corrective actions;\r\n10. Compliance reviews.\r\n\r\nCOMPLIANCE REPORTING\r\n\r\nThe HRMS may generate reports showing:\r\n\r\n1. Workplace violence and harassment complaints;\r\n2. Incident statistics;\r\n3. Investigation status;\r\n4. Training completion;\r\n5. Risk assessment status;\r\n6. Corrective actions;\r\n7. Policy acknowledgement;\r\n8. Compliance status.\r\n\r\nLEGAL COMPLIANCE DASHBOARD\r\n\r\nThe Legal Compliance dashboard may display:\r\n\r\n1. Active complaints;\r\n2. Pending investigations;\r\n3. Upcoming deadlines;\r\n4. Training compliance;\r\n5. Policy acknowledgement status;\r\n6. Workplace risk levels;\r\n7. Corrective action status.\r\n\r\nRELATED LAWS\r\n\r\nRepublic Act No. 7877, or the Anti-Sexual Harassment Act of 1995, addresses sexual harassment in employment, education, and training environments.\r\n\r\nRepublic Act No. 11313, or the Safe Spaces Act, addresses gender-based sexual harassment, including workplace-related harassment.\r\n\r\nRepublic Act No. 11058 provides for occupational safety and health standards and compliance mechanisms.\r\n\r\nRepublic Act No. 10173 provides rules concerning the protection of personal information.\r\n\r\nThe Labor Code of the Philippines provides the general framework for employment and labor relations.\r\n\r\nILO Convention No. 190 concerns violence and harassment in the world of work and may provide relevant international standards where applicable.\r\n\r\nLEGAL COMPLIANCE STATUS\r\n\r\nDepartment Order No. 259-26 should be maintained in the HRMS legal reference library together with related Philippine laws and DOLE issuances concerning workplace violence, harassment, occupational safety and health, gender-based harassment, and employee protection.\r\n\r\nThe HRMS should periodically review this reference against subsequent DOLE issuances and amendments.\r\n\r\nCOMPLIANCE DISCLAIMER\r\n\r\nThis record is intended for HRMS legal-reference and compliance-monitoring purposes.\r\n\r\nActual workplace violence and harassment cases should be handled according to the complete and current text of applicable laws, regulations, company policies, and competent government authority requirements.','2026-08-13 16:13:25'),
(44,'Republic Act','Republic Act No. 11551','Labor Education Act',1,'2021-05-28','2021-06-16','Republic of the Philippines','Active','Republic Act 11551, RA 11551, Labor Education Act, labor education, workers rights, labor rights, employment rights, labor standards, labor relations, Department of Labor and Employment, DOLE, workers education, employers, employees, labor laws, social dialogue','https://lawphil.net/statutes/repacts/ra2021/ra_11551_2021.html','modules/compliance/assets/law_reference/Republic Act No. 11551 – An Act Institutionalizing Labor Education in the Philippines.pdf','1987 Constitution of the Philippines; Labor Code of the Philippines, Presidential Decree No. 442, as amended; Department of Labor and Employment issuances concerning labor education and workers education','Republic Act No. 11551 institutionalizes labor education in the Philippines. It promotes awareness and understanding of labor rights, labor standards, occupational safety and health, social protection, labor relations, and other employment-related laws and policies. The law recognizes the importance of providing workers, employers and other stakeholders with accessible labor education to strengthen compliance, promote decent work and support informed participation in the workplace.','The law is relevant to HR departments, employers, employees, workers\' organizations and other labor stakeholders. HR compliance programs may incorporate labor education activities covering employee rights and responsibilities, labor standards, occupational safety and health, social protection, grievance mechanisms, labor relations and applicable employment laws.',1,1,'2026-08-13 18:37:24','Republic Act No. 11551 – An Act Institutionalizing Labor Education in the Philippines','Republic Act','Republic of the Philippines','RA 11551','2021','Republic Act No. 11551 institutionalizes labor education as part of the government\'s effort to promote awareness of labor and employment laws, policies and programs. It seeks to provide workers, employers and other stakeholders with information and education concerning labor rights and responsibilities, labor standards, occupational safety and health, social protection, labor relations, dispute prevention and settlement, and other matters affecting employment. The Act supports informed and meaningful participation in the workplace and promotes compliance with Philippine labor laws.','RA_11551_Labor_Education_Act.pdf','REPUBLIC OF THE PHILIPPINES\r\n\r\nCONGRESS OF THE PHILIPPINES\r\n\r\nREPUBLIC ACT NO. 11551\r\n\r\nAN ACT INSTITUTIONALIZING LABOR EDUCATION IN THE PHILIPPINES\r\n\r\nBe it enacted by the Senate and House of Representatives of the Philippines in Congress assembled:\r\n\r\nSECTION 1. SHORT TITLE\r\n\r\nThis Act shall be known as the \"Labor Education Act.\"\r\n\r\nSECTION 2. DECLARATION OF POLICY\r\n\r\nIt is the policy of the State to promote and protect the rights and welfare of workers and to ensure that workers, employers and other stakeholders are adequately informed about labor and employment laws, rules, regulations, policies and programs.\r\n\r\nThe State recognizes the importance of labor education in promoting harmonious labor-management relations, preventing labor disputes, protecting workers\' rights and ensuring compliance with labor standards and other applicable laws.\r\n\r\nSECTION 3. LABOR EDUCATION\r\n\r\nFor purposes of this Act, labor education refers to programs, activities and initiatives designed to provide workers, employers and other stakeholders with relevant information and knowledge concerning labor and employment laws, regulations, policies, rights, responsibilities and programs.\r\n\r\nLabor education may cover matters including labor standards, labor relations, occupational safety and health, social protection, workers\' rights and responsibilities, employment policies, dispute prevention and settlement and other labor and employment concerns.\r\n\r\nSECTION 4. OBJECTIVES\r\n\r\nThe labor education program shall promote awareness and understanding of labor and employment laws and policies.\r\n\r\nIt shall seek to empower workers to understand and exercise their rights and responsibilities.\r\n\r\nIt shall also assist employers in understanding their obligations under labor and employment laws and regulations.\r\n\r\nLabor education shall promote constructive labor-management relations and encourage the peaceful prevention and settlement of workplace disputes.\r\n\r\nSECTION 5. COVERAGE\r\n\r\nLabor education programs shall be made accessible to workers, employers, workers\' organizations, employers\' organizations, government agencies and other stakeholders concerned with labor and employment.\r\n\r\nThe programs may be implemented through appropriate educational activities, information campaigns, seminars, training programs, publications, online resources and other suitable means.\r\n\r\nSECTION 6. ROLE OF THE DEPARTMENT OF LABOR AND EMPLOYMENT\r\n\r\nThe Department of Labor and Employment shall take the lead in the implementation and coordination of labor education programs consistent with the objectives of this Act.\r\n\r\nDOLE may coordinate with other government agencies, workers\' organizations, employers\' organizations, educational institutions and other stakeholders in carrying out labor education activities.\r\n\r\nThe Department may develop appropriate programs, materials and mechanisms to promote effective labor education.\r\n\r\nSECTION 7. LABOR EDUCATION PROGRAMS\r\n\r\nLabor education programs may include information and training concerning labor standards and working conditions.\r\n\r\nPrograms may also address labor relations, workers\' rights, employer responsibilities, occupational safety and health, social protection and other employment-related laws and programs.\r\n\r\nThe programs should be designed to respond to the needs of workers, employers and other labor stakeholders.\r\n\r\nSECTION 8. INFORMATION AND EDUCATIONAL MATERIALS\r\n\r\nThe appropriate government agencies may develop and distribute information and educational materials concerning labor and employment laws, policies and programs.\r\n\r\nMaterials may be disseminated through traditional and electronic channels to promote accessibility and wider public awareness.\r\n\r\nSECTION 9. PARTICIPATION OF WORKERS AND EMPLOYERS\r\n\r\nWorkers and employers are encouraged to participate in labor education programs.\r\n\r\nWorkers\' organizations and employers\' organizations may assist in the development and implementation of labor education initiatives.\r\n\r\nParticipation in labor education activities may contribute to improved understanding of workplace rights and obligations and strengthen labor-management cooperation.\r\n\r\nSECTION 10. COORDINATION WITH OTHER GOVERNMENT AGENCIES\r\n\r\nDOLE may coordinate with government agencies having jurisdiction over matters involving labor, employment, occupational safety and health, social protection and related concerns.\r\n\r\nCoordination shall promote consistency and complementarity among government information and education programs.\r\n\r\nSECTION 11. FUNDING\r\n\r\nThe implementation of the Act shall be supported through appropriations and other funding sources authorized by law, subject to applicable budgeting, accounting and auditing rules.\r\n\r\nSECTION 12. IMPLEMENTING RULES AND REGULATIONS\r\n\r\nThe Department of Labor and Employment shall formulate and issue the necessary rules and regulations, guidelines and procedures for the effective implementation of this Act.\r\n\r\nThe implementing rules may provide for the organization, coordination, delivery and monitoring of labor education programs.\r\n\r\nSECTION 13. MONITORING AND EVALUATION\r\n\r\nAppropriate mechanisms shall be established to monitor and evaluate the implementation of labor education programs.\r\n\r\nThe evaluation shall consider the effectiveness, accessibility and relevance of labor education activities and materials.\r\n\r\nSECTION 14. SEPARABILITY CLAUSE\r\n\r\nIf any provision of this Act is declared invalid or unconstitutional, the remaining provisions not affected thereby shall remain in full force and effect.\r\n\r\nSECTION 15. REPEALING CLAUSE\r\n\r\nAll laws, decrees, orders, rules and regulations or parts thereof inconsistent with the provisions of this Act are repealed, amended or modified accordingly.\r\n\r\nSECTION 16. EFFECTIVITY\r\n\r\nThis Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation.','2026-08-13 16:00:00'),
(45,'Department Order','Department Order No. 259-26','Guidelines on the Prevention and Elimination of Violence and Harassment in the Workplace',1,NULL,NULL,'Department of Labor and Employment','Active','DOLE, Department Order 259-26, violence and harassment, workplace violence, workplace harassment, prevention of violence, elimination of harassment, safe workplace, decent work, employee protection, employer obligations, workplace policy, complaint mechanism, grievance procedure, gender-based violence, sexual harassment','https://www.dole.gov.ph/','modules/compliance/assets/law_reference/Department Order No. 259-26 – Guidelines on the Prevention and Elimination of Violence and Harassment in the Workplace.pdf','Republic Act No. 7877; Republic Act No. 11313; Republic Act No. 11058; Labor Code of the Philippines; ILO Violence and Harassment Convention No. 190','Department Order No. 259-26 provides guidelines concerning the prevention and elimination of violence and harassment in the workplace. The issuance is intended to strengthen workplace protection mechanisms, promote a safe and respectful working environment, establish preventive measures, and guide employers and workers in addressing workplace violence and harassment.','For final legal-reference records, the issuance date, effectivity date, specific provisions, compliance requirements, and complete text should be extracted directly from the official DOLE PDF before deployment.',1,1,'2026-08-13 17:58:55','Department Order No. 259-26 – Guidelines on the Prevention and Elimination of Violence and Harassment in the Workplace','Department Order','Department of Labor and Employment (DOLE)','DO 259-26','2026','Guidelines concerning the prevention and elimination of violence and harassment in the workplace. The issuance is relevant to employers, human resources personnel, employees, workplace committees and other persons responsible for maintaining a safe, respectful and harassment-free work environment.','DO_259_26_Guidelines_Prevention_Elimination_Violence_Harassment_Workplace.pdf','[FULL TEXT TO BE EXTRACTED DIRECTLY FROM THE OFFICIAL DOLE PDF]','2026-08-13 16:00:00'),
(46,'Department Order','Department Order No. 248-25','New Rules and Regulations on the Employment of Foreign Nationals in the Philippines',1,'2025-01-25','2025-02-09','Department of Labor and Employment','Active','DOLE, Department Order 248-25, DO 248-25, foreign nationals, Alien Employment Permit, AEP, employment of foreign nationals, labor market test, Filipino workers, job vacancy publication, newspaper publication, Skills Development Program, Understudy Training Program, UTP, Economic Needs Test, foreign workers, employer compliance, work permit, Labor Code','https://www.dole.gov.ph/','modules/compliance/assets/law_reference/DOLE Handbook on Workers Statutory Monetary Benefits - 2024 Edition.pdf','Presidential Decree No. 442 or the Labor Code of the Philippines, as amended; Republic Act No. 11647 or the Foreign Investments Act of 1991, as amended; Republic Act No. 11659 or the Public Service Act, as amended; Republic Act No. 7916 or the Special Economic Zone Act of 1995, as amended; Department Order No. 221-21; Department Order No. 248-A-25','Department Order No. 248-25 establishes new rules and regulations governing the employment of foreign nationals in the Philippines and the issuance, renewal, cancellation and regulation of Alien Employment Permits. The Order is intended to ensure that foreign nationals are employed only in positions where qualified, competent and willing Filipino workers are not available, while providing a standardized regulatory framework for employers and foreign nationals.','This issuance is a primary compliance reference for employers hiring foreign nationals in the Philippines. The rules cover AEP applications, labor market testing and publication requirements, documentary requirements, exemptions and exclusions, renewal, cancellation and revocation, employer responsibilities, foreign national responsibilities, administrative sanctions and related compliance procedures. Department Order No. 248-A-25 subsequently provided supplemental guidelines clarifying and amending provisions of this Order.',1,1,'2026-08-13 18:25:31','Department Order No. 248-25 – New Rules and Regulations on the Employment of Foreign Nationals in the Philippines','Department Order','Department of Labor and Employment (DOLE)','DO 248-25','2025','Department Order No. 248-25 establishes the updated regulatory framework for the employment of foreign nationals in the Philippines. It governs the application and issuance of Alien Employment Permits and related certificates and establishes requirements intended to protect employment opportunities for Filipino workers. The rules include labor market testing, publication of job vacancies, documentary requirements, evaluation of foreign national qualifications, skills transfer measures, employer obligations, renewal procedures, cancellation and revocation procedures, exemptions and exclusions, and administrative enforcement.','DO_248_25_New_Rules_and_Regulations_on_the_Employment_of_Foreign_Nationals_in_the_Philippines.pdf','REPUBLIC OF THE PHILIPPINES\r\n\r\nDEPARTMENT OF LABOR AND EMPLOYMENT\r\n\r\nDEPARTMENT ORDER NO. 248-25\r\n\r\nNEW RULES AND REGULATIONS ON THE EMPLOYMENT OF FOREIGN NATIONALS IN THE PHILIPPINES\r\n\r\nI. GENERAL PROVISIONS\r\n\r\nDepartment Order No. 248-25 establishes the new rules and regulations governing the employment of foreign nationals in the Philippines and the issuance and regulation of Alien Employment Permits.\r\n\r\nThe Order is issued pursuant to the authority of the Department of Labor and Employment under the Labor Code of the Philippines, as amended, and other applicable laws and regulations governing the employment of foreign nationals.\r\n\r\nThe rules are intended to regulate the employment of foreign nationals while safeguarding employment opportunities for Filipino workers.\r\n\r\nII. POLICY OBJECTIVES\r\n\r\nThe Department of Labor and Employment recognizes the importance of protecting the employment opportunities of Filipino workers while allowing the lawful employment of foreign nationals when their qualifications and skills are needed.\r\n\r\nThe rules establish procedures for determining whether a foreign national may lawfully be employed in the Philippines and whether the proposed position may be filled by a foreign worker under applicable laws and regulations.\r\n\r\nThe regulatory framework also promotes compliance with labor standards, transparency in the employment of foreign nationals and the transfer of knowledge and skills to Filipino workers.\r\n\r\nIII. COVERAGE\r\n\r\nThese Rules apply to foreign nationals who intend to engage in gainful employment in the Philippines and to domestic or foreign employers who desire to engage foreign nationals for employment in the country.\r\n\r\nThe rules cover applications for Alien Employment Permits, renewals, additional positions, amendments, cancellation and revocation, as well as certificates and other related transactions.\r\n\r\nIV. ALIEN EMPLOYMENT PERMIT\r\n\r\nAn Alien Employment Permit is a permit issued by the Department of Labor and Employment to a foreign national who is qualified to engage in gainful employment in the Philippines in a position where no Filipino worker is competent, able and willing to perform the services for which the foreign national is desired.\r\n\r\nThe AEP is issued in accordance with the applicable labor laws, rules and regulations.\r\n\r\nAn AEP is generally specific to the employer and position stated in the application and does not automatically authorize employment in another position or for another employer.\r\n\r\nV. EMPLOYMENT OF FOREIGN NATIONALS\r\n\r\nAn employer intending to employ a foreign national must comply with the requirements established by DOLE before the foreign national may lawfully engage in employment covered by the AEP requirement.\r\n\r\nThe employer shall submit the required application and supporting documents and comply with applicable publication and labor market testing requirements.\r\n\r\nThe employment of a foreign national remains subject to other applicable immigration, professional licensing, registration and regulatory requirements.\r\n\r\nVI. LABOR MARKET TEST\r\n\r\nThe rules provide for a labor market test intended to determine whether there are Filipino workers who are competent, able and willing to perform the services for which the foreign national is being considered.\r\n\r\nThe employer is required to comply with the prescribed publication requirements for the vacancy.\r\n\r\nThe labor market test is intended to support the policy of prioritizing qualified Filipino workers while allowing the employment of foreign nationals when appropriate under the law.\r\n\r\nVII. PUBLICATION OF JOB VACANCY\r\n\r\nEmployers applying for an AEP are required to comply with the applicable publication requirements for the position intended to be occupied by the foreign national.\r\n\r\nThe vacancy publication provides Filipino workers with an opportunity to apply for the position.\r\n\r\nThe publication must contain the information required under the applicable DOLE rules and must be made through the prescribed publication channel and within the required period.\r\n\r\nVIII. APPLICATION REQUIREMENTS\r\n\r\nAn AEP application shall be accompanied by the documentary requirements prescribed by the Department of Labor and Employment.\r\n\r\nThe requirements may include documents concerning the employer, the foreign national, the proposed position, qualifications, employment arrangement, publication of the vacancy and other information necessary for evaluation.\r\n\r\nThe Department may require additional documents when necessary to determine compliance with the rules.\r\n\r\nIX. QUALIFICATIONS OF FOREIGN NATIONALS\r\n\r\nThe foreign national must possess the qualifications, experience, skills and other credentials necessary for the position for which the AEP is being requested.\r\n\r\nThe Department may evaluate the qualifications of the foreign national in relation to the requirements of the position and the applicable labor market considerations.\r\n\r\nWhere the profession is regulated, the foreign national must also comply with the applicable professional licensing or authorization requirements.\r\n\r\nX. EMPLOYER RESPONSIBILITIES\r\n\r\nEmployers are responsible for ensuring that foreign nationals engaged for employment comply with the applicable AEP requirements.\r\n\r\nEmployers shall provide accurate information and supporting documents in connection with AEP applications.\r\n\r\nEmployers shall also comply with applicable reporting, recordkeeping and notification requirements involving foreign nationals.\r\n\r\nThe employer must ensure that the foreign national is employed only in accordance with the position, employer and conditions covered by the appropriate permit and other applicable authorizations.\r\n\r\nXI. FOREIGN NATIONAL RESPONSIBILITIES\r\n\r\nForeign nationals must comply with the conditions of their employment permit and other applicable Philippine laws and regulations.\r\n\r\nThey must provide accurate information and authentic supporting documents when applying for an AEP.\r\n\r\nA foreign national must not engage in employment outside the authority or conditions of the applicable permit.\r\n\r\nXII. SKILLS DEVELOPMENT AND KNOWLEDGE TRANSFER\r\n\r\nThe rules promote measures intended to facilitate the transfer of knowledge and skills from foreign nationals to Filipino workers.\r\n\r\nEmployers may be required to submit or implement an appropriate Skills Development Program or Understudy Training Program, depending on the circumstances and requirements applicable to the foreign national\'s employment.\r\n\r\nThese measures are intended to develop Filipino workers and support the eventual availability of qualified Filipino personnel for positions occupied by foreign nationals.\r\n\r\nXIII. UNDERSTUDY TRAINING PROGRAM\r\n\r\nWhere required, the employer may identify Filipino workers who will serve as understudies to the foreign national.\r\n\r\nThe Understudy Training Program is intended to facilitate the transfer of technical knowledge, professional skills, work methods and relevant expertise to Filipino workers.\r\n\r\nThe program shall comply with applicable DOLE requirements and guidelines.\r\n\r\nXIV. SKILLS DEVELOPMENT PROGRAM\r\n\r\nA Skills Development Program may be required where applicable to the position and circumstances of the foreign national\'s employment.\r\n\r\nThe program should identify the skills or competencies to be developed and the manner in which Filipino workers will benefit from the program.\r\n\r\nThe implementation of the program supports the policy of promoting Filipino workforce development.\r\n\r\nXV. ECONOMIC NEEDS AND LABOR MARKET CONSIDERATIONS\r\n\r\nThe Department of Labor and Employment may consider relevant economic and labor market conditions in evaluating applications for the employment of foreign nationals.\r\n\r\nThe evaluation is intended to ensure that the employment of foreign nationals is consistent with national development objectives and does not unnecessarily displace qualified Filipino workers.\r\n\r\nXVI. EXEMPTION FROM AEP\r\n\r\nCertain foreign nationals may be exempt from the AEP requirement when expressly covered by applicable laws, rules and regulations.\r\n\r\nPersons claiming exemption must comply with the documentary requirements and procedures prescribed by DOLE.\r\n\r\nThe issuance of a certificate or recognition of an exemption does not remove other applicable immigration, licensing or regulatory requirements.\r\n\r\nXVII. EXCLUSION FROM AEP\r\n\r\nCertain foreign nationals may be excluded from the AEP requirement under applicable laws and regulations.\r\n\r\nAn application for a Certificate of Exclusion may be required to establish that the foreign national falls within a category excluded from the AEP requirement.\r\n\r\nThe employer and foreign national remain responsible for complying with all other applicable Philippine laws.\r\n\r\nXVIII. RENEWAL OF AEP\r\n\r\nAn application for renewal must be filed in accordance with the period and requirements prescribed by DOLE.\r\n\r\nThe renewal application must demonstrate continuing compliance with the applicable requirements.\r\n\r\nWhere necessary, the Department may require updated documents, publication, training or skills development information and other supporting records.\r\n\r\nXIX. ADDITIONAL POSITION OR EMPLOYER\r\n\r\nAn AEP is generally associated with the employer and position stated in the application.\r\n\r\nA foreign national who will work for another employer or occupy a different position may be required to submit a new application or comply with the applicable amendment or additional-position requirements.\r\n\r\nEmployers must not assume that an existing AEP automatically authorizes employment under a different employer or position.\r\n\r\nXX. CANCELLATION AND REVOCATION\r\n\r\nAn AEP may be cancelled or revoked when the circumstances authorized under the applicable rules exist.\r\n\r\nGrounds may include violations of the conditions of the permit, submission of false information or documents, unauthorized employment, violation of applicable laws and regulations or other grounds provided by the governing rules.\r\n\r\nThe Department shall observe the applicable procedures in resolving cancellation or revocation matters.\r\n\r\nXXI. CHANGE OF EMPLOYER\r\n\r\nA foreign national who changes employer must comply with the applicable AEP requirements before commencing employment with the new employer.\r\n\r\nThe new employer shall submit the required application and supporting documents.\r\n\r\nThe foreign national may not rely solely on an AEP issued for a previous employer when the applicable rules require a new permit.\r\n\r\nXXII. CHANGE OF POSITION\r\n\r\nWhere a foreign national will occupy a position different from the position stated in the existing AEP, the employer must comply with the applicable requirements for the change.\r\n\r\nThe Department may require a new application or other appropriate transaction depending on the circumstances.\r\n\r\nXXIII. RECORDKEEPING\r\n\r\nEmployers shall maintain appropriate records and documentation relating to the employment of foreign nationals.\r\n\r\nRecords should include relevant employment documents, AEP documents, supporting certificates, training or skills development documentation and other records required by DOLE.\r\n\r\nSuch records may be subject to inspection or verification by authorized government officials.\r\n\r\nXXIV. MONITORING AND INSPECTION\r\n\r\nThe Department of Labor and Employment may monitor compliance with the rules governing the employment of foreign nationals.\r\n\r\nAuthorized DOLE personnel may verify the information submitted in an AEP application and inspect relevant employment records in accordance with applicable labor laws and procedures.\r\n\r\nEmployers are expected to cooperate with lawful compliance and inspection activities.\r\n\r\nXXV. ADMINISTRATIVE SANCTIONS\r\n\r\nViolations of the rules may result in administrative sanctions, cancellation or revocation of permits, monetary penalties or other consequences provided by applicable laws and regulations.\r\n\r\nEmployers and foreign nationals may be held responsible for violations within their respective areas of responsibility.\r\n\r\nXXVI. PROHIBITED ACTS\r\n\r\nEmployers and foreign nationals shall not circumvent the AEP requirements or submit false, misleading or fraudulent information.\r\n\r\nEmployment outside the scope of an approved AEP or applicable exemption or exclusion may constitute a violation.\r\n\r\nOther acts prohibited under the Labor Code, implementing rules and related issuances remain subject to the corresponding penalties.\r\n\r\nXXVII. GOVERNMENT COORDINATION\r\n\r\nThe Department of Labor and Employment may coordinate with other government agencies in implementing and enforcing the rules on the employment of foreign nationals.\r\n\r\nCoordination may involve immigration authorities, professional regulatory bodies, economic zone authorities and other agencies concerned with the employment and regulation of foreign nationals.\r\n\r\nXXVIII. IMPLEMENTING GUIDELINES\r\n\r\nThe Department may issue additional guidelines, forms, procedures and administrative issuances necessary to implement these Rules.\r\n\r\nSubsequent issuances may clarify documentary requirements, procedures, publication requirements, training requirements and other aspects of AEP administration.\r\n\r\nXXIX. TRANSITIONAL PROVISIONS\r\n\r\nExisting applications, permits and related transactions shall be handled in accordance with the applicable transitional provisions and procedures established by DOLE.\r\n\r\nEmployers and foreign nationals with existing AEPs must comply with the new requirements when renewal or other covered transactions are undertaken.\r\n\r\nXXX. EFFECTIVITY\r\n\r\nThis Department Order shall take effect fifteen (15) days after publication in a newspaper of general circulation.\r\n\r\nThe Department Order was published on January 25, 2025 and became effective on February 9, 2025.\r\n\r\nAll employers, foreign nationals and concerned parties are directed to comply with the provisions of these Rules.','2026-08-13 16:00:00'),
(47,'Department Order','Department Order No. 248-B-26','Centralizing Alien Employment Permit Functions',1,'2026-06-11','2026-06-11','Department of Labor and Employment','Active','DOLE, Department Order 248-B-26, DO 248-B, Alien Employment Permit, AEP, foreign nationals, Bureau of Local Employment, BLE, centralization, AEP application, AEP renewal, Certificate of Exemption, Certificate of Exclusion, Economic Needs Test, employment of foreign nationals, labor market protection','https://www.dole.gov.ph/','modules/compliance/assets/law_reference/Department Order No. 248-B-26.pdf','Department Order No. 248-25; Department Order No. 248-A-25; Labor Code of the Philippines; Alien Employment Permit rules and regulations','Department Order No. 248-B-26 centralizes the filing, processing, evaluation, approval, issuance, release, adjudication, enforcement, cancellation, revocation, renewal and administration of Alien Employment Permits under the Department of Labor and Employment Central Office through the Bureau of Local Employment. It also amends relevant provisions of Department Order Nos. 248 and 248-A, Series of 2025, to establish a centralized framework for the administration of Alien Employment Permits and related certificates and programs.','This issuance is particularly relevant to employers hiring foreign nationals in the Philippines and to HR personnel responsible for Alien Employment Permit compliance. Covered AEP applications, renewals, certificates, pending transactions and related proceedings should be handled in accordance with the centralized procedures and applicable DOLE guidelines.',1,1,'2026-08-13 18:00:39','Department Order No. 248-B-26 – Centralizing the Filing, Processing, Evaluation, Approval, Issuance, Release, Adjudication, and Enforcement Functions Relating to Alien Employment Permits, and Amending Relevant Provisions of Department Order Nos. 248 and 248-A, Series of 2025','Department Order','Department of Labor and Employment (DOLE)','DO 248-B-26','2026','Department Order No. 248-B-26 establishes a centralized system for the administration of Alien Employment Permits and related applications. The Bureau of Local Employment of the DOLE Central Office is designated to perform centralized functions relating to the filing, processing, evaluation, approval, issuance, release, adjudication and enforcement of AEPs and related transactions. The Order also provides mechanisms for the transfer of pending applications and records from DOLE Regional Offices to the Bureau of Local Employment.','DO_248_B_26_Centralizing_AEP_Functions.pdf','REPUBLIC OF THE PHILIPPINES\r\n\r\nDEPARTMENT OF LABOR AND EMPLOYMENT\r\n\r\nDEPARTMENT ORDER NO. 248-B-26\r\n\r\nCENTRALIZING THE FILING, PROCESSING, EVALUATION, APPROVAL, ISSUANCE, RELEASE, ADJUDICATION, AND ENFORCEMENT FUNCTIONS RELATING TO ALIEN EMPLOYMENT PERMITS, AND AMENDING RELEVANT PROVISIONS OF DEPARTMENT ORDER NOS. 248 AND 248-A, SERIES OF 2025\r\n\r\nI. PURPOSE\r\n\r\nDepartment Order No. 248-B-26 establishes a centralized framework for the administration and regulation of Alien Employment Permits and related applications, certificates and proceedings.\r\n\r\nThe Order is intended to strengthen the administration of the Alien Employment Permit system, promote uniform implementation of applicable rules, improve processing efficiency, strengthen regulatory oversight and support the protection of employment opportunities for Filipino workers.\r\n\r\nII. CENTRALIZATION OF AEP FUNCTIONS\r\n\r\nAll functions relating to the filing, processing, evaluation, review, approval, issuance, release, adjudication, enforcement, cancellation, revocation, renewal and administration of Alien Employment Permits are centralized under the DOLE Central Office through the Bureau of Local Employment.\r\n\r\nThe centralized functions include the processing of applications for Alien Employment Permits and related certificates and transactions covered by the applicable rules.\r\n\r\nThe Bureau of Local Employment serves as the principal office responsible for administering the centralized AEP system.\r\n\r\nIII. BUREAU OF LOCAL EMPLOYMENT\r\n\r\nThe Bureau of Local Employment shall perform the functions assigned to it under the centralized AEP framework.\r\n\r\nThese functions include receiving applications, conducting documentary and technical evaluation, reviewing applications, administering applicable labor market assessment procedures, maintaining records, issuing approved permits and certificates, and performing other functions necessary for AEP administration.\r\n\r\nThe BLE shall maintain appropriate records of applications, permits, certificates, proceedings and related transactions.\r\n\r\nIV. AMENDMENT OF DEPARTMENT ORDER NOS. 248 AND 248-A\r\n\r\nDepartment Order No. 248-B-26 amends relevant provisions of Department Order No. 248, Series of 2025, and Department Order No. 248-A, Series of 2025.\r\n\r\nReferences in the earlier issuances to DOLE Regional Offices and Regional Directors are modified where necessary to reflect the centralized administration of AEP functions.\r\n\r\nThe amendments establish the Bureau of Local Employment as the central office responsible for the covered AEP functions.\r\n\r\nV. APPLICATION FOR ALIEN EMPLOYMENT PERMIT\r\n\r\nApplications for Alien Employment Permits shall be filed and processed in accordance with the centralized procedures prescribed by the Department of Labor and Employment.\r\n\r\nEmployers shall submit the required application forms, supporting documents and other information necessary for evaluation.\r\n\r\nThe Bureau of Local Employment shall determine whether the application complies with applicable requirements before approval and issuance of the permit.\r\n\r\nVI. EVALUATION AND REVIEW\r\n\r\nThe Bureau of Local Employment shall conduct the appropriate documentary and technical evaluation of applications.\r\n\r\nThe evaluation may include verification of employer information, foreign national qualifications, position requirements, labor market considerations and other matters required under applicable rules.\r\n\r\nThe Department may require additional documents or clarification when necessary to determine compliance.\r\n\r\nVII. ECONOMIC NEEDS TEST\r\n\r\nThe Bureau of Local Employment shall administer the Economic Needs Test where required under the applicable rules.\r\n\r\nThe Economic Needs Test supports the evaluation of applications involving the employment of foreign nationals and considers relevant labor market and economic circumstances.\r\n\r\nThe test forms part of the regulatory process intended to ensure that the employment of foreign nationals is consistent with applicable labor policies.\r\n\r\nVIII. CERTIFICATE OF EXEMPTION\r\n\r\nApplications for Certificates of Exemption shall be processed under the centralized AEP framework.\r\n\r\nApplicants claiming exemption from the AEP requirement must submit the documents and information necessary to establish their eligibility under applicable laws, rules and regulations.\r\n\r\nThe Bureau of Local Employment shall evaluate the application and issue the appropriate certificate when the requirements are satisfied.\r\n\r\nIX. CERTIFICATE OF EXCLUSION\r\n\r\nApplications for Certificates of Exclusion shall likewise be handled under the centralized system.\r\n\r\nThe applicant must demonstrate that the foreign national falls within a category excluded from the AEP requirement under applicable laws and regulations.\r\n\r\nThe issuance of a Certificate of Exclusion does not dispense with other immigration, professional licensing or regulatory requirements that may apply.\r\n\r\nX. UNDERSTUDY TRAINING PROGRAM\r\n\r\nWhere required by applicable regulations, employers shall comply with requirements concerning Understudy Training Programs.\r\n\r\nThe program is intended to facilitate the transfer of knowledge, skills, technical expertise and work practices from foreign nationals to qualified Filipino workers.\r\n\r\nThe employer shall maintain appropriate records and comply with applicable DOLE requirements concerning the program.\r\n\r\nXI. SKILLS DEVELOPMENT PROGRAM\r\n\r\nWhere applicable, employers may be required to submit and implement a Skills Development Program.\r\n\r\nThe program should identify the skills and competencies to be developed among Filipino workers and establish appropriate activities for knowledge and skills transfer.\r\n\r\nThe purpose is to promote the development of Filipino workers and strengthen the availability of qualified local personnel.\r\n\r\nXII. RENEWAL OF AEP\r\n\r\nApplications for renewal of an Alien Employment Permit shall be processed under the centralized framework.\r\n\r\nEmployers must comply with the applicable renewal period, documentary requirements and other procedures prescribed by DOLE.\r\n\r\nThe Bureau of Local Employment may require updated information and supporting documents to determine continuing compliance.\r\n\r\nXIII. ADDITIONAL POSITION\r\n\r\nApplications involving an additional position shall be processed in accordance with the applicable AEP rules.\r\n\r\nAn employer must provide the required information concerning the additional position and comply with applicable evaluation and documentation requirements.\r\n\r\nThe approval of an additional position does not automatically modify other conditions applicable to the foreign national or employer.\r\n\r\nXIV. CANCELLATION AND REVOCATION\r\n\r\nThe Bureau of Local Employment shall administer applicable proceedings involving the cancellation or revocation of Alien Employment Permits.\r\n\r\nAn AEP may be cancelled or revoked on grounds provided by applicable laws, rules and regulations.\r\n\r\nThe concerned parties shall be afforded the applicable procedural rights and opportunities required by the governing rules.\r\n\r\nXV. MOTION FOR RECONSIDERATION\r\n\r\nA party affected by an order involving cancellation or revocation may file a motion for reconsideration in accordance with the applicable rules.\r\n\r\nThe motion shall be filed within the prescribed period and with the office designated under the applicable regulations.\r\n\r\nThe filing and resolution of a motion for reconsideration shall follow the procedures established by DOLE.\r\n\r\nXVI. TRANSFER OF PENDING APPLICATIONS\r\n\r\nThe Order provides for the transfer of pending AEP applications and related transactions from DOLE Regional Offices to the Bureau of Local Employment.\r\n\r\nThe transfer is intended to ensure continuity of processing and establish centralized custody of pending applications.\r\n\r\nRegional Offices shall provide the required records, inventories, status reports and supporting documentation concerning pending transactions.\r\n\r\nXVII. TRANSFER OF RECORDS\r\n\r\nRecords relating to pending and unresolved AEP applications shall be transmitted to the Bureau of Local Employment.\r\n\r\nThe records may include application forms, supporting documents, evaluation reports, endorsements, correspondence, databases and other relevant materials.\r\n\r\nThe transfer of records shall be conducted in accordance with the procedures and timelines established by DOLE.\r\n\r\nXVIII. INVENTORY AND STATUS REPORTING\r\n\r\nConcerned DOLE Regional Offices shall prepare inventories and status reports covering pending AEP applications and related transactions.\r\n\r\nThe inventory shall provide sufficient information to enable the Bureau of Local Employment to assume custody and continue processing the transferred transactions.\r\n\r\nRequired certifications and supporting documentation shall accompany the submission where applicable.\r\n\r\nXIX. ROLE OF DOLE REGIONAL OFFICES\r\n\r\nDOLE Regional Offices shall provide necessary administrative and operational support during the transition to the centralized AEP system.\r\n\r\nThey shall coordinate with the Bureau of Local Employment and facilitate the orderly transfer of pending applications and records.\r\n\r\nRegional Offices shall continue to perform functions assigned to them under applicable DOLE rules when such functions are not affected by the centralization.\r\n\r\nXX. EMPLOYER COMPLIANCE\r\n\r\nEmployers intending to employ foreign nationals must comply with all applicable AEP requirements.\r\n\r\nEmployers shall ensure that foreign nationals requiring an AEP possess the appropriate permit before engaging in employment covered by the requirement.\r\n\r\nEmployers shall maintain accurate records relating to the employment of foreign nationals and shall provide required information to DOLE.\r\n\r\nXXI. FOREIGN NATIONAL COMPLIANCE\r\n\r\nForeign nationals must comply with the conditions of their Alien Employment Permit and all other applicable Philippine laws and regulations.\r\n\r\nA foreign national must not engage in employment beyond the scope of the authority granted under the applicable permit.\r\n\r\nForeign nationals must provide accurate information and authentic documents when applying for or maintaining an AEP.\r\n\r\nXXII. RECORDKEEPING\r\n\r\nEmployers shall maintain appropriate employment and compliance records concerning foreign nationals.\r\n\r\nRecords may include copies of AEPs, certificates, employment contracts, identification documents, qualifications, training records and other documents required under applicable rules.\r\n\r\nRecords must be made available to authorized government personnel when lawfully required.\r\n\r\nXXIII. MONITORING AND ENFORCEMENT\r\n\r\nThe Department of Labor and Employment shall maintain appropriate monitoring and enforcement mechanisms for AEP compliance.\r\n\r\nThe Bureau of Local Employment shall perform centralized enforcement functions assigned under the Order and applicable regulations.\r\n\r\nEmployers and foreign nationals may be subject to administrative proceedings for violations of AEP requirements.\r\n\r\nXXIV. PROTECTION OF FILIPINO WORKERS\r\n\r\nThe centralized AEP system supports the policy of protecting employment opportunities for Filipino workers.\r\n\r\nThe evaluation of foreign national employment considers whether qualified Filipino workers are available and whether the proposed employment complies with applicable labor market requirements.\r\n\r\nThe system also promotes knowledge transfer and skills development for Filipino workers.\r\n\r\nXXV. SUPPLEMENTAL GUIDELINES\r\n\r\nThe Bureau of Local Employment may issue supplemental guidelines, operational procedures, forms, manuals and other implementation materials necessary to administer the centralized AEP system.\r\n\r\nSuch guidelines must remain consistent with Department Order No. 248-B-26, Department Order No. 248, Department Order No. 248-A and other applicable laws and regulations.\r\n\r\nXXVI. COORDINATION\r\n\r\nAll concerned DOLE bureaus, services, regional offices and attached agencies shall provide appropriate support to the Bureau of Local Employment in implementing the centralized AEP system.\r\n\r\nInter-office coordination shall be maintained to ensure proper processing of applications, transfer of records and enforcement of applicable requirements.\r\n\r\nXXVII. AMENDING AND REPEALING CLAUSE\r\n\r\nRelevant provisions of Department Order No. 248 and Department Order No. 248-A that are inconsistent with Department Order No. 248-B-26 are amended or modified accordingly.\r\n\r\nPrior procedures that are inconsistent with the centralized framework shall be adjusted to conform with the provisions of this Department Order.\r\n\r\nXXVIII. TRANSITIONAL PROVISIONS\r\n\r\nPending applications and proceedings covered by the Order shall be transferred and processed in accordance with the prescribed transition procedures.\r\n\r\nThe Bureau of Local Employment shall assume the appropriate custody and responsibility for transferred applications and records upon completion of the required turnover.\r\n\r\nXXIX. EFFECTIVITY\r\n\r\nDepartment Order No. 248-B-26 shall take effect in accordance with its publication and effectivity provisions.\r\n\r\nAll concerned DOLE offices, employers, foreign nationals and other covered parties are directed to comply with the applicable provisions of the Order.','2026-08-13 16:00:00'),
(48,'Labor Code Provision','Article 302 (formerly Article 287)','Retirement Pay',1,'1989-06-30',NULL,'Republic of the Philippines','Active','Labor Code, retirement pay, Article 302, Article 287, retirement benefits, statutory retirement pay, optional retirement, compulsory retirement, retirement age, five years of service, one-half month salary, RA 7641, retirement plan, collective bargaining agreement, employment benefits','https://lawphil.net/statutes/repacts/ra1993/ra_7641_1993.html','modules/compliance/assets/law_reference/Labor Code Retirement Provisions – Article 302 (formerly Article 287).pdf','Presidential Decree No. 442, Labor Code of the Philippines, as amended; Republic Act No. 7641; applicable retirement plans; collective bargaining agreements; employment contracts','The retirement provisions of the Labor Code establish the statutory retirement framework for qualified employees in the private sector. Article 302, formerly Article 287, provides for optional and compulsory retirement subject to the conditions established by law. Republic Act No. 7641 provides the statutory minimum retirement pay for covered employees who retire under circumstances covered by the law. The retirement benefit is generally based on at least one-half month salary for every year of service, subject to the statutory computation rules and applicable exclusions.','Employers should review the employee\'s length of service, applicable retirement age, existing retirement plan, collective bargaining agreement, employment contract and statutory requirements when determining retirement eligibility and retirement pay. A retirement plan or agreement may provide benefits more favorable than the statutory minimum. The statutory retirement benefit should be distinguished from SSS retirement benefits, which are administered separately under the Social Security Act.',1,1,'2026-08-13 17:23:32','Labor Code Retirement Provisions – Article 302 (formerly Article 287)','Labor Code Provision','Republic of the Philippines','Article 302','1989','Article 302 of the Labor Code, formerly Article 287, governs retirement of employees in the private sector. It provides the legal framework for optional and compulsory retirement and recognizes the statutory retirement pay established under Republic Act No. 7641. Covered employees who retire under the conditions prescribed by law are entitled to the applicable minimum retirement benefit, unless an applicable retirement plan, collective bargaining agreement or other arrangement provides a benefit at least equivalent to or more favorable than the statutory minimum.','Article_302_Labor_Code_Retirement_Provisions.pdf','REPUBLIC OF THE PHILIPPINES\r\n\r\nLABOR CODE OF THE PHILIPPINES\r\n\r\nARTICLE 302. RETIREMENT\r\n\r\nAny employee may be retired upon reaching the retirement age established in the collective bargaining agreement or other applicable employment contract.\r\n\r\nIn the absence of a retirement plan or agreement providing for retirement benefits, an employee may retire upon reaching the age of sixty (60) years or more, but not beyond sixty-five (65) years, which is the compulsory retirement age, provided that the employee has served at least five (5) years in the establishment.\r\n\r\nThe retiring employee shall be entitled to retirement pay equivalent to at least one-half (1/2) month salary for every year of service, a fraction of at least six (6) months being considered as one (1) whole year.\r\n\r\nFor purposes of determining retirement pay, the term one-half (1/2) month salary shall include fifteen (15) days salary based on the employee\'s latest salary rate, plus one-twelfth (1/12) of the thirteenth-month pay and the cash equivalent of not more than five (5) days of service incentive leave, unless the parties provide a more favorable computation.\r\n\r\nThe statutory retirement pay shall apply subject to the conditions and coverage prescribed by law.\r\n\r\nThe provisions on retirement shall not prejudice the right of an employee to benefits under applicable retirement plans, collective bargaining agreements, employment contracts, social security laws or other applicable laws.\r\n\r\nREPUBLIC ACT NO. 7641\r\n\r\nREPUBLIC ACT NO. 7641, otherwise known as the Retirement Pay Law, amended the Labor Code provisions on retirement and established a statutory minimum retirement benefit for qualified employees in the private sector.\r\n\r\nThe law provides that in the absence of a retirement plan or agreement providing retirement benefits, an employee may retire upon reaching the age of sixty (60) years or more but not beyond sixty-five (65) years, provided that the employee has served at least five (5) years in the establishment.\r\n\r\nThe retirement pay shall be equivalent to at least one-half (1/2) month salary for every year of service, with a fraction of at least six (6) months considered as one whole year.\r\n\r\nFor purposes of computing retirement pay, one-half (1/2) month salary consists of fifteen (15) days salary, plus one-twelfth (1/12) of the thirteenth-month pay and the cash equivalent of not more than five (5) days of service incentive leave.\r\n\r\nWhere the employee is covered by a retirement plan, collective bargaining agreement or other applicable arrangement, the employer must comply with the retirement benefit provided by that arrangement when it is more favorable than the statutory minimum.\r\n\r\nEmployees covered by a retirement plan must receive benefits in accordance with the terms and conditions of the applicable plan, provided that the benefits meet the minimum requirements established by law.\r\n\r\nRETIREMENT AGE\r\n\r\nThe statutory framework distinguishes between optional retirement and compulsory retirement.\r\n\r\nAn employee may retire upon reaching sixty (60) years of age or more, subject to the applicable conditions.\r\n\r\nCompulsory retirement generally occurs upon reaching sixty-five (65) years of age, subject to applicable laws, regulations and recognized exceptions.\r\n\r\nRETIREMENT PAY COMPUTATION\r\n\r\nThe statutory minimum retirement pay is based on at least one-half (1/2) month salary for every year of credited service.\r\n\r\nA fraction of at least six (6) months of service is considered as one full year for purposes of retirement pay computation.\r\n\r\nThe salary base used in computing retirement pay should follow the statutory definition and the applicable rules governing the employee\'s circumstances.\r\n\r\nEMPLOYER RETIREMENT PLANS\r\n\r\nAn employer may establish a retirement plan that provides benefits to employees.\r\n\r\nThe retirement plan may be established through company policy, employment agreement, collective bargaining agreement, trust arrangement or another legally recognized mechanism.\r\n\r\nWhere the retirement plan provides benefits equal to or greater than the statutory minimum, the plan may govern the employee\'s retirement benefit subject to applicable law.\r\n\r\nIf the retirement plan provides benefits lower than the statutory minimum for a covered employee, the employer must comply with the statutory minimum requirements.\r\n\r\nEXCLUSIONS AND COVERAGE\r\n\r\nThe statutory retirement pay provisions are subject to the coverage rules and exclusions provided by law.\r\n\r\nEmployees covered by a retirement plan or agreement may receive retirement benefits under that plan, provided the statutory minimum requirements are satisfied.\r\n\r\nRetirement benefits under the Labor Code should also be distinguished from retirement benefits provided by the Social Security System, government pension systems or other separate benefit programs.\r\n\r\nHR AND EMPLOYER COMPLIANCE\r\n\r\nEmployers should maintain accurate records of employee hiring dates, service periods, salary history, retirement plan coverage and retirement-related agreements.\r\n\r\nBefore processing retirement, HR personnel should verify the applicable retirement age, employee\'s credited service, retirement plan coverage, collective bargaining agreement, employment contract and statutory minimum benefit.\r\n\r\nThe employer should provide the employee with appropriate documentation concerning the retirement decision and computation of retirement benefits.\r\n\r\nRETIREMENT PAY VERSUS SSS RETIREMENT BENEFIT\r\n\r\nStatutory retirement pay under the Labor Code is an employer-provided employment benefit.\r\n\r\nSSS retirement benefits are separate benefits administered by the Social Security System under the applicable social security laws.\r\n\r\nAn employee may qualify for both benefits when the respective eligibility requirements are satisfied.\r\n\r\nMORE FAVORABLE BENEFITS\r\n\r\nNothing in the statutory minimum retirement provisions prevents an employer from providing retirement benefits more favorable to the employee.\r\n\r\nA collective bargaining agreement, employment contract, company retirement plan or other applicable agreement may provide retirement benefits exceeding the statutory minimum.\r\n\r\nWhere multiple retirement benefit arrangements apply, HR should evaluate the applicable provisions and determine which benefit or combination of benefits is legally due to the employee.\r\n\r\nCOMPLIANCE REQUIREMENT\r\n\r\nEmployers should ensure that retirement policies and practices comply with the Labor Code, Republic Act No. 7641, applicable Department of Labor and Employment rules, existing retirement plans, employment contracts and collective bargaining agreements.\r\n\r\nAny company retirement policy that provides benefits below the statutory minimum should be reviewed and corrected where necessary.\r\n\r\nThe retirement provisions should be applied consistently and without discrimination, subject to lawful distinctions recognized under applicable labor laws.','2026-08-13 16:00:00'),
(50,'Implementing Rules and Regulations','2026 IRR of Republic Act No. 11551','Implementing Rules and Regulations of the Labor Education Act',1,'2026-04-29','2026-04-29','Commission on Higher Education, Technical Education and Skills Development Authority, and Department of Labor and Employment','Active','RA 11551, Labor Education Act, 2026 IRR, labor education, tertiary education, higher education institutions, HEIs, technical vocational institutions, TVIs, CHED, TESDA, DOLE, labor rights, labor standards, labor relations, workplace practices, worker rights, worker responsibilities, labor education curriculum, NSTP, career guidance, labor empowerment','https://ched.gov.ph/','modules/compliance/assets/law_reference/2026 Implementing Rules and Regulations of Republic Act No. 11551 – Labor Education Act.pdf','Republic Act No. 11551; Labor Code of the Philippines; applicable CHED policies; applicable TESDA policies; Department of Labor and Employment labor laws and regulations','The 2026 Implementing Rules and Regulations of Republic Act No. 11551 provide the framework for integrating labor education into tertiary education and technical-vocational education in the Philippines. The IRR was signed on April 29, 2026 by the Commission on Higher Education, Technical Education and Skills Development Authority, and Department of Labor and Employment. It establishes implementation mechanisms for educating students about labor standards, labor relations, basic workplace practices, government labor programs and services, worker rights and responsibilities, and other essential employment-related matters.','The IRR is particularly relevant to higher education institutions, technical-vocational institutions, students and future workers. For HR and compliance purposes, the issuance is also relevant because it strengthens labor-law awareness before individuals enter the workforce. CHED has targeted implementation beginning Academic Year 2026–2027, with the initial rollout focused on incoming freshmen and integration through appropriate curricular mechanisms.',1,1,'2026-08-13 18:01:32','2026 Implementing Rules and Regulations of Republic Act No. 11551 – Labor Education Act','Implementing Rules and Regulations','Commission on Higher Education (CHED), Technical Education and Skills Development Authority (TESDA), and Department of Labor and Employment (DOLE)','IRR of RA 11551','2026','The 2026 Implementing Rules and Regulations operationalize Republic Act No. 11551, otherwise known as the Labor Education Act. The IRR establishes the framework for integrating labor education into tertiary education and technical-vocational education. It is intended to equip students and future workers with foundational knowledge of labor rights, labor standards, labor relations, workplace practices, government programs and services, negotiation, workplace relationships, and mechanisms for addressing grievances and other labor-related concerns. The rules provide guidance to CHED, TESDA, DOLE and covered educational institutions regarding curriculum integration, implementation, coordination, learning delivery and related labor education activities.','2026_IRR_RA_11551_Labor_Education_Act.pdf','REPUBLIC OF THE PHILIPPINES\r\n\r\nIMPLEMENTING RULES AND REGULATIONS\r\n\r\nREPUBLIC ACT NO. 11551\r\n\r\nAN ACT INTEGRATING LABOR EDUCATION IN THE TERTIARY EDUCATION CURRICULUM\r\n\r\nLABOR EDUCATION ACT\r\n\r\nI. GENERAL PROVISIONS\r\n\r\nThe Implementing Rules and Regulations provide the operational framework for Republic Act No. 11551, otherwise known as the Labor Education Act.\r\n\r\nThe IRR establishes mechanisms for integrating labor education into tertiary education and technical-vocational education programs.\r\n\r\nThe implementation is undertaken through coordination among the Commission on Higher Education, the Technical Education and Skills Development Authority, and the Department of Labor and Employment.\r\n\r\nII. POLICY OBJECTIVES\r\n\r\nThe IRR seeks to ensure that students and future workers possess basic knowledge and understanding of labor and employment matters before entering the workforce.\r\n\r\nLabor education is intended to promote awareness of workers\' rights and responsibilities, employer responsibilities, workplace standards, labor relations and available government programs and services.\r\n\r\nThe framework also seeks to promote harmonious workplace relationships and informed participation in employment.\r\n\r\nIII. COVERAGE\r\n\r\nThe implementation covers covered higher education institutions and technical-vocational institutions within the jurisdiction of CHED and TESDA.\r\n\r\nThe labor education framework is intended to reach students who are preparing for employment, entrepreneurship and participation in the labor market.\r\n\r\nCovered institutions shall implement labor education in accordance with the applicable curriculum and institutional requirements.\r\n\r\nIV. DEFINITION OF LABOR EDUCATION\r\n\r\nLabor education refers to the teaching of basic knowledge concerning labor rights and other skills relating to negotiation, fostering smooth interpersonal relations in the workplace, and mechanisms for redress of grievances and other concerns.\r\n\r\nLabor education may also include knowledge concerning labor standards, labor relations, workplace practices, government programs and services and other employment-related matters.\r\n\r\nV. ROLE OF CHED\r\n\r\nThe Commission on Higher Education shall provide the appropriate policy and curricular framework for the implementation of labor education in higher education institutions.\r\n\r\nCHED shall coordinate with DOLE and other relevant agencies in developing and implementing appropriate labor education policies and learning materials.\r\n\r\nCHED shall provide guidance to covered higher education institutions concerning the integration of labor education.\r\n\r\nVI. ROLE OF TESDA\r\n\r\nThe Technical Education and Skills Development Authority shall facilitate the integration of labor education into the technical-vocational education and training system.\r\n\r\nTESDA shall coordinate with DOLE and other concerned agencies in developing appropriate learning materials, competency-based approaches and implementation mechanisms.\r\n\r\nTVIs shall follow the applicable TESDA policies and requirements for integrating labor education concepts into their programs.\r\n\r\nVII. ROLE OF DOLE\r\n\r\nThe Department of Labor and Employment shall provide technical assistance and labor-related information necessary for the effective implementation of labor education.\r\n\r\nDOLE may provide information concerning labor standards, labor relations, occupational safety and health, social protection, government programs and services, workers\' rights and responsibilities, and other labor and employment matters.\r\n\r\nDOLE shall coordinate with CHED and TESDA in supporting the implementation of the IRR.\r\n\r\nVIII. LABOR EDUCATION IN HIGHER EDUCATION\r\n\r\nCovered higher education institutions shall integrate labor education in accordance with the framework established by CHED.\r\n\r\nLabor education may be offered or integrated through appropriate curricular mechanisms consistent with the requirements of the institution and applicable CHED policies.\r\n\r\nThe content should provide students with practical knowledge that they can apply when entering the workplace.\r\n\r\nIX. LABOR EDUCATION IN TECHNICAL-VOCATIONAL EDUCATION\r\n\r\nTechnical-vocational institutions shall integrate appropriate labor education concepts into their programs in accordance with TESDA requirements.\r\n\r\nThe content should provide trainees with knowledge of labor rights, responsibilities, workplace relationships, grievance mechanisms and other relevant employment matters.\r\n\r\nLabor education may be integrated into competency-based curricula and other appropriate learning activities.\r\n\r\nX. CORE LABOR EDUCATION AREAS\r\n\r\nLabor education may include basic labor standards and working conditions.\r\n\r\nIt may cover employment rights and responsibilities, wages and benefits, working hours, leave benefits and other fundamental labor standards.\r\n\r\nIt may also include labor relations, collective bargaining, grievance procedures, workplace dispute prevention and mechanisms for redress.\r\n\r\nXI. WORKPLACE PRACTICES\r\n\r\nStudents and trainees should be introduced to basic workplace practices.\r\n\r\nThese may include professional conduct, workplace communication, respectful relationships, cooperation, workplace responsibilities and compliance with applicable policies.\r\n\r\nThe objective is to prepare learners for actual workplace conditions.\r\n\r\nXII. GOVERNMENT PROGRAMS AND SERVICES\r\n\r\nLabor education may include information concerning relevant government programs and services.\r\n\r\nThese may include programs administered by DOLE and other government agencies concerning employment, social protection, worker assistance, occupational safety and health and related matters.\r\n\r\nThe information should help learners identify available government resources when they enter the workforce.\r\n\r\nXIII. WORKERS\' RIGHTS AND RESPONSIBILITIES\r\n\r\nLabor education shall promote awareness of workers\' rights under Philippine labor laws.\r\n\r\nLearners should also understand their corresponding responsibilities as employees and participants in the workplace.\r\n\r\nThe program should emphasize lawful and responsible exercise of workplace rights.\r\n\r\nXIV. EMPLOYER RESPONSIBILITIES\r\n\r\nLabor education may also introduce students to the responsibilities of employers under applicable labor laws.\r\n\r\nStudents should understand that employment relationships involve corresponding rights and responsibilities for both workers and employers.\r\n\r\nXV. LABOR RELATIONS\r\n\r\nThe labor education framework may cover basic principles of labor relations.\r\n\r\nLearners may be introduced to collective bargaining, workers\' organizations, labor-management cooperation, dispute prevention and lawful mechanisms for resolving labor disputes.\r\n\r\nXVI. NEGOTIATION AND WORKPLACE RELATIONSHIPS\r\n\r\nLabor education includes skills relating to negotiation and fostering smooth interpersonal relations in the workplace.\r\n\r\nLearners should be introduced to constructive communication and appropriate methods of addressing workplace concerns.\r\n\r\nThe objective is to promote respectful and productive employment relationships.\r\n\r\nXVII. GRIEVANCE AND REDRESS MECHANISMS\r\n\r\nLearners shall be introduced to mechanisms for addressing grievances and other workplace concerns.\r\n\r\nLabor education should explain the importance of using appropriate internal and external channels when workplace disputes arise.\r\n\r\nStudents should understand that grievances should be addressed through lawful and appropriate procedures.\r\n\r\nXVIII. LABOR EMPOWERMENT AND CAREER GUIDANCE\r\n\r\nThe framework supports labor empowerment and career guidance activities for students.\r\n\r\nWhere practicable and consistent with the law, covered institutions may conduct activities designed to prepare graduating students for entry into the workforce.\r\n\r\nSuch activities may provide practical information concerning labor rights, workplace expectations and available employment services.\r\n\r\nXIX. LEARNING MATERIALS\r\n\r\nCHED, TESDA and DOLE may develop, provide or recommend appropriate labor education learning materials.\r\n\r\nMaterials should be accurate, accessible, current and responsive to the needs of students and trainees.\r\n\r\nCovered institutions may use appropriate digital and traditional learning resources.\r\n\r\nXX. CAPACITY BUILDING\r\n\r\nCovered institutions may provide capacity-building activities for faculty, trainers and other personnel involved in labor education.\r\n\r\nTraining may include updates on labor laws, workplace practices, labor relations and government programs.\r\n\r\nDOLE may provide technical assistance and relevant labor information when appropriate.\r\n\r\nXXI. COORDINATION\r\n\r\nCHED, TESDA and DOLE shall coordinate in implementing the labor education framework.\r\n\r\nCoordination may include curriculum development, learning materials, technical assistance, training, monitoring and evaluation.\r\n\r\nOther government agencies and relevant stakeholders may participate when appropriate.\r\n\r\nXXII. IMPLEMENTATION BY EDUCATIONAL INSTITUTIONS\r\n\r\nCovered institutions shall determine appropriate mechanisms for integrating labor education based on their respective institutional and curricular structures.\r\n\r\nImplementation shall remain consistent with applicable CHED and TESDA standards.\r\n\r\nInstitutions shall ensure that labor education content is presented in a manner appropriate to the learners and their intended career or vocational pathway.\r\n\r\nXXIII. MONITORING AND EVALUATION\r\n\r\nCHED and TESDA shall monitor implementation within their respective jurisdictions.\r\n\r\nMonitoring may assess whether covered institutions have integrated appropriate labor education content and activities.\r\n\r\nThe agencies may issue additional guidance where implementation improvements are necessary.\r\n\r\nXXIV. INFORMATION DISSEMINATION\r\n\r\nGovernment agencies and educational institutions are encouraged to disseminate information concerning labor education.\r\n\r\nDigital platforms, orientations, seminars, classroom activities and other appropriate methods may be used.\r\n\r\nThe objective is to ensure that learners have meaningful access to labor and employment information.\r\n\r\nXXV. STAKEHOLDER PARTICIPATION\r\n\r\nWorkers\' organizations, employers\' organizations, educational institutions, government agencies and other stakeholders may participate in labor education initiatives.\r\n\r\nStakeholder participation may contribute practical workplace knowledge and strengthen the relevance of labor education.\r\n\r\nXXVI. IMPLEMENTATION TIMELINE\r\n\r\nThe implementation shall follow the timelines and transition mechanisms established by CHED and TESDA.\r\n\r\nCHED has identified Academic Year 2026–2027 as the target period for initial rollout in higher education, subject to the applicable institutional and regulatory processes.\r\n\r\nXXVII. TECHNICAL-VOCATIONAL IMPLEMENTATION\r\n\r\nTESDA shall establish appropriate mechanisms for integrating labor education into technical-vocational programs.\r\n\r\nLabor education concepts may be incorporated into competency-based curricula and other training components where appropriate.\r\n\r\nThe implementation should be aligned with the nature and requirements of the specific technical-vocational program.\r\n\r\nXXVIII. TECHNICAL ASSISTANCE\r\n\r\nCHED, TESDA and DOLE may provide technical assistance to covered institutions.\r\n\r\nTechnical assistance may include consultation, training, development of learning materials and clarification of labor education requirements.\r\n\r\nXXIX. FUNDING AND RESOURCES\r\n\r\nImplementation shall be supported by available resources and appropriations subject to applicable budgeting, accounting and auditing laws and regulations.\r\n\r\nCovered institutions may utilize existing resources and appropriate partnerships to support labor education activities.\r\n\r\nXXX. SEPARABILITY\r\n\r\nIf any provision of the IRR is declared invalid, the remaining provisions shall continue to be effective to the extent allowed by law.\r\n\r\nXXXI. REPEALING AND AMENDING PROVISIONS\r\n\r\nAll rules, regulations, guidelines and issuances inconsistent with the IRR shall be modified or repealed to the extent of the inconsistency.\r\n\r\nExisting policies shall continue to apply insofar as they are consistent with Republic Act No. 11551 and the IRR.\r\n\r\nXXXII. EFFECTIVITY\r\n\r\nThe Implementing Rules and Regulations shall take effect in accordance with the applicable publication and effectivity requirements.\r\n\r\nCHED, TESDA, DOLE and covered educational institutions shall undertake the necessary measures for implementation.','2026-08-13 16:00:00');

/*Table structure for table `lc_lala_conversations` */

DROP TABLE IF EXISTS `lc_lala_conversations`;

CREATE TABLE `lc_lala_conversations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `session_id` varchar(100) NOT NULL,
  `user_id` int(10) unsigned DEFAULT NULL,
