  KEY `idx_assigned_to` (`assigned_to`),
  KEY `idx_date_received` (`date_received`),
  KEY `idx_agency` (`external_agency`)
) ENGINE=InnoDB AUTO_INCREMENT=280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

