/*Table structure for table `lc_policies` */

DROP TABLE IF EXISTS `lc_policies`;

CREATE TABLE `lc_policies` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `policy_code` varchar(100) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `category_id` int(11) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `version` varchar(50) DEFAULT '1.0',
  `effective_date` date DEFAULT NULL,
  `acknowledgement_deadline` date DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Draft',
  `requires_acknowledgement` tinyint(1) DEFAULT 0,
  `attachment_path` varchar(500) DEFAULT NULL,
  `attachment_name` varchar(255) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `archived_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_lc_policies_created_by` (`created_by`),
  KEY `fk_lc_policies_approved_by` (`approved_by`),
  KEY `fk_lc_policies_category_id` (`category_id`),
  CONSTRAINT `fk_lc_policies_approved_by` FOREIGN KEY (`approved_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policies_category` FOREIGN KEY (`category_id`) REFERENCES `lc_policy_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policies_category_id` FOREIGN KEY (`category_id`) REFERENCES `lc_policy_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policies_created_by` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_policies` */

insert  into `lc_policies`(`id`,`policy_code`,`title`,`category_id`,`description`,`content`,`version`,`effective_date`,`acknowledgement_deadline`,`status`,`requires_acknowledgement`,`attachment_path`,`attachment_name`,`created_by`,`approved_by`,`published_at`,`archived_at`,`created_at`,`updated_at`) values 
(1,'POL-DATA-001','Remote Work Policy',1,'Guidelines for remote work arrangements, eligibility, and expectations.','This policy outlines the rules and expectations for employees working remotely.','1.0','2026-01-01','2026-01-15','Published',1,'/uploads/policies/remote-work-v1.pdf','remote-work-v1.pdf',1,1,'2026-01-01 08:00:00',NULL,'2026-01-01 00:00:00','2026-08-16 16:50:47'),
(2,'POL-DATA-002','Code of Conduct',2,'Standards of behavior and ethical guidelines for all employees.','All employees must adhere to the highest standards of professional conduct.','2.0','2026-02-15','2026-03-01','Published',1,'/uploads/policies/code-of-conduct-v2.pdf','code-of-conduct-v2.pdf',2,2,'2026-02-15 08:00:00',NULL,'2026-02-10 00:00:00','2026-08-16 16:50:47'),
(3,'POL-DATA-003','IT Security Policy',3,'Security protocols for IT systems, data protection, and access control.','This policy defines the security requirements for all IT systems and data.','1.0','2026-03-01','2026-03-15','Draft',1,NULL,NULL,3,NULL,NULL,NULL,'2026-02-25 00:00:00','2026-08-16 16:50:47'),
(4,'POL-DATA-004','Data Privacy Policy',2,'Compliance with data privacy regulations and handling of personal information.','We are committed to protecting personal data in accordance with applicable laws.','1.0','2026-04-10','2026-04-25','Published',1,'/uploads/policies/data-privacy-v1.pdf','data-privacy-v1.pdf',1,1,'2026-04-10 08:00:00',NULL,'2026-04-05 00:00:00','2026-08-16 16:50:47'),
(5,'POL-DATA-005','Employee Handbook',1,'Comprehensive guide covering company policies, benefits, and procedures.','This handbook contains important information about our company policies.','3.0','2026-05-20','2026-06-05','Published',1,'/uploads/policies/employee-handbook-v3.pdf','employee-handbook-v3.pdf',4,4,'2026-05-20 08:00:00',NULL,'2026-05-15 00:00:00','2026-08-16 16:50:47'),
(6,'POL-DATA-006','Anti-Harassment Policy',2,'Zero-tolerance policy against harassment and discrimination in the workplace.','Harassment of any kind will not be tolerated in our workplace.','1.0','2026-06-01','2026-06-15','For Review',1,NULL,NULL,5,NULL,NULL,NULL,'2026-05-25 00:00:00','2026-08-16 16:50:47'),
(7,'POL-DATA-007','Social Media Policy',1,'Guidelines for employee use of social media platforms.','Employees must follow these guidelines when using social media.','1.0','2026-07-15','2026-07-30','Published',1,'/uploads/policies/social-media-v1.pdf','social-media-v1.pdf',2,2,'2026-07-15 08:00:00',NULL,'2026-07-10 00:00:00','2026-08-16 16:50:47'),
(8,'POL-DATA-008','Business Continuity Plan',4,'Procedures for maintaining operations during emergencies or disruptions.','This plan ensures business continuity during unforeseen events.','2.0','2026-08-01','2026-08-12','Published',1,NULL,NULL,6,NULL,NULL,NULL,'2026-07-28 00:00:00','2026-10-21 02:19:21'),
(9,'POL-DATA-009','Workplace Safety Policy',2,'Health and safety standards to ensure a safe working environment.','All employees must follow safety procedures to maintain a safe workplace.','1.0','2026-09-05','2026-09-20','Published',1,'/uploads/policies/safety-v1.pdf','safety-v1.pdf',3,3,'2026-09-05 08:00:00',NULL,'2026-09-01 00:00:00','2026-08-16 16:50:47'),
(10,'POL-DATA-010','Expense Reimbursement Policy',6,'Rules and procedures for submitting and processing expense reports.','This policy outlines the process for expense reimbursement.','1.0','2025-12-01','2025-12-15','Archived',1,'/uploads/policies/expense-v1.pdf','expense-v1.pdf',4,4,'2025-12-01 08:00:00','2026-06-01 08:00:00','2025-11-25 00:00:00','2026-08-16 16:50:47');

/*Table structure for table `lc_policy_acknowledgments` */

DROP TABLE IF EXISTS `lc_policy_acknowledgments`;

CREATE TABLE `lc_policy_acknowledgments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `policy_id` int(11) DEFAULT NULL,
  `date_acknowledged` datetime DEFAULT NULL,
  `ip_address` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `policy_employee` (`policy_id`,`employee_id`),
  KEY `fk_lc_policy_ack_employee` (`employee_id`),
  CONSTRAINT `fk_lc_policy_ack_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policy_ack_policy` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policy_acknowledgments_policy_id` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_policy_acknowledgments` */

/*Table structure for table `lc_policy_assignments` */

DROP TABLE IF EXISTS `lc_policy_assignments`;

CREATE TABLE `lc_policy_assignments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `policy_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `due_date` date DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Pending',
  `reminder_sent_at` datetime DEFAULT NULL,
  `reminder_count` int(11) DEFAULT 0,
  `assigned_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `policy_employee` (`policy_id`,`employee_id`),
  KEY `status` (`status`),
  KEY `fk_lc_policy_assignments_employee` (`employee_id`),
  CONSTRAINT `fk_lc_policy_assignments_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policy_assignments_policy` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_lc_policy_assignments_policy_id` FOREIGN KEY (`policy_id`) REFERENCES `lc_policies` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=627 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

