/*Table structure for table `lc_sent_history` */

DROP TABLE IF EXISTS `lc_sent_history`;

CREATE TABLE `lc_sent_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `message` text DEFAULT NULL,
  `type` varchar(50) DEFAULT NULL,
  `department` varchar(100) DEFAULT NULL,
  `is_read` tinyint(1) DEFAULT 0,
  `module` varchar(100) DEFAULT NULL,
  `sender_email` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=322 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `lc_sent_history` */

insert  into `lc_sent_history`(`id`,`employee_id`,`email`,`title`,`message`,`type`,`department`,`is_read`,`module`,`sender_email`,`created_at`,`updated_at`) values 
(1,1005,'enriquezblythe@gmail.com','Re: Action Required: Government Registration Documents - Jhon Carlo  Garcia','Dear Jhon Carlo  Garcia,\n\nThis is a reminder regarding your government registration documents. Our records indicate that your registration is currently marked as \"Missing\".\n\nEmployee Information:\n- Employee No.: EMP-000029\n- Department: Recruitment and Onboarding\n- Overall Status: Missing\n\nGovernment IDs Requiring Attention:\n- SSS Number (Missing)\n- PhilHealth Number (Missing)\n- Pag-IBIG Number (Missing)\n- TIN (Missing)\n\nPlease submit the required documents to the HR department at your earliest convenience. If you have any questions or need assistance, feel free to reach out to us.\n\nBest regards,\nHR Department\n\nOn 9/29/2026, 7:49:45 PM, Cheska Baustita wrote:','notification',NULL,0,'compliance','cheska.baustita@bcp.edu.ph','2026-09-29 19:49:45','2026-09-29 19:49:45'),
(2,1005,'enriquezblythe@gmail.com','Fwd:','NOTICE TO EXPLAIN (NTE)\nAdministrative Due Process Notice Requiring Letter of Intent\n\nDate Issued: September 29, 2026\nEmployee Name: \nEmployee Number: EMP-000029\nDepartment: Recruitment and Onboarding\nPosition: HR Staff\n\nDear ,\n\nThis Notice to Explain (NTE) is issued in accordance with the Company\'s Code of Conduct, disciplinary procedures, the Philippine Labor Code, applicable Department of Labor and Employment (DOLE) regulations, and the principles of administrative due process.\n\nYou are hereby required to personally appear before the Human Resources Department to explain your side regarding the incident described below. This notice is issued to provide you with a fair and reasonable opportunity to be heard before any administrative action or decision is made.\n\nDetails of the Alleged Incident\n\nDate of Incident: 2026-09-22\nTime: 08:15:00\nLocation: Main Office\nIncident Description: Employee was reported for repeated late arrivals during the current payroll period. The matter is currently under initial review.\n\nYou are directed to report to the HR Office immediately to discuss this matter and submit your letter of intent together with any supporting documents, evidence, or witness statements.\n\nFailure to report to the HR Office within the prescribed period, without a valid reason, may be considered a waiver of your opportunity to explain. The Company may proceed with the administrative evaluation based on the available records and evidence.\n\nPlease be advised that the issuance of this Notice does not constitute a finding of guilt nor the imposition of disciplinary action. It is issued solely to ensure compliance with the requirements of administrative due process and to provide you with an opportunity to be heard.\n\nPlease refer to the attached Notice to Explain (NTE) document for the complete details, formal record, and further instructions related to this notice.\n\nRegards,\nCheska  Bautista\nHR Directress\n\n---\nThis is a system-generated NTE for academic demonstration purposes.\n\n---------- Forwarded message ---------\nFrom: Unknown\nSubject: No subject','warning',NULL,0,'compliance','enriquezblythe@gmail.com','2026-09-29 20:30:43','2026-09-29 20:30:43'),
