/*Table structure for table `lc_sss_contributions` */

DROP TABLE IF EXISTS `lc_sss_contributions`;

CREATE TABLE `lc_sss_contributions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `contribution_number` varchar(100) DEFAULT NULL,
  `status` enum('Submitted','Pending','Overdue','Rejected') NOT NULL DEFAULT 'Pending',
  `payroll_notified` tinyint(1) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_lc_sss_employee` (`employee_id`),
  CONSTRAINT `fk_lc_sss_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

