/*Table structure for table `lc_termination_loi_tokens` */

DROP TABLE IF EXISTS `lc_termination_loi_tokens`;

CREATE TABLE `lc_termination_loi_tokens` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `complaint_id` int(11) NOT NULL,
  `token_hash` char(64) NOT NULL,
  `respondent_email` varchar(254) NOT NULL,
  `expires_at` datetime NOT NULL,
  `used_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_termination_loi_token_hash` (`token_hash`),
  KEY `idx_termination_loi_complaint` (`complaint_id`),
  KEY `idx_termination_loi_expiry` (`expires_at`)
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

