insert  into `ld_lesson`(`id`,`module_id`,`title`,`content_type`,`content_body`,`video_url`,`order_index`,`status`,`created_at`,`updated_at`) values 
(1,1,'Why Workplace Safety Matters','text','<h3>Introduction</h3><p>A safe workplace protects people, productivity, and reputation. This lesson explains the business and human reasons behind workplace safety.</p>',NULL,1,'active','2026-10-18 19:19:35','2026-10-18 19:19:35'),
(2,1,'Roles, Rights, and Responsibilities','text','<h3>Everyone Has a Role</h3><p>Understand employee rights, employer duties, and how to report concerns through the correct channels.</p>',NULL,2,'active','2026-10-18 19:19:35','2026-10-18 19:19:35'),
(3,2,'Spotting Common Workplace Hazards','text','<h3>Hazard Awareness</h3><p>Learn how to identify physical, ergonomic, chemical, and psychosocial hazards before they cause harm.</p>',NULL,1,'active','2026-10-18 19:19:35','2026-10-18 19:19:35'),
(4,2,'The Hierarchy of Risk Controls','text','<h3>Controlling Risk</h3><p>Elimination, substitution, engineering controls, administrative controls, and PPE - applied in the right order.</p>',NULL,2,'active','2026-10-18 19:19:35','2026-10-18 19:19:35'),
(5,3,'The Communication Process','text','<h3>Sender, Message, Receiver</h3><p>Explore the communication loop and the barriers that cause misunderstandings at work.</p>',NULL,1,'active','2026-10-18 19:19:35','2026-10-18 19:19:35'),
