/*Table structure for table `legal_documents` */

DROP TABLE IF EXISTS `legal_documents`;

CREATE TABLE `legal_documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `document_name` varchar(255) NOT NULL,
  `category` varchar(100) NOT NULL,
  `reference_number` varchar(150) DEFAULT NULL,
  `issuing_authority` varchar(255) DEFAULT NULL,
  `establishment_name` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `issue_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `file_path` varchar(500) NOT NULL,
  `original_filename` varchar(255) NOT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `file_size` bigint(20) unsigned DEFAULT NULL,
  `renewal_status` enum('active','expiring_soon','expired','renewed','no_expiry') NOT NULL DEFAULT 'active',
  `renewal_alert_days` int(10) unsigned NOT NULL DEFAULT 30,
  `renewal_notes` text DEFAULT NULL,
  `uploaded_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `responsible_head` varchar(255) DEFAULT NULL,
  `responsible_email` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_legal_documents_category` (`category`),
  KEY `idx_legal_documents_expiry` (`expiry_date`),
  KEY `idx_legal_documents_status` (`renewal_status`),
  KEY `idx_legal_documents_name` (`document_name`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `legal_documents` */

insert  into `legal_documents`(`id`,`document_name`,`category`,`reference_number`,`issuing_authority`,`establishment_name`,`description`,`issue_date`,`expiry_date`,`file_path`,`original_filename`,`mime_type`,`file_size`,`renewal_status`,`renewal_alert_days`,`renewal_notes`,`uploaded_by`,`created_at`,`updated_at`,`responsible_head`,`responsible_email`) values 
