/*Table structure for table `pm_competencies` */

DROP TABLE IF EXISTS `pm_competencies`;

CREATE TABLE `pm_competencies` (
  `competency_id` int(11) NOT NULL,
  `competency_name` varchar(255) NOT NULL,
  `competency_code` varchar(50) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`competency_id`),
  UNIQUE KEY `competency_name` (`competency_name`),
  KEY `idx_competencies_active` (`is_active`),
  KEY `idx_competencies_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pm_competencies` */

/*Table structure for table `pm_competency_ratings` */

DROP TABLE IF EXISTS `pm_competency_ratings`;

CREATE TABLE `pm_competency_ratings` (
  `rating_id` int(11) NOT NULL,
  `assignment_id` int(11) NOT NULL,
  `competency_id` int(11) NOT NULL,
  `rating_score` decimal(4,2) DEFAULT NULL,
  `feedback_text` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`rating_id`),
  KEY `idx_competency_ratings_assignment` (`assignment_id`),
  KEY `idx_competency_ratings_competency` (`competency_id`),
  CONSTRAINT `fk_competency_ratings_assignment` FOREIGN KEY (`assignment_id`) REFERENCES `pm_feedback_assignments` (`assignment_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_competency_ratings_competency` FOREIGN KEY (`competency_id`) REFERENCES `pm_competencies` (`competency_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pm_competency_ratings_competency_id` FOREIGN KEY (`competency_id`) REFERENCES `pm_competencies` (`competency_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pm_competency_ratings` */

/*Table structure for table `pm_competency_summary` */

DROP TABLE IF EXISTS `pm_competency_summary`;

CREATE TABLE `pm_competency_summary` (
  `competency_summary_id` int(11) NOT NULL,
  `summary_id` int(11) NOT NULL,
  `competency_id` int(11) NOT NULL,
  `competency_name` varchar(255) DEFAULT NULL,
  `average_rating` decimal(4,2) DEFAULT NULL,
  `strength_indicator` tinyint(1) DEFAULT 0,
  `improvement_indicator` tinyint(1) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`competency_summary_id`),
  KEY `idx_competency_summary_summary` (`summary_id`),
  KEY `idx_competency_summary_competency` (`competency_id`),
  CONSTRAINT `fk_competency_summary_competency` FOREIGN KEY (`competency_id`) REFERENCES `pm_competencies` (`competency_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_competency_summary_summary` FOREIGN KEY (`summary_id`) REFERENCES `pm_feedback_summary` (`summary_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pm_competency_summary_summary_id` FOREIGN KEY (`summary_id`) REFERENCES `pm_feedback_summary` (`summary_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pm_competency_summary` */

/*Table structure for table `pm_employee_training` */

DROP TABLE IF EXISTS `pm_employee_training`;

CREATE TABLE `pm_employee_training` (
  `employee_training_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `training_id` int(11) NOT NULL,
  `recommendation_id` int(11) DEFAULT NULL,
  `assigned_date` date DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `attendance_status` enum('Not Started','Attended','Absent') DEFAULT 'Not Started',
  `completion_status` enum('Pending','In Progress','Completed') DEFAULT 'Pending',
  `completion_percentage` decimal(5,2) DEFAULT 0.00,
  `final_score` decimal(6,2) DEFAULT NULL,
  `certificate_status` enum('Not Issued','Issued') DEFAULT 'Not Issued',
  `certificate_reference` varchar(255) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`employee_training_id`),
  KEY `idx_employee_training_employee` (`employee_id`),
  KEY `idx_employee_training_program` (`training_id`),
  KEY `idx_employee_training_recommendation` (`recommendation_id`),
  KEY `idx_employee_training_status` (`completion_status`),
  CONSTRAINT `fk_employee_training_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_employee_training_program` FOREIGN KEY (`training_id`) REFERENCES `pm_training_programs` (`training_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_employee_training_recommendation` FOREIGN KEY (`recommendation_id`) REFERENCES `pm_training_recommendations` (`recommendation_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pm_employee_training_recommendation_id` FOREIGN KEY (`recommendation_id`) REFERENCES `pm_training_recommendations` (`recommendation_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pm_employee_training_training_id` FOREIGN KEY (`training_id`) REFERENCES `pm_training_programs` (`training_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pm_employee_training` */

