/*Table structure for table `pr_final_settlements` */

DROP TABLE IF EXISTS `pr_final_settlements`;

CREATE TABLE `pr_final_settlements` (
  `settlement_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `exit_settlement_id` int(11) DEFAULT NULL,
  `exit_case_type` enum('resignation','termination') NOT NULL,
  `exit_case_id` int(11) NOT NULL,
  `last_working_date` date NOT NULL,
  `settlement_date` date DEFAULT NULL,
  `total_earnings` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_deductions` decimal(15,2) NOT NULL DEFAULT 0.00,
  `net_settlement` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` enum('draft','processing','calculated','for_approval','approved','paid','cancelled') NOT NULL DEFAULT 'draft',
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `payment_reference` varchar(100) DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`settlement_id`),
  KEY `idx_final_settlement_employee` (`employee_id`),
  KEY `idx_final_settlement_exit` (`exit_settlement_id`),
  KEY `idx_final_settlement_case` (`exit_case_type`,`exit_case_id`),
  KEY `idx_final_settlement_status` (`status`),
  KEY `idx_final_settlement_date` (`settlement_date`),
  KEY `fk_pr_final_settlements_approved_by` (`approved_by`),
  KEY `fk_pr_final_settlements_created_by` (`created_by`),
  CONSTRAINT `fk_pr_final_settlements_approved_by` FOREIGN KEY (`approved_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_final_settlements_created_by` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_final_settlements_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_final_settlements_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_final_settlements_exit` FOREIGN KEY (`exit_settlement_id`) REFERENCES `exit_employee_settlements` (`settlement_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `pr_final_settlements` */

/*Table structure for table `pr_pagibig_rates` */

