/*Table structure for table `pr_part_time_rates` */

DROP TABLE IF EXISTS `pr_part_time_rates`;

CREATE TABLE `pr_part_time_rates` (
  `part_time_rate_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `hourly_rate` decimal(10,2) NOT NULL,
  `effective_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`part_time_rate_id`),
  KEY `idx_ptr_employee` (`employee_id`),
  KEY `idx_ptr_effective_date` (`effective_date`),
  KEY `idx_ptr_status` (`status`),
  CONSTRAINT `fk_ptr_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

