/*Table structure for table `pr_payslip_items` */

DROP TABLE IF EXISTS `pr_payslip_items`;

CREATE TABLE `pr_payslip_items` (
  `payslip_item_id` int(11) NOT NULL AUTO_INCREMENT,
  `payslip_id` int(11) DEFAULT NULL,
  `item_type` enum('earning','deduction') DEFAULT NULL,
  `category` varchar(30) DEFAULT NULL,
  `description` varchar(100) DEFAULT NULL,
  `amount` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`payslip_item_id`),
  KEY `fk_payslip_items` (`payslip_id`),
  KEY `idx_payslip_items_category` (`item_type`,`category`),
  CONSTRAINT `fk_payslip_items` FOREIGN KEY (`payslip_id`) REFERENCES `pr_payslips` (`payslip_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

