/*Table structure for table `pr_payslips` */

DROP TABLE IF EXISTS `pr_payslips`;

CREATE TABLE `pr_payslips` (
  `payslip_id` int(11) NOT NULL AUTO_INCREMENT,
  `run_id` int(11) DEFAULT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `gross_pay` decimal(10,2) DEFAULT NULL,
  `total_deductions` decimal(10,2) DEFAULT NULL,
  `net_pay` decimal(10,2) DEFAULT NULL,
  `generated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `is_exit_settlement` tinyint(1) DEFAULT 0 COMMENT 'Flag: 1 if this is an exit/final payslip',
  `settlement_id` int(11) DEFAULT NULL COMMENT 'Links to exit_employee_settlements.id',
  `resignation_id` int(11) DEFAULT NULL COMMENT 'Links to exit_resignations.id',
  PRIMARY KEY (`payslip_id`),
  KEY `fk_employee_payslips` (`employee_id`),
  KEY `fk_employee_runs` (`run_id`),
  KEY `fk_pr_payslips_settlement` (`settlement_id`),
  KEY `fk_pr_payslips_resignation_id` (`resignation_id`),
  CONSTRAINT `fk_employee_payslips` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_employee_runs` FOREIGN KEY (`run_id`) REFERENCES `pr_runs` (`run_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_payslips_resignation` FOREIGN KEY (`resignation_id`) REFERENCES `exit_resignations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_payslips_resignation_id` FOREIGN KEY (`resignation_id`) REFERENCES `ep_resignation_requests` (`resignation_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_payslips_run_id` FOREIGN KEY (`run_id`) REFERENCES `pr_runs` (`run_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_payslips_settlement` FOREIGN KEY (`settlement_id`) REFERENCES `exit_employee_settlements` (`settlement_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=120 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `pr_payslips` */

