/*Table structure for table `rao_experience` */

DROP TABLE IF EXISTS `rao_experience`;

CREATE TABLE `rao_experience` (
  `experience_id` int(11) NOT NULL AUTO_INCREMENT,
  `application_id` int(11) NOT NULL,
  `company_name` varchar(255) NOT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `employer` varchar(150) DEFAULT NULL,
  `position` varchar(150) NOT NULL,
  `description` varchar(150) NOT NULL,
  PRIMARY KEY (`experience_id`),
  KEY `idx_experience_application_id` (`application_id`),
  CONSTRAINT `fk_experience_application` FOREIGN KEY (`application_id`) REFERENCES `rao_applications` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

