/*Table structure for table `rao_interviews` */

DROP TABLE IF EXISTS `rao_interviews`;

CREATE TABLE `rao_interviews` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `application_id` int(11) NOT NULL,
