/*Table structure for table `sd_announcement_attachments` */

DROP TABLE IF EXISTS `sd_announcement_attachments`;

CREATE TABLE `sd_announcement_attachments` (
  `attachment_id` int(11) NOT NULL AUTO_INCREMENT,
  `announcement_id` int(11) NOT NULL,
  `file_path` varchar(255) NOT NULL,
  `original_name` varchar(150) NOT NULL,
  `file_size` int(10) unsigned DEFAULT NULL,
  `uploaded_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`attachment_id`),
  KEY `idx_ann_att_announcement` (`announcement_id`),
  KEY `idx_ann_att_uploaded_by` (`uploaded_by`),
  CONSTRAINT `fk_ann_att_announcement` FOREIGN KEY (`announcement_id`) REFERENCES `sd_announcements` (`announcement_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ann_att_uploaded_by` FOREIGN KEY (`uploaded_by`) REFERENCES `em_employees` (`employee_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `sd_announcement_attachments` */

/*Table structure for table `sd_announcement_audiences` */

DROP TABLE IF EXISTS `sd_announcement_audiences`;

CREATE TABLE `sd_announcement_audiences` (
  `audience_id` int(11) NOT NULL AUTO_INCREMENT,
  `announcement_id` int(11) NOT NULL,
  `audience_type` enum('Department','Unit','Employee') NOT NULL,
  `department_id` int(11) DEFAULT NULL,
  `unit_id` int(11) DEFAULT NULL,
  `employee_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`audience_id`),
  UNIQUE KEY `uq_ann_aud_dept` (`announcement_id`,`department_id`),
  UNIQUE KEY `uq_ann_aud_unit` (`announcement_id`,`unit_id`),
  UNIQUE KEY `uq_ann_aud_emp` (`announcement_id`,`employee_id`),
  KEY `idx_ann_aud_dept` (`department_id`),
  KEY `idx_ann_aud_unit` (`unit_id`),
  KEY `idx_ann_aud_emp` (`employee_id`),
  CONSTRAINT `fk_ann_aud_announcement` FOREIGN KEY (`announcement_id`) REFERENCES `sd_announcements` (`announcement_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ann_aud_department` FOREIGN KEY (`department_id`) REFERENCES `em_departments` (`department_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ann_aud_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ann_aud_unit` FOREIGN KEY (`unit_id`) REFERENCES `em_units` (`unit_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `sd_announcement_audiences` */

/*Table structure for table `sd_announcement_deliveries` */

DROP TABLE IF EXISTS `sd_announcement_deliveries`;

CREATE TABLE `sd_announcement_deliveries` (
  `announcement_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `delivered_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`announcement_id`,`user_id`),
  KEY `idx_ann_del_user` (`user_id`),
  CONSTRAINT `fk_ann_del_announcement` FOREIGN KEY (`announcement_id`) REFERENCES `sd_announcements` (`announcement_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ann_del_user` FOREIGN KEY (`user_id`) REFERENCES `user_account` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

