/*Table structure for table `ta_holidays` */

DROP TABLE IF EXISTS `ta_holidays`;

CREATE TABLE `ta_holidays` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `holiday_date` date NOT NULL,
  `is_recurring` tinyint(1) DEFAULT 0,
  `country_code` varchar(10) DEFAULT 'PH',
  `description` text DEFAULT NULL,
  `category` varchar(50) DEFAULT 'national',
  `holiday_scope` varchar(30) NOT NULL DEFAULT 'national',
  `province_name` varchar(100) DEFAULT NULL,
  `is_working_day` tinyint(1) NOT NULL DEFAULT 0,
  `source` varchar(30) NOT NULL DEFAULT 'manual',
  `is_active` tinyint(1) DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_holidays_creator` (`created_by`),
  CONSTRAINT `fk_holidays_creator` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

