/*Table structure for table `ta_leave_requests` */

DROP TABLE IF EXISTS `ta_leave_requests`;

CREATE TABLE `ta_leave_requests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `leave_type_id` int(11) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `date_submitted` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL,
  `status` enum('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',
  `details` varchar(255) DEFAULT NULL,
  `reason` text DEFAULT NULL COMMENT 'Detailed reason for leave request',
  `supporting_document` varchar(255) DEFAULT NULL,
  `documents` longtext DEFAULT NULL COMMENT 'JSON array of uploaded document file paths',
  `document_uploaded_at` timestamp NULL DEFAULT NULL,
  `reject_reason` varchar(255) DEFAULT NULL,
  `balance_deducted` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `fk_ta_leave_requests_employee` (`employee_id`),
  KEY `fk_ta_leave_requests_leave_type` (`leave_type_id`),
  CONSTRAINT `fk_ta_leave_requests_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_leave_requests_leave_type` FOREIGN KEY (`leave_type_id`) REFERENCES `ta_leave_types` (`leave_type_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_leave_requests_leave_type_id` FOREIGN KEY (`leave_type_id`) REFERENCES `ta_leave_types` (`leave_type_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `ta_leave_requests` */

/*Table structure for table `ta_leave_types` */

DROP TABLE IF EXISTS `ta_leave_types`;

CREATE TABLE `ta_leave_types` (
  `leave_type_id` int(11) NOT NULL AUTO_INCREMENT,
  `leave_type_name` varchar(50) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `days_per_year` int(11) NOT NULL DEFAULT 10,
  `is_deductible` tinyint(1) DEFAULT 1,
  `requires_approval` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `accrual_frequency` enum('yearly','monthly') NOT NULL DEFAULT 'yearly',
  `monthly_accrual_days` decimal(4,1) DEFAULT NULL,
  PRIMARY KEY (`leave_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

