/*Table structure for table `ta_shift_assignments` */

DROP TABLE IF EXISTS `ta_shift_assignments`;

CREATE TABLE `ta_shift_assignments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `shift_id` int(11) NOT NULL,
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_ta_shift_assignments_employee` (`employee_id`),
  KEY `fk_ta_shift_assignments_shift` (`shift_id`),
  KEY `fk_ta_shift_assignments_created_by` (`created_by`),
  CONSTRAINT `fk_ta_shift_assignments_created_by` FOREIGN KEY (`created_by`) REFERENCES `user_account` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_shift_assignments_employee` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_shift_assignments_employee_id` FOREIGN KEY (`employee_id`) REFERENCES `em_employees` (`employee_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_shift_assignments_shift` FOREIGN KEY (`shift_id`) REFERENCES `ta_shifts` (`shift_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ta_shift_assignments_shift_id` FOREIGN KEY (`shift_id`) REFERENCES `ta_shifts` (`shift_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `ta_shift_assignments` */

/*Table structure for table `ta_shift_exclusions` */

DROP TABLE IF EXISTS `ta_shift_exclusions`;

CREATE TABLE `ta_shift_exclusions` (
  `exclusion_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_shift_id` int(11) NOT NULL,
  `exclusion_date` date NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`exclusion_id`),
  KEY `fk_ta_shift_exclusions_employee_shift` (`employee_shift_id`),
  CONSTRAINT `fk_ta_shift_exclusions_employee_shift` FOREIGN KEY (`employee_shift_id`) REFERENCES `ta_employee_shifts` (`employee_shift_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `ta_shift_exclusions` */

/*Table structure for table `ta_shift_weekday_times` */

DROP TABLE IF EXISTS `ta_shift_weekday_times`;

CREATE TABLE `ta_shift_weekday_times` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `shift_id` int(11) NOT NULL,
  `weekday` tinyint(4) NOT NULL COMMENT '0=Sunday,1=Monday...6=Saturday',
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `break_start` time DEFAULT NULL,
  `break_end` time DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `shift_id` (`shift_id`),
  KEY `weekday` (`weekday`),
  CONSTRAINT `fk_ta_shift_weekday_times_shift` FOREIGN KEY (`shift_id`) REFERENCES `ta_shifts` (`shift_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `ta_shift_weekday_times` */

