/* Trigger structure for table `em_employees` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `after_employee_insert_to_faculty` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'payrollb'@'localhost' */ /*!50003 TRIGGER `after_employee_insert_to_faculty` AFTER INSERT ON `em_employees` FOR EACH ROW BEGIN
  IF COALESCE(NEW.is_archived, 0) = 0 AND EXISTS (
       SELECT 1 FROM em_positions p
       WHERE p.position_id = NEW.position_id
         AND (p.position_name LIKE '%Instructor%' OR p.position_name LIKE '%Professor%')
     ) THEN
    INSERT INTO cc_faculty (employee_id, faculty_code, first_name, middle_name, last_name, email, department, max_load)
    SELECT NEW.employee_id, NEW.employee_code, NEW.first_name, NEW.middle_name, NEW.last_name, NEW.email, NULL,
           CASE NEW.employment_type WHEN 'Full-time' THEN 45 WHEN 'Part-time' THEN 15 WHEN 'OJT/Training' THEN 4 ELSE 15 END
    FROM DUAL
    WHERE NOT EXISTS (SELECT 1 FROM cc_faculty WHERE employee_id = NEW.employee_id);
  END IF;
END */$$


DELIMITER ;

